        pcall(function()
            local bytes = _G.MWB64Decode(b64)
            _G._MWIconLoadN = (_G._MWIconLoadN or 0) + 1
            local fname = "mw_icon_" .. safeKey .. "_" .. tostring(_G._MWIconLoadN) .. ".png"
