local embeddedLogin = (function()
    local API = {
        Version = "UniversalLogin.MeowUI.Offline.NoKey",
        Started = false,
        Stopped = false,
        Subscribers = {},
        Errors = 0,
    }
    _G.AdityaOrgLogin = API

    local L = {
        Authorized = true,
        Licensed = true,
        Pending = false,
        Status = "Authorized (Offline - No Key Required)",
        Key = "NO_KEY",
        DestroyUI = function() end,
        Login = function() return true end,
        Logout = function() return true end,
    }
    _G.LunarLoginRuntime = L
    API.Runtime = L

    function API.IsAuthorized()
        return not API.Stopped
    end

    function API.Bind(onAuthorized, onLocked)
        local handle = { OnAuthorized = onAuthorized, OnLocked = onLocked }
        API.Subscribers[handle] = handle
        if API.Started and onAuthorized then
            pcall(onAuthorized, L.Status)
        end
        return function()
            API.Subscribers[handle] = nil
        end
    end

    function API.Start(options)
        if API.Stopped then
            return false, "MODULE_STOPPED"
        end
        API.Started = true
        for _, binding in pairs(API.Subscribers) do
            if binding.OnAuthorized then
                pcall(binding.OnAuthorized, L.Status)
            end
        end
        return true
    end

    function API.OnlineError(msg, fatal)
        pcall(function()
            print("[OFFLINE_LOGIN] " .. tostring(msg))
        end)
    end

    function API.Stop()
        API.Stopped = true
        API.Started = false
        for _, binding in pairs(API.Subscribers) do
            if binding.OnLocked then
                pcall(binding.OnLocked)
            end
        end
    end

    function API.Login(key)
        return true
    end

    function API.Status()
        return {
            authorized = true,
            pending = false,
            message = L.Status,
        }
    end

    function API.Update()
    end

    _G.MasterLicenseLogin = function() return true end
    _G.MasterLicenseLogout = function() return true end
    _G.MasterLicenseStatus = function() return { authorized = true, pending = false } end

    return API
end)()

