    function PlayerMapMarker.IsAI(pawn)
        if pawn.bIsAI == true or pawn.bIsAI == 1 or pawn.bIsAIBot == true or pawn.bIsABot == true then
            return true
        end
        local ping = tonumber(
            (pawn.PlayerState and pawn.PlayerState.Ping) or pawn.Ping or (pawn.GetPing and pawn:GetPing())
        )
        if ping and ping >= 0 and ping <= 3 then
            return true
        end
        if Game.IsAI then
            local ok, value = pcall(Game.IsAI, Game, pawn)
            if ok then
                return value == true or value == 1
            end
        end
        return false
    end
