        viewport.pc, viewport.fn, viewport.mode = nil, nil, nil
        Core.ViewFramePC = nil
    end
    function PlayerMapMarker.GetDynamicViewportSize(pc)
        if Core.ViewFramePC == pc then
            return Core.ViewWidth, Core.ViewHeight
        end
        local fn = pc.GetViewportSize
        if viewport.pc ~= pc or viewport.fn ~= fn then
            viewport.pc, viewport.fn, viewport.mode = pc, fn, nil
        end
        local function read(mode)
            if mode == "vector" then
                viewport.point.X, viewport.point.Y = 0, 0
                local ok, w, h = pcall(fn, pc, viewport.point)
                if ok and viewport.point.X > 200 and viewport.point.Y > 200 then
                    return viewport.point.X, viewport.point.Y
                end
                if ok and finite(w) and finite(h) and w > 200 and h > 200 then
                    return w, h
                end
            elseif mode == "returns" then
                local ok, w, h = pcall(fn, pc, 0, 0)
                if ok and finite(w) and finite(h) and w > 200 and h > 200 then
                    return w, h
                end
            else
                local ok, v = pcall(function()
                    return WidgetLayoutLibrary.GetViewportSize(pc)
                end)
                if ok and v and finite(v.X) and finite(v.Y) and v.X > 200 and v.Y > 200 then
                    return v.X, v.Y
                end
            end
        end
        if viewport.mode then
            local w, h = read(viewport.mode)
            if w then
                return w, h
            end
            viewport.mode = nil
        end
        for _, mode in ipairs({ "vector", "returns", "library" }) do
            local w, h = read(mode)
            if w then
                viewport.mode = mode
                return w, h
            end
        end
        return 1920, 1080
    end
