    function _G.SaveModSettings()
        local lines = {}
        for key, value in pairs(_G.MWConfig) do
            lines[#lines + 1] = "c." .. key .. "=" .. tostring(value)
        end
        for key, value in pairs(_G.MWState.CustomTextData) do
            if finite(value) then
                lines[#lines + 1] = "t." .. key .. "=" .. tostring(value)
            end
        end
        table.sort(lines)
        for _, path in ipairs(paths("MEOW_MINIMAL.cfg")) do
            local f = io.open(path .. ".tmp", "wb")
            if f then
                local ok, written = pcall(f.write, f, table.concat(lines, "\n"))
                local closed = pcall(f.close, f)
                if ok and written and closed and os.rename(path .. ".tmp", path) then
                    return true
                end
            end
        end
        return false
    end
    function Core.LoadSettings()
        local defaults = _G.MWDefaultConfig()
        for _, path in ipairs(paths("MEOW_MINIMAL.cfg")) do
            local f = io.open(path, "rb")
            if f then
                local text = f:read(65537)
                f:close()
                if #text <= 65536 then
                    for scope, key, raw in text:gmatch("([ct])%.([%w_]+)=([^\r\n]+)") do
                        local target = scope == "c" and _G.MWConfig or _G.MWState.CustomTextData
                        local reference = scope == "c" and defaults[key] or target[key]
                        if scope == "c" and key == "EspMaxDistance" then
                            target[key] = defaults.EspMaxDistance
                        elseif type(reference) == "boolean" and (raw == "true" or raw == "false") then
                            target[key] = raw == "true"
                        elseif type(reference) == "number" then
                            local n = tonumber(raw)
                            if finite(n) then
                                target[key] = math.max(0, math.min(1000, n))
                            end
                        end
                    end
                end
                return
            end
        end
    end
    function Core.ResolveCanvas()
        local time = now()
        if time < (Core.NextCanvasCheck or 0) and Valid(Core.Canvas) then
            return Core.Canvas
        end
        Core.NextCanvasCheck = time + 0.25
        local tools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local ui = tools.GetMainControlBaseUI()
        local canvas = Valid(ui) and (ui.CanvasPanel_0 or ui.CanvasPanel_42) or nil
        if not Valid(canvas) then
            return nil
        end
        local canvasToken = objectToken(canvas)
        if canvasToken ~= Core.CanvasToken or not Valid(Core.Canvas) then
            if Core.Clear then
                Core.Clear()
            end
            if LM and LM.Reset then
                LM.Reset()
            end
            Core.Canvas = canvas
            Core.CanvasToken = canvasToken
        end
        return canvas
    end
