    -- MODULE: skin-manager.lua
    do
        local driver = rawget(_G, "SRCManagedSkinDriver")
        if not driver then
            driver = {
                Schema = 1,
                Enabled = false,
                Loaded = false,
                Entries = {},
                Status = "Off",
                RawRequire = require,
            }
            _G.SRCManagedSkinDriver = driver
            local function clock()
                return _G.RealNow and _G.RealNow() or os.clock()
            end
            function driver.Cancel(entry)
                if entry.Handle ~= nil then
                    if entry.Actor then
                        pcall(entry.Actor.RemoveGameTimer, entry.Actor, entry.Handle)
                    elseif entry.Base.RemoveTimer then
                        pcall(entry.Base.RemoveTimer, entry.Handle)
                    end
                end
                entry.Handle = nil
                entry.Cancelled = true
                driver.Entries[entry] = nil
            end
            local function schedule(entry)
                if entry.Cancelled or not driver.Enabled then
                    return
                end
                if entry.Actor and not Valid(entry.Actor) then
                    driver.Cancel(entry)
                    return
                end
                entry.Generation = (entry.Generation or 0) + 1
                local generation = entry.Generation
                local function callback(...)
                    if not driver.Enabled or entry.Cancelled or generation ~= entry.Generation then
                        return
                    end
                    if entry.Kind == "once" then
                        entry.Handle = nil
                        driver.Entries[entry] = nil
                    end

                    return entry.Callback(...)
                end
                local delay = entry.Remaining or entry.Delay
                entry.Due = clock() + delay
                if entry.Actor then
                    entry.Handle = entry.Actor:AddGameTimer(delay, entry.Kind == "loop", callback)
                elseif entry.Kind == "loop" then
                    local args = entry.Args
                    entry.Handle = entry.Base.AddTimerLoop(delay, callback, table.unpack(args, 1, args.n))
                else
                    entry.Handle = entry.Base.AddTimerOnce(delay, callback)
                end
                entry.Remaining = nil
            end
            local function register(base, kind, delay, callback, args, actor)
                assert(type(callback) == "function", "skin_timer_callback_missing")
                local entry = {
                    Base = base,
                    Kind = kind,
                    Delay = math.max(0, tonumber(delay) or 0),
                    Callback = callback,
                    Args = args or { n = 0 },
                    Actor = actor,
                }
                driver.Entries[entry] = true
                schedule(entry)
                return entry
            end
            function driver.Require(name)
                local base = driver.RawRequire(name)
                if name ~= "common.time_ticker" then
                    return base
                end
                if driver.Proxy and driver.ProxyBase == base then
                    return driver.Proxy
                end
                local proxy = setmetatable({}, { __index = base })
                if type(base.AddTimerOnce) == "function" then
                    function proxy.AddTimerOnce(delay, callback)
                        return register(base, "once", delay, callback)
                    end
                end
                if type(base.AddTimerLoop) == "function" then
                    function proxy.AddTimerLoop(delay, callback, ...)
                        local args = { n = select("#", ...), ... }
                        return register(base, "loop", delay, callback, args)
                    end
                end
                function proxy.RemoveTimer(token)
                    if type(token) == "table" and driver.Entries[token] then
                        driver.Cancel(token)
                    elseif type(token) ~= "table" and base.RemoveTimer then
                        return base.RemoveTimer(token)
                    end
                end
                driver.Proxy, driver.ProxyBase = proxy, base
                return proxy
            end
            function driver.AddActorTimer(actor, delay, repeating, callback)
                return register(nil, repeating and "loop" or "once", delay, callback, nil, actor)
            end
            function driver.RemoveActorTimer(actor, token)
                if type(token) == "table" then
                    driver.Cancel(token)
                elseif actor and actor.RemoveGameTimer then
                    return actor:RemoveGameTimer(token)
                end
            end
            function driver.Pause()
                driver.Enabled = false
                for entry in pairs(driver.Entries) do
                    entry.Generation = (entry.Generation or 0) + 1
                    if entry.Kind == "once" then
                        entry.Remaining = math.max(0, (entry.Due or clock()) - clock())
                    else
                        entry.Remaining = entry.Delay
                    end
                    if entry.Handle ~= nil then
                        if entry.Actor then
                            pcall(entry.Actor.RemoveGameTimer, entry.Actor, entry.Handle)
                        elseif entry.Base.RemoveTimer then
                            pcall(entry.Base.RemoveTimer, entry.Handle)
                        end
                    end
                    entry.Handle = nil
                end
            end
            function driver.Resume()
                driver.Enabled = true
                for entry in pairs(driver.Entries) do
                    if entry.Handle == nil then
                        schedule(entry)
                    end
                end
            end
        end
        Core.SkinDriver = driver
        local categories = {
            SkinWeapons = {
                "SkinMatchWeapon",
                "SkinWeaponWatcher",
                "InventureNTHUY2004",
                "SkinEnable_M416",
                "SkinEnable_AKM",
                "SkinEnable_SCAR",
                "SkinEnable_M762",
                "SkinEnable_AUG",
                "SkinEnable_UMP",
                "SkinEnable_UZI",
                "SkinEnable_Groza",
                "SkinEnable_S12K",
                "SkinEnable_DBS",
            },
            SkinOutfits = {
                "SkinMatchOutfit",
                "SkinMatchFace",
                "SkinEnable_Suit",
                "SkinEnable_Top",
                "SkinEnable_Gloves",
                "SkinEnable_Bottom",
                "SkinEnable_Shoes",
                "SkinEnable_Bag",
                "SkinEnable_Helmet",
            },
            SkinVehicles = {
                "SkinMatchVehicle",
                "SkinEnable_Dacia",
                "SkinEnable_UAZ",
                "SkinEnable_Coupe",
                "SkinEnable_Buggy",
                "SkinEnable_Mirado",
            },
            SkinAirborne = { "SkinMatchAirborne", "SkinEnable_Parachute" },
            SkinPets = { "ModPet" },
            SkinEmotes = { "ModEmote" },
            SkinEffects = { "SkinDeadBox", "SkinAttachment", "KillMessage" },
        }
        function Core.ApplySkinSettings()
            local config = _G.NTHUY2004Config
            if not driver.Loaded or not config then
                return
            end
            config.ModSkin = driver.Enabled
            config.UseScriptSkins = driver.Enabled
            config.TelegramReport = false
            config.UnlimitedCash = false
            config.FreeLobbyShop = false
            config.ModPersonalInfo = false
            for key, fields in pairs(categories) do
                for _, field in ipairs(fields) do
                    config[field] = driver.Enabled and _G.MWConfig[key] == true
                end
            end
        end
        function Core.SetSkinEnabled(enabled)
            if not enabled then
                if driver.Loaded and _G.StopSkinAlwaysOn then
                    pcall(_G.StopSkinAlwaysOn)
                end
                driver.Pause()
                driver.Status = "Off"
                Core.ApplySkinSettings()
                return true
            end
            if not LM or not LM.IsVerified() then
                return false, "Sign in first"
            end
            if driver.Failed then
                return false, "Restart the game to retry loading skins"
            end
            if _G._SkinAlwaysOnLoaded and not driver.Loaded then
                return false, "Another skin loader is active; restart the game"
            end
            driver.Enabled = true
            local ok, err = pcall(function()
                if not driver.Loaded then
                    Core.LoadSkinPayload(driver)
                    assert(type(_G.StartSkinAlwaysOn) == "function", "skin_start_missing")
                    driver.Loaded = true
                end
                _G.StartSkinAlwaysOn()
                if _G._SkinLastStartError then
                    error(_G._SkinLastStartError)
                end
                Core.ApplySkinSettings()
                driver.Resume()
            end)
            if not ok then
                driver.Failed = true
                driver.Error = tostring(err)
                driver.Status = "Load failed; restart game"
                if _G.StopSkinAlwaysOn then
                    pcall(_G.StopSkinAlwaysOn)
                end
                _G._SkinAlwaysOnStopped = true
                if _G.NTHUY2004Config then
                    _G.NTHUY2004Config.ModSkin = false
                    _G.NTHUY2004Config.UseScriptSkins = false
                end
                driver.Pause()
                Core.ApplySkinSettings()
                return false, driver.Status
            end
            driver.Status = "On"
            return true
        end
        function Core.SkinTick(pc)
            if _G.MWConfig.SkinEnabled ~= driver.Enabled then
                local ok, err = Core.SetSkinEnabled(_G.MWConfig.SkinEnabled)
                if not ok then
                    _G.MWConfig.SkinEnabled = false
                    Core.Report("skin", err)
                end
            end
            if not driver.Enabled or not driver.Loaded then
                return
            end
            local time = now()
            if time >= (Core.NextSkinPulse or 0) then
                Core.NextSkinPulse = time + 0.5
                if (_G.NeedCheckDeadBoxTimer or 0) > 0 and _G.DeadBox_TemperRequest then
                    local ok, err = pcall(_G.DeadBox_TemperRequest, pc)
                    if not ok then
                        Core.Report("skin-effects", err)
                    end
                end
            end
        end
    end

    -- MODULE: skin-payload.lua
    function Core.LoadSkinPayload(SkinDriver)
        local require = SkinDriver.Require
        _G.slua_nthuy2004 = _G.slua_nthuy2004 or _G.slua
        if _G._SkinAlwaysOnLoaded then
        else
            _G._SkinAlwaysOnLoaded = true
            _G._SkinAlwaysOnStarted = false
            _G._SkinAlwaysOnStopped = false

            local GameplayStatics, GameplayData
            local function EnsureCoreGameplay()
                if not GameplayStatics then
                    pcall(function()
                        GameplayStatics = import("GameplayStatics")
                    end)
                end
                if not GameplayData then
                    pcall(function()
                        GameplayData = require("GameLua.GameCore.Data.GameplayData")
                    end)
                end
                return GameplayData ~= nil
            end
            pcall(EnsureCoreGameplay)

            local function Notify(msg)
                local s = "[VIP SKIN UNLOCK] " .. tostring(msg)
                pcall(function()
                    if _G.NTHUY2004Notify then
                        _G.NTHUY2004Notify(s)
                    end
                end)
                pcall(function()
                    local sh = import("ScriptHelperClient")
                    if sh and sh.AddOnScreenDebugMessage then
                        sh.AddOnScreenDebugMessage(
                            s,
                            -1,
                            3.0,
                            { R = 1, G = 1, B = 0, A = 1 },
                            { X = 1.2, Y = 1.2 }
                        )
                    end
                end)
            end

            local _slua = rawget(_G, "slua_nthuy2004")

            local function Valid(obj)
                if not obj then
                    return false
                end
                if _slua and _slua.isValid then
