                    return _G.AddOutfitLobbyState
                end

                local LOBBY = setmetatable({}, {
                    __index = function(_, k)
                        return F.lobbyState()[k]
                    end,
                    __newindex = function(_, k, v)
                        F.lobbyState()[k] = v
                    end,
