                    return v and tonumber(v.resID or v.res_id) or nil
                end

                function F.resToCustSlot(resID, st)
                    resID, st = tonumber(resID), tonumber(st)
                    if not resID or resID <= 0 then
                        return nil
                    end
                    st = st or F.subType(F.cfg(resID))
                    if st == HAT_SUB or HAT_SUBS[st] then
                        return F.CUST_SLOT.HatEquipemtSlot
                    end
                    if st == OUTFIT_SUB then
                        return F.CUST_SLOT.ClothesEquipemtSlot
                    end
                    if st == PANTS_SUB then
