                    end
                    if F.isParachuteRes(resID) or st == PARACHUTE_SUB then
                        return F.CUST_SLOT.ParachuteEquipemtSlot
                    end
                    if F.isGlideRes(resID) or GLIDER_SUBS[st] then
                        return F.CUST_SLOT.GlideEquipemtSlot
                    end
                    return nil
                end

                function F.isSuitRes(resID)
                    if F.subType(F.cfg(resID)) ~= OUTFIT_SUB then
                        return false
                    end
                    return F.wardrobeTab(resID) ~= TAB_CLOTHES
                end

                function F.isTshirtRes(resID)
                    return F.subType(F.cfg(resID)) == OUTFIT_SUB and F.wardrobeTab(resID) == TAB_CLOTHES
                end

                function F.weaponIdFromSkin(resID)
                    local m = CDataTable
                        and CDataTable.GetTableData
                        and CDataTable.GetTableData("WeaponSkinMapping", resID)
                    if not m then
                        return nil
                    end
                    return m.WeaponID or m.WeaponId
                end

                function F.isValidWeaponId(weaponID)
                    weaponID = tonumber(weaponID)
                    if not weaponID or weaponID <= 0 then
                        return false
                    end
                    if weaponID == MELEE_ID then
                        return true
                    end

                    if weaponID >= 108000 and weaponID < 109000 then
                        return true
                    end
                    return weaponID >= 101000 and weaponID < 108000
                end

                function F.isValidWeaponPersistEntry(weaponID, resID)
                    weaponID, resID = tonumber(weaponID), tonumber(resID)
                    if not F.isValidWeaponId(weaponID) or not resID or resID <= 0 then
                        return false
                    end
                    if weaponID == resID then
                        return false
                    end
                    if resID >= 1800000 and resID < 1810000 then
                        return false
                    end
                    if resID >= 1900000 and resID < 2000000 then
                        return false
                    end

                    if weaponID == MELEE_ID then
                        return F.subType(F.cfg(resID)) == MELEE_ID
                    end
                    local wid = tonumber(F.weaponIdFromSkin(resID))
                    return wid and wid == weaponID
                end

                function F.sanitizeConfigWeapons(wmap)
                    if type(wmap) ~= "table" then
                        return {}
                    end
                    local clean = {}
                    for wid, res in pairs(wmap) do
                        wid, res = tonumber(wid), tonumber(res)

                        if wid == MELEE_ID and res and F.subType(F.cfg(res)) == MELEE_ID then
                            local mapped = tonumber(F.weaponIdFromSkin(res))
                            if mapped and mapped > 0 then
                                clean[mapped] = res
                            end
                        elseif F.isValidWeaponPersistEntry(wid, res) then
                            clean[wid] = res
                        end
                    end
                    return clean
                end

                function F.indexWeaponSkin(resID, insID)
                    resID, insID = tonumber(resID), tonumber(insID)
                    if not resID or not insID then
                        return
                    end
                    local c = F.cfg(resID)
                    local st = F.subType(c)
                    if not (GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st]) then
                        return
                    end
                    if GRENADE_SUB[st] then
                        local base = GRENADE_BASE_BY_SUB[st]
                        if base then
                            R.byWeapon[base] = R.byWeapon[base] or {}
                            R.byWeapon[base][resID] = insID
                        end
                        return
                    end
                    local wid = F.weaponIdFromSkin(resID)
                    wid = tonumber(wid)
                    if not wid or wid <= 0 then
                        return
                    end
                    R.byWeapon[wid] = R.byWeapon[wid] or {}
                    R.byWeapon[wid][resID] = insID
                end

                function F.isInjectedIns(ins)
                    return ins and R.insToRes[tonumber(ins)] ~= nil
                end

                function F.isInjectedRes(res)
                    return res and R.resToIns[tonumber(res)] ~= nil
                end

                function F.isWeaponSkinRes(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    local st = F.subType(F.cfg(resID))
                    return GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st]
                end

                function F.isGrenadeSkinRes(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    return GRENADE_SUB[F.subType(F.cfg(resID))] == true
                end

                function F.grenadeBaseFromSkin(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return nil
                    end
                    local st = F.subType(F.cfg(resID))
                    return st and GRENADE_BASE_BY_SUB[st] or nil
                end

                function F.saveGrenadeToCache(baseID, resID, insID)
                    baseID, resID, insID = tonumber(baseID), tonumber(resID), tonumber(insID)
                    if not baseID or not GRENADE_FIELD_BY_BASE[baseID] then
                        return
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not F.isGrenadeSkinRes(resID) then
                        return
                    end
                    if F.grenadeBaseFromSkin(resID) ~= baseID then
                        return
                    end
                    local cch = F.cache()
                    cch.grenades = cch.grenades or {}
                    cch.grenades[baseID] = { resID = resID, insID = insID or 0 }
                    PERSIST.configGrenades = PERSIST.configGrenades or {}
                    PERSIST.configGrenades[baseID] = resID
                    MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
                    MATCH_CONFIG.grenadeSkins[baseID] = resID
                    _matchApplied = false
                    F.perfInvalidateLobby()
                    F.persistMarkDirty()
                end

                function F.getCachedGrenadeSkin(baseID)
                    baseID = tonumber(baseID) or 0
                    local cch = F.cache()
                    local w = cch.grenades and cch.grenades[baseID]
                    if w and tonumber(w.resID) and tonumber(w.resID) > 0 then
                        return tonumber(w.resID)
                    end
                    local p = PERSIST.configGrenades and tonumber(PERSIST.configGrenades[baseID])
                    if p and p > 0 then
                        return p
                    end
                    local m = MATCH_CONFIG.grenadeSkins and tonumber(MATCH_CONFIG.grenadeSkins[baseID])
                    if m and m > 0 then
                        return m
                    end
                    return nil
                end

                function F.applyInitialConsumableAvatar()
                    return "DIT ME MAY INBOX @nthmod"
                end

                local function F_patchGrenadeImpl(mod, key, wrapFn, flagKey)
                    if not mod then
                        return false
                    end
                    local impl = mod.__inner_impl or mod
                    if type(impl) ~= "table" then
                        return false
                    end
                    flagKey = flagKey or ("_NTHUY2004_" .. tostring(key))
                    if impl[flagKey] then
                        return true
                    end
                    local orig = impl[key]
                    if type(orig) ~= "function" then
                        return false
                    end
                    impl[flagKey] = true
                    impl[key] = wrapFn(orig)

                    pcall(function()
                        if mod.__inner_impl and mod[key] ~= nil then
                            rawset(mod, key, nil)
                        end
                    end)
                    return true
                end

                function F.hookGrenadeAvatarLookup()
                    pcall(function()
                        local AvatarUtil = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarUtil")
                        if AvatarUtil then
                            AvatarUtil.GM_GrenadeAvatarTest = true
                        end
                    end)

                    pcall(function()
                        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                        if not ADU or not ADU.TryGetGrenadeAvatarID or ADU._NTHUY2004GrenadeHooked then
                            return
                        end
                        ADU._NTHUY2004GrenadeHooked = true
                        local o = ADU.TryGetGrenadeAvatarID
                        ADU.TryGetGrenadeAvatarID = function(uPlayerController, ItemID)
                            local base = tonumber(ItemID) or 0
                            if base > 100000 then
                                base = math.floor(base / 100)
                            end
                            if GRENADE_FIELD_BY_BASE[base] then
                                local override = F.getCachedGrenadeSkin(base)
                                if override and override > 0 then
                                    return override
                                end
                            end
                            return o(uPlayerController, ItemID)
                        end
                    end)

                    pcall(function()
                        F.hookArmorInventoryAvatar()
                        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                        if ADU and not ADU._NTHUY2004ConsumableApplyHooked then
                            ADU._NTHUY2004ConsumableApplyHooked = true
                            if ADU.InitialEquipmentAvatar and not ADU._NTHUY2004WrapInitEquipForGrenade then
                                ADU._NTHUY2004WrapInitEquipForGrenade = true
                                local o = ADU.InitialEquipmentAvatar
                                ADU.InitialEquipmentAvatar = function(PlayerInfo, uPlayerController)
                                    o(PlayerInfo, uPlayerController)
                                    pcall(F.applyInitialConsumableAvatar)
                                end
                            end
                        end
                    end)
                end

                function F.resolveGrenadeBaseFromItemId(itemId)
                    itemId = tonumber(itemId) or 0
                    if itemId <= 0 then
                        return nil
                    end
                    if GRENADE_FIELD_BY_BASE[itemId] then
                        return itemId
                    end
                    if itemId > 100000 then
                        local asProto = math.floor(itemId / 100)
                        if GRENADE_FIELD_BY_BASE[asProto] then
                            return asProto
                        end
                    end
                    local st = nil
                    pcall(function()
                        st = F.subType(F.cfg(itemId))
                    end)
                    if st and GRENADE_BASE_BY_SUB[st] then
                        return GRENADE_BASE_BY_SUB[st]
                    end
                    return nil
                end

                function F.resolveGrenadeSkinForProjectile(proj)
                    if not proj then
                        return nil
                    end
                    local skin = nil
                    pcall(function()
                        local tid = 0
                        if proj.ItemDefineID then
                            tid = tonumber(proj.ItemDefineID.TypeSpecificID) or 0
                        end
                        local base = F.resolveGrenadeBaseFromItemId(tid)
                        if base then
                            skin = F.getCachedGrenadeSkin(base)
                        end
                        if (not skin or skin <= 0) and type(proj.GetAvatarID) == "function" then
                            local pc = proj.GetInstigatorControllerSafety
                                and proj:GetInstigatorControllerSafety()
                            local avData = pc and pc.InitialConsumableAvatar
                            if avData then
                                local aid = tonumber(proj:GetAvatarID(avData)) or 0
                                if aid > 0 then
                                    skin = aid
                                end
                            end
                        end
                        if (not skin or skin <= 0) and slua.isValid(proj.GrenadeAvatarComponent_BP) then
                            local comp = proj.GrenadeAvatarComponent_BP
                            if comp.GetCurGrenadeAvatarID then
                                local cur = tonumber(comp:GetCurGrenadeAvatarID()) or 0
                                if cur > 0 then
                                    skin = cur
                                end
                            end
                        end
                        if skin and skin > 0 then
                            local b = F.resolveGrenadeBaseFromItemId(skin)
                            if b then
                                local cached = F.getCachedGrenadeSkin(b)
                                if cached and cached > 0 then
                                    skin = cached
                                end
                            end
                        end
                    end)
                    return skin
                end

                function F.getGrenadeBindCfg(skin)
                    skin = tonumber(skin) or 0
                    if skin <= 0 then
                        return nil
                    end
                    local cfg = nil
                    pcall(function()
                        cfg = CDataTable.GetTableData("GrenadeKillGunBindMap", skin)
                    end)
                    if cfg then
                        return cfg
                    end
                    pcall(function()
                        local tbl = CDataTable.GetTable("GrenadeKillGunBindMap")
                        if not tbl then
                            return
                        end
                        for _, row in pairs(tbl) do
                            if row and tonumber(row.GrenadeID) == skin then
                                cfg = row
                                break
                            end
                        end
                    end)
                    return cfg
                end

                function F.syncGrenadeExplodeAssetsFromHandle(proj, skin)
                    skin = tonumber(skin) or 0
                    if skin <= 0 or not proj then
                        return false
                    end
                    local synced = false
                    pcall(function()
                        local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
                        if not slua.isValid(comp) then
                            return
                        end
                        local handle = nil
                        pcall(function()
                            if comp.GetItemAvatarHandle then
                                handle = comp:GetItemAvatarHandle(skin)
                            end
                        end)
                        pcall(function()
                            if slua.isValid(handle) then
                                return
                            end
                            local UBackpackUtils = import("BackpackUtils")
                            local did = UBackpackUtils.GetItemDefineIDByItemID(skin)
                            if did then
                                handle = UBackpackUtils.CreateBattleItemHandle(did, comp, false)
                            end
                        end)
                        if not slua.isValid(handle) then
                            return
                        end
                        local UBackpackGrenadeAvatarHandle = import("BackpackGrenadeAvatarHandle")
                        pcall(function()
                            if
                                Game
                                and Game.IsClassOf
                                and not Game:IsClassOf(handle, UBackpackGrenadeAvatarHandle)
                            then
                                handle = nil
                            end
                        end)
                        if not slua.isValid(handle) then
                            return
                        end

                        local function putAsset(key, obj)
                            if not key or not slua.isValid(obj) then
                                return
                            end
                            pcall(function()
                                if comp.AssetObjectMap and comp.AssetObjectMap.Add then
                                    comp.AssetObjectMap:Add(tostring(key), obj)
                                end
                            end)
                            if key == "ExplodeParticleSystem" or tostring(key):find("Explode", 1, true) then
                                proj.ExplodeParticleSystem = obj
                            end
                            synced = true
                        end

                        local function loadSoftParticle(entry)
                            if not entry then
                                return
                            end
                            local key = entry.Key or entry.Name
                            local ps = entry.GrenadeParticleSystem
                            if slua.isValid(ps) then
                                putAsset(key, ps)
                                return
                            end
                            pcall(function()
                                local path = nil
                                if
                                    entry.GrenadeParticleSystem and entry.GrenadeParticleSystem.AssetPathName
                                then
                                    path = entry.GrenadeParticleSystem.AssetPathName
                                end
                                if path and path ~= "" then
                                    local UBusinessHelper = import("BusinessHelper")
                                    local uAsset = UBusinessHelper.LoadAssetFromPath(path)
                                    if slua.isValid(uAsset) then
                                        putAsset(key, uAsset)
                                    end
                                end
                            end)
                        end

                        if handle.GrenadeParticleSystemArray and handle.GrenadeParticleSystemArray.Num then
                            for i = 0, handle.GrenadeParticleSystemArray:Num() - 1 do
                                loadSoftParticle(handle.GrenadeParticleSystemArray:Get(i))
                            end
                        end

                        local fxIdx = 0
                        pcall(function()
                            fxIdx = tonumber(comp.OverrideFXIndex) or tonumber(comp.OverrideFxIndex) or 0
                        end)
                        if
                            fxIdx > 0
                            and handle.GrenadeSkinFxSystemArray
                            and handle.GrenadeSkinFxSystemArray.Num
                        then
                            for i = 0, handle.GrenadeSkinFxSystemArray:Num() - 1 do
                                local set = handle.GrenadeSkinFxSystemArray:Get(i)
                                if set and tonumber(set.Index) == fxIdx then
                                    if set.FxList and set.FxList.Num then
                                        for j = 0, set.FxList:Num() - 1 do
                                            loadSoftParticle(set.FxList:Get(j))
                                        end
                                    end
                                    pcall(function()
                                        local seq = set.ExLevelSequence
                                        local path = seq and (seq.AssetPathName or seq)
                                        if type(path) == "string" and path ~= "" then
                                            comp.ExLevelSeqPath = path
                                            local UBusinessHelper = import("BusinessHelper")
                                            comp.ExLevelSeqCache = UBusinessHelper.LoadAssetFromPath(path)
                                        end
                                    end)
                                    pcall(function()
                                        local seq = set.SkyExLevelSequence
                                        local path = seq and (seq.AssetPathName or seq)
                                        if type(path) == "string" and path ~= "" then
                                            comp.SkyExLevelSeqPath = path
                                            local UBusinessHelper = import("BusinessHelper")
                                            comp.SkyExLevelSeqCache = UBusinessHelper.LoadAssetFromPath(path)
                                        end
                                    end)
                                end
                            end
                        end
                    end)
                    return synced
                end

                function F.setGrenadeOverrideFxFromTable(comp, skin)
                    skin = tonumber(skin) or 0
                    if skin <= 0 or not comp or not slua.isValid(comp) then
                        return false
                    end
                    local setOk = false
                    pcall(function()
                        local Cfg = F.getGrenadeBindCfg(skin)
                        local FxGunID = 0
                        if
                            Cfg
                            and Cfg.UnlockFxGunIDList_a
                            and Cfg.UnlockFxGunIDList_a.Num
                            and Cfg.UnlockFxGunIDList_a:Num() > 0
                        then
                            FxGunID = Cfg.UnlockFxGunIDList_a:Get(0)
                        end
                        if FxGunID and FxGunID > 0 then
                            if comp.SetOverrideFxIndex then
                                comp:SetOverrideFxIndex(FxGunID)
                            end
                            if comp.SetOverrideSoundIndex then
                                comp:SetOverrideSoundIndex(FxGunID)
                            end
                            pcall(function()
                                if comp.OnRep_OverrideFXIndexChanged then
                                    comp:OnRep_OverrideFXIndexChanged()
                                end
                            end)
                            pcall(function()
                                if comp.OnRep_OverrideSoundIndexChanged then
                                    comp:OnRep_OverrideSoundIndexChanged()
                                end
                            end)
                            setOk = true
                        end
                    end)
                    return setOk
                end

                function F.spawnGrenadeSkinExplodeFx(proj)
                    if not Client or not proj or not slua.isValid(proj) then
                        return
                    end
                    local skin = F.resolveGrenadeSkinForProjectile(proj)
                    if not skin or skin <= 0 then
                        return
                    end
                    local loc = nil
                    pcall(function()
                        loc = proj:K2_GetActorLocation()
                    end)
                    if not loc then
                        return
                    end
                    local scale = 1
                    pcall(function()
                        scale = (proj.DynamicModifier and proj.DynamicModifier.EffectRange) or 1
                    end)
                    local comp = proj.GrenadeAvatarComponent_BP
                    pcall(function()
                        if
                            slua.isValid(comp)
                            and comp.UseHighLevelParticle
                            and comp:UseHighLevelParticle()
                        then
                            comp:SpawnHighLevelParticleActor(loc)
                            return
                        end
                    end)
                    pcall(function()
                        if slua.isValid(proj.ExplodeParticleSystem) then
                            local UGameplayStatics = import("GameplayStatics")
                            UGameplayStatics.SpawnEmitterAtLocation(
                                proj,
                                proj.ExplodeParticleSystem,
                                loc,
                                FRotator(0, 0, 0),
                                FVector(1, 1, 1) * scale,
                                true
                            )
                        end
                    end)
                end

                function F.prepareGrenadeExplodeFx(proj)
                    if not F.skinFeat("SkinMatchGrenade") then
                        return
                    end
                    if not proj or not slua.isValid(proj) then
                        return
                    end
                    F.applyGrenadeSkinToProjectile(proj)
                    local skin = F.resolveGrenadeSkinForProjectile(proj)
                    if not skin or skin <= 0 then
                        return
                    end
                    local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
                    if slua.isValid(comp) then
                        F.forceGrenadeAvatarComp(comp, skin)
                        F.setGrenadeOverrideFxFromTable(comp, skin)
                        F.syncGrenadeExplodeAssetsFromHandle(proj, skin)
                    end
                    pcall(function()
                        if type(proj.OnGrenadeFxOverride) == "function" then
                            proj:OnGrenadeFxOverride()
                        end
                    end)
                    pcall(function()
                        if type(proj.ResetGrenadeAvatar) == "function" then
                            proj:ResetGrenadeAvatar()
                        end
                    end)
                    pcall(function()
                        if type(proj.RefreshProjectileSkin) == "function" then
                            proj:RefreshProjectileSkin(false)
                        end
                    end)
                end

                function F.forceGrenadeAvatarComp(av, skin)
                    skin = tonumber(skin) or 0
                    if skin <= 0 or not av or not slua.isValid(av) then
                        return false
                    end
                    local ok = false
                    pcall(function()
                        if av.PreChangeGrenadeAvatar then
                            av:PreChangeGrenadeAvatar(skin)
                            ok = true
                        end
                    end)
                    pcall(function()
                        if av.ChangeItemAvatar then
                            av:ChangeItemAvatar(skin, false)
                            ok = true
                        end
                    end)
                    pcall(function()
                        if av.ChangeItemAvatar then
                            av:ChangeItemAvatar(skin, true)
                            ok = true
                        end
                    end)
                    pcall(function()
                        if av.SyncChangeItemAvatar then
                            av:SyncChangeItemAvatar(skin)
                            ok = true
                        end
                    end)
                    pcall(function()
                        F.setGrenadeOverrideFxFromTable(av, skin)
                    end)
                    pcall(function()
                        if av.CheckHasOverrideFx then
                            local pc = nil
                            pcall(function()
                                local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                                pc = GameplayData.GetPlayerController()
                            end)
                            if not pc then
                                pcall(function()
                                    pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                                end)
                            end
                            if pc then
                                av:CheckHasOverrideFx(pc, skin)
                            end
                        end
                    end)
                    return ok
                end

                function F.applyGrenadeSkinToProjectile(proj, typeSpecificID)
                    if not F.skinFeat("SkinMatchGrenade") then
                        return false
                    end
                    if not proj then
                        return false
                    end
                    local applied = false
                    pcall(function()
                        if not slua.isValid(proj) then
                            return
                        end
                        local tid = tonumber(typeSpecificID) or 0
                        if tid <= 0 then
                            pcall(function()
                                if proj.ItemDefineID then
                                    tid = tonumber(proj.ItemDefineID.TypeSpecificID) or 0
                                end
                            end)
                        end
                        local base = F.resolveGrenadeBaseFromItemId(tid)
                        local skin = base and F.getCachedGrenadeSkin(base) or nil

                        if not skin or skin <= 0 then
                            pcall(function()
                                local pc = proj.GetInstigatorControllerSafety
                                    and proj:GetInstigatorControllerSafety()
                                local avData = pc and pc.InitialConsumableAvatar
                                if type(proj.GetAvatarID) == "function" and avData then
                                    local aid = tonumber(proj:GetAvatarID(avData)) or -1
                                    if aid > 0 then
                                        skin = aid
                                        if not base then
                                            base = F.resolveGrenadeBaseFromItemId(aid)
                                        end
                                        if base then
                                            local c = F.getCachedGrenadeSkin(base)
                                            if c and c > 0 then
                                                skin = c
                                            end
                                        end
                                    end
                                end
                            end)
                        end

                        if not skin or skin <= 0 then
                            pcall(function()
                                local pc = proj.GetInstigatorControllerSafety
                                    and proj:GetInstigatorControllerSafety()
                                local avData = pc and pc.InitialConsumableAvatar
                                if not avData then
                                    return
                                end
                                for b, field in pairs(GRENADE_FIELD_BY_BASE) do
                                    local cached = F.getCachedGrenadeSkin(b)
                                    if cached and cached > 0 then
                                        pcall(function()
                                            avData[field] = cached
                                        end)
                                    end
                                end
                                if type(proj.GetAvatarID) == "function" then
                                    local aid = tonumber(proj:GetAvatarID(avData)) or -1
                                    if aid > 0 then
                                        skin = aid
                                    end
                                end
                            end)
                        end
                        if not skin or skin <= 0 then
                            return
                        end

                        local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
                        if F.forceGrenadeAvatarComp(comp, skin) then
                            applied = true
                        end
                        pcall(function()
                            local pc = proj.GetInstigatorControllerSafety
                                and proj:GetInstigatorControllerSafety()
                            if pc and type(proj.CheckHasOverrideFxAndSound) == "function" then
                                proj:CheckHasOverrideFxAndSound(pc, skin)
                            end
                        end)
                        pcall(function()
                            if type(proj.ResetGrenadeAvatar) == "function" then
                                proj:ResetGrenadeAvatar()
                            end
                        end)
                        pcall(function()
                            if type(proj.RefreshProjectileSkin) == "function" then
                                proj:RefreshProjectileSkin(false)
                            end
                        end)
                    end)
                    return applied
                end

                function F.matchApplyGrenadeSkin()
                    if not F.skinFeat("SkinMatchGrenade") then
                        return true
                    end
                    F.hookGrenadeAvatarLookup()
                    F.applyInitialConsumableAvatar()
                    pcall(function()
                        local char = F.getLocalChar()
                        if not char then
                            return
                        end
                        local w = char.GetCurrentWeapon and char:GetCurrentWeapon()
                        if w and slua.isValid(w) then
                            F.applyGrenadeSkinToHeldWeapon(w)
                        end

                        pcall(function()
                            if not char.GetInventoryWeapons then
                                return
                            end
                            local list = char:GetInventoryWeapons()
                            if not list then
                                return
                            end
                            local n = (list.Num and list:Num()) or #list or 0
                            for i = 0, n - 1 do
                                local ww = list.Get and list:Get(i) or list[i]
                                if ww and slua.isValid(ww) then
                                    F.applyGrenadeSkinToHeldWeapon(ww)
                                end
                            end
                        end)
                    end)
                    return true
                end

                function F.applyGrenadeSkinToHeldWeapon(weapon)
                    if not F.skinFeat("SkinMatchGrenade") then
                        return
                    end
                    if not weapon or not slua.isValid(weapon) then
                        return
                    end
                    pcall(function()
                        local resId = 0
                        pcall(function()
                            if weapon.GetItemDefineID then
                                local did = weapon:GetItemDefineID()
                                resId = did and tonumber(did.TypeSpecificID) or 0
                            end
                        end)
                        if resId <= 0 then
                            pcall(function()
                                resId = tonumber(weapon.ItemID) or tonumber(weapon.TypeSpecificID) or 0
                            end)
                        end
                        local base = F.resolveGrenadeBaseFromItemId(resId)

                        if not base then
                            local st = nil
                            pcall(function()
                                st = F.subType(F.cfg(resId))
                            end)
                            if st and GRENADE_BASE_BY_SUB[st] then
                                base = GRENADE_BASE_BY_SUB[st]
                            end
                        end
                        if not base then
                            pcall(function()
                                local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                                if not pc then
                                    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                                    pc = GameplayData.GetPlayerController()
                                end
                                if not pc or not pc.GrenadeAvatarItemList then
                                    return
                                end
                                for b, _ in pairs(GRENADE_FIELD_BY_BASE) do
                                    local proto = b * 100
                                    local skin = nil
                                    pcall(function()
                                        skin = pc.GrenadeAvatarItemList:Get(proto)
                                    end)
                                end
                            end)
                        end
                        if not base then
                            return
                        end
                        local skin = F.getCachedGrenadeSkin(base)
                        if not skin or skin <= 0 then
                            return
                        end

                        local function applyTo(av)
                            if F.forceGrenadeAvatarComp(av, skin) then
                                pcall(function()
                                    if weapon.DelayHandleAvatarMeshChanged then
                                        weapon:DelayHandleAvatarMeshChanged()
                                    end
                                end)
                                return true
                            end
                            return false
                        end

                        local av = nil
                        pcall(function()
                            if weapon.GetGrenadeAvatar then
                                av = weapon:GetGrenadeAvatar()
                            end
                        end)
                        pcall(function()
                            if not av then
                                av = weapon.GrenadeAvatarComponent_BP or weapon.GrenadeAvatarComponent
                            end
                        end)
                        local did = applyTo(av)

                        if not did then
                            pcall(function()
                                if not weapon.GetComponentsByClass then
                                    return
                                end
                                local UGrenadeAvatarComponent = import("GrenadeAvatarComponent")
                                if not UGrenadeAvatarComponent then
                                    return
                                end
                                local comps = weapon:GetComponentsByClass(UGrenadeAvatarComponent)
                                if not comps then
                                    return
                                end
                                local n = (comps.Num and comps:Num()) or 0
                                for i = 0, n - 1 do
                                    local c = comps:Get(i)
                                    if applyTo(c) then
                                        did = true
                                    end
                                end
                            end)
                        end

                        if did then
                            pcall(function()
                                local char = F.getLocalChar()
                                if not char or not char.AddGameTimer then
                                    return
                                end
                                for _, d in ipairs({ 0.05, 0.2, 0.5, 1.0, 2.0 }) do
                                    SkinDriver.AddActorTimer(char, d, false, function()
                                        if weapon and slua.isValid(weapon) then
                                            local a = nil
                                            pcall(function()
                                                if weapon.GetGrenadeAvatar then
                                                    a = weapon:GetGrenadeAvatar()
                                                end
                                            end)
                                            pcall(function()
                                                if not a then
                                                    a = weapon.GrenadeAvatarComponent_BP
                                                        or weapon.GrenadeAvatarComponent
                                                end
                                            end)
                                            applyTo(a)
                                        end
                                    end)
                                end
                            end)
                        end
                    end)
                end

                function F.putOnGrenade(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d and tonumber(d.resID)
                    end
                    if not resID or not F.isGrenadeSkinRes(resID) then
                        return false
                    end
                    local base = F.grenadeBaseFromSkin(resID)
                    if not base then
                        return false
                    end
                    local st = F.subType(F.cfg(resID))
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    F.saveGrenadeToCache(base, resID, insID)
                    F.ensureInjectedItemAlive(nil, resID, insID)
                    local ready = F.isResourcesReady(resID)
                    if not ready then
                        F.requestResourceDownload(resID)
                    end
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if fbd.PutOnThrowObjectSkin then
                            fbd:PutOnThrowObjectSkin(insID)
                        end
                    end)
                    pcall(F.applyInitialConsumableAvatar)
                    pcall(function()
                        local lw = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if lw and lw.ShowGrenadeModel then
                            lw:ShowGrenadeModel(resID, true)
                        end
                    end)
                    if ready then
                        local item = {
                            res_id = resID,
                            resID = resID,
                            instid = insID,
                            ins_id = insID,
                            insID = insID,
                            expire_ts = 0,
                            expireTS = 0,
                            count = 1,
                            itemSubType = st,
                        }
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
                    end
                    return true
                end

                function F.isWeaponSkinIns(insID)
                    insID = tonumber(insID)
                    if not insID then
                        return false
                    end
                    local res = R.insToRes[insID]
                    return res and F.isWeaponSkinRes(res)
                end

                function F.cleanArmoryPollution()
                    pcall(function()
                        local Arm = require("client.logic.armory.logic_armory")
                        if not Arm.rsp_list then
                            return
                        end
                        if Arm.rsp_list.install_list then
                            for wid, entry in pairs(Arm.rsp_list.install_list) do
                                local ins = tonumber(entry and entry.skin_id)
                                if ins and not F.isWeaponSkinIns(ins) then
                                    Arm.rsp_list.install_list[wid] = nil
                                end
                            end
                        end
                        if Arm.rsp_list.skin_list then
                            for wid, skins in pairs(Arm.rsp_list.skin_list) do
                                if type(skins) == "table" then
                                    for resID in pairs(skins) do
                                        if not F.isWeaponSkinRes(tonumber(resID)) then
                                            skins[resID] = nil
                                        end
                                    end
                                end
                            end
                        end
                    end)
                end

                function F.depotSubType(insID, resID)
                    resID = tonumber(resID) or tonumber(R.insToRes[insID])
                    local st = F.subType(F.cfg(resID))
                    if st then
                        return st
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    return d and tonumber(d.itemSubType)
                end

                function F.tryLocalWearByIns(insID)
                    insID = tonumber(insID)
                    if not insID then
                        return false
                    end

                    if
                        _G.NTHUY2004Config
                        and _G.NTHUY2004Config.ModSkin == false
                        and not (_G.NTHUY2004Config.FreeLobbyShop == true)
                    then
                        return false
                    end
                    local resID = R.insToRes[insID]
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not resID and d then
                        resID = tonumber(d.resID or d.res_id)
                    end
                    if not resID or resID <= 0 then
                        return false
                    end
                    local st = F.depotSubType(insID, resID)

                    local function mapLocal()
                        if not R.insToRes[insID] then
                            R.insToRes[insID] = resID
                            R.resToIns[resID] = insID
                        end
                    end

                    if st == GLOVES_SUB then
                        mapLocal()
                        F.putOnGloves(insID)
                        return true
                    end
                    F.clearItemExpire(d, insID, resID)
                    F.ensureDepotItemValid(insID, resID)
                    if F.isParachuteRes(resID) then
                        mapLocal()
                        return F.putOnParachute(insID)
                    end
                    if F.isGlideRes(resID) or GLIDER_SUBS[st] then
                        mapLocal()
                        return F.putOnGlider(insID)
                    end

                    if st == OUTFIT_SUB then
                        mapLocal()

                        local xsuitMeta = nil
                        pcall(function()
                            if
                                type(FLS) == "table"
                                and FLS.IsEnabled
                                and FLS.IsEnabled()
                                and FLS.resolveXSuitMeta
                                and FLS.setXSuitWardrobeBranch
                            then
                                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                                if LogicXSuit and LogicXSuit.IsXSuit and LogicXSuit.IsXSuit(resID) then
                                    xsuitMeta = FLS.resolveXSuitMeta(resID)
                                    if xsuitMeta then
                                        FLS.rememberXSuitWorkshopUnlock(xsuitMeta)
                                        FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
                                        FLS._xsuitWardrobeBranchPrefer[xsuitMeta.period] = xsuitMeta
                                        FLS.setXSuitWardrobeBranch(xsuitMeta, { skipEvent = true })
                                    end
                                end
                            end
                        end)
                        if F.isSuitRes(resID) or F.wardrobeTab(resID) == TAB_SUIT then
                            F.putOnOutfit(insID)
                        else
                            F.putOnRoleWear(insID)
                        end
                        if xsuitMeta then
                            pcall(function()
                                if
                                    EventSystem
                                    and EVENTTYPE_GOLDEN_SUIT
                                    and EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH
                                then
                                    EventSystem:postEvent(
                                        EVENTTYPE_GOLDEN_SUIT,
                                        EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH,
                                        xsuitMeta.period,
                                        xsuitMeta.branchId or 0,
                                        resID
                                    )
                                end
                                if FLS.refreshXSuitWardrobeWearFlags then
                                    FLS.refreshXSuitWardrobeWearFlags(xsuitMeta.period, resID, insID)
                                end
                            end)
                        end
                        return true
                    end
                    if st == HAT_SUB or HEAD_SUBS[st] then
                        mapLocal()
                        F.putOnHat(insID)
                        return true
                    end
                    if FACE_SUBS[st] then
                        mapLocal()
                        F.putOnFaceAccessory(insID)
                        return true
                    end
                    if BODY_SUBS[st] or HELMET_SUBS[st] then
                        mapLocal()
                        F.putOnRoleWear(insID)
                        return true
                    end

                    if not F.isInjectedIns(insID) then
                        return false
                    end
                    if GUN_SUB[st] then
                        local wid = F.weaponIdFromSkin(resID)
                        if wid then
                            F.equipWeaponSkin(wid, insID)
                        end
                        return true
                    end
                    if st == MELEE_ID then
                        local mapped = tonumber(F.weaponIdFromSkin(resID))
                        F.equipWeaponSkin((mapped and mapped > 0) and mapped or MELEE_ID, insID)
                        return true
                    end
                    if GRENADE_SUB[st] then
                        mapLocal()
                        return F.putOnGrenade(insID)
                    end
                    if F.isHallThemeRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
                        mapLocal()
                        return F.putOnHallTheme(insID)
                    end
                    if F.isVehicleRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
                        mapLocal()
                        return F.putOnVehicle(insID)
                    end
                    return false
                end

                function F.isHallThemeRes(resID)
                    local c = F.cfg(tonumber(resID))
                    if not c then
                        return false
                    end
                    local t = c.ItemType or c.itemType
                    return t == HALL_THEME_TYPE
                end

                function F.isResourcesReady(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if not F.isInjectedRes(resID) then
                        return true
                    end
                    local ready = false
                    pcall(function()
                        local PufferConst = require("client.slua.logic.download.puffer_const")
                        local mgr =
                            ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
                        if mgr and mgr.GetStateByItemID then
                            local st = mgr:GetStateByItemID(resID)
                            ready = st == PufferConst.ENUM_DownloadState.Done
                        end
                    end)
                    return ready
                end

                function F.isOdPakReady(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    local ready = false
                    pcall(function()
                        local PufferConst = require("client.slua.logic.download.puffer_const")
                        local Done = PufferConst.ENUM_DownloadState.Done
                        local mgr =
                            ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
                        if mgr and mgr.GetStateByItemID then
                            ready = mgr:GetStateByItemID(resID) == Done
                            if ready then
                                return
                            end
                        end
                        local PM = require("client.slua.logic.download.puffer.puffer_manager")
                        if PM and PM.GetState then
                            ready = PM.GetState(PufferConst.ENUM_DownloadType.ODPAK, { resID }) == Done
                        end
                    end)
                    return ready
                end

                function F.requestOdPakDownload(resID, onDone)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return
                    end
                    if F.isOdPakReady(resID) then
                        if onDone then
                            pcall(onDone)
                        end
                        return
                    end
                    _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
                    _G.AddOutfitDownloadCbs = _G.AddOutfitDownloadCbs or {}
                    local key = "odpak_" .. tostring(resID)
                    if onDone then
                        _G.AddOutfitDownloadCbs[key] = _G.AddOutfitDownloadCbs[key] or {}
                        _G.AddOutfitDownloadCbs[key][#_G.AddOutfitDownloadCbs[key] + 1] = onDone
                    end
                    if _G.AddOutfitDownloadQueued[key] then
                        return
                    end
                    _G.AddOutfitDownloadQueued[key] = true
                    pcall(function()
                        local PM = require("client.slua.logic.download.puffer.puffer_manager")
                        local PufferConst = require("client.slua.logic.download.puffer_const")
                        PM.Download(
                            PufferConst.ENUM_DownloadType.ODPAK,
                            { resID },
                            "AddOutfitVehPart",
                            function()
                                _G.AddOutfitDownloadQueued[key] = nil
                                local cbs = _G.AddOutfitDownloadCbs[key]
                                _G.AddOutfitDownloadCbs[key] = nil
                                if type(cbs) == "table" then
                                    for _, cb in ipairs(cbs) do
                                        pcall(cb)
                                    end
                                end
                            end
                        )
                    end)
                end

                function F.requestResourceDownload(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return
                    end

                    if F.isInjectedRes(resID) then
                        if F.isResourcesReady(resID) then
                            return
                        end
                        _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
                        if _G.AddOutfitDownloadQueued[resID] then
                            return
                        end
                        _G.AddOutfitDownloadQueued[resID] = true
                        pcall(function()
                            local PM = require("client.slua.logic.download.puffer.puffer_manager")
                            local PufferConst = require("client.slua.logic.download.puffer_const")
                            PM.Download(
                                PufferConst.ENUM_DownloadType.ODPAK,
                                { resID },
                                "AddOutfit",
                                function()
                                    _G.AddOutfitDownloadQueued[resID] = nil
                                end
                            )
                        end)
                        return
                    end
                    F.requestOdPakDownload(resID)
                end

                function F.ensureInjectedResources()
                    for res in pairs(R.resToIns) do
                        F.requestResourceDownload(tonumber(res))
                    end
                end

                function F.restorePufferHooks()
                    pcall(function()
                        local mgr =
                            ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
                        if mgr and _G.AddOutfitPufferOrig then
                            mgr.GetStateByItemID = _G.AddOutfitPufferOrig
                        end
                    end)
                    pcall(function()
                        local PM = require("client.slua.logic.download.puffer.puffer_manager")
                        if PM and _G.AddOutfitPufferGetStateOrig then
                            PM.GetState = _G.AddOutfitPufferGetStateOrig
                        end
                    end)
                    pcall(function()
                        local VAC =
                            require("GameLua.GameCore.Module.Vehicle.Component.VehicleAvatarComponent")
                        local vacImpl = VAC and VAC.__inner_impl
                        if vacImpl and _G.AddOutfitVehOrigAssets then
                            vacImpl.LuaIsAssetsAlreadyAvailable = _G.AddOutfitVehOrigAssets
                        end
                    end)
                end

                function F.invalidateSocialWearCache()
                    local s = _G.AddOutfitSocialState
                    if s then
                        s.wearPatchKey, s.snapshotKey, s.fullSnapshot, s.lastHandSkin = nil, nil, nil, nil
                    end
                end

                function F.clearWeaponEquippedMark(weaponID)
                    _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
                    if weaponID then
                        _G.AddOutfitWeaponEquipped[tonumber(weaponID)] = nil
                    else
                        for k in pairs(_G.AddOutfitWeaponEquipped) do
                            _G.AddOutfitWeaponEquipped[k] = nil
                        end
                    end
                end

                function F.isWeaponVisuallyEquipped(weaponID, insID)
                    weaponID, insID = tonumber(weaponID), tonumber(insID)
                    if not weaponID or not insID then
                        return false
                    end
                    return _G.AddOutfitWeaponEquipped and _G.AddOutfitWeaponEquipped[weaponID] == insID
                end

                function F.saveWeaponToCache(weaponID, resID, insID)
                    F.clearWeaponEquippedMark(weaponID)
                    weaponID, resID, insID = tonumber(weaponID), tonumber(resID), tonumber(insID)
                    if not F.isValidWeaponPersistEntry(weaponID, resID) then
                        return
                    end
                    local cch = F.cache()
                    cch.weapons[weaponID] = { resID = resID, insID = insID or 0 }
                    PERSIST.configWeapons = PERSIST.configWeapons or {}
                    PERSIST.configWeapons[weaponID] = resID
                    _G.AddOutfitLastAppliedSkin = {}
                    _matchApplied = false
                    F.perfInvalidateLobby()
                    F.invalidateSocialWearCache()
                    F.persistMarkDirty()
                    F.log("ÃÂ°ÃÂ§ÃÆÃÂ±ÃÂ© ÃÂ³ÃÆÃâ ", weaponID, "Ã¢â â", resID)
                end

                function F.cacheWeaponSkinFromIns(weaponID, insID)
                    weaponID, insID = tonumber(weaponID), tonumber(insID)
                    if not weaponID or not insID or insID <= 0 then
                        return
                    end
                    if F.isInjectedIns(insID) then
                        local res = R.insToRes[insID]
                        if res and F.subType(F.cfg(res)) == MELEE_ID then
                            local mapped = tonumber(F.weaponIdFromSkin(res))
                            if mapped and mapped > 0 then
                                weaponID = mapped
                            end
                        end
                        F.saveWeaponToCache(weaponID, res, insID)
                        return
                    end
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        if d and d.resID and tonumber(d.resID) > 0 then
                            local res = tonumber(d.resID)
                            if F.subType(F.cfg(res)) == MELEE_ID then
                                local mapped = tonumber(F.weaponIdFromSkin(res))
                                if mapped and mapped > 0 then
                                    weaponID = mapped
                                end
                            end
                            F.saveWeaponToCache(weaponID, res, insID)
                        end
                    end)
                end

                function F.saveEquip(resID, insID)
                    resID, insID = tonumber(resID), tonumber(insID)
                    if not resID or not insID then
                        return
                    end
                    local c = F.cfg(resID)
                    local st = F.subType(c)
                    local cch = F.cache()
                    if st == OUTFIT_SUB then
                        if F.wardrobeTab(resID) == TAB_CLOTHES then
                            cch.tshirtRes, cch.tshirtIns = resID, insID
                            _G.AddOutfitLastLobbyTshirtRes = resID
                            F.persistRememberSlot("tshirt", resID)
                        else
                            cch.outfitRes, cch.outfitIns = resID, insID
                            _G.AddOutfitLastLobbyOutfitRes = resID
                            F.persistRememberSlot("outfit", resID)
                            F.invalidateSocialWearCache()
                        end
                    elseif st == HAT_SUB then
                        cch.hatRes, cch.hatIns = resID, insID
                        _G.AddOutfitLastLobbyHatRes = resID
                        F.persistRememberSlot("hat", resID)
                    elseif st == MASK_SUB then
                        cch.maskRes, cch.maskIns = resID, insID
                        _G.AddOutfitLastLobbyMaskRes = resID
                        F.persistRememberSlot("mask", resID)
                    elseif st == GLASS_SUB then
                        cch.glassRes, cch.glassIns = resID, insID
                        _G.AddOutfitLastLobbyGlassRes = resID
                        F.persistRememberSlot("glass", resID)
                    elseif st == PANTS_SUB then
                        cch.pantsRes, cch.pantsIns = resID, insID
                        _G.AddOutfitLastLobbyPantsRes = resID
                        F.persistRememberSlot("pants", resID)
                    elseif st == SHOES_SUB then
                        cch.shoesRes, cch.shoesIns = resID, insID
                        _G.AddOutfitLastLobbyShoesRes = resID
                        F.persistRememberSlot("shoes", resID)
                    elseif BAG_SUBS[st] then
                        resID = F.equipToLobbyMappingID(resID)
                        cch.bagRes, cch.bagIns = resID, insID
                        _G.AddOutfitLastLobbyBagRes = resID
                        _G.BackpackSkin = resID
                        F.persistRememberSlot("bag", resID)
                    elseif HELMET_SUBS[st] then
                        resID = F.equipToLobbyMappingID(resID)
                        cch.helmetRes, cch.helmetIns = resID, insID
                        _G.AddOutfitLastLobbyHelmetRes = resID
                        _G.HelmetSkin = resID
                        F.persistRememberSlot("helmet", resID)
                    elseif st == PARACHUTE_SUB then
                        cch.parachuteRes, cch.parachuteIns = resID, insID
                        _G.AddOutfitLastLobbyParachuteRes = resID
                        F.persistRememberSlot("parachute", resID)
                    elseif F.isGlideRes(resID) then
                        cch.gliderRes, cch.gliderIns = resID, insID
                        _G.AddOutfitLastLobbyGliderRes = resID
                        F.persistRememberSlot("glider", resID)
                    elseif st == GLOVES_SUB then
                        cch.glovesRes, cch.glovesIns = resID, insID
                        _G.AddOutfitLastLobbyGlovesRes = resID
                        F.persistRememberSlot("gloves", resID)
                    elseif GUN_SUB[st] then
                        local wid = F.weaponIdFromSkin(resID)
                        if wid then
                            F.saveWeaponToCache(wid, resID, insID)
                        end
                    elseif st == MELEE_ID then
                        local wid = tonumber(F.weaponIdFromSkin(resID))
                        if wid and wid > 0 then
                            F.saveWeaponToCache(wid, resID, insID)
                        else
                            F.saveWeaponToCache(MELEE_ID, resID, insID)
                        end
                    elseif GRENADE_SUB[st] then
                        local base = F.grenadeBaseFromSkin(resID)
                        if base then
                            F.saveGrenadeToCache(base, resID, insID)
                        end
                    end
                    _matchApplied = false
                    F.perfInvalidateLobby()
                    F.persistMarkDirty()
                end

                function F.findWornInsBySubType(st, filterFn)
                    st = tonumber(st)
                    if not st then
                        return nil
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local AvatarData = require("client.logic.data.AvatarData")
                    for _, ins in pairs(AvatarData.GetRoleWear()) do
                        ins = tonumber(ins)
                        if ins and ins > 0 then
                            local d = wd:GetHallDepotItemDataByInsID(ins)
                            if d and tonumber(d.itemSubType) == st then
                                local res = tonumber(d.resID)
                                if not filterFn or filterFn(res, d) then
                                    return ins, res
                                end
                            end
                        end
                    end
                    return nil
                end

                function F.syncHatCacheFromLobby()
                    local cch = F.cache()
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(HAT_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.hatRes, cch.hatIns = tonumber(res), ins
                            return
                        end
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                        local headIns = tonumber(bag and bag.head_show) or 0
                        if headIns <= 0 then
                            return
                        end
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(headIns)
                            or wd:GetHallDepotItemDataByInsID(headIns)
                        if not d or not d.resID or tonumber(d.resID) <= 0 then
                            return
                        end
                        local st = tonumber(d.itemSubType or F.subType(F.cfg(d.resID)))
                        if HEAD_SUBS[st] then
                            cch.hatRes, cch.hatIns = tonumber(d.resID), headIns
                        end
                    end)
                end

                function F.syncFaceCacheFromLobby()
                    local cch = F.cache()
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(MASK_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.maskRes, cch.maskIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyMaskRes = tonumber(res)
                        end
                    end)
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(GLASS_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.glassRes, cch.glassIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyGlassRes = tonumber(res)
                        end
                    end)
                end

                function F.syncBodyCacheFromLobby()
                    local cch = F.cache()
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                            return F.wardrobeTab(r) == TAB_CLOTHES
                        end)
                        if ins and res and tonumber(res) > 0 then
                            cch.tshirtRes, cch.tshirtIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyTshirtRes = tonumber(res)
                        end
                    end)
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(PANTS_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.pantsRes, cch.pantsIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyPantsRes = tonumber(res)
                        end
                    end)
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(SHOES_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.shoesRes, cch.shoesIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyShoesRes = tonumber(res)
                        end
                    end)
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(GLOVES_SUB)
                        if ins and res and tonumber(res) > 0 then
                            cch.glovesRes, cch.glovesIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyGlovesRes = tonumber(res)
                        end
                    end)
                    pcall(function()
                        for st in pairs(BAG_SUBS) do
                            local ins, res = F.findWornInsBySubType(st)
                            if ins and res and tonumber(res) > 0 then
                                cch.bagRes, cch.bagIns = tonumber(res), ins
                                _G.AddOutfitLastLobbyBagRes = tonumber(res)
                                break
                            end
                        end
                    end)
                    pcall(function()
                        for st in pairs(HELMET_SUBS) do
                            local ins, res = F.findWornInsBySubType(st)
                            if ins and res and tonumber(res) > 0 then
                                cch.helmetRes, cch.helmetIns = tonumber(res), ins
                                _G.AddOutfitLastLobbyHelmetRes = tonumber(res)
                                break
                            end
                        end
                    end)
                    pcall(function()
                        local ins, res = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                            return F.isSuitRes(r)
                        end)
                        if ins and res and tonumber(res) > 0 then
                            cch.outfitRes, cch.outfitIns = tonumber(res), ins
                            _G.AddOutfitLastLobbyOutfitRes = tonumber(res)
                        end
                    end)
                end

                function F.syncAirborneCacheFromLobby(saveToConfig)
                    local cch = F.cache()
                    local cfgPara = tonumber(PERSIST.configSlots and PERSIST.configSlots.parachute)
                    local cfgGlide = tonumber(PERSIST.configSlots and PERSIST.configSlots.glider)
                    local changed = false

                    local function maybeSave(slotName, res)
                        if not saveToConfig or not res or res <= 0 then
                            return
                        end
                        if
                            slotName == "parachute"
                            and res == DEFAULT_PARACHUTE_RES
                            and cfgPara
                            and cfgPara > 0
                            and cfgPara ~= DEFAULT_PARACHUTE_RES
                        then
                            return
                        end
                        F.persistRememberSlot(slotName, res)
                        changed = true
                    end

                    local function applyPara(res, ins)
                        res, ins = tonumber(res), tonumber(ins)
                        if not res or not ins or not F.isParachuteRes(res) then
                            return
                        end
                        if cfgPara and cfgPara > 0 and not saveToConfig then
                            if res == cfgPara then
                                cch.parachuteIns = ins
                            end
                            return
                        end
                        if res == DEFAULT_PARACHUTE_RES and not saveToConfig then
                            return
                        end
                        if cch.parachuteRes ~= res or cch.parachuteIns ~= ins then
                            cch.parachuteRes, cch.parachuteIns = res, ins
                            _G.AddOutfitLastLobbyParachuteRes = res
                            maybeSave("parachute", res)
                        end
                    end

                    local function applyGlide(res, ins)
                        res, ins = tonumber(res), tonumber(ins)
                        if not res or not ins or not F.isGlideRes(res) then
                            return
                        end
                        if cfgGlide and cfgGlide > 0 and not saveToConfig then
                            if res == cfgGlide then
                                cch.gliderIns = ins
                            end
                            return
                        end
                        if cch.gliderRes ~= res or cch.gliderIns ~= ins then
                            cch.gliderRes, cch.gliderIns = res, ins
                            _G.AddOutfitLastLobbyGliderRes = res
                            maybeSave("glider", res)
                        end
                    end

                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local paraIns = tonumber(fbd.GetParachute and fbd:GetParachute()) or 0
                        if paraIns > 0 then
                            local d = wd:GetValidHallDepotItemDataByInsID(paraIns)
                                or wd:GetHallDepotItemDataByInsID(paraIns)
                            applyPara(d and tonumber(d.resID), paraIns)
                        end
                        local glideIns = tonumber(fbd.GetAircraftOrGliding and fbd:GetAircraftOrGliding())
                            or 0
                        if glideIns > 0 then
                            local d = wd:GetValidHallDepotItemDataByInsID(glideIns)
                                or wd:GetHallDepotItemDataByInsID(glideIns)
                            applyGlide(d and tonumber(d.resID), glideIns)
                        end
                    end)
                    pcall(function()
                        for st in pairs(GLIDER_SUBS) do
                            local ins, res = F.findWornInsBySubType(st)
                            if ins and res then
                                applyGlide(res, ins)
                                break
                            end
                        end
                        local ins, res = F.findWornInsBySubType(PARACHUTE_SUB)
                        if ins and res then
                            applyPara(res, ins)
                        end
                    end)
                    if changed then
                        F.persistMarkDirty()
                    end
                end

                function F.syncWeaponCacheFromLobby(force)
                    if LOBBY.lobbySynced and not force then
                        return
                    end
                    LOBBY.lobbySynced = true
                    PERF.mappingsDirty = true
                    PERF.desiredSkins = nil
                    for k in pairs(PERF.skinTarget) do
                        PERF.skinTarget[k] = nil
                    end
                    local cch = F.cache()
                    local function putWeapon(weaponID, res, insID)
                        weaponID, res, insID = tonumber(weaponID), tonumber(res), tonumber(insID)
                        if not weaponID or not res or res <= 0 then
                            return
                        end
                        if weaponID == MELEE_ID and F.subType(F.cfg(res)) == MELEE_ID then
                            local mapped = tonumber(F.weaponIdFromSkin(res))
                            if mapped and mapped > 0 then
                                weaponID = mapped
                            end
                        end
                        if not F.isValidWeaponPersistEntry(weaponID, res) then
                            return
                        end
                        cch.weapons[weaponID] = { resID = res, insID = insID or 0 }
                    end
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                        if bag and bag.weapon_skin_list then
                            for weaponID, entry in pairs(bag.weapon_skin_list) do
                                weaponID = tonumber(weaponID)
                                local insID = tonumber(entry and (entry.skin_id or entry.skinId)) or 0
                                if weaponID and weaponID > 0 and insID > 0 then
                                    local res
                                    if F.isInjectedIns(insID) then
                                        res = tonumber(R.insToRes[insID])
                                    else
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                                            or wd:GetHallDepotItemDataByInsID(insID)
                                        res = d and tonumber(d.resID)
                                    end
                                    putWeapon(weaponID, res, insID)
                                end
                            end
                        end
                    end)
                    pcall(function()
                        local Arm = require("client.logic.armory.logic_armory")
                        if Arm.rsp_list and Arm.rsp_list.install_list then
                            for weaponID, entry in pairs(Arm.rsp_list.install_list) do
                                weaponID = tonumber(weaponID)
                                local insID = tonumber(entry and entry.skin_id) or 0
                                if weaponID and weaponID > 0 and insID > 0 then
                                    local res
                                    if F.isInjectedIns(insID) then
                                        res = tonumber(R.insToRes[insID])
                                    else
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                                            or wd:GetHallDepotItemDataByInsID(insID)
                                        res = d and tonumber(d.resID)
                                    end
                                    putWeapon(weaponID, res, insID)
                                end
                            end
                        end
                    end)
                    F.syncHatCacheFromLobby()
                    F.syncFaceCacheFromLobby()
                    F.syncBodyCacheFromLobby()
                end

                function F.getCachedWeaponSkin(weaponID)
                    weaponID = tonumber(weaponID) or 0
                    if weaponID <= 0 then
                        return nil
                    end
                    F.syncWeaponCacheFromLobby()
                    local w = F.cache().weapons[weaponID]
                    if w and w.resID and w.resID > 0 then
                        return w.resID
                    end
                    return nil
                end

                function F.getMatchWeaponSkin(weaponID)
                    weaponID = tonumber(weaponID) or 0
                    local fromCache = F.getCachedWeaponSkin(weaponID)
                    if fromCache then
                        return fromCache
                    end
                    if MATCH_CONFIG.weaponSkins then
                        local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponID])
                        if fixed and fixed > 0 then
                            return fixed
                        end
                    end
                    return nil
                end

                function F.levelFromEquipArmorID(equipID)
                    equipID = tonumber(equipID) or 0
                    if equipID >= 501001 and equipID <= 501199 then
                        local rem = equipID % 10
                        if rem >= 1 and rem <= 6 then
                            return math.min(rem, 3)
                        end
                        return 1
                    end
                    if equipID >= 502001 and equipID <= 502199 then
                        local rem = equipID % 10
                        if rem >= 1 and rem <= 6 then
                            return math.min(rem, 3)
                        end
                        return 1
                    end
                    if equipID >= 1501000000 and equipID < 1503000000 then
                        local lvDigit = math.floor(equipID / 1000) % 10
                        if lvDigit >= 1 and lvDigit <= 3 then
                            return lvDigit
                        end
                    end
                    return 1
                end

                function F.resolveInvArmorSkinID(currentID)
                    currentID = tonumber(currentID) or 0
                    if currentID <= 0 then
                        return 0
                    end
                    local isBag = (currentID >= 501001 and currentID <= 501199)
                        or (currentID >= 1501000000 and currentID < 1502000000)
                    local isHelmet = (currentID >= 502001 and currentID <= 502199)
                        or (currentID >= 1502000000 and currentID < 1503000000)
                    if not isBag and not isHelmet then
                        pcall(function()
                            local cfg = CDataTable.GetTableData("Item", currentID)
                            local ist = cfg and tonumber(cfg.ItemSubType) or 0
                            if ist == 501 or ist == 504 then
                                isBag = true
                            end
                            if ist == 502 or ist == 505 then
                                isHelmet = true
                            end
                        end)
                    end
                    if isBag then
                        local bagRes = tonumber(_G.BackpackSkin)
                            or tonumber(
                                F.getDesiredWear(
                                    "bagRes",
                                    "bagRes",
                                    "AddOutfitLastLobbyBagRes",
                                    F.syncBodyCacheFromLobby
                                )
                            )
                            or 0
                        if bagRes <= 0 then
                            return 0
                        end
                        return tonumber(F.levelSkinID(bagRes, F.levelFromEquipArmorID(currentID))) or 0
                    end
                    if isHelmet then
                        local helmetRes = tonumber(_G.HelmetSkin)
                            or tonumber(
                                F.getDesiredWear(
                                    "helmetRes",
                                    "helmetRes",
                                    "AddOutfitLastLobbyHelmetRes",
                                    F.syncBodyCacheFromLobby
                                )
                            )
                            or 0
                        if helmetRes <= 0 then
                            return 0
                        end
                        return tonumber(F.levelSkinID(helmetRes, F.levelFromEquipArmorID(currentID))) or 0
                    end
                    return 0
                end

                function F.applyInitialEquipmentAvatar()
                    local bagRes = tonumber(_G.BackpackSkin)
                        or tonumber(
                            F.getDesiredWear(
                                "bagRes",
                                "bagRes",
                                "AddOutfitLastLobbyBagRes",
                                F.syncBodyCacheFromLobby
                            )
                        )
                        or 0
                    local helmetRes = tonumber(_G.HelmetSkin)
                        or tonumber(
                            F.getDesiredWear(
                                "helmetRes",
                                "helmetRes",
                                "AddOutfitLastLobbyHelmetRes",
                                F.syncBodyCacheFromLobby
                            )
                        )
                        or 0
                    if bagRes <= 0 and helmetRes <= 0 then
                        return false
                    end
                    if bagRes > 0 and F.resolveBackpackMappingBase then
                        bagRes = F.resolveBackpackMappingBase(bagRes)
                        _G.BackpackSkin = bagRes
                    end
                    if helmetRes > 0 and F.resolveBackpackMappingBase then
                        helmetRes = F.resolveBackpackMappingBase(helmetRes)
                        _G.HelmetSkin = helmetRes
                    end

                    local changed = false
                    pcall(function()
                        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                        if not pc or not slua.isValid(pc) then
                            pcall(function()
                                local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                                pc = GameplayData.GetPlayerController()
                            end)
                        end
                        if not pc or not slua.isValid(pc) then
                            return
                        end

                        local av = pc.InitialEquipmentAvatar
                        local useTable = (av == nil) or (type(av) == "table")
                        if useTable then
                            av = (type(av) == "table") and av or {}
                            if bagRes > 0 and tonumber(av.BagAvatar) ~= bagRes then
                                av.BagAvatar = bagRes
                                av.BagAvatarList = {
                                    [1] = F.levelSkinID(bagRes, 1),
                                    [2] = F.levelSkinID(bagRes, 2),
                                    [3] = F.levelSkinID(bagRes, 3),
                                }
                                changed = true
                            end
                            if helmetRes > 0 and tonumber(av.HelmetAvatar) ~= helmetRes then
                                av.HelmetAvatar = helmetRes
                                av.HelmetAvatarList = {
                                    [1] = F.levelSkinID(helmetRes, 1),
                                    [2] = F.levelSkinID(helmetRes, 2),
                                    [3] = F.levelSkinID(helmetRes, 3),
                                }
                                changed = true
                            end
                            if changed then
                                pc.InitialEquipmentAvatar = av
                            end
                        else
                            if bagRes > 0 then
                                local curBag = nil
                                pcall(function()
                                    curBag = tonumber(av.BagAvatar)
                                end)
                                if curBag ~= bagRes then
                                    pcall(function()
                                        av.BagAvatar = bagRes
                                    end)
                                    pcall(function()
                                        av.BagAvatarList = {
                                            [1] = F.levelSkinID(bagRes, 1),
                                            [2] = F.levelSkinID(bagRes, 2),
                                            [3] = F.levelSkinID(bagRes, 3),
                                        }
                                    end)
                                    changed = true
                                end
                            end
                            if helmetRes > 0 then
                                local curHelm = nil
                                pcall(function()
                                    curHelm = tonumber(av.HelmetAvatar)
                                end)
                                if curHelm ~= helmetRes then
                                    pcall(function()
                                        av.HelmetAvatar = helmetRes
                                    end)
                                    pcall(function()
                                        av.HelmetAvatarList = {
                                            [1] = F.levelSkinID(helmetRes, 1),
                                            [2] = F.levelSkinID(helmetRes, 2),
                                            [3] = F.levelSkinID(helmetRes, 3),
                                        }
                                    end)
                                    changed = true
                                end
                            end
                        end

                        if changed then
                            pcall(function()
                                if
                                    slua.isValid(pc.PlayerState)
                                    and pc.PlayerState.MetroPlayerStateAvatarFeature
                                then
                                    pc.PlayerState.MetroPlayerStateAvatarFeature.InitialEquipmentAvatar =
                                        pc.InitialEquipmentAvatar
                                end
                            end)

                            pcall(function()
                                if pc.Broadcast and pc.OnEquipmentAvatarChange then
                                    pc:Broadcast("OnEquipmentAvatarChange")
                                end
                            end)
                        end
                    end)
                    return changed
                end

                function F.hookArmorInventoryAvatar()
                    if _G.AddOutfitArmorInvAvatarHooked then
                        return
                    end
                    _G.AddOutfitArmorInvAvatarHooked = true

                    pcall(function()
                        local M = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackArmorSlotUI")
                        local impl = M and (M.__inner_impl or M)
                        if not impl or not impl.GetEquipmentAvatarRes or impl._AddOutfitArmorAvatarHooked then
                            return
                        end
                        impl._AddOutfitArmorAvatarHooked = true
                        local o = impl.GetEquipmentAvatarRes
                        impl.GetEquipmentAvatarRes = function(self, BattleItemData)
                            local override = 0
                            pcall(function()
                                if not BattleItemData then
                                    return
                                end
                                local DefineID = BattleItemData.DefineID
                                    or slua.IndexReference(BattleItemData, "DefineID")
                                local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                                override = F.resolveInvArmorSkinID(tid) or 0
                            end)
                            if override and override > 0 then
                                return override
                            end
                            return o(self, BattleItemData)
                        end
                    end)

                    pcall(function()
                        local M = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackItemUI")
                        local impl = M and (M.__inner_impl or M)
                        if not impl or not impl.GetAvatarID or impl._AddOutfitItemAvatarHooked then
                            return
                        end
                        impl._AddOutfitItemAvatarHooked = true
                        local o = impl.GetAvatarID
                        impl.GetAvatarID = function(self, inData)
                            local override = 0
                            pcall(function()
                                if not inData then
                                    return
                                end
                                local DefineID = inData.DefineID or slua.IndexReference(inData, "DefineID")
                                local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                                override = F.resolveInvArmorSkinID(tid) or 0
                            end)
                            if override and override > 0 then
                                return override
                            end
                            return o(self, inData)
                        end
                    end)

                    pcall(function()
                        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                        if not ADU or not ADU.InitialEquipmentAvatar or ADU._AddOutfitInitEquipAvHooked then
                            return
                        end
                        ADU._AddOutfitInitEquipAvHooked = true
                        local o = ADU.InitialEquipmentAvatar
                        ADU.InitialEquipmentAvatar = function(PlayerInfo, uPlayerController)
                            o(PlayerInfo, uPlayerController)
                            pcall(F.applyInitialEquipmentAvatar)
                        end
                    end)
                end

                function _G.Inventure_NTHUY2004(Backpack)
                    if not Backpack or not slua.isValid(Backpack) then
                        return
                    end
                    if
                        not _G.NTHUY2004Config
                        or not _G.NTHUY2004Config.ModSkin
                        or not _G.NTHUY2004Config.InventureNTHUY2004
                    then
                        return
                    end

                    pcall(function()
                        local bagRes = tonumber(
                            F.getDesiredWear(
                                "bagRes",
                                "bagRes",
                                "AddOutfitLastLobbyBagRes",
                                F.syncBodyCacheFromLobby
                            )
                        ) or 0
                        local helmetRes = tonumber(
                            F.getDesiredWear(
                                "helmetRes",
                                "helmetRes",
                                "AddOutfitLastLobbyHelmetRes",
                                F.syncBodyCacheFromLobby
                            )
                        ) or 0
                        if bagRes > 0 then
                            _G.BackpackSkin = bagRes
                        end
                        if helmetRes > 0 then
                            _G.HelmetSkin = helmetRes
                        end
                    end)

                    pcall(F.applyInitialEquipmentAvatar)
                    pcall(F.applyInitialConsumableAvatar)
                    pcall(F.hookArmorInventoryAvatar)
                    pcall(F.hookGrenadeAvatarLookup)

                    if not Backpack.ItemListNet or not Backpack.ItemListNet.IncArray then
                        return
                    end

                    local BagArray = Backpack.ItemListNet.IncArray
                    local ItemCount = BagArray:Num()
                    if ItemCount <= 0 or ItemCount > 500 then
                        return
                    end

                    local fpFirst, fpLast = 0, 0
                    pcall(function()
                        local a = BagArray:Get(0)
                        fpFirst = a
                                and a.Unit
                                and a.Unit.DefineID
                                and tonumber(a.Unit.DefineID.TypeSpecificID)
                            or 0
                        if ItemCount > 1 then
                            local b = BagArray:Get(ItemCount - 1)
                            fpLast = b
                                    and b.Unit
                                    and b.Unit.DefineID
                                    and tonumber(b.Unit.DefineID.TypeSpecificID)
                                or 0
                        end
                    end)
                    local fp = string.format(
                        "%d:%d:%d:%s:%s",
                        ItemCount,
                        fpFirst,
                        fpLast,
                        tostring(_G.BackpackSkin or 0),
                        tostring(_G.HelmetSkin or 0)
                    )
                    local now = os.clock()
                    if
                        _G._NTHUY2004_InvFP == fp
                        and _G._NTHUY2004_InvSynced
                        and _G._NTHUY2004_InvSyncAt
                        and (now - _G._NTHUY2004_InvSyncAt) < 12.0
                    then
                        return
                    end

                    local bNeedRefreshBag = false
                    local EBattleItemAdditionalDataType = nil
                    pcall(function()
                        EBattleItemAdditionalDataType = import("EBattleItemAdditionalDataType")
                    end)
                    local EDataType_WeaponAvatar = (
                        EBattleItemAdditionalDataType and EBattleItemAdditionalDataType.WeaponAvatar
                    ) or 7

                    local function resolveInvSkin(currentID)
                        currentID = tonumber(currentID) or 0
                        if currentID <= 0 then
                            return 0
                        end
                        local armorSkin = F.resolveInvArmorSkinID(currentID)
                        if armorSkin and armorSkin > 0 then
                            return armorSkin
                        end

                        if GRENADE_FIELD_BY_BASE[currentID] then
                            local g = F.getCachedGrenadeSkin(currentID)
                            if g and g > 0 then
                                return g
                            end
                        end

                        if F.isGrenadeSkinRes(currentID) then
                            return currentID
                        end

                        local skin = F.getMatchWeaponSkin(currentID)
                        if skin and skin > 0 then
                            return tonumber(skin) or 0
                        end
                        if F.resolveWeaponTypeID then
                            local typeId = F.resolveWeaponTypeID(currentID)
                            if typeId and typeId > 0 and typeId ~= currentID then
                                skin = F.getMatchWeaponSkin(typeId)
                                if skin and skin > 0 then
                                    return tonumber(skin) or 0
                                end
                            end
                        end
                        if F.get_skin_id then
                            local sid = tonumber(F.get_skin_id(currentID, currentID)) or 0
                            if sid > 0 and sid ~= currentID then
                                return sid
                            end
                        end
                        return 0
                    end

                    local function writeWeaponAvatar(AdditionalData, NewSkinID)
                        if not AdditionalData then
                            return false
                        end
                        local bFoundAvatar = false
                        local dataCount = 0
                        pcall(function()
                            dataCount = AdditionalData:Num()
                        end)
                        local changed = false

                        for k = 0, dataCount - 1 do
                            local Data = AdditionalData:Get(k)
                            if Data and Data.EDataType == EDataType_WeaponAvatar then
                                if Data.IntData ~= NewSkinID then
                                    Data.IntData = NewSkinID
                                    AdditionalData:Set(k, Data)
                                    changed = true
                                end
                                bFoundAvatar = true
                                break
                            end
                        end

                        if not bFoundAvatar and dataCount > 0 then
                            local TD = AdditionalData:Get(0)
                            if TD then
                                TD.EDataType = EDataType_WeaponAvatar
                                TD.IntData = NewSkinID
                                TD.StringData = ""
                                AdditionalData:Add(TD)
                                changed = true
                            end
                        elseif not bFoundAvatar then
                            local okAdd = pcall(function()
                                AdditionalData:Add({
                                    EDataType = EDataType_WeaponAvatar,
                                    IntData = NewSkinID,
                                    StringData = "",
                                })
                            end)
                            if okAdd then
                                changed = true
                            end
                        end
                        return changed
                    end

                    local function patchUnitAdditional(Unit, NewSkinID)
                        if not Unit then
                            return false
                        end
                        local AdditionalData = Unit.AdditionalData
                        if not AdditionalData then
                            pcall(function()
                                AdditionalData = slua.IndexReference(Unit, "AdditionalData")
                            end)
                        end
                        return writeWeaponAvatar(AdditionalData, NewSkinID)
                    end

                    for j = 0, ItemCount - 1 do
                        local Item = BagArray:Get(j)
                        if Item and Item.Unit and Item.Unit.DefineID then
                            local CurrentID = Item.Unit.DefineID.TypeSpecificID
                            local NewSkinID = resolveInvSkin(CurrentID)
                            if NewSkinID > 0 then
                                if patchUnitAdditional(Item.Unit, NewSkinID) then
                                    BagArray:Set(j, Item)
                                    bNeedRefreshBag = true
                                end
                            end
                        end
                    end

                    pcall(function()
                        local BackpackUtils = import("BackpackUtils")
                        local arr = BackpackUtils.GetEuqippedArmorInBackpack(Backpack)
                        if not arr then
                            return
                        end
                        for _, BattleItemData in pairs(arr) do
                            local DefineID = BattleItemData
                                and (
                                    slua.IndexReference(BattleItemData, "DefineID") or BattleItemData.DefineID
                                )
                            local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                            local NewSkinID = resolveInvSkin(tid)
                            if NewSkinID > 0 and patchUnitAdditional(BattleItemData, NewSkinID) then
                                bNeedRefreshBag = true
                            end
                        end
                    end)

                    if bNeedRefreshBag then
                        pcall(function()
                            if type(Backpack.OnRep_ItemListNet) == "function" then
                                Backpack:OnRep_ItemListNet()
                            elseif type(Backpack.OnRep_ItemListNet) == "userdata" then
                                Backpack.OnRep_ItemListNet()
                            end
                        end)
                    end

                    _G._NTHUY2004_InvFP = fp
                    _G._NTHUY2004_InvSynced = true
                    _G._NTHUY2004_InvSyncAt = now
                end
                _G.Inventure_BangJO = _G.Inventure_NTHUY2004

                function _G.InventureInit()
                    if
                        not _G.NTHUY2004Config
                        or not _G.NTHUY2004Config.ModSkin
                        or not _G.NTHUY2004Config.InventureNTHUY2004
                    then
                        _G._NTHUY2004_InvSynced = false
                        return
                    end

                    local now = os.clock()
                    if
                        _G._NTHUY2004_InvInitAt
                        and (now - _G._NTHUY2004_InvInitAt) < 6.0
                        and _G._NTHUY2004_InvSynced
                    then
                        return
                    end
                    _G._NTHUY2004_InvInitAt = now
                    pcall(F.hookArmorInventoryAvatar)
                    pcall(F.applyInitialEquipmentAvatar)
                    pcall(function()
                        local PlayerController = slua_GameFrontendHUD
                            and slua_GameFrontendHUD:GetPlayerController()
                        if not PlayerController or not slua.isValid(PlayerController) then
                            return
                        end
                        local BC = (
                            PlayerController.GetBackpackComponent and PlayerController:GetBackpackComponent()
                        )
                            or (
                                PlayerController.GetBackPackComponent
                                and PlayerController:GetBackPackComponent()
                            )
                        if BC and slua.isValid(BC) then
                            _G.Inventure_NTHUY2004(BC)
                        end
                    end)
                end

                function F.removeRoleWearBySubType(st, filterFn)
                    st = tonumber(st)
                    if not st then
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local AvatarData = require("client.logic.data.AvatarData")
                    for _, ins in pairs(AvatarData.GetRoleWear()) do
                        ins = tonumber(ins)
                        if ins and ins > 0 then
                            local d = wd:GetHallDepotItemDataByInsID(ins)
                            if d and tonumber(d.itemSubType) == st then
                                local res = tonumber(d.resID)
                                if not filterFn or filterFn(res, d) then
                                    AvatarData.RemoveRoleWearDataByValue(ins)
                                end
                            end
                        end
                    end
                end

                function F.syncFashionBagRolewear()
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        fbd:SaveRolewearToFashionBag(fbd:GetFashionBagUseIndex())
                    end)
                end

                local _ticker
                pcall(function()
                    _ticker = require("common.time_ticker")
                end)
                function F.later(sec, fn)
                    if _G.SetTimer then
                        pcall(_G.SetTimer, sec, fn)
                        return
                    end
                    if _ticker and _ticker.AddTimer then
                        pcall(_ticker.AddTimer, sec, fn)
                    end
                end

                function F.getPC()
                    if slua_GameFrontendHUD then
                        local pc = slua_GameFrontendHUD:GetPlayerController()
                        if slua.isValid(pc) then
                            return pc
                        end
                    end
                    local ok, gd = pcall(require, "GameLua.GameCore.Data.GameplayData")
                    if ok and gd then
                        local pc = gd.GetPlayerController()
                        if slua.isValid(pc) then
                            return pc
                        end
                    end
                    return nil
                end

                function F.syncVehicleSlotsToDataMgr()
                    local cch = F.cache()
                    DataMgr.VehicleSlotList = DataMgr.VehicleSlotList or {}
                    for subType, slots in pairs(cch.vehicleSlots or {}) do
                        local arr = DataMgr.VehicleSlotList[subType]
                        if not arr then
                            arr = {}
                            DataMgr.VehicleSlotList[subType] = arr
                        end
                        for k in pairs(arr) do
                            arr[k] = nil
                        end
                        for idx, e in pairs(slots or {}) do
                            if e and tonumber(e.insID) and tonumber(e.insID) > 0 then
                                arr[tonumber(idx)] = tonumber(e.insID)
                            end
                        end
                    end
                end

                function F.mergeInjectedIntoVehicleSlotList(serverList)
                    serverList = serverList or {}
                    local cch = F.cache()
                    for subType, slots in pairs(cch.vehicleSlots or {}) do
                        subType = tonumber(subType)
                        if subType and type(slots) == "table" then
                            local arr = serverList[subType]
                            if not arr then
                                arr = {}
                                serverList[subType] = arr
                            end
                            for idx, e in pairs(slots) do
                                idx = tonumber(idx)
                                local insID = e and tonumber(e.insID)
                                if idx and insID and insID > 0 and F.isInjectedIns(insID) then
                                    arr[idx] = insID
                                end
                            end
                        end
                    end
                    local cfg = PERSIST.configVehicleSlots
                    if cfg then
                        for subType, slotMap in pairs(cfg) do
                            subType = tonumber(subType)
                            if subType and type(slotMap) == "table" then
                                local arr = serverList[subType]
                                if not arr then
                                    arr = {}
                                    serverList[subType] = arr
                                end
                                for idx, res in pairs(slotMap) do
                                    idx, res = tonumber(idx), tonumber(res)
                                    local ins = res and R.resToIns[res]
                                    if idx and ins and F.isInjectedIns(ins) then
                                        arr[idx] = ins
                                    end
                                end
                            end
                        end
                    end
                    return serverList
                end

                function F.applyVehicleSlotsFromConfigMap(slotMap)
                    if not slotMap or not next(slotMap) then
                        return false
                    end
                    local cch = F.cache()
                    cch.vehicleSlots = cch.vehicleSlots or {}
                    local any = false
                    local normalized = {}
                    for subType, slots in pairs(slotMap) do
                        subType = tonumber(subType)
                        if subType and type(slots) == "table" then
                            for idx, res in pairs(slots) do
                                idx, res = tonumber(idx), tonumber(res)
                                local ins = res and R.resToIns[res]
                                if idx and ins and res then
                                    local st = F.vehicleSlotSubType(res) or subType
                                    normalized[st] = normalized[st] or {}
                                    normalized[st][idx] = { resID = res, insID = ins }
                                    any = true
                                end
                            end
                        end
                    end
                    if any then
                        for st, slots in pairs(normalized) do
                            cch.vehicleSlots[st] = cch.vehicleSlots[st] or {}
                            for idx, e in pairs(slots) do
                                cch.vehicleSlots[st][idx] = e
                            end
                        end

                        local fixed = {}
                        for st, slots in pairs(normalized) do
                            fixed[st] = {}
                            for idx, e in pairs(slots) do
                                fixed[st][idx] = e.resID
                            end
                        end
                        PERSIST.configVehicleSlots = fixed
                        F.persistMarkDirty()
                    end
                    return any
                end

                function F.notifyVehicleSlotUI()
                    pcall(function()
                        local WRH = require("client.network.Protocol.WardrobeNewHandler")
                        WRH.on_depot_modify_combat_vehicle_rsp(0, DataMgr.VehicleSlotList or {})
                    end)
                end

                function F.mergeInjectedVehicleSkinTable(serverTable)
                    serverTable = serverTable or {}
                    local cfg = PERSIST.configVehicleSlots
                    if not cfg then
                        return serverTable
                    end
                    for subType, slotMap in pairs(cfg) do
                        subType = tonumber(subType)
                        if subType and type(slotMap) == "table" then
                            local res = tonumber(slotMap[1] or slotMap["1"])
                            local ins = res and R.resToIns[res]
                            if ins and F.isInjectedIns(ins) then
                                serverTable[subType] = ins
                            end
                        end
                    end
                    local cch = F.cache()
                    for subType, slots in pairs(cch.vehicleSlots or {}) do
                        subType = tonumber(subType)
                        local e = slots and (slots[1] or slots["1"])
                        local insID = e and tonumber(e.insID)
                        if subType and insID and insID > 0 and F.isInjectedIns(insID) then
                            serverTable[subType] = insID
                        end
                    end
                    return serverTable
                end

                function F.equipVehicleTypesFromConfig(slotMap)
                    slotMap = slotMap or PERSIST.configVehicleSlots
                    if not slotMap or not next(slotMap) then
                        return false
                    end
                    DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
                    local subTypes = {}
                    for st in pairs(slotMap) do
                        local n = tonumber(st)
                        if n then
                            subTypes[#subTypes + 1] = n
                        end
                    end
                    table.sort(subTypes)
                    local any, lobbyRes, lobbyIns = false, nil, nil
                    for _, subType in ipairs(subTypes) do
                        local slots = slotMap[subType] or slotMap[tostring(subType)]
                        if type(slots) == "table" then
                            local res = tonumber(slots[1] or slots["1"])
                            local ins = res and R.resToIns[res]
                            if ins and F.isInjectedIns(ins) then
                                DataMgr.vehicleSkinInsIDTable[subType] = ins
                                any = true
                                if not lobbyIns then
                                    lobbyRes, lobbyIns = res, ins
                                end
                            end
                        end
                    end
                    if any then
                        pcall(function()
                            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                            TabSurveillance.VehicleChange()
                        end)
                    end
                    return any, lobbyRes, lobbyIns
                end

                function F.applyLobbyVehicleDisplay(resID, insID, showVehicle)
                    insID = tonumber(insID)
                    resID = tonumber(resID)
                    if not insID or insID <= 0 then
                        return
                    end
                    _G.AddOutfitApplyingConfig = true
                    pcall(function()
                        DataMgr.vst_skin = insID
                    end)
                    pcall(function()
                        local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                        HallThemeUtils.ProcPutOnVehicle(
                            { res_id = resID, instid = insID },
                            showVehicle ~= false
                        )
                    end)
                    pcall(F.applyVehicleSkinsToPC)
                    _G.AddOutfitApplyingConfig = false
                end

                function F.setLobbyVehicleManual(subType, resID, insID)
                    insID = tonumber(insID)
                    resID = tonumber(resID)
                    subType = tonumber(subType)
                    if not insID then
                        return
                    end
                    if F.isChassisLightId(resID) or subType == CHASSIS_LIGHT_SUB then
                        return
                    end
                    if resID and not F.isVehicleRes(resID) then
                        return
                    end
                    if not F.isInjectedIns(insID) and not F.isVehicleRes(resID) then
                        return
                    end
                    if not resID then
                        resID = R.insToRes[insID]
                    end
                    if not subType and resID then
                        subType = tonumber(F.vehicleSlotSubType(resID) or F.vehicleSubType(resID))
                    end
                    _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or {}
                    _G.AddOutfitLobbyVeh.manual = true
                    _G.AddOutfitLobbyVeh.subType = subType
                    _G.AddOutfitLobbyVeh.resID = resID
                    _G.AddOutfitLobbyVeh.insID = insID
                    PERSIST.lobbyVehicleSubType = subType
                    PERSIST.lobbyVehicleIns = insID
                    PERSIST.lobbyVehicleResID = resID
                    F.rememberVehicleSkinMap(resID, insID)
                    F.persistMarkDirty()
                end

                function F.resolveLobbyVehicle(slotMap)
                    slotMap = slotMap or PERSIST.configVehicleSlots
                    local L = _G.AddOutfitLobbyVeh or {}
                    local st = tonumber(PERSIST.lobbyVehicleSubType) or tonumber(L.subType)
                    local res = tonumber(PERSIST.lobbyVehicleResID) or tonumber(L.resID)
                    if res and res > 0 then
                        local ins = R.resToIns[res]
                        if ins then
                            if not st then
                                st = tonumber(F.vehicleSubType(res))
                            end
                            return res, ins, st
                        end
                    end
                    local ins = tonumber(PERSIST.lobbyVehicleIns) or tonumber(L.insID)
                    if ins and F.isInjectedIns(ins) then
                        res = R.insToRes[ins] or res
                        if not st and res then
                            st = tonumber(F.vehicleSubType(res))
                        end
                        return res, ins, st
                    end
                    if st and slotMap then
                        local slots = slotMap[st] or slotMap[tostring(st)]
                        local res = slots and tonumber(slots[1] or slots["1"])
                        ins = res and R.resToIns[res]
                        if ins then
                            return res, ins, st
                        end
                    end
                    local subTypes = {}
                    for s in pairs(slotMap or {}) do
                        local n = tonumber(s)
                        if n then
                            subTypes[#subTypes + 1] = n
                        end
                    end
                    table.sort(subTypes)
                    if subTypes[1] then
                        st = subTypes[1]
                        local slots = slotMap[st] or slotMap[tostring(st)]
                        local res = slots and tonumber(slots[1] or slots["1"])
                        ins = res and R.resToIns[res]
                        if ins then
                            return res, ins, st
                        end
                    end
                    return nil, nil, nil
                end

                function F.syncLobbyVehicleResFromIns()
                    if PERSIST.lobbyVehicleResID and PERSIST.lobbyVehicleResID > 0 then
                        return
                    end
                    local ins = tonumber(PERSIST.lobbyVehicleIns)
                    if ins and R.insToRes[ins] then
                        PERSIST.lobbyVehicleResID = R.insToRes[ins]
                        F.persistMarkDirty()
                    end
                end

                function F.hasExplicitLobbyVehicle()
                    local res = tonumber(PERSIST.lobbyVehicleResID)
                    local st = tonumber(PERSIST.lobbyVehicleSubType)
                    if F.isChassisLightId(res) or st == CHASSIS_LIGHT_SUB then
                        return false
                    end
                    if res and res > 0 and not F.isVehicleRes(res) then
                        return false
                    end
                    if res and res > 0 then
                        return true
                    end
                    if (tonumber(PERSIST.lobbyVehicleIns) or 0) > 0 then
                        return true
                    end
                    local L = _G.AddOutfitLobbyVeh
                    if L and L.manual and ((tonumber(L.resID) or 0) > 0 or (tonumber(L.insID) or 0) > 0) then
                        return true
                    end
                    return false
                end

                function F.shouldApplyLobbyFromConfig(silent)
                    if not F.hasExplicitLobbyVehicle() then
                        return false
                    end
                    local _, lobbyIns = F.resolveLobbyVehicle(PERSIST.configVehicleSlots)
                    if not lobbyIns then
                        return false
                    end
                    local cur = tonumber(DataMgr.vst_skin)
                    if cur == lobbyIns then
                        return false
                    end
                    return true
                end

                function F.reapplyVehicleSlotsFromConfig(silent)
                    local slotMap = PERSIST.configVehicleSlots
                    if not slotMap or not next(slotMap) then
                        return false
                    end
                    if not F.applyVehicleSlotsFromConfigMap(slotMap) then
                        return false
                    end
                    F.syncVehicleSlotsToDataMgr()
                    F.notifyVehicleSlotUI()
                    F.equipVehicleTypesFromConfig(slotMap)
                    if F.shouldApplyLobbyFromConfig(silent) then
                        local lobbyRes, lobbyIns = F.resolveLobbyVehicle(slotMap)
                        if lobbyIns then
                            F.applyLobbyVehicleDisplay(lobbyRes, lobbyIns, not silent)
                        elseif not silent then
                            pcall(F.applyVehicleSkinsToPC)
                            F.perfInvalidateLobby()
                        end
                    end
                    return true
                end

                function F.applyHallThemeDisplay(resID, insID)
                    insID = tonumber(insID)
                    resID = tonumber(resID)
                    if not insID or not resID then
                        return false
                    end
                    if not F.isInjectedIns(insID) then
                        return false
                    end
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return false
                    end
                    _G.AddOutfitApplyingTheme = true
                    pcall(function()
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        HT.ProcPutOnHallTheme({ res_id = resID, instid = insID }, nil)
                    end)
                    _G.AddOutfitApplyingTheme = false
                    local cch = F.cache()
                    cch.hallThemeRes, cch.hallThemeIns = resID, insID
                    return true
                end

                function F.setHallThemeManual(resID, insID)
                    insID = tonumber(insID)
                    resID = tonumber(resID)
                    if not insID or not F.isInjectedIns(insID) then
                        return
                    end
                    if not resID then
                        resID = R.insToRes[insID]
                    end
                    _G.AddOutfitLobbyTheme = _G.AddOutfitLobbyTheme or {}
                    _G.AddOutfitLobbyTheme.manual = true
                    _G.AddOutfitLobbyTheme.resID = resID
                    _G.AddOutfitLobbyTheme.insID = insID
                    PERSIST.hallThemeResID = resID
                    PERSIST.hallThemeIns = insID
                    local cch = F.cache()
                    cch.hallThemeRes, cch.hallThemeIns = resID, insID
                    F.persistMarkDirty()
                end

                function F.resolveHallTheme()
                    local L = _G.AddOutfitLobbyTheme or {}
                    local res = tonumber(PERSIST.hallThemeResID) or tonumber(L.resID)
                    if res and R.resToIns[res] then
                        return res, R.resToIns[res]
                    end
                    local ins = tonumber(PERSIST.hallThemeIns) or tonumber(L.insID)
                    if ins and F.isInjectedIns(ins) then
                        return R.insToRes[ins], ins
                    end
                    return nil, nil
                end

                function F.shouldApplyHallThemeFromConfig(silent)
                    local _, ins = F.resolveHallTheme()
                    if not ins then
                        return false
                    end
                    local cur = nil
                    pcall(function()
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        cur = tonumber(HT.GetThemeInstId())
                    end)
                    if cur == ins then
                        return false
                    end
                    if _G.AddOutfitLobbyTheme and _G.AddOutfitLobbyTheme.manual then
                        return true
                    end
                    if silent and cur and cur > 0 and F.isInjectedIns(cur) then
                        return false
                    end
                    return true
                end

                function F.putOnHallTheme(insID)
                    insID = tonumber(insID)
                    if not insID or not F.isInjectedIns(insID) then
                        return false
                    end
                    local resID = R.insToRes[insID]
                    if F.applyHallThemeDisplay(resID, insID) then
                        F.setHallThemeManual(resID, insID)
                        return true
                    end
                    return false
                end

                function F.reapplyHallThemeFromConfig(silent)
                    if not F.shouldApplyHallThemeFromConfig(silent) then
                        return false
                    end
                    local res, ins = F.resolveHallTheme()
                    if not res or not ins then
                        return false
                    end
                    return F.applyHallThemeDisplay(res, ins)
                end

                function F.syncVehicleCacheFromDataMgr()
                    local cch = F.cache()
                    cch.vehicleSlots = cch.vehicleSlots or {}
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    for subType, slots in pairs(DataMgr.VehicleSlotList or {}) do
                        subType = tonumber(subType)
                        if subType and type(slots) == "table" then
                            cch.vehicleSlots[subType] = cch.vehicleSlots[subType] or {}
                            for idx, insID in pairs(slots) do
                                idx, insID = tonumber(idx), tonumber(insID)
                                if idx and insID and insID > 0 then
                                    local res = R.insToRes[insID]
                                    if not res then
                                        pcall(function()
                                            local d = wd:GetHallDepotItemDataByInsID(insID)
                                            res = d and tonumber(d.resID)
                                        end)
                                    end
                                    if res and res > 0 then
                                        cch.vehicleSlots[subType][idx] = { resID = res, insID = insID }
                                    end
                                end
                            end
                        end
                    end
                end

                function F.vehicleSubType(resID)
                    local c = F.cfg(resID)
                    return c and (c.ItemSubType or c.itemSubType)
                end

                function F.vehicleSlotSubType(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return nil
                    end
                    if F.isChassisLightId and F.isChassisLightId(resID) then
                        return nil
                    end

                    local function validSt(st)
                        st = tonumber(st)
                        if not st or st == CHASSIS_LIGHT_SUB then
                            return nil
                        end
                        if st >= 2200 and st < 2300 then
                            return nil
                        end
                        if (st >= 900 and st < 2000) or (st >= 9100 and st < 10000) or st == 1101 then
                            return st
                        end
                        return nil
                    end
                    if resID >= 12200000 and resID < 12300000 then
                        return nil
                    end

                    local orig = F.vehicleOriginalID and F.vehicleOriginalID(resID) or resID
                    local st = validSt(F.vehicleSubType(orig))
                    if st then
                        return st
                    end

                    pcall(function()
                        local t = DataMgr and DataMgr.defaultVehicleSkinResIDTable
                        if type(t) ~= "table" then
                            return
                        end
                        for sub, defRes in pairs(t) do
                            defRes = tonumber(defRes)
                            if defRes and (defRes == orig or defRes == resID) then
                                st = validSt(sub)
                                if st then
                                    return
                                end
                            end
                        end
                    end)
                    if st then
                        return st
                    end

                    pcall(function()
                        local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
                        local t = wm and wm.DefaultVehiclesId
                        if type(t) ~= "table" then
                            return
                        end
                        for sub, defRes in pairs(t) do
                            defRes = tonumber(defRes)
                            if defRes and (defRes == orig or defRes == resID) then
                                st = validSt(sub)
                                if st then
                                    return
                                end
                            end
                        end
                    end)
                    if st then
                        return st
                    end

                    st = validSt(F.vehicleSubType(resID))
                    if st then
                        return st
                    end

                    pcall(function()
                        local UAvatarUtils = import("AvatarUtils")
                        local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(resID))
                        if not shape or shape < 0 then
                            return
                        end
                        local function matchTable(t)
                            if type(t) ~= "table" then
                                return
                            end
                            for sub, defRes in pairs(t) do
                                defRes = tonumber(defRes)
                                if defRes and defRes > 0 then
                                    local s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defRes))
                                    if s == shape then
                                        st = validSt(sub)
                                        if st then
                                            return true
                                        end
                                    end
                                end
                            end
                        end
                        if matchTable(DataMgr and DataMgr.defaultVehicleSkinResIDTable) then
                            return
                        end
                        local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
                        matchTable(wm and wm.DefaultVehiclesId)
                    end)
                    return st
                end

                function F.tabsEqual(a, b)
                    if a == b then
                        return true
                    end
                    if a == nil or b == nil then
                        return false
                    end
                    local na, nb = tonumber(a), tonumber(b)
                    if na and nb then
                        return na == nb
                    end
                    return tostring(a) == tostring(b)
                end

                function F.vehicleWardrobeTab(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return nil
                    end
                    local function fromCfg(id)
                        local c = F.cfg(id)
                        if not c then
                            return nil
                        end
                        local t = c.WardrobeTab
                        if t == nil or t == 0 or t == "" then
                            return nil
                        end
                        return t
                    end
                    local tab = fromCfg(resID)
                    if tab ~= nil then
                        return tab
                    end
                    local orig = F.vehicleOriginalID(resID) or resID
                    if tonumber(orig) ~= resID then
                        tab = fromCfg(orig)
                        if tab ~= nil then
                            return tab
                        end
                    end
                    local st = tonumber(F.vehicleSlotSubType(resID) or F.vehicleSubType(resID))
                    if st then
                        pcall(function()
                            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                            local wt = TabSurveillance.GetWardrobeTabByItemSubType(st)
                            if wt ~= nil and wt ~= "" then
                                tab = wt
                            end
                        end)
                        if tab ~= nil then
                            return tab
                        end
                        pcall(function()
                            local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
                            local def = wm and wm.DefaultVehiclesId and wm.DefaultVehiclesId[st]
                            if def then
                                tab = fromCfg(tonumber(def))
                            end
                        end)
                    end
                    return tab
                end

                function F.fixInjectedVehicleDepotTabs(entity)
                    entity = entity or F.getEntity()
                    if not entity or not entity._data then
                        return
                    end
                    for i = 1, (entity._DataCount or #entity._data) do
                        local d = entity._data[i]
                        if d then
                            local res = tonumber(d.resID or d.res_id)
                            if res and F.isInjectedRes(res) and F.isVehicleRes(res) then
                                local c = F.cfg(res)
                                local mainCfg = tonumber(c and c.WardrobeMainTab)

                                if mainCfg == PAGE_PARACHUTE then
                                    d.mainTabType = PAGE_PARACHUTE
                                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(res)
                                    if tab and tab ~= 0 and tab ~= "" then
                                        d.subTabType = tab
                                    end
                                else
                                    local tab = F.vehicleWardrobeTab(res)
                                    if tab ~= nil and tab ~= 0 and tab ~= "" then
                                        d.subTabType = tab
                                        d.mainTabType = PAGE_VEHICLE
                                    end
                                    local st = F.vehicleSlotSubType(res)
                                    if st then
                                        d.itemSubType = st
                                    end
                                end
                            end
                        end
                    end
                end

                function F.fixInjectedEmoteDepotTabs(entity)
                    entity = entity or F.getEntity()
                    if not entity or not entity._data then
                        return
                    end
                    local MOTION_TAB = 21
                    for i = 1, (entity._DataCount or #entity._data) do
                        local d = entity._data[i]
                        if d then
                            local res = tonumber(d.resID or d.res_id)
                            if res and F.isInjectedRes(res) and F.isEmoteRes(res) then
                                local c = F.cfg(res)
                                local main = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                                local tab = c and c.WardrobeTab
                                if tab == nil or tab == 0 or tab == "" then
                                    tab = F.wardrobeTab(res)
                                end
                                if tab == nil or tab == 0 or tab == "" then
                                    tab = MOTION_TAB
                                end
                                d.mainTabType = main
                                d.subTabType = tab
                                if d.resID == nil and d.res_id ~= nil then
                                    d.resID = res
                                end
                                if c and c.ItemSubType then
                                    d.itemSubType = c.ItemSubType
                                end
                                if c and c.ItemType then
                                    d.itemType = c.ItemType
                                end
                                d.expire_ts = 0
                                d.expireTS = 0
                            end
                        end
                    end
                end

                function F.fixInjectedParachuteDepotTabs(entity)
                    entity = entity or F.getEntity()
                    if not entity or not entity._data then
                        return
                    end
                    for i = 1, (entity._DataCount or #entity._data) do
                        local d = entity._data[i]
                        if d then
                            local res = tonumber(d.resID or d.res_id)
                            if
                                res
                                and F.isInjectedRes(res)
                                and (F.isParachuteRes(res) or F.isGlideRes(res))
                            then
                                local c = F.cfg(res)
                                d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                                local tab = (c and c.WardrobeTab) or F.wardrobeTab(res)
                                if tab and tab ~= 0 and tab ~= "" then
                                    d.subTabType = tab
                                end
                                if d.resID == nil then
                                    d.resID = res
                                end
                                d.expire_ts = 0
                                d.expireTS = 0
                            end
                        end
                    end
                end
                function F.modifyInjectedVehicleSlot(insID, slotIndex, equip)
                    insID = tonumber(insID)
                    slotIndex = tonumber(slotIndex)
                    if not insID or not slotIndex then
                        return false
                    end
                    local resID = R.insToRes[insID]
                    if not resID and insID >= INS_BASE then
                        pcall(function()
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            resID = d and tonumber(d.resID or d.res_id)
                        end)
                    end
                    if not resID then
                        return false
                    end
                    if not F.isVehicleRes(resID) then
                        return false
                    end
                    local st = F.vehicleSlotSubType(resID)
                    if not st then
                        return false
                    end
                    local cch = F.cache()
                    cch.vehicleSlots = cch.vehicleSlots or {}
                    cch.vehicleSlots[st] = cch.vehicleSlots[st] or {}
                    if equip then
                        for _, slots in pairs(cch.vehicleSlots) do
                            for i, e in pairs(slots) do
                                if e and tonumber(e.insID) == insID then
                                    slots[i] = nil
                                end
                            end
                        end
                        cch.vehicleSlots[st][slotIndex] = { resID = resID, insID = insID }
                        PERSIST.configVehicleSlots = PERSIST.configVehicleSlots or {}
                        PERSIST.configVehicleSlots[st] = PERSIST.configVehicleSlots[st] or {}
                        PERSIST.configVehicleSlots[st][slotIndex] = resID
                    else
                        local e = cch.vehicleSlots[st][slotIndex]
                        if e and tonumber(e.insID) == insID then
                            cch.vehicleSlots[st][slotIndex] = nil
                            if PERSIST.configVehicleSlots and PERSIST.configVehicleSlots[st] then
                                PERSIST.configVehicleSlots[st][slotIndex] = nil
                            end
                        end
                    end
                    F.syncVehicleSlotsToDataMgr()
                    if equip and slotIndex == 1 then
                        DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
                        DataMgr.vehicleSkinInsIDTable[st] = insID
                        pcall(function()
                            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                            TabSurveillance.VehicleChange()
                        end)
                    end
                    F.persistMarkDirty()
                    F.notifyVehicleSlotUI()
                    return true
                end

                function F.buildVstInBattleFromSlots()
                    local vst = {}
                    local function insToRes(insID)
                        insID = tonumber(insID)
                        if not insID or insID <= 0 then
                            return nil
                        end
                        local res = R.insToRes[insID]
                        if res and res > 0 then
                            return res
                        end
                        pcall(function()
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            res = d and tonumber(d.resID)
                        end)
                        if res and res > 0 then
                            return res
                        end
                        if insID >= 1000000 and F.cfg(insID) then
                            return insID
                        end
                        return nil
                    end
                    local function fillFromSlots(subType, slots)
                        subType = tonumber(subType)
                        if not subType or type(slots) ~= "table" then
                            return
                        end
                        local resList = {}
                        for idx = 1, 8 do
                            local val = slots[idx] or slots[tostring(idx)]
                            local res = insToRes(val)
                            if not res and type(val) == "table" then
                                res = tonumber(val.resID or val.res_id)
                            end
                            if res and res > 0 then
                                resList[#resList + 1] = res
                            end
                        end
                        if #resList > 0 then
                            vst[subType] = resList
                        end
                    end
                    for subType, slots in pairs(DataMgr.VehicleSlotList or {}) do
                        fillFromSlots(subType, slots)
                    end
                    if not next(vst) then
                        local cch = F.cache()
                        for subType, slots in pairs(cch.vehicleSlots or {}) do
                            local resList = {}
                            for idx = 1, 8 do
                                local e = slots[idx]
                                local res = e and tonumber(e.resID)
                                if res and res > 0 then
                                    resList[#resList + 1] = res
                                end
                            end
                            if #resList > 0 then
                                vst[tonumber(subType)] = resList
                            end
                        end
                    end
                    if not next(vst) then
                        local bySub = {}
                        for res, _ in pairs(R.resToIns) do
                            res = tonumber(res)
                            local c = F.cfg(res)
                            local st = c and tonumber(F.subType(c))
                            if res and st and st >= 900 then
                                bySub[st] = bySub[st] or {}
                                bySub[st][#bySub[st] + 1] = res
                            end
                        end
                        for st, list in pairs(bySub) do
                            table.sort(list)
                            vst[st] = list
                        end
                    end
                    return vst
                end

                function F.isVehicleSkinAllowed(skinId)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end
                    if F.isInjectedRes(skinId) then
                        return true
                    end
                    for _, list in pairs(F.buildVstInBattleFromSlots()) do
                        for _, res in ipairs(list or {}) do
                            if tonumber(res) == skinId then
                                return true
                            end
                        end
                    end
                    return false
                end
                function F.isSkinInVehiclePCList(skinId)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end
                    local pc = F.getPC()
                    if not slua.isValid(pc) or not pc.VehicleAvatarSkinList then
                        return false
                    end
                    local UAvatarUtils = import("AvatarUtils")
                    local shape = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
                    if shape and shape >= 0 then
                        local entry = pc.VehicleAvatarSkinList:Get(shape)
                        if entry and entry.SkinList then
                            for _, id in pairs(entry.SkinList) do
                                if tonumber(id) == skinId then
                                    return true
                                end
                            end
                        end
                    end
                    return false
                end

                function F.shouldHandleVehicleSkinClick(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    return F.isVehicleSkinAllowed(resID) or F.isSkinInVehiclePCList(resID)
                end

                function F.getMatchVehicle()
                    local found = nil
                    pcall(function()
                        local subs = SubsystemMgr:Get("VehicleControlUISubSystem")
                        if subs and subs.GetVehicleUserComponent then
                            local uuc = subs:GetVehicleUserComponent()
                            if slua.isValid(uuc) and slua.isValid(uuc.Vehicle) then
                                found = uuc.Vehicle
                            end
                        end
                    end)
                    if slua.isValid(found) then
                        return found
                    end
                    local pc = F.getPC()
                    if slua.isValid(pc) and pc.GetPlayerCharacterSafety then
                        local char = pc:GetPlayerCharacterSafety()
                        if slua.isValid(char) then
                            if char.GetCurrentVehicle then
                                local v = char:GetCurrentVehicle()
                                if slua.isValid(v) then
                                    return v
                                end
                            end
                            if char.CurrentVehicle and slua.isValid(char.CurrentVehicle) then
                                return char.CurrentVehicle
                            end
                        end
                    end
                    return nil
                end

                function F.applyClientVehicleSkin(skinId, vehicle, pc)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end
                    pc = pc or F.getPC()
                    vehicle = vehicle or F.getMatchVehicle()
                    if not slua.isValid(vehicle) then
                        return false
                    end

                    local UAvatarUtils = import("AvatarUtils")
                    pcall(function()
                        if slua.isValid(pc) then
                            pc.ShowVehicleSkin = skinId
                            local shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
                            if shapeType and shapeType >= 0 and pc.VehicleAvatarList then
                                pc.VehicleAvatarList:Add(shapeType, skinId)
                            end
                        end
                    end)

                    local applied = false
                    local av = nil
                    pcall(function()
                        if vehicle.GetAvatarComponent then
                            av = vehicle:GetAvatarComponent()
                        end
                        if not slua.isValid(av) then
                            av = vehicle.VehicleAvatarComponent_BP
                        end
                    end)

                    if slua.isValid(av) then
                        pcall(function()
                            if av.bIsLobbyAvatar ~= nil then
                                av.bIsLobbyAvatar = false
                            end
                        end)
                        pcall(function()
                            if av.CanChangeAvatar ~= nil then
                                av.CanChangeAvatar = true
                            end
                        end)
                        pcall(function()
                            if slua.isValid(pc) and av.SetVehicleNetAvatarData then
                                av:SetVehicleNetAvatarData(pc)
                            end
                        end)
                        pcall(function()
                            if av.ChangeItemAvatar then
                                av:ChangeItemAvatar(skinId, false)
                                applied = true
                            elseif av.PreChangeVehicleAvatar then
                                av:PreChangeVehicleAvatar(skinId)
                                applied = true
                            end
                        end)
                        pcall(function()
                            if av.PostChangeItemAvatar then
                                av:PostChangeItemAvatar(false)
                            end
                        end)
                    end

                    pcall(function()
                        local battleCls = import("VehicleAvatarComponentBattleBase")
                        local battleAv = vehicle:GetComponentByClass(battleCls)
                        if slua.isValid(battleAv) then
                            if battleAv.ChangeVehicleAvatar then
                                battleAv:ChangeVehicleAvatar(skinId, false)
                                applied = true
                            end
                            pcall(function()
                                local VehiclePlateLicenseUtil = require(
                                    "GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil"
                                )
                                local uid = pc and pc.PlayerUID or 0
                                local bTire = VehiclePlateLicenseUtil.NeedOpenHighTire(tonumber(uid), skinId)
                                if battleAv.PreChangeHighTireLight then
                                    battleAv:PreChangeHighTireLight(skinId, bTire)
                                end
                            end)
                        end
                    end)

                    pcall(function()
                        if vehicle.ChangeVehicleAvatar and slua.isValid(pc) then
                            vehicle:ChangeVehicleAvatar(pc)
                            applied = true
                        end
                    end)

                    pcall(function()
                        if vehicle.ForceNetUpdate then
                            vehicle:ForceNetUpdate()
                        end
                    end)
                    pcall(function()
                        if slua.isValid(pc) and pc.ForceNetUpdate then
                            pc:ForceNetUpdate()
                        end
                    end)
                    return applied
                end

                function F.getVehicleSkinIds()
                    local out, seen = {}, {}
                    local function add(res)
                        res = tonumber(res)
                        if res and res > 0 and not seen[res] then
                            seen[res] = true
                            out[#out + 1] = res
                        end
                    end
                    for _, list in pairs(F.buildVstInBattleFromSlots()) do
                        for _, res in ipairs(list) do
                            add(res)
                        end
                    end
                    for res in pairs(R.resToIns) do
                        local c = F.cfg(tonumber(res))
                        local st = c and tonumber(F.subType(c))
                        if st and st >= 900 then
                            add(res)
                        end
                    end
                    return out
                end
                function F.buildVehVst(skinIds)
                    local bySub = {}
                    for _, skinId in ipairs(skinIds or {}) do
                        local subType = 961
                        local ok, c = pcall(function()
                            return CDataTable.GetTableData("Item", skinId)
                        end)
                        if ok and c and c.ItemSubType then
                            subType = c.ItemSubType
                        end
                        bySub[subType] = bySub[subType] or {}
                        bySub[subType][#bySub[subType] + 1] = skinId
                    end
                    return bySub
                end

                function F.directInjectVehicleSkinList(pc, skinIds)
                    if not slua.isValid(pc) or not pc.VehicleAvatarSkinList then
                        return
                    end
                    local UAvatarUtils = import("AvatarUtils")
                    for _, skinId in ipairs(skinIds or {}) do
                        local shapeType = nil
                        pcall(function()
                            shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
                        end)
                        if shapeType and shapeType >= 0 then
                            pcall(function()
                                pc.VehicleAvatarList:Add(shapeType, skinId)
                            end)
                            local entry = pc.VehicleAvatarSkinList:Get(shapeType)
                            if entry and entry.SkinList then
                                pcall(function()
                                    entry.SkinList:Add(skinId)
                                end)
                            end
                        end
                    end
                end

                function F.mergeVstIntoPlayerInfo(playerInfo)
                    if not playerInfo then
                        return
                    end
                    F.syncVehicleCacheFromDataMgr()
                    local vst = F.buildVehVst(F.getVehicleSkinIds())
                    if not next(vst) then
                        return
                    end
                    playerInfo.vst_in_battle = playerInfo.vst_in_battle or {}
                    for subType, list in pairs(vst) do
                        playerInfo.vst_in_battle[subType] = list
                    end
                    local first
                    for _, list in pairs(vst) do
                        first = list[1]
                        break
                    end
                    if first and first > 0 then
                        playerInfo.vst_skin = first
                    end
                end

                function F.applyVehicleSkinsToPC(pc)
                    pc = pc or F.getPC()
                    if not slua.isValid(pc) then
                        return false
                    end
                    local skinIds = F.getVehicleSkinIds()
                    if #skinIds == 0 then
                        return false
                    end
                    local vst = F.buildVehVst(skinIds)
                    local avatarList, avatarSkinList = {}, {}
                    for _, skinList in pairs(vst) do
                        local itemArray = {}
                        for _, resid in ipairs(skinList) do
                            if resid and resid > 0 then
                                itemArray[#itemArray + 1] = { ItemTableID = resid, Count = 1 }
                                avatarList[#avatarList + 1] = { ItemTableID = resid, Count = 1 }
                            end
                        end
                        if #itemArray > 0 then
                            avatarSkinList[#avatarSkinList + 1] = { Items = itemArray }
                        end
                    end
                    pcall(function()
                        pc.bEnableFuzzyAvatarOnClient = false
                    end)
                    pcall(function()
                        pc.ShowVehicleSkin = skinIds[1]
                    end)
                    if #avatarList > 0 then
                        pcall(function()
                            pc.InitialVehicleAvatarList = avatarList
                            pc:InitVehicleAvatarList()
                        end)
                    end
                    if #avatarSkinList > 0 then
                        pcall(function()
                            pc.InitialVehicleAvatarSkinList = avatarSkinList
                            pc:InitVehicleAvatarSkinList()
                        end)
                    end
                    F.directInjectVehicleSkinList(pc, skinIds)
                    pcall(function()
                        F.applyVehiclePartDataToPC(pc, skinIds[1])
                    end)
                    return true
                end
                function F.serverChangeVehicleAvatar(skinId, pc)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end
                    pc = pc or F.getPC()
                    if not slua.isValid(pc) then
                        return false
                    end

                    F.applyVehicleSkinsToPC(pc)

                    pcall(function()
                        pc.ShowVehicleSkin = skinId
                        local UAvatarUtils = import("AvatarUtils")
                        local shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
                        if shapeType and shapeType >= 0 and pc.VehicleAvatarList then
                            pc.VehicleAvatarList:Add(shapeType, skinId)
                        end
                        F.directInjectVehicleSkinList(pc, { skinId })
                    end)

                    local ok = false
                    pcall(function()
                        if pc.ServerChangeVehicleAvatar then
                            pc:ServerChangeVehicleAvatar(skinId)
                            ok = true
                        end
                    end)

                    pcall(function()
                        if pc.PlayerState and slua.isValid(pc.PlayerState) then
                            pc.PlayerState.nVst_skin = skinId
                        end
                    end)

                    pcall(function()
                        pc:ForceNetUpdate()
                    end)
                    return ok
                end

                _G.AddOutfitVehSel = _G.AddOutfitVehSel
                    or { override = nil, overrideVehicle = nil, byShape = {} }
                local VEHSEL = _G.AddOutfitVehSel
                _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh
                    or { manual = false, subType = nil, resID = nil, insID = nil }
                local _vehTickLastApply = 0
                local VEH_SWITCH_EFFECT_ID = 7303001

                function F.prepVehicleSwitchEffect(av, vehicle)
                    if not slua.isValid(av) then
                        return
                    end
                    if not F.isInRealMatch() then
                        pcall(function()
                            av.curSwitchEffectId = 0
                        end)
                        return
                    end
                    pcall(function()
                        local effectId = VEH_SWITCH_EFFECT_ID
                        local m = PERSIST.configVehicleMod
                        if m and tonumber(m.switchEffect) and tonumber(m.switchEffect) > 0 then
                            effectId = tonumber(m.switchEffect)
                        else
                            pcall(function()
                                local LVF = ModuleManager.GetModule(
                                    ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                                )
                                if
                                    LVF
                                    and tonumber(LVF.equip_switch_effect)
                                    and tonumber(LVF.equip_switch_effect) > 0
                                then
                                    effectId = tonumber(LVF.equip_switch_effect)
                                end
                            end)
                        end
                        av.curSwitchEffectId = effectId
                        F.requestResourceDownload(effectId)
                        local defaultId = 0
                        pcall(function()
                            defaultId = tonumber(av:GetDefaultAvatarID()) or 0
                        end)
                        local curId = 0
                        if slua.isValid(vehicle) then
                            pcall(function()
                                curId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0
                            end)
                            if curId <= 0 then
                                pcall(function()
                                    curId = tonumber(vehicle.ClientUsedAvatarID) or 0
                                end)
                            end
                        end
                        if curId <= 0 then
                            curId = defaultId
                        end
                        if not av.lastEquipedAvatarId or av.lastEquipedAvatarId <= 0 then
                            av.lastEquipedAvatarId = curId > 0 and curId or defaultId
                        end
                    end)
                end

                function F.getVehiclePartSlots()
                    local brake, canopy = 1, 3
                    pcall(function()
                        local E = import("EVehiclePartSlot")
                        if not E then
                            return
                        end
                        brake = E.BrakeCaliper or E.EVehiclePartSlot__BrakeCaliper or brake
                        canopy = E.Canopy or E.EVehiclePartSlot__Canopy or canopy
                    end)
                    return brake, canopy
                end

                function F.getDesiredMultiSlotPartsForSkin(skinId)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return {}
                    end
                    pcall(F.applyVehicleModPersistToLVF)
                    local m = F.vehicleModPersist and F.vehicleModPersist()
                        or (PERSIST.configVehicleMod or {})
                    local LVF = nil
                    pcall(function()
                        LVF = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                        )
                    end)
                    local SLOT_BRAKE, SLOT_CANOPY = F.getVehiclePartSlots()
                    local brakeMap = F.expandVehicleFeatureMap and F.expandVehicleFeatureMap(m.brakeCaliper)
                        or (m.brakeCaliper or {})
                    local canopyMap = F.expandVehicleFeatureMap and F.expandVehicleFeatureMap(m.canopy)
                        or (m.canopy or {})
                    local function pick(mapPersist, mapLvf)
                        local id = mapPersist and tonumber(mapPersist[skinId])
                        if id and id > 0 then
                            return id
                        end
                        id = mapLvf and tonumber(mapLvf[skinId])
                        if id and id > 0 then
                            return id
                        end
                        local gid = nil
                        pcall(function()
                            local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
                            gid = cfg and tonumber(cfg.vehicle_group_id)
                        end)
                        if not gid then
                            return nil
                        end
                        local function scan(map)
                            if type(map) ~= "table" then
                                return nil
                            end
                            for vid, resid in pairs(map) do
                                vid, resid = tonumber(vid), tonumber(resid)
                                if vid and resid and resid > 0 then
                                    local ok, g2 = pcall(function()
                                        local c = CDataTable.GetTableData("VehicleRefitInfo", vid)
                                        return c and tonumber(c.vehicle_group_id)
                                    end)
                                    if ok and g2 == gid then
                                        return resid
                                    end
                                end
                            end
                            return nil
                        end
                        return scan(mapPersist) or scan(mapLvf)
                    end
                    local brake = pick(brakeMap, LVF and LVF.equip_brake_caliper)
                    local canopy = pick(canopyMap, LVF and LVF.equip_sunroof)
                    local parts = {}
                    if brake then
                        parts[SLOT_BRAKE] = brake
                        parts[1] = brake
                    end
                    if canopy then
                        parts[SLOT_CANOPY] = canopy
                        parts[3] = canopy
                    end
                    return parts
                end

                function F.getDesiredRefitStyleListForSkin(skinId)
                    skinId = tonumber(skinId)
                    if not skinId then
                        return {}
                    end
                    pcall(F.applyVehicleModPersistToVRH)

                    pcall(function()
                        local m = F.vehicleModPersist and F.vehicleModPersist() or PERSIST.configVehicleMod
                        if not m or type(m.refit) ~= "table" or m.refit[skinId] then
                            return
                        end
                        local gid = nil
                        pcall(function()
                            local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
                            gid = cfg and tonumber(cfg.vehicle_group_id)
                        end)
                        if not gid then
                            return
                        end
                        for vid, st in pairs(m.refit) do
                            local g2 = nil
                            pcall(function()
                                local c = CDataTable.GetTableData("VehicleRefitInfo", tonumber(vid))
                                g2 = c and tonumber(c.vehicle_group_id)
                            end)
                            if g2 == gid and type(st) == "table" then
                                local VRH = require("client.network.Protocol.VehicleRefitHandler")
                                if VRH then
                                    VRH.resCarInfoList = VRH.resCarInfoList or {}
                                    VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
                                    VRH.resCarInfoList.car_list[skinId] = VRH.resCarInfoList.car_list[skinId]
                                        or {}
                                    for partId, styleId in pairs(st) do
                                        partId, styleId = tonumber(partId) or partId, tonumber(styleId)
                                        if styleId then
                                            VRH.resCarInfoList.car_list[skinId][partId] = styleId
                                        end
                                    end
                                end
                                break
                            end
                        end
                    end)
                    local list = {}
                    pcall(function()
                        local VRH = require("client.network.Protocol.VehicleRefitHandler")
                        local fromHandler = VRH and VRH.GetCarStyleList and VRH.GetCarStyleList(skinId)
                        if type(fromHandler) == "table" then
                            for _, sid in ipairs(fromHandler) do
                                sid = tonumber(sid)
                                if sid and sid > 0 then
                                    list[#list + 1] = sid
                                end
                            end
                        end
                    end)
                    if #list > 0 then
                        return list
                    end
                    local m = PERSIST.configVehicleMod
                    local styles = m and m.refit and m.refit[skinId]
                    if type(styles) == "table" then
                        for _, sid in pairs(styles) do
                            sid = tonumber(sid)
                            if sid and sid > 0 then
                                list[#list + 1] = sid
                            end
                        end
                    end
                    return list
                end

                function F.getDesiredVehicleModChassisLight(skinId)
                    skinId = tonumber(skinId)
                    if not skinId then
                        return nil
                    end
                    local m = F.vehicleModPersist and F.vehicleModPersist() or PERSIST.configVehicleMod
                    local id = m and m.chassisLight and tonumber(m.chassisLight[skinId])
                    if id and id > 0 then
                        return id
                    end
                    pcall(function()
                        local LVF = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                        )
                        if LVF and LVF.equip_chassis_light then
                            id = tonumber(LVF.equip_chassis_light[skinId])
                        end
                    end)
                    if id and id > 0 then
                        return id
                    end
                    local gid = nil
                    pcall(function()
                        local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
                        gid = cfg and tonumber(cfg.vehicle_group_id)
                    end)
                    if gid and m and type(m.chassisLight) == "table" then
                        for vid, resid in pairs(m.chassisLight) do
                            vid, resid = tonumber(vid), tonumber(resid)
                            if vid and resid and resid > 0 then
                                local g2 = nil
                                pcall(function()
                                    local c = CDataTable.GetTableData("VehicleRefitInfo", vid)
                                    g2 = c and tonumber(c.vehicle_group_id)
                                end)
                                if g2 == gid then
                                    return resid
                                end
                            end
                        end
                    end
                    local map = PERSIST.configChassisLightMap
                    id = map and tonumber(map[skinId])
                    if id and id > 0 then
                        return id
                    end
                    return nil
                end

                function F.applyVehicleModPartsToVehicle(vehicle, skinId)
                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then
                        return false
                    end
                    if not slua.isValid(vehicle) then
                        return false
                    end
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        pcall(function()
                            skinId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId())
                        end)
                    end
                    if not skinId or skinId <= 0 then
                        pcall(function()
                            skinId = tonumber(vehicle.ClientUsedAvatarID)
                        end)
                    end
                    if not skinId or skinId <= 0 then
                        return false
                    end

                    local parts = F.getDesiredMultiSlotPartsForSkin(skinId)
                    local av = F.getVehicleAvatarComp(vehicle)
                    local applied = false
                    if next(parts) and slua.isValid(av) then
                        pcall(function()
                            av.bEnableMultiSlot = true
                        end)
                        pcall(function()
                            if av.SetLobbyMultiSlotEquipData then
                                av:SetLobbyMultiSlotEquipData(parts)
                            end
                        end)
                        pcall(function()
                            if av.SetNetMultiSlotData then
                                av:SetNetMultiSlotData(parts)
                                applied = true
                            end
                        end)
                        pcall(function()
                            if av.EquipSlots then
                                av:EquipSlots(parts, false)
                                applied = true
                            end
                        end)
                        pcall(function()
                            if av.ApplyMultiSlotMeshes then
                                av:ApplyMultiSlotMeshes()
                            end
                        end)
                    end
                    local SLOT_BRAKE, SLOT_CANOPY = F.getVehiclePartSlots()
                    pcall(function()
                        local bid = parts[SLOT_BRAKE] or parts[1]
                        if vehicle.SetBrakeCaliperShowData and bid then
                            vehicle:SetBrakeCaliperShowData(bid)
                            applied = true
                        end
                    end)
                    pcall(function()
                        local cid = parts[SLOT_CANOPY] or parts[3]
                        if vehicle.SetCanopyShowData and cid then
                            vehicle:SetCanopyShowData(cid)
                            applied = true
                        end
                    end)
                    pcall(function()
                        local lightId = F.getDesiredVehicleModChassisLight(skinId)
                        if lightId and lightId > 0 then
                            F.applyVehicleChassisLight(vehicle, skinId, lightId)
                            applied = true
                        end
                    end)
                    return applied
                end

                function F.scheduleVehicleModPartsApply(vehicle, skinId)
                    skinId = tonumber(skinId)
                    local vref = slua.isValid(vehicle) and vehicle or nil
                    local function try()
                        local v = slua.isValid(vref) and vref or F.getCurrentVehicleForSkin()
                        if not slua.isValid(v) then
                            return
                        end
                        local sid = skinId
                        if not sid or sid <= 0 then
                            pcall(function()
                                sid = tonumber(v.GetAvatarId and v:GetAvatarId())
                            end)
                        end
                        F.applyVehicleModPartsToVehicle(v, sid)
                    end

                    F.later(0.8, try)
                end

                function F.isParachuteRes(resID)
                    return F.subType(F.cfg(tonumber(resID))) == PARACHUTE_SUB
                end

                function F.isGlideRes(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    local st = F.subType(F.cfg(resID))
                    if GLIDER_SUBS[st] then
                        return true
                    end
                    local ok, r = pcall(function()
                        local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
                        if MDH.IsGlideByItemID and MDH.IsGlideByItemID(resID) then
                            return true
                        end
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        return wd.IsGlideType(st)
                    end)
                    return ok and r == true
                end

                function F.vehicleOriginalID(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return nil
                    end
                    local original = nil
                    pcall(function()
                        local m = CDataTable
                            and CDataTable.GetTableData
                            and CDataTable.GetTableData("VehiclePlaneSkinMapping", resID)
                        original = tonumber(m and (m.OrginalID or m.OriginalID))
                    end)
                    if original and original > 0 then
                        return original
                    end
                    local st = tonumber(F.vehicleSubType(resID))
                    if st and st >= 900 and st < 7000 then
                        local def = nil
                        pcall(function()
                            def = tonumber(
                                DataMgr.defaultVehicleSkinResIDTable
                                    and DataMgr.defaultVehicleSkinResIDTable[st]
                            )
                        end)
                        if def and def > 0 then
                            return def
                        end
                        pcall(function()
                            local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
                            def = tonumber(wm and wm.DefaultVehiclesId and wm.DefaultVehiclesId[st])
                        end)
                        if def and def > 0 then
                            return def
                        end
                    end
                    return resID
                end

                function F.rememberVehicleSkinMap(resID, insID)
                    resID = tonumber(resID)
                    if not resID or not F.isVehicleRes(resID) then
                        return
                    end
                    _G.AddOutfitLastVehicleSkinRes = resID
                    local base = F.vehicleOriginalID(resID) or resID
                    _G.VehicleSkinMap = _G.VehicleSkinMap or {}
                    _G.VehicleSkinMap[base] = resID
                    if tonumber(base) ~= resID then
                        _G.VehicleSkinMap[resID] = resID
                    end
                    if insID then
                        pcall(function()
                            DataMgr.vst_skin = tonumber(insID)
                            local st = F.vehicleSlotSubType(resID) or F.vehicleSubType(resID)
                            DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
                            if st then
                                DataMgr.vehicleSkinInsIDTable[st] = tonumber(insID)
                            end
                        end)
                    end
                end

                function F.resolveVehicleSkinForAvatar(defaultID)
                    defaultID = tonumber(defaultID)
                    if not defaultID or defaultID <= 0 then
                        return nil
                    end
                    local base = F.vehicleOriginalID(defaultID) or defaultID
                    local map = _G.VehicleSkinMap
                    if map then
                        local skin = tonumber(map[base])
                            or tonumber(map[defaultID])
                            or tonumber(map[tostring(base)])
                        if skin and skin > 0 then
                            return skin
                        end
                    end
                    local lobby = tonumber(PERSIST.lobbyVehicleResID)
                        or tonumber((_G.AddOutfitLobbyVeh or {}).resID)
                        or tonumber(_G.AddOutfitLastVehicleSkinRes)
                    if lobby and lobby > 0 then
                        local lobbyBase = F.vehicleOriginalID(lobby) or lobby
                        if lobbyBase == base or lobby == defaultID then
                            return lobby
                        end
                    end
                    return nil
                end

                function F.resolveLobbyVehicleSkinRes()
                    local last = tonumber(_G.AddOutfitLastVehicleSkinRes)
                        or tonumber(PERSIST.lobbyVehicleResID)
                        or tonumber((_G.AddOutfitLobbyVeh or {}).resID)
                    if last and last > 0 then
                        return last
                    end
                    local res = F.resolveLobbyVehicle(PERSIST.configVehicleSlots)
                    return tonumber(res)
                end

                function F.isVehicleRes(resID)
                    resID = tonumber(resID)
                    if not resID or F.isChassisLightId(resID) then
                        return false
                    end

                    if resID >= 12200000 and resID < 12300000 then
                        return false
                    end
                    local c = F.cfg(resID)
                    local itemType = tonumber(c and (c.ItemType or c.itemType))
                    if itemType == 22 then
                        return false
                    end
                    local st = tonumber(F.subType(c))
                    if st and st >= 2200 and st < 2300 then
                        return false
                    end

                    if st and st ~= CHASSIS_LIGHT_SUB then
                        if (st >= 900 and st < 2000) or (st >= 9100 and st < 10000) or st == 1101 then
                            return true
                        end
                    end
                    local ok, hasMap = pcall(function()
                        return CDataTable
                            and CDataTable.GetTableData
                            and CDataTable.GetTableData("VehiclePlaneSkinMapping", resID) ~= nil
                    end)
                    return ok and hasMap == true
                end

                function F.ensureInjectedItemAlive(entity, resID, insID)
                    entity = entity or F.getEntity()
                    insID = tonumber(insID) or (resID and R.resToIns[tonumber(resID)])
                    resID = tonumber(resID) or (insID and R.insToRes[insID])
                    if not entity or not insID then
                        return
                    end
                    pcall(function()
                        local d = entity:GetDataByInsID(insID)
                        if d then
                            d.expire_ts = 0
                            d.expireTS = 0
                            d.valid_hours = 0
                        end
                    end)
                end

                function F.ensureAllInjectedAlive()
                    local entity = F.getEntity()
                    if not entity then
                        return
                    end
                    for res, ins in pairs(R.resToIns) do
                        F.ensureInjectedItemAlive(entity, res, ins)
                    end
                end

                function F.putOnVehicle(insID)
                    insID = tonumber(insID)
                    if not insID then
                        return false
                    end
                    local resID = R.insToRes[insID]
                    if not resID or not F.isVehicleRes(resID) then
                        return false
                    end
                    F.ensureInjectedItemAlive(nil, resID, insID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return false
                    end
                    local st = F.vehicleSlotSubType(resID) or F.vehicleSubType(resID)
                    pcall(function()
                        DataMgr.vst_skin = insID
                        DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
                        if st then
                            DataMgr.vehicleSkinInsIDTable[st] = insID
                        end
                    end)
                    local item = {
                        res_id = resID,
                        resID = resID,
                        instid = insID,
                        ins_id = insID,
                        insID = insID,
                        expire_ts = 0,
                        expireTS = 0,
                        count = 1,
                    }
                    pcall(function()
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        HT.ProcPutOnVehicle(item, true)
                        if HT.ShowThemeVehicle then
                            HT.ShowThemeVehicle()
                        end
                    end)
                    pcall(function()
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
                    end)
                    F.setLobbyVehicleManual(st, resID, insID)
                    F.rememberVehicleSkinMap(resID, insID)
                    pcall(function()
                        local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
                        TabSurveillance.VehicleChange()
                    end)
                    pcall(function()
                        if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                            EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                        end
                    end)
                    return true
                end
                function F.isChassisLightId(id)
                    return CHASSIS_LIGHT_IDS[tonumber(id)] == true
                end

                function F.getDesiredChassisLight(vehicleSkinId)
                    vehicleSkinId = tonumber(vehicleSkinId)
                    if F.getDesiredVehicleModChassisLight then
                        local fromMod = F.getDesiredVehicleModChassisLight(vehicleSkinId)
                        if fromMod and fromMod > 0 then
                            return fromMod
                        end
                    end
                    local map = PERSIST.configChassisLightMap
                    if vehicleSkinId and map and map[vehicleSkinId] then
                        local v = tonumber(map[vehicleSkinId])
                        if F.isChassisLightId(v) then
                            return v
                        end
                    end
                    local def = tonumber(PERSIST.configChassisLight) or DEFAULT_CHASSIS_LIGHT
                    return F.isChassisLightId(def) and def or DEFAULT_CHASSIS_LIGHT
                end

                function F.saveChassisLight(vehicleSkinId, lightId)
                    vehicleSkinId = tonumber(vehicleSkinId)
                    lightId = tonumber(lightId)
                    if not F.isChassisLightId(lightId) then
                        return
                    end
                    PERSIST.configChassisLightMap = PERSIST.configChassisLightMap or {}
                    if vehicleSkinId and vehicleSkinId > 0 then
                        PERSIST.configChassisLightMap[vehicleSkinId] = lightId
                    else
                        PERSIST.configChassisLight = lightId
                    end
                    F.requestResourceDownload(lightId)
                    F.persistMarkDirty()
                end

                function F.getVehicleLicenseComp(vehicle)
                    if not slua.isValid(vehicle) then
                        return nil
                    end
                    local lic = nil
                    pcall(function()
                        if vehicle.GetLicenseComponent then
                            lic = vehicle:GetLicenseComponent()
                        end
                    end)
                    if slua.isValid(lic) then
                        return lic
                    end
                    pcall(function()
                        lic = vehicle.BP_Lobby_VehicleLicenseComponent
                    end)
                    if slua.isValid(lic) then
                        return lic
                    end
                    pcall(function()
                        local cls = import("VehicleLicenseNumberComponent")
                        lic = vehicle:GetComponentByClass(cls)
                    end)
                    return slua.isValid(lic) and lic or nil
                end

                function F.applyVehicleChassisLight(vehicle, skinId, lightId)
                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then
                        if _G.NTHUY2004Config and _G.NTHUY2004Config.ModSkin == false then
                            return false
                        end
                    end

                    skinId = tonumber(skinId)
                    lightId = tonumber(lightId) or F.getDesiredChassisLight(skinId)
                    if not F.isChassisLightId(lightId) then
                        return false
                    end
                    if not slua.isValid(vehicle) then
                        return false
                    end
                    if skinId and skinId > 0 then
                        F.requestResourceDownload(skinId)
                    end
                    F.requestResourceDownload(lightId)
                    local applied = false
                    pcall(function()
                        if vehicle.SetChassisLightShowData then
                            vehicle:SetChassisLightShowData(lightId)
                            applied = true
                        end
                    end)
                    local lic = F.getVehicleLicenseComp(vehicle)
                    if not slua.isValid(lic) then
                        return applied
                    end
                    pcall(function()
                        local vid = skinId
                        if not vid or vid <= 0 then
                            pcall(function()
                                if vehicle.GetAvatarId then
                                    vid = tonumber(vehicle:GetAvatarId())
                                end
                            end)
                        end
                        if not vid or vid <= 0 then
                            pcall(function()
                                vid = tonumber(lic.LicensePlate and lic.LicensePlate.ItemID)
                            end)
                        end
                        if vid and vid > 0 then
                            lic.curVehicleAvatarId = vid
                            if lic.ChangeNetData_ItemID then
                                lic:ChangeNetData_ItemID(vid)
                            elseif lic.LicensePlate then
                                lic.LicensePlate.ItemID = vid
                            end
                        end
                        if lic.LicensePlate then
                            lic.LicensePlate.ChassisLightId = lightId
                        end
                        if lic.SetChassisLightData and vid and vid > 0 then
                            lic:SetChassisLightData(vid, lightId)
                        elseif lic.PreChangeChassisLight then
                            lic:PreChangeChassisLight()
                        end
                        applied = true
                    end)
                    return applied
                end

                function F.scheduleChassisLightApply(vehicle, skinId)
                    skinId = tonumber(skinId)
                    local vref = slua.isValid(vehicle) and vehicle or nil
                    local function try()
                        local v = slua.isValid(vref) and vref or F.getCurrentVehicleForSkin()
                        if slua.isValid(v) then
                            F.applyVehicleChassisLight(v, skinId)
                        end
                    end
                    F.later(0.4, try)
                    F.later(1.1, try)
                end

                function F.getVehicleShape(vehicle)
                    if not slua.isValid(vehicle) then
                        return nil
                    end
                    local shape = vehicle.VehicleShapeType
                    if shape and tonumber(shape) >= 0 then
                        return tonumber(shape)
                    end
                    pcall(function()
                        local UAvatarUtils = import("AvatarUtils")
                        local defId = vehicle.AvatarDefaultCfg and vehicle.AvatarDefaultCfg.TypeSpecificID
                        if defId and tonumber(defId) > 0 then
                            shape = UAvatarUtils.GetVehicleShapeBySkinID(tonumber(defId))
                        end
                    end)
                    return shape and tonumber(shape) >= 0 and tonumber(shape) or nil
                end

                function F.getDesiredVehicleSkinForShape(shape, defaultId)
                    shape = tonumber(shape)
                    if not shape or shape < 0 then
                        return nil
                    end
                    F.syncVehicleCacheFromDataMgr()
                    local UAvatarUtils = import("AvatarUtils")
                    if defaultId then
                        local mapped = F.resolveVehicleSkinForAvatar(defaultId)
                        if mapped and mapped > 0 then
                            return mapped
                        end
                    end
                    local map = _G.VehicleSkinMap
                    if map then
                        for baseId, skin in pairs(map) do
                            skin = tonumber(skin)
                            if skin and skin > 0 then
                                local s = nil
                                pcall(function()
                                    s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(skin))
                                end)
                                if s == shape then
                                    return skin
                                end
                                local b = tonumber(baseId)
                                if b then
                                    pcall(function()
                                        s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(b))
                                    end)
                                    if s == shape then
                                        return skin
                                    end
                                end
                            end
                        end
                    end
                    local vst = F.buildVstInBattleFromSlots()
                    for _, list in pairs(vst) do
                        local skin = list and tonumber(list[1])
                        if skin and skin > 0 then
                            local s = UAvatarUtils.GetVehicleShapeBySkinID(skin)
                            if s == shape then
                                return skin
                            end
                        end
                    end
                    local pc = F.getPC()
                    if slua.isValid(pc) and pc.VehicleAvatarList then
                        local skin = tonumber(pc.VehicleAvatarList:Get(shape))
                        if skin and skin > 0 then
                            return skin
                        end
                    end
                    return nil
                end
                function F.getVehicleAvatarComp(vehicle)
                    if not slua.isValid(vehicle) then
                        return nil
                    end
                    local av = nil
                    pcall(function()
                        av = vehicle.VehicleAvatar
                    end)
                    if slua.isValid(av) then
                        return av
                    end
                    pcall(function()
                        if vehicle.GetAvatarComponent then
                            av = vehicle:GetAvatarComponent()
                        end
                    end)
                    if slua.isValid(av) then
                        return av
                    end
                    pcall(function()
                        av = vehicle.VehicleAvatarComponent_BP
                    end)
                    if slua.isValid(av) then
                        return av
                    end
                    return nil
                end

                function F.getCurrentVehicleForSkin()
                    local char = F.getLocalChar()
                    if char and slua.isValid(char) then
                        local v = nil
                        pcall(function()
                            v = char.CurrentVehicle
                        end)
                        if slua.isValid(v) then
                            return v
                        end
                    end
                    return F.getMatchVehicle()
                end

                function F.forceVehicleAvatar(skinId, vehicle)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end
                    if not F.isResourcesReady(skinId) then
                        F.requestResourceDownload(skinId)
                        return false
                    end
                    vehicle = slua.isValid(vehicle) and vehicle or F.getCurrentVehicleForSkin()
                    if not slua.isValid(vehicle) then
                        return false
                    end
                    local av = F.getVehicleAvatarComp(vehicle)
                    if not slua.isValid(av) then
                        return false
                    end
                    local applied = false
                    F.prepVehicleSwitchEffect(av, vehicle)
                    pcall(function()
                        if av.CanChangeAvatar ~= nil then
                            av.CanChangeAvatar = true
                        end
                    end)
                    pcall(function()
                        local parts = F.getDesiredMultiSlotPartsForSkin
                                and F.getDesiredMultiSlotPartsForSkin(skinId)
                            or {}
                        if next(parts) then
                            pcall(function()
                                av.bEnableMultiSlot = true
                            end)
                            pcall(function()
                                if av.SetLobbyMultiSlotEquipData then
                                    av:SetLobbyMultiSlotEquipData(parts)
                                end
                            end)
                            pcall(function()
                                if av.SetNetMultiSlotData then
                                    av:SetNetMultiSlotData(parts)
                                end
                            end)
                        end
                        av:ChangeItemAvatar(skinId, true)
                        applied = true
                        _G.CurrentEquipVehicleID = skinId
                    end)
                    if applied then
                        F.scheduleChassisLightApply(vehicle, skinId)
                        pcall(function()
                            F.applyVehicleModPartsToVehicle(vehicle, skinId)
                        end)
                        if F.scheduleVehicleModPartsApply then
                            F.scheduleVehicleModPartsApply(vehicle, skinId)
                        end
                    end
                    return applied
                end

                function F.vehicleAvatarTemper()
                    local vehicle = F.getCurrentVehicleForSkin()
                    if not slua.isValid(vehicle) then
                        return
                    end
                    local av = F.getVehicleAvatarComp(vehicle)
                    if not slua.isValid(av) then
                        return
                    end

                    local defaultId = 0
                    pcall(function()
                        defaultId = tonumber(av:GetDefaultAvatarID()) or 0
                    end)
                    if defaultId <= 0 then
                        return
                    end

                    local shape = nil
                    pcall(function()
                        shape = tonumber(import("AvatarUtils").GetVehicleShapeBySkinID(defaultId))
                    end)

                    local skinId = nil
                    if
                        VEHSEL.override
                        and slua.isValid(VEHSEL.overrideVehicle)
                        and VEHSEL.overrideVehicle == vehicle
                    then
                        skinId = VEHSEL.override
                    end
                    if not skinId and shape then
                        skinId = VEHSEL.byShape[shape]
                    end
                    if not skinId then
                        skinId = F.resolveVehicleSkinForAvatar(defaultId)
                    end
                    if not skinId and shape then
                        skinId = F.getDesiredVehicleSkinForShape(shape, defaultId)
                    end
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 or skinId == defaultId then
                        return
                    end

                    local cur = 0
                    pcall(function()
                        cur = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0
                    end)
                    if cur <= 0 then
                        pcall(function()
                            cur = tonumber(vehicle.GetVehicleSkinItemID and vehicle:GetVehicleSkinItemID())
                                or 0
                        end)
                    end
                    if cur == skinId then
                        return
                    end

                    F.forceVehicleAvatar(skinId, vehicle)
                end
                function F.vehicleSkinTick()
                    if not F.skinFeat("SkinMatchVehicle") then
                        return
                    end

                    local vehicle = F.getCurrentVehicleForSkin and F.getCurrentVehicleForSkin()
                    if not slua.isValid(vehicle) then
                        return
                    end
                    F.vehicleAvatarTemper()
                    local now = os.clock()
                    if now - _vehTickLastApply < 5.0 then
                        return
                    end
                    _vehTickLastApply = now
                    F.applyVehicleSkinsToPC()
                end

                function F.startVehicleSkinTicker()
                    pcall(function()
                        if not F.skinFeat("SkinMatchVehicle") then
                            if _G.AddOutfitVehTickerId and _ticker and _ticker.RemoveTimer then
                                pcall(function()
                                    _ticker.RemoveTimer(_G.AddOutfitVehTickerId)
                                end)
                                _G.AddOutfitVehTickerId = nil
                                _G.AddOutfitVehTickerVer = nil
                            end
                            return
                        end
                        if not _ticker then
                            return
                        end

                        if _G.AddOutfitVehTickerVer == 2 and _G.AddOutfitVehTickerId then
                            return
                        end
                        if _G.AddOutfitVehTickerId and _ticker.RemoveTimer then
                            pcall(function()
                                _ticker.RemoveTimer(_G.AddOutfitVehTickerId)
                            end)
                            _G.AddOutfitVehTickerId = nil
                        end
                        if _ticker.AddTimerLoop then
                            _G.AddOutfitVehTickerId = _ticker.AddTimerLoop(2.5, function()
                                local fn = _G.AddOutfit and _G.AddOutfit.vehicleSkinTick
                                if fn then
                                    pcall(fn)
                                end
                            end, -1, 2.5)
                            _G.AddOutfitVehTickerVer = 2
                        end
                    end)
                end

                function F.matchApplyVehicleSkin(skinId)
                    skinId = tonumber(skinId)
                    if not skinId or skinId <= 0 then
                        return false
                    end

                    local vehicle = F.getCurrentVehicleForSkin()

                    VEHSEL.override = skinId
                    VEHSEL.overrideVehicle = slua.isValid(vehicle) and vehicle or nil

                    pcall(function()
                        local UAvatarUtils = import("AvatarUtils")
                        local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(skinId))
                        if shape and shape >= 0 then
                            VEHSEL.byShape[shape] = skinId
                        end
                        local av = F.getVehicleAvatarComp(vehicle)
                        if slua.isValid(av) then
                            local defaultId = tonumber(av:GetDefaultAvatarID()) or 0
                            if defaultId > 0 then
                                local defShape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defaultId))
                                if defShape and defShape >= 0 then
                                    VEHSEL.byShape[defShape] = skinId
                                end
                            end
                        end
                    end)

                    F.applyVehicleSkinsToPC(F.getPC())
                    local ok = F.forceVehicleAvatar(skinId, vehicle)
                    F.startVehicleSkinTicker()
                    return ok
                end

                function F.autoApplyVehicleSkinOnEnter(vehicle)
                    if not slua.isValid(vehicle) then
                        return
                    end
                    F.syncVehicleCacheFromDataMgr()
                    F.applyVehicleSkinsToPC(F.getPC())
                    F.startVehicleSkinTicker()
                    pcall(function()
                        local av = F.getVehicleAvatarComp(vehicle)
                        if not slua.isValid(av) then
                            return
                        end
                        local defId = 0
                        pcall(function()
                            defId = tonumber(av:GetDefaultAvatarID()) or 0
                        end)
                        local currentId = 0
                        pcall(function()
                            currentId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0
                        end)
                        local vehTarget = F.resolveVehicleSkinForAvatar(defId)
                        if (not vehTarget or vehTarget <= 0) and _G.VehicleSkinMap then
                            local defStr = tostring(defId)
                            for baseId, targetSkin in pairs(_G.VehicleSkinMap) do
                                if defStr:find(tostring(baseId), 1, true) then
                                    vehTarget = tonumber(targetSkin)
                                    break
                                end
                            end
                        end
                        if vehTarget and vehTarget > 0 and currentId ~= vehTarget then
                            F.requestResourceDownload(vehTarget)
                            F.forceVehicleAvatar(vehTarget, vehicle)
                            _G.CurrentEquipVehicleID = vehTarget
                        end
                    end)
                    F.later(0.6, function()
                        pcall(F.vehicleAvatarTemper)
                        local skinId = nil
                        pcall(function()
                            skinId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId())
                        end)
                        pcall(function()
                            F.applyVehiclePartDataToPC(F.getPC(), skinId)
                        end)
                        F.scheduleChassisLightApply(vehicle, skinId)
                        pcall(function()
                            F.applyVehicleModPartsToVehicle(vehicle, skinId)
                        end)
                    end)
                end
                local function GetOutfitConfigPaths(fileName)
                    local paths = {
                        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                            .. fileName,
                        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                            .. fileName,
                        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                            .. fileName,
                        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                            .. fileName,
                        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                            .. fileName,
                        "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
                        "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName,
                        "ShadowTrackerExtra/Saved/Paks/" .. fileName,
                        "../../ShadowTrackerExtra/Saved/Paks/" .. fileName,
                    }
                    pcall(function()
                        if os and os.getenv then
                            local homeDir = os.getenv("HOME")
                            if homeDir and homeDir ~= "" then
                                table.insert(
                                    paths,
                                    1,
                                    homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName
                                )
                            end
                        end
                    end)
                    return paths
                end

                local LEGACY_CONFIG_PATHS = {}
                local CONFIG_PATHS = GetOutfitConfigPaths("NTHUY2004_cfg453_outfit_script.json")

                function F.outfitConfigFileName()
                    if _G.NTHUY2004Config and _G.NTHUY2004Config.UseScriptSkins == false then
                        return "NTHUY2004_cfg453_outfit_custom.json"
                    end
                    return "NTHUY2004_cfg453_outfit_script.json"
                end

                function F.refreshOutfitConfigPaths()
                    CONFIG_PATHS = GetOutfitConfigPaths(F.outfitConfigFileName())
                    return CONFIG_PATHS
                end

                function F.onUseScriptSkinsChanged()
                    local useScript = not (_G.NTHUY2004Config and _G.NTHUY2004Config.UseScriptSkins == false)
                    if PERSIST._modeBound and PERSIST._modeUseScript == useScript then
                        return
                    end

                    if PERSIST._modeBound and PERSIST.dirty then
                        pcall(F.persistFlush)
                    end
                    PERSIST._modeUseScript = useScript
                    PERSIST._modeBound = true
                    PERSIST.path = nil
                    PERSIST.lastWritten = nil
                    PERSIST.loaded = nil
                    PERSIST.dirty = false
                    PERSIST.scheduled = false
                    PERSIST.configSlots = {}
                    PERSIST.configWeapons = {}
                    PERSIST.configDepotItems = {}
                    PERSIST.configVehicleSlots = {}
                    PERSIST.configMotionSlots = {}
                    PERSIST.configChassisLight = nil
                    PERSIST.configChassisLightMap = {}
                    PERSIST.configVehicleMod = nil
                    PERSIST.configPetResID = nil
                    PERSIST.lobbyVehicleSubType = nil
                    PERSIST.lobbyVehicleIns = nil
                    PERSIST.lobbyVehicleResID = nil
                    PERSIST.hallThemeResID = nil
                    PERSIST.hallThemeIns = nil
                    _G.NTHUY2004_DumpExtraSkins = {}
                    F.refreshOutfitConfigPaths()
                    pcall(F.persistLoadFromDisk)
                    pcall(F.syncDepotItemsFromPersist)
                    pcall(F.applyPersistSlotsToCache)
                    pcall(F.syncGlobalWearSkins)
                    pcall(function()
                        local entity = F.getEntity and F.getEntity()
                        if entity then
                            F.injectAll(entity)
                        end
                    end)
                    pcall(function()
                        if F.reapplyVehicleModPersist then
                            F.reapplyVehicleModPersist(true)
                        end
                    end)
                end

                local PERSIST_SLOTS = {
                    { "outfit", "outfitRes", "outfitIns", "AddOutfitLastLobbyOutfitRes" },
                    { "tshirt", "tshirtRes", "tshirtIns", "AddOutfitLastLobbyTshirtRes" },
                    { "pants", "pantsRes", "pantsIns", "AddOutfitLastLobbyPantsRes" },
                    { "shoes", "shoesRes", "shoesIns", "AddOutfitLastLobbyShoesRes" },
                    { "hat", "hatRes", "hatIns", "AddOutfitLastLobbyHatRes" },
                    { "mask", "maskRes", "maskIns", "AddOutfitLastLobbyMaskRes" },
                    { "glass", "glassRes", "glassIns", "AddOutfitLastLobbyGlassRes" },
                    { "bag", "bagRes", "bagIns", "AddOutfitLastLobbyBagRes" },
                    { "helmet", "helmetRes", "helmetIns", "AddOutfitLastLobbyHelmetRes" },
                    { "parachute", "parachuteRes", "parachuteIns", "AddOutfitLastLobbyParachuteRes" },
                    { "glider", "gliderRes", "gliderIns", "AddOutfitLastLobbyGliderRes" },
                    { "gloves", "glovesRes", "glovesIns", "AddOutfitLastLobbyGlovesRes" },
                }

                function F.isPersistableWearRes(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if F.isInjectedRes(resID) then
                        return true
                    end
                    if F.isParachuteRes(resID) or F.isGlideRes(resID) then
                        return true
                    end
                    if PERSIST.configSlots then
                        for _, v in pairs(PERSIST.configSlots) do
                            if tonumber(v) == resID then
                                return true
                            end
                        end
                    end
                    return false
                end

                function F.persistRememberSlot(slotName, resID)
                    slotName = slotName and tostring(slotName)
                    resID = tonumber(resID)
                    if not slotName or not resID or resID <= 0 then
                        return
                    end
                    PERSIST.configSlots = PERSIST.configSlots or {}
                    PERSIST.configSlots[slotName] = resID
                end

                function F.persistRememberDepotItem(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if not F.shouldPersistDepotGrant or not F.shouldPersistDepotGrant(resID) then
                        return false
                    end
                    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
                    PERSIST.configDepotItems[resID] = true
                    if F.pruneDepotItemsUpgradeGroup then
                        F.pruneDepotItemsUpgradeGroup(resID)
                    end
                    F.invalidateDepotGroupCache()
                    return true
                end

                function F.syncDepotItemsFromPersist()
                    if type(PERSIST.configDepotItems) ~= "table" then
                        return
                    end
                    _G.NTHUY2004_DumpExtraSkins = _G.NTHUY2004_DumpExtraSkins or {}
                    for res, on in pairs(PERSIST.configDepotItems) do
                        if on then
                            res = tonumber(res)
                            if res and res > 0 then
                                _G.NTHUY2004_DumpExtraSkins[res] = true
                            end
                        end
                    end
                end

                function F.persistLoadDepotItemsFromSaved(saved)
                    if type(saved) ~= "table" or type(saved.depotItems) ~= "table" then
                        return
                    end
                    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
                    for _, res in ipairs(saved.depotItems) do
                        res = tonumber(res)
                        if res and res > 0 then
                            PERSIST.configDepotItems[res] = true
                        end
                    end
                    if F.collapsePersistedDepotUpgradeGroups then
                        F.collapsePersistedDepotUpgradeGroups()
                    end
                    F.syncDepotItemsFromPersist()
                end

                function F.persistLoadXSuitUnlocksFromSaved(saved)
                    if type(saved) ~= "table" or type(saved.xsuitUnlocks) ~= "table" then
                        return
                    end
                    local fls = _G.NTHUY2004_FreeLobbyShop
                    if type(fls) ~= "table" or not fls.rememberXSuitWorkshopUnlock then
                        return
                    end
                    for _, u in ipairs(saved.xsuitUnlocks) do
                        if type(u) == "table" and tonumber(u.period) and tonumber(u.itemId) then
                            fls.rememberXSuitWorkshopUnlock({
                                period = tonumber(u.period),
                                branchId = tonumber(u.branchId) or 0,
                                level = tonumber(u.current) or tonumber(u.level) or 1,
                                itemId = tonumber(u.itemId),
                            })
                            pcall(function()
                                if F.registerDumpExtraSkin then
                                    F.registerDumpExtraSkin(tonumber(u.itemId))
                                end
                            end)
                        end
                    end
                end

                function F.getWeaponUpgradeLevel(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return nil, nil
                    end
                    F._weaponUpgradeCache = F._weaponUpgradeCache or {}
                    local cached = F._weaponUpgradeCache[resID]
                    if cached then
                        return cached[1], cached[2]
                    end
                    local groupID, level = nil, nil
                    pcall(function()
                        local cfg = CDataTable.GetTableDataByFilter("ItemUpgradeConfig", "ItemID", resID)
                        if cfg then
                            groupID = tonumber(cfg.GroupID)
                            level = tonumber(cfg.Level)
                        end
                    end)
                    if groupID and groupID > 0 and level and level > 0 then
                        F._weaponUpgradeCache[resID] = { groupID, level }
                        return groupID, level
                    end
                    F._weaponUpgradeCache[resID] = { nil, nil }
                    return nil, nil
                end

                function F.invalidateDepotGroupCache()
                    F._depotGroupBest = nil
                end

                function F.buildDepotGroupBestCache()
                    local cache = {}
                    local function consider(res)
                        res = tonumber(res)
                        if not res then
                            return
                        end
                        local gid, lvl = F.getWeaponUpgradeLevel(res)
                        if gid and lvl then
                            local cur = cache[gid]
                            if not cur or lvl > cur.level then
                                cache[gid] = { res = res, level = lvl }
                            end
                        end
                    end
                    for res, on in pairs(PERSIST.configDepotItems or {}) do
                        if on then
                            consider(res)
                        end
                    end
                    for res, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            consider(res)
                        end
                    end
                    pcall(function()
                        local entity = F.getEntity()
                        if entity and entity._data then
                            for i = 1, (entity._DataCount or #entity._data) do
                                local d = entity._data[i]
                                if d and (tonumber(d.count) or 0) > 0 then
                                    consider(d.resID or d.res_id)
                                end
                            end
                        end
                    end)
                    F._depotGroupBest = cache
                end

                function F.persistForgetDepotItem(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return
                    end
                    if PERSIST.configDepotItems then
                        PERSIST.configDepotItems[resID] = nil
                    end
                    if _G.NTHUY2004_DumpExtraSkins then
                        _G.NTHUY2004_DumpExtraSkins[resID] = nil
                    end
                    F.invalidateDepotGroupCache()
                end

                function F.pruneDepotItemsUpgradeGroup(resID)
                    local groupID, level = F.getWeaponUpgradeLevel(resID)
                    if not groupID or not level then
                        return
                    end
                    local toRemove = {}
                    local function markRemove(r)
                        r = tonumber(r)
                        if not r or r == resID then
                            return
                        end
                        local gid, lvl = F.getWeaponUpgradeLevel(r)
                        if gid == groupID and lvl and lvl <= level then
                            toRemove[r] = true
                        end
                    end
                    for r, on in pairs(PERSIST.configDepotItems or {}) do
                        if on then
                            markRemove(r)
                        end
                    end
                    for r, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            markRemove(r)
                        end
                    end
                    for r in pairs(toRemove) do
                        F.persistForgetDepotItem(r)
                    end
                end

                function F.collapsePersistedDepotUpgradeGroups()
                    if type(PERSIST.configDepotItems) ~= "table" then
                        return
                    end
                    local bestByGroup = {}
                    for res, on in pairs(PERSIST.configDepotItems) do
                        if on then
                            res = tonumber(res)
                            local gid, lvl = F.getWeaponUpgradeLevel(res)
                            if gid and lvl then
                                local cur = bestByGroup[gid]
                                if not cur or lvl > cur.level then
                                    bestByGroup[gid] = { res = res, level = lvl }
                                end
                            end
                        end
                    end
                    for gid, best in pairs(bestByGroup) do
                        for res, on in pairs(PERSIST.configDepotItems) do
                            if on then
                                res = tonumber(res)
                                local g2, l2 = F.getWeaponUpgradeLevel(res)
                                if g2 == gid and l2 and l2 < best.level then
                                    F.persistForgetDepotItem(res)
                                end
                            end
                        end
                    end
                    F.syncDepotItemsFromPersist()
                end

                function F.getHighestDepotLevelForGroup(groupID)
                    groupID = tonumber(groupID)
                    if not groupID then
                        return nil, nil
                    end
                    if not F._depotGroupBest then
                        F.buildDepotGroupBestCache()
                    end
                    local best = F._depotGroupBest[groupID]
                    if best then
                        return best.res, best.level
                    end
                    return nil, nil
                end

                function F.shouldInjectDepotRes(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    local groupID, level = F.getWeaponUpgradeLevel(resID)
                    if not groupID or not level then
                        return true
                    end
                    local bestRes, bestLevel = F.getHighestDepotLevelForGroup(groupID)
                    if not bestLevel or bestLevel <= 0 then
                        return true
                    end
                    if bestLevel > level then
                        return false
                    end
                    if bestLevel == level and bestRes and bestRes ~= resID then
                        return F.isInjectedDepotAlive and F.isInjectedDepotAlive(bestRes) == true
                    end
                    return true
                end

                function F.persistReplaceDepotItem(oldResID, newResID)
                    oldResID, newResID = tonumber(oldResID), tonumber(newResID)
                    if oldResID and oldResID > 0 then
                        F.persistForgetDepotItem(oldResID)
                    end
                    if
                        newResID
                        and newResID > 0
                        and F.shouldPersistDepotGrant
                        and F.shouldPersistDepotGrant(newResID)
                    then
                        PERSIST.configDepotItems = PERSIST.configDepotItems or {}
                        PERSIST.configDepotItems[newResID] = true
                        _G.NTHUY2004_DumpExtraSkins = _G.NTHUY2004_DumpExtraSkins or {}
                        _G.NTHUY2004_DumpExtraSkins[newResID] = true
                        F.pruneDepotItemsUpgradeGroup(newResID)
                    end
                    F.invalidateDepotGroupCache()
                end

                function F.persistForgetSlot(slotName)
                    if PERSIST.configSlots and slotName then
                        PERSIST.configSlots[tostring(slotName)] = nil
                    end
                end

                function F.persistRememberMotionSlot(slot, resID)
                    slot = tonumber(slot)
                    resID = tonumber(resID)
                    if not slot or slot <= 0 then
                        return
                    end
                    PERSIST.configMotionSlots = PERSIST.configMotionSlots or {}
                    if resID and resID > 0 and F.isEmoteRes(resID) then
                        PERSIST.configMotionSlots[slot] = resID
                    else
                        PERSIST.configMotionSlots[slot] = nil
                    end
                    F.persistMarkDirty()
                end

                function F.persistLoadMotionSlotsFromSaved(saved)
                    if type(saved) ~= "table" or type(saved.motionSlots) ~= "table" then
                        return
                    end
                    PERSIST.configMotionSlots = PERSIST.configMotionSlots or {}
                    for idxStr, res in pairs(saved.motionSlots) do
                        local idx, r = tonumber(idxStr), tonumber(res)
                        if idx and idx > 0 and r and r > 0 and F.isEmoteRes(r) then
                            PERSIST.configMotionSlots[idx] = r
                        end
                    end
                end

                function F.applyPersistedMotionSlots()
                    if not PERSIST.configMotionSlots then
                        return false
                    end
                    local any = false
                    for slot, resID in pairs(PERSIST.configMotionSlots) do
                        slot = tonumber(slot)
                        resID = tonumber(resID)
                        if slot and slot > 0 and resID and resID > 0 then
                            local ins = F.resolveInsForRes(resID)
                            if ins and ins > 0 then
                                F.ensureMotionSlotCapacity(slot)
                                DataMgr.MotionSlotList[slot] = ins
                                _G.AddOutfitLocalMotionSlots = _G.AddOutfitLocalMotionSlots or {}
                                _G.AddOutfitLocalMotionSlots[slot] = ins
                                any = true
                            end
                        end
                    end
                    if any then
                        F.invalidateInGameEmoteCache()
                        F.postMotionSlotUpdate()
                    end
                    return any
                end

                function F.persistLoadSlotsFromSaved(saved)
                    if type(saved) ~= "table" then
                        return
                    end
                    PERSIST.configSlots = PERSIST.configSlots or {}
                    for _, s in ipairs(PERSIST_SLOTS) do
                        local res = tonumber(saved[s[1]])
                        if res and res > 0 then
                            PERSIST.configSlots[s[1]] = res
                        end
                    end
                    F.persistLoadMotionSlotsFromSaved(saved)
                    F.applyPersistSlotsToCache()
                end

                function F.resolveInsForRes(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return nil
                    end
                    if R.resToIns[resID] then
                        return R.resToIns[resID]
                    end
                    local ins
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local list = wd.GetHallDepotItemListByResID and wd:GetHallDepotItemListByResID(resID)
                        if list then
                            for _, v in pairs(list) do
                                local id = tonumber(v.insID or v.instid or v.ins_id)
                                if id and id > 0 then
                                    ins = id
                                    break
                                end
                            end
                        end
                        if not ins then
                            local d = wd.GetValidHallDepotItemDataByInsID
                                and wd:GetValidHallDepotItemDataByInsID(resID)
                            if not d and wd.GetHallDepotItemDataByResID then
                                d = wd:GetHallDepotItemDataByResID(resID)
                            end
                            if d then
                                ins = tonumber(d.insID or d.instid or d.ins_id)
                            end
                        end
                    end)
                    return ins
                end

                function F.applyPersistSlotsToCache()
                    if not PERSIST.configSlots then
                        return
                    end
                    local cch = F.cache()
                    for _, s in ipairs(PERSIST_SLOTS) do
                        local slotName, cacheResKey, cacheInsKey, globalKey = s[1], s[2], s[3], s[4]
                        local res = tonumber(PERSIST.configSlots[slotName])
                        if res and res > 0 then
                            cch[cacheResKey] = res
                            _G[globalKey] = res
                            local ins = F.resolveInsForRes(res)
                            if ins and ins > 0 then
                                cch[cacheInsKey] = ins
                            end
                        end
                    end
                end

                function F.getDesiredGliderRes()
                    F.applyPersistSlotsToCache()
                    local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.glider)
                    if r and r > 0 then
                        return r
                    end
                    F.syncAirborneCacheFromLobby()
                    return F.getDesiredWear("gliderRes", "gliderRes", "AddOutfitLastLobbyGliderRes")
                end

                function F.getDesiredParachuteRes()
                    F.applyPersistSlotsToCache()
                    local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.parachute)
                    if r and r > 0 then
                        return r
                    end
                    F.syncAirborneCacheFromLobby()
                    return F.getDesiredWear("parachuteRes", "parachuteRes", "AddOutfitLastLobbyParachuteRes")
                end

                function F.getAvatarComp2(char)
                    if not char or not slua.isValid(char) then
                        return nil
                    end
                    local comp
                    pcall(function()
                        if char.getAvatarComponent2 then
                            comp = char:getAvatarComponent2()
                        end
                        if (not comp or not slua.isValid(comp)) and char.AvatarComponent2 then
                            comp = char.AvatarComponent2
                        end
                        if (not comp or not slua.isValid(comp)) and char.CharacterAvatarComp2_BP then
                            comp = char.CharacterAvatarComp2_BP
                        end
                    end)
                    return comp
                end

                function F.isCharacterAirborne(char)
                    if not char or not slua.isValid(char) then
                        return false
                    end
                    local ok, r = pcall(function()
                        local EParachuteState = import("EParachuteState")
                        local st = char.ParachuteState
                        return st and st ~= EParachuteState.PS_None
                    end)
                    return ok and r == true
                end

                function F.reapplyWeaponsFromConfig()
                    local wmap = F.sanitizeConfigWeapons(PERSIST.configWeapons)
                    local dropped = false
                    for k in pairs(PERSIST.configWeapons or {}) do
                        if not wmap[tonumber(k) or k] then
                            dropped = true
                            break
                        end
                    end
                    PERSIST.configWeapons = wmap
                    if dropped then
                        F.persistMarkDirty()
                    end
                    if not next(wmap) then
                        return false
                    end
                    local cch = F.cache()
                    local any = false
                    for wid, res in pairs(wmap) do
                        wid, res = tonumber(wid), tonumber(res)
                        local ins = res and R.resToIns[res]
                        if wid and ins and F.isInjectedIns(ins) then
                            cch.weapons[wid] = { resID = res, insID = ins }

                            if wid == MELEE_ID or (wid >= 108000 and wid < 109000) then
                                F.syncWeaponArmorySilent(wid, ins)
                            elseif F.equipWeaponSkin(wid, ins) then
                                any = true
                            else
                                F.syncWeaponArmorySilent(wid, ins)
                            end
                        end
                    end
                    return any
                end

                function F.persistEncode()
                    local cch = F.cache()
                    local parts = {}
                    for _, s in ipairs(PERSIST_SLOTS) do
                        local res = tonumber(PERSIST.configSlots and PERSIST.configSlots[s[1]])
                            or tonumber(cch[s[2]])
                        if res and res > 0 and F.isPersistableWearRes(res) then
                            parts[#parts + 1] = string.format('  "%s": %d', s[1], res)
                        end
                    end
                    local wparts = {}
                    local wmap = {}
                    for wid, res in pairs(F.sanitizeConfigWeapons(PERSIST.configWeapons)) do
                        wmap[wid] = res
                    end
                    for wid, w in pairs(cch.weapons or {}) do
                        local res = w and tonumber(w.resID)
                        wid = tonumber(wid)
                        if F.isValidWeaponPersistEntry(wid, res) then
                            wmap[wid] = res
                        end
                    end
                    for wid, res in pairs(wmap) do
                        wparts[#wparts + 1] = string.format('    "%d": %d', wid, res)
                    end
                    table.sort(wparts)
                    parts[#parts + 1] = '  "weapons": {\n' .. table.concat(wparts, ",\n") .. "\n  }"
                    local gparts = {}
                    local gmap = {}
                    for base, res in pairs(PERSIST.configGrenades or {}) do
                        base, res = tonumber(base), tonumber(res)
                        if
                            base
                            and GRENADE_FIELD_BY_BASE[base]
                            and res
                            and res > 0
                            and F.isGrenadeSkinRes(res)
                        then
                            gmap[base] = res
                        end
                    end
                    local cchG = F.cache().grenades
                    for base, w in pairs(cchG or {}) do
                        local res = w and tonumber(w.resID)
                        base = tonumber(base)
                        if
                            base
                            and GRENADE_FIELD_BY_BASE[base]
                            and res
                            and res > 0
                            and F.isGrenadeSkinRes(res)
                        then
                            gmap[base] = res
                        end
                    end
                    for base, res in pairs(gmap) do
                        gparts[#gparts + 1] = string.format('    "%d": %d', base, res)
                    end
                    table.sort(gparts)
                    parts[#parts + 1] = '  "grenades": {\n' .. table.concat(gparts, ",\n") .. "\n  }"
                    local vparts = {}
                    local function appendVehicleSlots(src)
                        for subType, slots in pairs(src or {}) do
                            local sparts = {}
                            if type(slots) == "table" then
                                for idx, val in pairs(slots) do
                                    local res = type(val) == "table" and tonumber(val.resID) or tonumber(val)
                                    if res and res > 0 then
                                        sparts[#sparts + 1] =
                                            string.format('      "%d": %d', tonumber(idx), res)
                                    end
                                end
                            end
                            table.sort(sparts)
                            if #sparts > 0 then
                                vparts[#vparts + 1] = string.format(
                                    '    "%d": {\n%s\n    }',
                                    tonumber(subType),
                                    table.concat(sparts, ",\n")
                                )
                            end
                        end
                    end
                    local hasCacheSlots = false
                    for _ in pairs(cch.vehicleSlots or {}) do
                        hasCacheSlots = true
                        break
                    end
                    if hasCacheSlots then
                        appendVehicleSlots(cch.vehicleSlots)
                    elseif PERSIST.configVehicleSlots then
                        appendVehicleSlots(PERSIST.configVehicleSlots)
                    end
                    table.sort(vparts)
                    parts[#parts + 1] = '  "vehicleSlots": {\n' .. table.concat(vparts, ",\n") .. "\n  }"
                    if
                        PERSIST.lobbyVehicleSubType
                        and PERSIST.lobbyVehicleSubType > 0
                        and PERSIST.lobbyVehicleSubType ~= CHASSIS_LIGHT_SUB
                        and not F.isChassisLightId(PERSIST.lobbyVehicleResID)
                        and F.isVehicleRes(PERSIST.lobbyVehicleResID)
                    then
                        parts[#parts + 1] =
                            string.format('  "lobbyVehicleSubType": %d', PERSIST.lobbyVehicleSubType)
                    end
                    if
                        PERSIST.lobbyVehicleResID
                        and PERSIST.lobbyVehicleResID > 0
                        and F.isVehicleRes(PERSIST.lobbyVehicleResID)
                    then
                        parts[#parts + 1] =
                            string.format('  "lobbyVehicleResID": %d', PERSIST.lobbyVehicleResID)
                    end
                    if
                        PERSIST.lobbyVehicleIns
                        and PERSIST.lobbyVehicleIns > 0
                        and F.isVehicleRes(PERSIST.lobbyVehicleResID or R.insToRes[PERSIST.lobbyVehicleIns])
                    then
                        parts[#parts + 1] = string.format('  "lobbyVehicleIns": %d', PERSIST.lobbyVehicleIns)
                    end
                    local hres = tonumber(cch.hallThemeRes) or tonumber(PERSIST.hallThemeResID)
                    if hres and hres > 0 and F.isInjectedRes(hres) then
                        parts[#parts + 1] = string.format('  "hallTheme": %d', hres)
                    end
                    local cl = tonumber(PERSIST.configChassisLight)
                    if F.isChassisLightId(cl) then
                        parts[#parts + 1] = string.format('  "chassisLight": %d', cl)
                    end
                    local cmap = PERSIST.configChassisLightMap
                    if cmap and next(cmap) then
                        local cparts = {}
                        for vid, lid in pairs(cmap) do
                            vid, lid = tonumber(vid), tonumber(lid)
                            if vid and vid > 0 and F.isChassisLightId(lid) then
                                cparts[#cparts + 1] = string.format('    "%d": %d', vid, lid)
                            end
                        end
                        table.sort(cparts)
                        if #cparts > 0 then
                            parts[#parts + 1] = '  "chassisLightMap": {\n'
                                .. table.concat(cparts, ",\n")
                                .. "\n  }"
                        end
                    end

                    do
                        local vm = PERSIST.configVehicleMod
                        if type(vm) == "table" then
                            local function encMap(t)
                                local arr = {}
                                for k, v in pairs(t or {}) do
                                    k, v = tonumber(k), tonumber(v)
                                    if k and v and v > 0 then
                                        arr[#arr + 1] = string.format('      "%d": %d', k, v)
                                    end
                                end
                                table.sort(arr)
                                return arr
                            end
                            local sections = {}
                            for _, key in ipairs({
                                "wheelHub",
                                "brakeCaliper",
                                "canopy",
                                "chassisLight",
                                "plateBg",
                            }) do
                                local arr = encMap(vm[key])
                                if #arr > 0 then
                                    sections[#sections + 1] =
                                        string.format('    "%s": {\n%s\n    }', key, table.concat(arr, ",\n"))
                                end
                            end
                            if tonumber(vm.switchEffect) and tonumber(vm.switchEffect) > 0 then
                                sections[#sections + 1] =
                                    string.format('    "switchEffect": %d', tonumber(vm.switchEffect))
                            end
                            local refitParts = {}
                            for carId, styles in pairs(vm.refit or {}) do
                                carId = tonumber(carId)
                                if carId and type(styles) == "table" then
                                    local sarr = encMap(styles)
                                    if #sarr > 0 then
                                        refitParts[#refitParts + 1] = string.format(
                                            '      "%d": {\n%s\n      }',
                                            carId,
                                            table.concat(sarr, ",\n")
                                        )
                                    end
                                end
                            end
                            table.sort(refitParts)
                            if #refitParts > 0 then
                                sections[#sections + 1] = '    "refit": {\n'
                                    .. table.concat(refitParts, ",\n")
                                    .. "\n    }"
                            end
                            local accParts = {}
                            for carId, accs in pairs(vm.accessories or {}) do
                                carId = tonumber(carId)
                                if carId and type(accs) == "table" then
                                    local aarr = {}
                                    for accId, on in pairs(accs) do
                                        accId = tonumber(accId)
                                        if accId and on then
                                            aarr[#aarr + 1] = string.format('        "%d": 1', accId)
                                        end
                                    end
                                    table.sort(aarr)
                                    if #aarr > 0 then
                                        accParts[#accParts + 1] = string.format(
                                            '      "%d": {\n%s\n      }',
                                            carId,
                                            table.concat(aarr, ",\n")
                                        )
                                    end
                                end
                            end
                            table.sort(accParts)
                            if #accParts > 0 then
                                sections[#sections + 1] = '    "accessories": {\n'
                                    .. table.concat(accParts, ",\n")
                                    .. "\n    }"
                            end
                            if #sections > 0 then
                                parts[#parts + 1] = '  "vehicleMod": {\n'
                                    .. table.concat(sections, ",\n")
                                    .. "\n  }"
                            end
                        end
                    end
                    local msParts = {}
                    for idx, res in pairs(PERSIST.configMotionSlots or {}) do
                        idx, res = tonumber(idx), tonumber(res)
                        if idx and idx > 0 and res and res > 0 and F.isEmoteRes(res) then
                            msParts[#msParts + 1] = string.format('    "%d": %d', idx, res)
                        end
                    end
                    table.sort(msParts)
                    if #msParts > 0 then
                        parts[#parts + 1] = '  "motionSlots": {\n' .. table.concat(msParts, ",\n") .. "\n  }"
                    end
                    local petRes = tonumber(PERSIST.configPetResID) or tonumber(_G.AddOutfitLastPetRes)
                    if petRes and petRes >= 50001 and petRes < 50100 then
                        parts[#parts + 1] = string.format('  "pet": %d', petRes)
                    end
                    local pcSrc = _G.NTHUY2004_ProfileCustomEquip or PERSIST.profileCustom
                    if pcSrc and next(pcSrc) then
                        local pcParts = {}
                        for pk, pv in pairs(pcSrc) do
                            if pv ~= nil and pv ~= "" then
                                if type(pv) == "number" then
                                    pcParts[#pcParts + 1] = string.format('    "%s": %d', pk, pv)
                                elseif type(pv) == "string" then
                                    local num = tonumber(pv)
                                    if num and tostring(num) == pv then
                                        pcParts[#pcParts + 1] = string.format('    "%s": %d', pk, num)
                                    else
                                        local esc = pv:gsub("\\", "\\\\"):gsub('"', '\\"')
                                        pcParts[#pcParts + 1] = string.format('    "%s": "%s"', pk, esc)
                                    end
                                end
                            end
                        end
                        table.sort(pcParts)
                        if #pcParts > 0 then
                            parts[#parts + 1] = '  "profileCustom": {\n'
                                .. table.concat(pcParts, ",\n")
                                .. "\n  }"
                        end
                    end
                    local depotSeen, depotParts = {}, {}
                    local depotBestByGroup = {}
                    local depotBestXSuit = {}
                    local function trackDepotRes(res)
                        res = tonumber(res)
                        if not res or res <= 0 then
                            return
                        end
                        if F.shouldPersistDepotGrant and not F.shouldPersistDepotGrant(res) then
                            return
                        end
                        local xsMeta = nil
                        pcall(function()
                            local fls = _G.NTHUY2004_FreeLobbyShop
                            if type(fls) == "table" and fls.resolveXSuitMeta then
                                xsMeta = fls.resolveXSuitMeta(res)
                            end
                        end)
                        if xsMeta and xsMeta.period then
                            local key = tostring(xsMeta.period) .. ":" .. tostring(xsMeta.branchId or 0)
                            local cur = depotBestXSuit[key]
                            if not cur or (tonumber(xsMeta.level) or 1) > (tonumber(cur.level) or 1) then
                                depotBestXSuit[key] = { res = res, level = tonumber(xsMeta.level) or 1 }
                            end
                            return
                        end
                        local gid, lvl = F.getWeaponUpgradeLevel and F.getWeaponUpgradeLevel(res)
                        if gid and lvl then
                            local cur = depotBestByGroup[gid]
                            if not cur or lvl > cur.level then
                                depotBestByGroup[gid] = { res = res, level = lvl }
                            end
                        else
                            depotSeen[res] = true
                        end
                    end
                    for res, on in pairs(PERSIST.configDepotItems or {}) do
                        if on then
                            trackDepotRes(res)
                        end
                    end
                    for res, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            trackDepotRes(res)
                        end
                    end

                    pcall(function()
                        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                        local entity = F.getEntity and F.getEntity()
                        if not LogicXSuit or not LogicXSuit.IsXSuit or not entity or not entity._data then
                            return
                        end
                        for i = 1, (entity._DataCount or #entity._data) do
                            local d = entity._data[i]
                            local res = d and tonumber(d.resID or d.res_id)
                            if res and (tonumber(d.count) or 0) > 0 and LogicXSuit.IsXSuit(res) then
                                trackDepotRes(res)
                            end
                        end
                    end)
                    for _, best in pairs(depotBestByGroup) do
                        depotSeen[best.res] = true
                    end
                    for _, best in pairs(depotBestXSuit) do
                        depotSeen[best.res] = true
                    end
                    for res in pairs(depotSeen) do
                        depotParts[#depotParts + 1] = tostring(res)
                    end
                    table.sort(depotParts, function(a, b)
                        return tonumber(a) < tonumber(b)
                    end)
                    if #depotParts > 0 then
                        parts[#parts + 1] = '  "depotItems": [' .. table.concat(depotParts, ", ") .. "]"
                    end

                    pcall(function()
                        local fls = _G.NTHUY2004_FreeLobbyShop
                        local unlocks = (type(fls) == "table" and fls._xsuitWorkshopUnlocks) or {}
                        local xu = {}
                        for _, u in pairs(unlocks) do
                            if type(u) == "table" and tonumber(u.period) and tonumber(u.itemId) then
                                xu[#xu + 1] = string.format(
                                    '    {"period":%d,"branchId":%d,"current":%d,"itemId":%d}',
                                    tonumber(u.period),
                                    tonumber(u.branchId) or 0,
                                    tonumber(u.current) or 1,
                                    tonumber(u.itemId)
                                )
                            end
                        end
                        table.sort(xu)
                        if #xu > 0 then
                            parts[#parts + 1] = '  "xsuitUnlocks": [\n' .. table.concat(xu, ",\n") .. "\n  ]"
                        end
                    end)
                    return "{\n" .. table.concat(parts, ",\n") .. "\n}\n"
                end

                function F.persistWrite(txt)
                    if not (io and io.open) then
                        return false
                    end
                    if PERSIST.path then
                        local f
                        pcall(function()
                            f = io.open(PERSIST.path, "w")
                        end)
                        if f then
                            f:write(txt)
                            f:close()
                            return true
                        end
                        PERSIST.path = nil
                    end
                    for _, p in ipairs(CONFIG_PATHS) do
                        local f
                        pcall(function()
                            f = io.open(p, "w")
                        end)
                        if not f then
                            pcall(function()
                                local dir = p:match("^(.*)/[^/]+$")
                                if dir and os and os.execute then
                                    os.execute('mkdir -p "' .. dir .. '"')
                                end
                            end)
                            pcall(function()
                                f = io.open(p, "w")
                            end)
                        end
                        if f then
                            f:write(txt)
                            f:close()
                            PERSIST.path = p
                            return true
                        end
                    end
                    return false
                end

                function F.persistFlush()
                    if not PERSIST.dirty then
                        return
                    end
                    PERSIST.dirty = false
                    pcall(function()
                        local txt = F.persistEncode()
                        if txt == PERSIST.lastWritten then
                            return
                        end
                        if F.persistWrite(txt) then
                            PERSIST.lastWritten = txt
                        end
                    end)
                end

                F.persistMarkDirty = function()
                    PERSIST.dirty = true
                    if PERSIST.scheduled then
                        return
                    end
                    PERSIST.scheduled = true
                    F.later(2.0, function()
                        PERSIST.scheduled = false
                        F.persistFlush()
                    end)
                end

                function F.saveOutfitConfigToDisk()
                    F.loadDumpExtraSkins()
                    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
                    for res, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            res = tonumber(res)
                            if
                                res
                                and res > 0
                                and F.shouldPersistDepotGrant
                                and F.shouldPersistDepotGrant(res)
                            then
                                PERSIST.configDepotItems[res] = true
                            end
                        end
                    end

                    pcall(function()
                        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                        local entity = F.getEntity and F.getEntity()
                        if not LogicXSuit or not LogicXSuit.IsXSuit or not entity or not entity._data then
                            return
                        end
                        for i = 1, (entity._DataCount or #entity._data) do
                            local d = entity._data[i]
                            local res = d and tonumber(d.resID or d.res_id)
                            if res and (tonumber(d.count) or 0) > 0 and LogicXSuit.IsXSuit(res) then
                                if F.registerDumpExtraSkin then
                                    F.registerDumpExtraSkin(res)
                                end
                                PERSIST.configDepotItems[res] = true
                                local fls = _G.NTHUY2004_FreeLobbyShop
                                if
                                    type(fls) == "table"
                                    and fls.rememberXSuitWorkshopUnlock
                                    and fls.resolveXSuitMeta
                                then
                                    local meta = fls.resolveXSuitMeta(res)
                                    if meta then
                                        fls.rememberXSuitWorkshopUnlock(meta)
                                    end
                                end
                            end
                        end
                    end)
                    if F.collapsePersistedDepotUpgradeGroups then
                        F.collapsePersistedDepotUpgradeGroups()
                    end
                    PERSIST.dirty = true
                    F.persistFlush()
                    return PERSIST.path
                        or (F.outfitConfigFileName and F.outfitConfigFileName())
                        or "NTHUY2004_cfg453_outfit_script.json"
                end

                _G.SaveOutfitConfig = function()
                    local ok, path = false, nil
                    pcall(function()
                        if F.refreshOutfitConfigPaths then
                            F.refreshOutfitConfigPaths()
                        end
                        if F.saveOutfitConfigToDisk then
                            path = F.saveOutfitConfigToDisk()
                            ok = path ~= nil
                        end
                    end)
                    if ok then
                        Notify(
                            "Da luu config skin: "
                                .. tostring(
                                    path or (F.outfitConfigFileName and F.outfitConfigFileName()) or "?"
                                )
                        )
                    else
                        Notify("Luu config skin that bai")
                    end
                    return ok
                end

                function F.applyProfileCustomFromPersist()
                    local pc = PERSIST.loaded and PERSIST.loaded.profileCustom
                    if not pc or not next(pc) then
                        return
                    end
                    _G.NTHUY2004_ProfileCustomEquip = _G.NTHUY2004_ProfileCustomEquip or {}
                    for k, v in pairs(pc) do
                        if v ~= nil and v ~= "" then
                            _G.NTHUY2004_ProfileCustomEquip[k] = v
                        end
                    end
                end

                function F.persistProfileCustomSave()
                    local E = _G.NTHUY2004_ProfileCustomEquip
                    if not E or not next(E) then
                        return
                    end
                    PERSIST.profileCustom = PERSIST.profileCustom or {}
                    for k, v in pairs(E) do
                        if v ~= nil and v ~= "" then
                            PERSIST.profileCustom[k] = v
                        end
                    end
                    F.persistMarkDirty()
                end

                function F.persistParse(txt)
                    if not txt or #txt == 0 then
                        return nil
                    end
                    local out = { weapons = {}, grenades = {}, vehicleSlots = {} }
                    local parsed = false
                    pcall(function()
                        local t = json and json.decode and json.decode(txt)
                        if type(t) == "table" then
                            for k, v in pairs(t) do
                                if k == "weapons" and type(v) == "table" then
                                    for wk, wv in pairs(v) do
                                        local wid, res = tonumber(wk), tonumber(wv)
                                        if F.isValidWeaponPersistEntry(wid, res) then
                                            out.weapons[wid] = res
                                        end
                                    end
                                elseif k == "grenades" and type(v) == "table" then
                                    for gk, gv in pairs(v) do
                                        local base, res = tonumber(gk), tonumber(gv)
                                        if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                                            out.grenades[base] = res
                                        end
                                    end
                                elseif k == "vehicleSlots" and type(v) == "table" then
                                    for stk, slotMap in pairs(v) do
                                        local st = tonumber(stk)
                                        if st then
                                            out.vehicleSlots[st] = out.vehicleSlots[st] or {}
                                            for idxStr, res in pairs(slotMap) do
                                                local idx, r = tonumber(idxStr), tonumber(res)
                                                if idx and r and r > 0 then
                                                    out.vehicleSlots[st][idx] = r
                                                end
                                            end
                                        end
                                    end
                                elseif k == "chassisLightMap" and type(v) == "table" then
                                    out.chassisLightMap = {}
                                    for vk, lv in pairs(v) do
                                        local vid, lid = tonumber(vk), tonumber(lv)
                                        if vid and lid and F.isChassisLightId(lid) then
                                            out.chassisLightMap[vid] = lid
                                        end
                                    end
                                elseif k == "vehicleMod" and type(v) == "table" then
                                    out.vehicleMod = {
                                        wheelHub = {},
                                        brakeCaliper = {},
                                        canopy = {},
                                        chassisLight = {},
                                        plateBg = {},
                                        refit = {},
                                        accessories = {},
                                        switchEffect = tonumber(v.switchEffect),
                                    }
                                    local function loadMap(src, dst)
                                        if type(src) ~= "table" then
                                            return
                                        end
                                        for sk, sv in pairs(src) do
                                            local a, b = tonumber(sk), tonumber(sv)
                                            if a and b and b > 0 then
                                                dst[a] = b
                                            end
                                        end
                                    end
                                    loadMap(v.wheelHub, out.vehicleMod.wheelHub)
                                    loadMap(v.brakeCaliper, out.vehicleMod.brakeCaliper)
                                    loadMap(v.canopy, out.vehicleMod.canopy)
                                    loadMap(v.chassisLight, out.vehicleMod.chassisLight)
                                    loadMap(v.plateBg, out.vehicleMod.plateBg)
                                    if type(v.refit) == "table" then
                                        for ck, styles in pairs(v.refit) do
                                            local carId = tonumber(ck)
                                            if carId and type(styles) == "table" then
                                                out.vehicleMod.refit[carId] = {}
                                                loadMap(styles, out.vehicleMod.refit[carId])
                                            end
                                        end
                                    end
                                    if type(v.accessories) == "table" then
                                        for ck, accs in pairs(v.accessories) do
                                            local carId = tonumber(ck)
                                            if carId and type(accs) == "table" then
                                                out.vehicleMod.accessories[carId] = {}
                                                for ak, av in pairs(accs) do
                                                    local accId = tonumber(ak)
                                                    if accId and av then
                                                        out.vehicleMod.accessories[carId][accId] = 1
                                                    end
                                                end
                                            end
                                        end
                                    end
                                elseif k == "motionSlots" and type(v) == "table" then
                                    out.motionSlots = {}
                                    for idxStr, res in pairs(v) do
                                        local idx, r = tonumber(idxStr), tonumber(res)
                                        if idx and idx > 0 and r and r > 0 then
                                            out.motionSlots[idx] = r
                                        end
                                    end
                                elseif k == "profileCustom" and type(v) == "table" then
                                    out.profileCustom = {}
                                    for pk, pv in pairs(v) do
                                        if pv ~= nil and pv ~= "" then
                                            out.profileCustom[pk] = pv
                                        end
                                    end
                                elseif k == "depotItems" and type(v) == "table" then
                                    out.depotItems = {}
                                    for _, res in ipairs(v) do
                                        local r = tonumber(res)
                                        if r and r > 0 then
                                            out.depotItems[#out.depotItems + 1] = r
                                        end
                                    end
                                elseif k == "xsuitUnlocks" and type(v) == "table" then
                                    out.xsuitUnlocks = {}
                                    for _, u in ipairs(v) do
                                        if type(u) == "table" then
                                            local period = tonumber(u.period)
                                            local itemId = tonumber(u.itemId)
                                            if period and itemId then
                                                out.xsuitUnlocks[#out.xsuitUnlocks + 1] = {
                                                    period = period,
                                                    branchId = tonumber(u.branchId) or 0,
                                                    current = tonumber(u.current) or tonumber(u.level) or 1,
                                                    itemId = itemId,
                                                }
                                            end
                                        end
                                    end
                                else
                                    local n = tonumber(v)
                                    if n and n > 0 then
                                        out[k] = n
                                    end
                                end
                            end
                            parsed = true
                        end
                    end)
                    if not parsed then
                        for k, v in txt:gmatch('"([%w_]+)"%s*:%s*(%d+)') do
                            local n = tonumber(v)
                            if n and n > 0 then
                                local wid = tonumber(k)
                                if wid and F.isValidWeaponPersistEntry(wid, n) then
                                    out.weapons[wid] = n
                                elseif not wid then
                                    out[k] = n
                                end
                            end
                        end
                    end
                    return out
                end

                function F.persistApplyParsedFile(txt, path, isModeFile)
                    if not txt then
                        return false
                    end
                    PERSIST.path = isModeFile and path or nil
                    PERSIST.lastWritten = isModeFile and txt or nil
                    PERSIST.loaded = F.persistParse(txt)
                    if not isModeFile then
                        PERSIST.dirty = true
                    end
                    F.applyProfileCustomFromPersist()
                    F.persistLoadSlotsFromSaved(PERSIST.loaded)
                    F.persistLoadDepotItemsFromSaved(PERSIST.loaded)
                    F.persistLoadXSuitUnlocksFromSaved(PERSIST.loaded)
                    if PERSIST.loaded and PERSIST.loaded.vehicleSlots then
                        PERSIST.configVehicleSlots = PERSIST.loaded.vehicleSlots
                    end
                    if PERSIST.loaded and PERSIST.loaded.weapons then
                        local raw = PERSIST.loaded.weapons
                        PERSIST.configWeapons = F.sanitizeConfigWeapons(raw)
                        if next(raw) and not next(PERSIST.configWeapons) then
                            F.persistMarkDirty()
                        elseif next(raw) then
                            for wid, res in pairs(raw) do
                                if not F.isValidWeaponPersistEntry(tonumber(wid), tonumber(res)) then
                                    F.persistMarkDirty()
                                    break
                                end
                            end
                        end
                    end
                    if PERSIST.loaded and PERSIST.loaded.grenades then
                        PERSIST.configGrenades = {}
                        local cch = F.cache()
                        cch.grenades = cch.grenades or {}
                        MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
                        for base, res in pairs(PERSIST.loaded.grenades) do
                            base, res = tonumber(base), tonumber(res)
                            if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                                PERSIST.configGrenades[base] = res
                                cch.grenades[base] = { resID = res, insID = R.resToIns[res] or 0 }
                                MATCH_CONFIG.grenadeSkins[base] = res
                            end
                        end
                    end
                    PERSIST.lobbyVehicleSubType =
                        tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleSubType)
                    PERSIST.lobbyVehicleResID = tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleResID)
                    PERSIST.lobbyVehicleIns = tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleIns)
                    if
                        PERSIST.lobbyVehicleSubType
                        or PERSIST.lobbyVehicleIns
                        or PERSIST.lobbyVehicleResID
                    then
                        if
                            F.isChassisLightId(PERSIST.lobbyVehicleResID)
                            or PERSIST.lobbyVehicleSubType == CHASSIS_LIGHT_SUB
                            or not F.isVehicleRes(PERSIST.lobbyVehicleResID)
                        then
                            PERSIST.lobbyVehicleSubType = nil
                            PERSIST.lobbyVehicleResID = nil
                            PERSIST.lobbyVehicleIns = nil
                        else
                            _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or {}
                            _G.AddOutfitLobbyVeh.manual = true
                            _G.AddOutfitLobbyVeh.subType = PERSIST.lobbyVehicleSubType
                            _G.AddOutfitLobbyVeh.resID = PERSIST.lobbyVehicleResID
                            _G.AddOutfitLobbyVeh.insID = PERSIST.lobbyVehicleIns
                            F.rememberVehicleSkinMap(PERSIST.lobbyVehicleResID, PERSIST.lobbyVehicleIns)
                        end
                    end
                    PERSIST.hallThemeResID = tonumber(PERSIST.loaded and PERSIST.loaded.hallTheme)
                    PERSIST.hallThemeIns = nil
                    if PERSIST.hallThemeResID then
                        _G.AddOutfitLobbyTheme = _G.AddOutfitLobbyTheme or {}
                        _G.AddOutfitLobbyTheme.manual = true
                        _G.AddOutfitLobbyTheme.resID = PERSIST.hallThemeResID
                    end
                    PERSIST.configChassisLight = tonumber(PERSIST.loaded and PERSIST.loaded.chassisLight)
                    if PERSIST.loaded and PERSIST.loaded.chassisLightMap then
                        PERSIST.configChassisLightMap = PERSIST.loaded.chassisLightMap
                    end
                    if PERSIST.loaded and type(PERSIST.loaded.vehicleMod) == "table" then
                        PERSIST.configVehicleMod = PERSIST.loaded.vehicleMod
                    end
                    return true
                end

                function F.persistLoadFromDisk()
                    if not (io and io.open) then
                        return
                    end
                    pcall(F.refreshOutfitConfigPaths)
                    pcall(function()
                        for _, p in ipairs(CONFIG_PATHS) do
                            local f
                            pcall(function()
                                f = io.open(p, "r")
                            end)
                            if f then
                                local txt = f:read("*a")
                                f:close()
                                if F.persistApplyParsedFile(txt, p, true) then
                                    return
                                end
                            end
                        end
                    end)
                end

                function F.persistApplyLoaded()
                    local saved = PERSIST.loaded
                    if not saved then
                        return
                    end
                    PERSIST.loaded = nil
                    local cch = F.cache()
                    local any = false
                    for _, s in ipairs(PERSIST_SLOTS) do
                        local res = tonumber(saved[s[1]])
                            or tonumber(PERSIST.configSlots and PERSIST.configSlots[s[1]])
                        if res and res > 0 and not cch[s[2]] then
                            local ins = R.resToIns[res]
                            if ins then
                                cch[s[2]], cch[s[3]] = res, ins
                                _G[s[4]] = res
                                any = true
                            end
                        end
                    end
                    PERSIST.configWeapons = F.sanitizeConfigWeapons(saved.weapons or PERSIST.configWeapons)
                    if saved.weapons and F.reapplyWeaponsFromConfig() then
                        any = true
                    end
                    if saved.grenades then
                        PERSIST.configGrenades = {}
                        cch.grenades = cch.grenades or {}
                        MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
                        for base, res in pairs(saved.grenades) do
                            base, res = tonumber(base), tonumber(res)
                            if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                                PERSIST.configGrenades[base] = res
                                cch.grenades[base] = { resID = res, insID = R.resToIns[res] or 0 }
                                MATCH_CONFIG.grenadeSkins[base] = res
                                any = true
                            end
                        end
                        pcall(F.applyInitialConsumableAvatar)
                    end
                    if saved.vehicleSlots then
                        PERSIST.configVehicleSlots = saved.vehicleSlots
                        if F.reapplyVehicleSlotsFromConfig(true) then
                            any = true
                        end
                    end
                    if saved.hallTheme then
                        PERSIST.hallThemeResID = tonumber(saved.hallTheme)
                        if PERSIST.hallThemeResID and F.reapplyHallThemeFromConfig(true) then
                            any = true
                        end
                    end
                    if saved.chassisLight then
                        PERSIST.configChassisLight = tonumber(saved.chassisLight)
                    end
                    if saved.chassisLightMap then
                        PERSIST.configChassisLightMap = saved.chassisLightMap
                    end
                    if saved.motionSlots then
                        F.persistLoadMotionSlotsFromSaved(saved)
                        if F.applyPersistedMotionSlots() then
                            any = true
                        end
                    end
                    if saved.pet then
                        local petId = tonumber(saved.pet)
                        if petId and petId >= 50001 and petId < 50100 then
                            PERSIST.configPetResID = petId
                            _G.AddOutfitLastPetRes = petId
                            _G.OutfitMap = _G.OutfitMap or {}
                            _G.OutfitMap.Pet = petId
                            any = true
                        end
                    end
                    if any then
                        _matchApplied = false
                        F.perfInvalidateLobby()
                    end
                end

                function F.getEntity()
                    local ok, dc = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_data_center")
                    if not ok or not dc then
                        return nil
                    end
                    local ok2, e = pcall(dc.GetWardrobeData)
                    return ok2 and e or nil
                end

                function F.firstInsForRes(entity, resID)
                    local arr = entity.ResIDToIndexArrayMap and entity.ResIDToIndexArrayMap[resID]
                    if not arr then
                        return nil
                    end
                    for _, idx in pairs(arr) do
                        local d = entity._data[idx]
                        if d and d.count and d.count > 0 then
                            return d.insID
                        end
                    end
                    return nil
                end

                function F.injectOne(entity, resID, insID, addCount)
                    resID, insID = tonumber(resID), tonumber(insID)
                    addCount = tonumber(addCount) or 1
                    if not resID or not insID then
                        return false
                    end

                    if resID >= 1501001000 and resID < 1501002000 then
                        resID = resID - 1000
                    elseif resID >= 1502001000 and resID < 1502002000 then
                        resID = resID - 1000
                    end
                    local ownedIns = F.firstInsForRes(entity, resID)
                    if ownedIns then
                        if addCount > 0 and F.isStackableDepotItem(resID) then
                            return F.addDepotItemStack(entity, resID, ownedIns, addCount, nil)
                        end
                        F.ensureInjectedItemAlive(entity, resID, ownedIns)
                        R.resToIns[resID] = ownedIns
                        R.insToRes[ownedIns] = resID
                        F.indexWeaponSkin(resID, ownedIns)
                        return true
                    end
                    local row = {
                        instid = insID,
                        res_id = resID,
                        count = addCount > 0 and addCount or 1,
                        lock_cnt = 0,
                        isnew = 0,
                        valid_hours = 0,
                        expire_ts = 0,
                    }
                    entity:AddData(row)
                    pcall(function()
                        if entity.LoadConfigForData and CDataTable and CDataTable.GetTableData then
                            local idx = entity._DataCount
                            if idx and entity._data[idx] then
                                entity:LoadConfigForData(entity._data[idx], CDataTable.GetTableData)
                                local d = entity._data[idx]
                                if d.resID == nil then
                                    d.resID = resID
                                end
                                if d.expireTS == nil then
                                    d.expireTS = 0
                                end

                                if F.isVehicleRes(resID) then
                                    local c = F.cfg(resID)
                                    local mainCfg = tonumber(c and c.WardrobeMainTab)
                                    if mainCfg == PAGE_PARACHUTE then
                                        d.mainTabType = PAGE_PARACHUTE
                                        local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID)
                                        if tab and tab ~= 0 and tab ~= "" then
                                            d.subTabType = tab
                                        end
                                    else
                                        local tab = F.vehicleWardrobeTab(resID)
                                        if tab ~= nil and tab ~= 0 and tab ~= "" then
                                            d.subTabType = tab
                                            d.mainTabType = PAGE_VEHICLE
                                        end
                                        local st = F.vehicleSlotSubType(resID)
                                        if st then
                                            d.itemSubType = st
                                        end
                                    end
                                elseif F.isEmoteRes(resID) then
                                    local c = F.cfg(resID)
                                    d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID) or 21
                                    if tab == 0 or tab == "" then
                                        tab = 21
                                    end
                                    d.subTabType = tab
                                    if c and c.ItemSubType then
                                        d.itemSubType = c.ItemSubType
                                    end
                                    if c and c.ItemType then
                                        d.itemType = c.ItemType
                                    end
                                elseif F.isParachuteRes(resID) or F.isGlideRes(resID) then
                                    local c = F.cfg(resID)
                                    d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID)
                                    if tab and tab ~= 0 and tab ~= "" then
                                        d.subTabType = tab
                                    end
                                    d.expire_ts = 0
                                    d.expireTS = 0
                                end
                            end
                        end
                    end)
                    R.insToRes[insID] = resID
                    R.resToIns[resID] = insID
                    F.indexWeaponSkin(resID, insID)
                    return true
                end

                function F.isStackableDepotItem(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    local c = F.cfg(resID)
                    if not c then
                        return true
                    end
                    local t = tonumber(c.ItemType or c.itemType)
                    if not t then
                        return true
                    end
                    if
                        t == 30
                        or t == 21
                        or t == 6
                        or t == 39
                        or t == 620
                        or t == 16
                        or t == 102
                        or t == 103
                        or t == 618
                        or t == 619
                    then
                        return true
                    end
                    if t == 100 then
                        local field
                        pcall(function()
                            if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
                                field = _G.UnlimitedCash.moneyTypeToField(resID)
                            end
                        end)
                        return field == nil
                    end
                    local st = F.subType(c)
                    if GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st] then
                        return false
                    end
                    if t == 1 or t == 4 or t == 8 or t == 9 or t == 11 or t == 22 or t == 25 or t == 40 then
                        return false
                    end
                    if t == 500 or t == 501 or t == 502 then
                        return false
                    end
                    if F.isVehicleRes and F.isVehicleRes(resID) then
                        return false
                    end
                    if F.isEmoteRes and F.isEmoteRes(resID) then
                        return false
                    end
                    return true
                end

                function F.isDataMgrCurrency(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    local field
                    pcall(function()
                        if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
                            field = _G.UnlimitedCash.moneyTypeToField(resID)
                        end
                    end)
                    return field ~= nil
                end

                function F.grantCurrencyItem(resID, count)
                    resID = tonumber(resID)
                    count = tonumber(count) or 1
                    if not resID or count < 1 then
                        return false
                    end
                    local field
                    pcall(function()
                        if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
                            field = _G.UnlimitedCash.moneyTypeToField(resID)
                        end
                    end)
                    if not field or not DataMgr then
                        return false
                    end
                    DataMgr[field] = (tonumber(DataMgr[field]) or 0) + count
                    pcall(function()
                        if EventSystem and EVENTTYPE_DATA_MGR then
                            if EVENTID_DATAMGR_TICKET_CHANGE then
                                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE)
                            end
                            if EVENTID_DATAMGR_GOLD_CHANGE then
                                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_GOLD_CHANGE)
                            end
                        end
                    end)
                    return true
                end

                function F.notifyDepotItemChange(resID, insID, count, markNew)
                    resID, insID = tonumber(resID), tonumber(insID)
                    count = tonumber(count) or 1
                    if not resID or not insID or insID <= 0 then
                        return false
                    end
                    local changeList = {
                        [insID] = {
                            isnew = markNew and 1 or 0,
                            instid = insID,
                            res_id = resID,
                            count = count,
                        },
                    }
                    pcall(function()
                        if EventSystem and EVENTTYPE_DATA_MGR then
                            if EVENTID_DATAMGR_HALL_DEPOT_CHANGE then
                                EventSystem:postEvent(
                                    EVENTTYPE_DATA_MGR,
                                    EVENTID_DATAMGR_HALL_DEPOT_CHANGE,
                                    changeList
                                )
                            end
                            if markNew and EVENTID_DATAMGR_HALL_DEPOT_ADD_NEW then
                                EventSystem:postEvent(
                                    EVENTTYPE_DATA_MGR,
                                    EVENTID_DATAMGR_HALL_DEPOT_ADD_NEW,
                                    changeList
                                )
                            end
                        end
                    end)
                    return true
                end

                function F.addDepotItemStack(entity, resID, insID, addCount, opts)
                    entity = entity or F.getEntity()
                    resID, insID = tonumber(resID), tonumber(insID)
                    addCount = tonumber(addCount) or 1
                    if not entity or not resID or not insID or addCount < 1 then
                        return false
                    end
                    local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
                    if not d then
                        return false
                    end
                    local newCount = (tonumber(d.count) or 0) + addCount
                    d.count = newCount
                    d.expire_ts = 0
                    d.expireTS = 0
                    d.valid_hours = 0
                    pcall(function()
                        if
                            entity.LoadConfigForData
                            and CDataTable
                            and CDataTable.GetTableData
                            and not d.bConfigLoaded
                        then
                            entity:LoadConfigForData(d, CDataTable.GetTableData)
                        end
                    end)
                    pcall(function()
                        if entity.ChangeData then
                            entity:ChangeData({
                                instid = insID,
                                res_id = resID,
                                count = newCount,
                                lock_cnt = d.lock_cnt or 0,
                                isnew = (opts and opts.markNew) and 1 or ((d.isNew == true) and 1 or 0),
                                valid_hours = 0,
                                expire_ts = 0,
                            })
                        end
                    end)
                    if
                        F.isInjectedIns(insID)
                        or F.isInjectedRes(resID)
                        or insID >= (DUMP_INS_BASE or 2100000000)
                    then
                        R.resToIns[resID] = insID
                        R.insToRes[insID] = resID
                    end
                    if opts and opts.markNew then
                        F.markDepotItemNew(resID, insID, addCount)
                    else
                        F.notifyDepotItemChange(resID, insID, newCount, false)
                    end
                    return true
                end

                function F.grantDepotItem(resID, count, opts)
                    count = tonumber(count) or 1
                    resID = tonumber(resID)
                    opts = type(opts) == "table" and opts or nil
                    if not resID or resID <= 0 or count < 1 then
                        return false
                    end
                    if F.grantCurrencyItem(resID, count) then
                        return true
                    end
                    local entity = F.getEntity()
                    if not entity or not entity.bInit then
                        return false
                    end
                    local ownedIns = F.firstInsForRes(entity, resID)
                    if ownedIns and F.isStackableDepotItem(resID) then
                        local ok = F.addDepotItemStack(entity, resID, ownedIns, count, opts)
                        if ok then
                            F.refreshWardrobe()
                            F.scheduleInjectRefresh()
                        end
                        return ok
                    end
                    local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                    if not F.injectOne(entity, resID, insID, count) then
                        return false
                    end
                    insID = R.resToIns[resID] or insID
                    if opts and opts.markNew and insID then
                        F.markDepotItemNew(resID, insID, count)
                    elseif insID then
                        F.notifyDepotItemChange(resID, insID, count, false)
                    end
                    if F.registerDumpExtraSkin then
                        F.registerDumpExtraSkin(resID)
                    end
                    F.invalidateDepotGroupCache()
                    F.refreshWardrobe()
                    F.scheduleInjectRefresh()
                    F.scheduleDepotReinject()
                    return true
                end

                function F.getEntityDepotCount(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return 0
                    end
                    local entity = F.getEntity()
                    if entity and entity.GetItemCountByResID then
                        local n = tonumber(entity:GetItemCountByResID(resID)) or 0
                        if n > 0 then
                            return n
                        end
                    end
                    local ins = R.resToIns[resID]
                    if ins and entity and entity.GetDataByInsID then
                        local d = entity:GetDataByInsID(ins)
                        if d and (tonumber(d.count) or 0) > 0 then
                            return tonumber(d.count) or 0
                        end
                    end
                    return 0
                end

                function F.getDepotCount(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return 0
                    end
                    if F.isDataMgrCurrency(resID) then
                        local n = 0
                        pcall(function()
                            local UC = _G.UnlimitedCash
                            if UC and UC.getBalance then
                                n = tonumber(UC.getBalance(resID)) or 0
                            end
                        end)
                        return n
                    end

                    if type(FLS) == "table" and FLS.getXSuitVirtualMatCount then
                        local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
                        if vn > 0 then
                            return vn
                        end
                    end
                    local n = F.getEntityDepotCount(resID)
                    if n > 0 then
                        return n
                    end
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        if F._wardrobeOrigCountByRes and wd then
                            n = tonumber(F._wardrobeOrigCountByRes(wd, resID)) or 0
                        elseif wd and wd.GetHallDepotItemCountByResID then
                            n = tonumber(wd:GetHallDepotItemCountByResID(resID)) or 0
                        end
                    end)
                    return n
                end

                function F.consumeDepotItem(resID, count)
                    resID = tonumber(resID)
                    count = tonumber(count) or 1
                    if not resID or count < 1 then
                        return false
                    end
                    if F.isDataMgrCurrency(resID) then
                        local ok = false
                        pcall(function()
                            local UC = _G.UnlimitedCash
                            if UC and UC.spend then
                                ok = UC.spend(resID, count, true) == true
                            end
                        end)
                        return ok
                    end

                    if
                        type(FLS) == "table"
                        and FLS.spendXSuitVirtualMat
                        and FLS.isXSuitVirtualMat
                        and FLS.isXSuitVirtualMat(resID)
                    then
                        return FLS.spendXSuitVirtualMat(resID, count) == true
                    end
                    local entity = F.getEntity()
                    if not entity or not entity.bInit then
                        return false
                    end
                    if F.getDepotCount(resID) < count then
                        return false
                    end
                    local ownedIns = F.firstInsForRes(entity, resID) or R.resToIns[resID]
                    if not ownedIns then
                        return false
                    end
                    local d = entity.GetDataByInsID and entity:GetDataByInsID(ownedIns)
                    if not d then
                        return false
                    end
                    local cur = tonumber(d.count) or 0
                    if cur < count then
                        return false
                    end
                    local newCount = cur - count
                    d.count = newCount
                    d.expire_ts = 0
                    if d.expireTS ~= nil then
                        d.expireTS = 0
                    end
                    pcall(function()
                        if entity.ChangeData then
                            entity:ChangeData({
                                instid = ownedIns,
                                res_id = resID,
                                count = newCount,
                                lock_cnt = d.lock_cnt or 0,
                                isnew = 0,
                                valid_hours = 0,
                                expire_ts = 0,
                            })
                        end
                    end)
                    if F.isInjectedIns(ownedIns) or F.isInjectedRes(resID) or ownedIns >= 2100000000 then
                        R.resToIns[resID] = ownedIns
                        R.insToRes[ownedIns] = resID
                    end
                    F.notifyDepotItemChange(resID, ownedIns, newCount, false)
                    return true
                end

                function F.simulateWeaponUpgrade(instid, group_id, item_level, item_cost)
                    instid = tonumber(instid)
                    group_id = tonumber(group_id)
                    item_level = tonumber(item_level)
                    if not instid or not group_id or not item_level then
                        return false
                    end
                    local oldInsID = instid
                    local oldResID = nil
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local item = wd:GetHallDepotItemDataByInsID(instid)
                        if item then
                            oldResID = tonumber(item.resID or item.res_id)
                        end
                    end)
                    if not oldResID then
                        local entity = F.getEntity()
                        local d = entity and entity.GetDataByInsID and entity:GetDataByInsID(instid)
                        if d then
                            oldResID = tonumber(d.resID or d.res_id)
                        end
                    end
                    if not oldResID then
                        return false
                    end
                    local mgr = nil
                    pcall(function()
                        mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.ItemUpgradeModule)
                    end)
                    if not mgr then
                        return false
                    end
                    local groupList = mgr:GetUpgradeGroupByID(group_id)
                    if type(groupList) ~= "table" or not groupList[item_level] then
                        return false
                    end
                    local nextItemID = tonumber(groupList[item_level].ItemID)
                    if not nextItemID or nextItemID <= 0 then
                        return false
                    end
                    local function consumeCost(resID, need)
                        resID, need = tonumber(resID), tonumber(need) or 0
                        if not resID or need <= 0 then
                            return true
                        end
                        return F.consumeDepotItem(resID, need) == true
                    end
                    if type(item_cost) == "table" and next(item_cost) then
                        for costIns, costCnt in pairs(item_cost) do
                            costIns = tonumber(costIns)
                            costCnt = tonumber(costCnt) or 0
                            if costIns and costCnt > 0 then
                                local entity = F.getEntity()
                                local d = entity and entity.GetDataByInsID and entity:GetDataByInsID(costIns)
                                local resID = d and tonumber(d.resID or d.res_id)
                                if not resID or not consumeCost(resID, costCnt) then
                                    return false
                                end
                            end
                        end
                    else
                        local cfg = mgr.GetUpgradeCfg and mgr:GetUpgradeCfg(oldResID)
                        local matCfgs = (cfg and mgr.CreateMaterialList and mgr:CreateMaterialList(cfg))
                            or (mgr.GetItemUpgradeMaterialList and mgr:GetItemUpgradeMaterialList(oldResID))
                            or {}
                        if type(matCfgs) ~= "table" then
                            return false
                        end
                        for _, cost in ipairs(matCfgs) do
                            if not consumeCost(cost.CostItem, cost.CostItemNum) then
                                return false
                            end
                        end
                    end
                    local entity = F.getEntity()
                    if entity and F.purgeEntityDepotItem then
                        F.purgeEntityDepotItem(entity, oldResID, oldInsID)
                    end
                    pcall(function()
                        if F.unequipInjectedIns then
                            F.unequipInjectedIns(oldInsID, oldResID)
                        end
                    end)
                    if not F.grantDepotItem(nextItemID, 1) then
                        return false
                    end
                    if F.persistReplaceDepotItem then
                        F.persistReplaceDepotItem(oldResID, nextItemID)
                    end
                    pcall(function()
                        if F.saveWeaponToCache and F.weaponIdFromSkin then
                            local wid = F.weaponIdFromSkin(nextItemID)
                            local newInsID = tonumber(R.resToIns[nextItemID])
                            if wid and newInsID then
                                F.saveWeaponToCache(wid, nextItemID, newInsID)
                            end
                        end
                    end)
                    local newInsID = tonumber(R.resToIns[nextItemID])
                    if not newInsID then
                        pcall(function()
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local item = wd:GetHallDepotItemDataByResID(nextItemID)
                            if item then
                                newInsID = tonumber(item.insID or item.instid or item.ins_id)
                            end
                        end)
                    end
                    if not newInsID then
                        return false
                    end
                    local ret = { newInsID, oldInsID }
                    pcall(function()
                        local ItemUpGradeHandler = require("client.network.Protocol.ItemUpGradeHandler")
                        if ItemUpGradeHandler and ItemUpGradeHandler.on_upgrade_item_rsp then
                            ItemUpGradeHandler.on_upgrade_item_rsp(0, ret)
                        end
                    end)
                    pcall(function()
                        if F.refreshWardrobe then
                            F.refreshWardrobe()
                        end
                    end)
                    return true
                end

                function F.shouldMarkDepotItemNew(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if F.isDataMgrCurrency(resID) then
                        return false
                    end
                    local c = F.cfg(resID)
                    if not c then
                        return false
                    end
                    local t = tonumber(c.ItemType or c.itemType)
                    if t == 30 or t == 21 or t == 6 or t == 39 or t == 620 then
                        return true
                    end
                    local ok = false
                    pcall(function()
                        local WardrobeLogicManager = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if WardrobeLogicManager and WardrobeLogicManager.IsWardrobeShow then
                            ok = WardrobeLogicManager:IsWardrobeShow(c) == true
                        end
                    end)
                    return ok
                end

                function F.markDepotItemNew(resID, insID, count)
                    resID, insID = tonumber(resID), tonumber(insID)
                    count = tonumber(count) or 1
                    if not resID or not insID or insID <= 0 then
                        return false
                    end
                    if not F.shouldMarkDepotItemNew(resID) then
                        F.notifyDepotItemChange(resID, insID, count, false)
                        return false
                    end
                    local entity = F.getEntity()
                    if not entity then
                        return false
                    end
                    pcall(function()
                        if entity.ChangeItemNewState then
                            entity:ChangeItemNewState(insID, true)
                        end
                        local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
                        if d then
                            d.isNew = true
                            count = tonumber(d.count) or count
                        end
                    end)
                    F.notifyDepotItemChange(resID, insID, count, true)
                    return true
                end

                function F.reviveExpiredOwned(entity)
                    entity = entity or F.getEntity()
                    if not entity or not entity.bInit or not entity._data then
                        return
                    end
                    local now = 0
                    pcall(function()
                        local TimeUtil = require("client.common.time_util")
                        now = tonumber(TimeUtil.GetServerTimeInSec()) or 0
                    end)
                    if now <= 0 then
                        return
                    end
                    _G.AddOutfitRevived = _G.AddOutfitRevived or {}
                    local n = 0
                    for i = 1, (entity._DataCount or #entity._data) do
                        local d = entity._data[i]
                        if d then
                            local exp = tonumber(d.expire_ts or d.expireTS) or 0
                            local res = tonumber(d.res_id or d.resID)
                            local ins = tonumber(d.instid or d.insID)
                            if exp > 0 and exp <= now and res and ins and (tonumber(d.count) or 0) > 0 then
                                d.expire_ts = 0
                                if d.expireTS ~= nil then
                                    d.expireTS = 0
                                end
                                if d.valid_hours ~= nil then
                                    d.valid_hours = 0
                                end
                                _G.AddOutfitRevived[res] = ins
                                n = n + 1
                            end
                        end
                    end
                end

                function F.mergeRevivedIntoMaps()
                    for res, ins in pairs(_G.AddOutfitRevived or {}) do
                        if not R.resToIns[res] then
                            R.resToIns[res] = ins
                            R.insToRes[ins] = res
                            F.indexWeaponSkin(res, ins)
                        end
                    end
                end

                function F.injectArmory(resID, insID)
                    local wid = F.weaponIdFromSkin(resID)
                    if not wid then
                        return
                    end
                    local Arm = require("client.logic.armory.logic_armory")
                    Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
                    Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
                    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
                    if not Arm.rsp_list.skin_list[wid] then
                        Arm.rsp_list.skin_list[wid] = {}
                    end
                    Arm.rsp_list.skin_list[wid][resID] = { is_open = 1 }
                    Arm.WardrobeInsList = Arm.WardrobeInsList or {}
                    Arm.WardrobeInsList[resID] = insID
                end

                function F.mergeInjectedArmorySkins()
                    for _, skins in pairs(R.byWeapon) do
                        for resID, insID in pairs(skins) do
                            F.injectArmory(resID, insID)
                        end
                    end
                end

                local DUMP_INS_BASE = 2100000000
                local DUMP_SKIN_FILE = "NTHUY2004_cfg453_dump_skins.txt"

                function F.loadDumpExtraSkins()
                    _G.NTHUY2004_DumpExtraSkins = _G.NTHUY2004_DumpExtraSkins or {}
                    if _G.NTHUY2004_DumpExtraLoaded then
                        return
                    end
                    _G.NTHUY2004_DumpExtraLoaded = true
                    pcall(function()
                        local paths = GetConfigPaths(DUMP_SKIN_FILE)
                        for _, path in ipairs(paths) do
                            local ok, f = pcall(io.open, path, "r")
                            if ok and f then
                                for line in f:lines() do
                                    local id = tonumber((tostring(line or ""):gsub("%s+", "")))
                                    if id and id > 0 then
                                        _G.NTHUY2004_DumpExtraSkins[id] = true
                                    end
                                end
                                f:close()
                                return
                            end
                        end
                    end)
                end

                function F.shouldPersistDepotGrant(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if F.isDataMgrCurrency and F.isDataMgrCurrency(resID) then
                        return false
                    end
                    if F.isStackableDepotItem and F.isStackableDepotItem(resID) then
                        return false
                    end
                    return true
                end

                function F.registerDumpExtraSkin(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false
                    end
                    if not F.shouldPersistDepotGrant(resID) then
                        return false
                    end
                    F.loadDumpExtraSkins()
                    _G.NTHUY2004_DumpExtraSkins = _G.NTHUY2004_DumpExtraSkins or {}
                    _G.NTHUY2004_DumpExtraSkins[resID] = true
                    if F.persistRememberDepotItem then
                        F.persistRememberDepotItem(resID)
                    end
                    local insID = R.resToIns[resID]
                    if insID then
                        local c = F.cfg(resID)
                        local st = F.subType(c)
                        if GUN_SUB[st] or st == MELEE_ID then
                            F.injectArmory(resID, insID)
                        end
                        pcall(function()
                            local entity = F.getEntity()
                            if not entity then
                                return
                            end
                            if F.isVehicleRes and F.isVehicleRes(resID) then
                                F.fixInjectedVehicleDepotTabs(entity)
                            elseif F.isEmoteRes and F.isEmoteRes(resID) then
                                F.fixInjectedEmoteDepotTabs(entity)
                            elseif
                                (F.isParachuteRes and F.isParachuteRes(resID))
                                or (F.isGlideRes and F.isGlideRes(resID))
                            then
                                F.fixInjectedParachuteDepotTabs(entity)
                            end
                        end)
                    end
                    return true
                end

                function F.reinjectMissingDumpExtras(entity)
                    entity = entity or F.getEntity()
                    if not entity or not entity.bInit then
                        return 0
                    end
                    F.loadDumpExtraSkins()
                    local n = 0
                    for resID, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            resID = tonumber(resID)
                            if
                                resID
                                and not F.isInjectedDepotAlive(resID)
                                and F.shouldInjectDepotRes(resID)
                            then
                                local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                                if F.injectOne(entity, resID, insID) then
                                    n = n + 1
                                    insID = R.resToIns[resID] or insID
                                    local c = F.cfg(resID)
                                    local st = F.subType(c)
                                    if GUN_SUB[st] or st == MELEE_ID then
                                        F.injectArmory(resID, insID)
                                    end
                                end
                            end
                        end
                    end
                    if n > 0 then
                        pcall(F.fixInjectedVehicleDepotTabs, entity)
                        pcall(F.fixInjectedEmoteDepotTabs, entity)
                        pcall(F.fixInjectedParachuteDepotTabs, entity)
                    end
                    return n
                end

                function F.dumpInsForRes(resID)
                    return DUMP_INS_BASE + (tonumber(resID) or 0)
                end

                function F.injectDumpItem(resID, opts)
                    local cfg = _G.NTHUY2004Config
                    if cfg and cfg.ModSkin == false and not (cfg.FreeLobbyShop == true) and not ucOn() then
                        return false, "modskin_off"
                    end
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return false, "bad_id"
                    end
                    opts = type(opts) == "table" and opts or nil
                    F.loadDumpExtraSkins()
                    local entity = F.getEntity()
                    if not entity or not entity.bInit then
                        return false, "no_depot"
                    end
                    local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                    if not F.injectOne(entity, resID, insID) then
                        return false, "inject_fail"
                    end
                    insID = R.resToIns[resID] or insID
                    if opts and opts.markNew and insID then
                        F.markDepotItemNew(resID, insID, opts.count or 1)
                    end
                    local c = F.cfg(resID)
                    local st = F.subType(c)
                    if GUN_SUB[st] or st == MELEE_ID then
                        F.injectArmory(resID, R.resToIns[resID] or insID)
                    end
                    pcall(function()
                        if F.isVehicleRes and F.isVehicleRes(resID) then
                            F.fixInjectedVehicleDepotTabs(entity)
                            local pc = GameplayData
                                and GameplayData.GetPlayerController
                                and GameplayData.GetPlayerController()
                            if pc and F.directInjectVehicleSkinList then
                                F.directInjectVehicleSkinList(pc, { resID })
                            end
                        elseif F.isEmoteRes and F.isEmoteRes(resID) then
                            F.fixInjectedEmoteDepotTabs(entity)
                        elseif
                            (F.isParachuteRes and F.isParachuteRes(resID))
                            or (F.isGlideRes and F.isGlideRes(resID))
                        then
                            F.fixInjectedParachuteDepotTabs(entity)
                        end
                    end)
                    _G.NTHUY2004_DumpExtraSkins[resID] = true
                    if F.persistRememberDepotItem then
                        F.persistRememberDepotItem(resID)
                    end
                    pcall(F.sanitizeAllInjectedExpire)
                    pcall(F.ensureInjectedResources)
                    F.refreshWardrobe()
                    F.scheduleInjectRefresh()
                    return true, "ok"
                end

                _G.NTHUY2004_AddDumpSkinToDepot = function(resID)
                    local ok, err = F.injectDumpItem(resID)
                    return ok == true, err
                end

                local FLS = false
                function F.inferSubTypeFromItemId(resID)
                    resID = tonumber(resID) or 0
                    if resID >= 401000 and resID < 402000 then
                        return 401
                    end
                    if resID >= 402000 and resID < 403000 then
                        return 402
                    end
                    if resID >= 403000 and resID < 404000 then
                        return 403
                    end
                    if resID >= 404000 and resID < 405000 then
                        return 404
                    end
                    if resID >= 405000 and resID < 406000 then
                        return 405
                    end
                    if resID >= 452000 and resID < 453000 then
                        return 452
                    end
                    if resID >= 501001 and resID <= 501199 then
                        return 501
                    end
                    if resID >= 502001 and resID <= 502199 then
                        return 502
                    end
                    if resID >= 1401000 and resID < 1402000 then
                        return 701
                    end
                    return 0
                end

                function F.classifyDumpSkinCategory(resID)
                    resID = tonumber(resID) or 0
                    local st = F.subType(F.cfg(resID)) or F.inferSubTypeFromItemId(resID) or 0
                    local isBag = (st == 501 or st == 504)
                        or (resID >= 1501000000 and resID < 1502000000)
                        or (resID >= 501001 and resID <= 501199)
                    local isHat = (st == 401) or (resID >= 401000 and resID < 402000)
                    local isHelmet = (st == 502 or st == 505)
                        or (resID >= 1502000000 and resID < 1503000000)
                        or (resID >= 502001 and resID <= 502199)
                    if isHat or isHelmet then
                        return 1
                    end
                    if isBag then
                        return 2
                    end
                    if GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st] then
                        return 4
                    end
                    if resID >= 1101000000 and resID < 1200000000 then
                        return 4
                    end
                    if resID >= 612000000 and resID < 616000000 then
                        return 4
                    end
                    if resID >= 612000 and resID < 617000 then
                        return 4
                    end
                    if st == 701 or (resID >= 1401000 and resID < 1402000) then
                        return 0
                    end
                    if st == 402 or st == 407 then
                        return 0
                    end
                    if st == 404 or st == 405 or st == 452 then
                        return 3
                    end
                    if resID >= 404000 and resID < 406000 then
                        return 3
                    end
                    if resID >= 452000 and resID < 453000 then
                        return 3
                    end
                    if st == 403 or (resID >= 403000 and resID < 404000) then
                        return 3
                    end
                    if resID >= 1400000 and resID < 1500000 then
                        return 3
                    end
                    if resID >= 140000 and resID < 1401000 then
                        return 3
                    end
                    return 0
                end

                function F.shouldClearDumpSkin(resID, category)
                    resID = tonumber(resID)
                    category = tonumber(category) or 0
                    if not resID or resID <= 0 then
                        return false
                    end
                    F.loadDumpExtraSkins()
                    local inDepot = F.isInjectedRes(resID)
                    local inDump = _G.NTHUY2004_DumpExtraSkins and _G.NTHUY2004_DumpExtraSkins[resID] == true
                    if not inDepot and not inDump then
                        return false
                    end
                    if category == 0 then
                        return true
                    end
                    return F.classifyDumpSkinCategory(resID) == category
                end

                function F.isInjectedDepotAlive(resID, insID)
                    resID, insID = tonumber(resID), tonumber(insID)
                    if not insID or insID <= 0 then
                        if resID and resID > 0 then
                            insID = tonumber(R.resToIns[resID])
                        end
                    end
                    if not insID or insID <= 0 then
                        return false
                    end
                    if not R.insToRes[insID] then
                        return false
                    end
                    local entity = F.getEntity()
                    if not entity or not entity.GetDataByInsID then
                        return false
                    end
                    local d = entity:GetDataByInsID(insID)
                    return d ~= nil and (tonumber(d.count) or 0) > 0
                end

                function F.unequipInjectedIns(insID, resID)
                    insID = tonumber(insID)
                    if not insID or insID <= 0 then
                        return
                    end
                    pcall(function()
                        local AvatarData = require("client.logic.data.AvatarData")
                        AvatarData.RemoveRoleWearDataByValue(insID)
                    end)
                    pcall(function()
                        local cch = F.cache()
                        local function clearSlot(resKey, insKey)
                            if tonumber(cch[insKey]) == insID then
                                cch[resKey], cch[insKey] = nil, nil
                            end
                        end
                        clearSlot("outfitRes", "outfitIns")
                        clearSlot("hatRes", "hatIns")
                        clearSlot("maskRes", "maskIns")
                        clearSlot("glassRes", "glassIns")
                        clearSlot("tshirtRes", "tshirtIns")
                        clearSlot("pantsRes", "pantsIns")
                        clearSlot("shoesRes", "shoesIns")
                        clearSlot("bagRes", "bagIns")
                        clearSlot("helmetRes", "helmetIns")
                        clearSlot("parachuteRes", "parachuteIns")
                        clearSlot("gliderRes", "gliderIns")
                        clearSlot("glovesRes", "glovesIns")
                        for wid, w in pairs(cch.weapons or {}) do
                            if w and tonumber(w.insID) == insID then
                                cch.weapons[wid] = nil
                            end
                        end
                    end)
                    if resID and tonumber(resID) == tonumber(_G.BackpackSkin) then
                        _G.BackpackSkin = nil
                    end
                    if resID and tonumber(resID) == tonumber(_G.HelmetSkin) then
                        _G.HelmetSkin = nil
                    end
                end

                function F.purgeEntityDepotItem(entity, resID, insID)
                    entity = entity or F.getEntity()
                    resID, insID = tonumber(resID), tonumber(insID)
                    if not entity or not insID or insID <= 0 then
                        return false
                    end

                    local removed = false
                    local function zeroData(d)
                        if not d then
                            return
                        end
                        d.count = 0
                        d.insID = 0
                        d.instid = 0
                        d.ins_id = 0
                        d.resID = 0
                        d.res_id = 0
                        removed = true
                    end

                    pcall(function()
                        for _, fn in ipairs({
                            "DeleteData",
                            "RemoveData",
                            "DelDataByInsID",
                            "DeleteDataByInsID",
                            "RemoveDataByInsID",
                        }) do
                            if entity[fn] then
                                entity[fn](entity, insID)
                                removed = true
                            end
                        end
                    end)

                    pcall(function()
                        if entity._data then
                            for i = 1, (entity._DataCount or #entity._data) do
                                local d = entity._data[i]
                                if d then
                                    local ins = tonumber(d.insID or d.instid or d.ins_id)
                                    local res = tonumber(d.resID or d.res_id)
                                    if ins == insID or (resID and res == resID and ins == insID) then
                                        zeroData(d)
                                    end
                                end
                            end
                        end
                    end)

                    pcall(function()
                        if entity.GetDataByInsID then
                            zeroData(entity:GetDataByInsID(insID))
                        end
                    end)

                    pcall(function()
                        if resID and entity.ResIDToIndexArrayMap then
                            entity.ResIDToIndexArrayMap[resID] = nil
                        end
                        for _, mapName in ipairs({
                            "InsIDToIndexArrayMap",
                            "InsIdToIndexArrayMap",
                            "InstIDToIndexArrayMap",
                            "InsIDToIndexMap",
                        }) do
                            local m = entity[mapName]
                            if m then
                                m[insID] = nil
                            end
                        end
                        for _, fn in ipairs({
                            "RebuildIndexMap",
                            "BuildIndexMap",
                            "InitIndexMap",
                            "UpdateIndexMap",
                        }) do
                            if entity[fn] then
                                entity[fn](entity)
                            end
                        end
                    end)

                    return removed
                end

                function F.forceWardrobeDepotRefresh()
                    LOBBY.wardrobeRefreshed = false
                    F.invalidateSocialWearCache()
                    F.refreshWardrobe()
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        local tryFns = {
                            "RefreshCurrentPageItemList",
                            "UpdateItemList",
                            "RefreshItemList",
                            "OnUpdateItemList",
                            "InitItemList",
                            "UpdateWardrobeItemList",
                            "RefreshWardrobeItemList",
                            "ReloadCurrentPage",
                        }
                        for _, fn in ipairs(tryFns) do
                            if wl[fn] then
                                pcall(wl[fn], wl)
                            end
                        end
                        if wl.GetInstance then
                            local inst = wl:GetInstance()
                            if inst then
                                for _, fn in ipairs({
                                    "RefreshItemList",
                                    "UpdateItemList",
                                    "OnShow",
                                    "Refresh",
                                    "ReloadData",
                                }) do
                                    if inst[fn] then
                                        pcall(inst[fn], inst)
                                    end
                                end
                            end
                        end
                    end)
                    pcall(function()
                        local subs = {
                            "client.slua.umg.Wardrobe.subtab_avatar",
                            "client.slua.umg.Wardrobe.subtab_suit",
                            "client.slua.umg.Wardrobe.subtab_bag",
                            "client.slua.umg.Wardrobe.subtab_gun",
                        }
                        for _, path in ipairs(subs) do
                            local ok, cls = pcall(require, path)
                            if ok and cls then
                                for _, fn in ipairs({
                                    "RefreshItemList",
                                    "UpdateItemList",
                                    "OnShow",
                                    "Refresh",
                                    "ReloadData",
                                }) do
                                    if cls[fn] then
                                        pcall(cls[fn], cls)
                                    end
                                    if cls.__inner_impl and cls.__inner_impl[fn] then
                                        pcall(cls.__inner_impl[fn], cls.__inner_impl)
                                    end
                                end
                            end
                        end
                    end)
                    F.scheduleInjectRefresh()
                end

                function F.removeInjectedFromDepot(entity, resID, insID)
                    resID, insID = tonumber(resID), tonumber(insID)
                    if not resID or not insID then
                        return false
                    end

                    F.unequipInjectedIns(insID, resID)
                    F.purgeEntityDepotItem(entity, resID, insID)

                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        if wd and wd.GetHallDepotItemDataByInsID then
                            local hd = wd:GetHallDepotItemDataByInsID(insID)
                            if hd then
                                hd.count = 0
                                hd.insID = 0
                                hd.instid = 0
                                hd.ins_id = 0
                                hd.resID = 0
                                hd.res_id = 0
                            end
                        end
                    end)

                    if F.isWeaponSkinRes(resID) then
                        pcall(function()
                            local wid = F.weaponIdFromSkin(resID)
                            local Arm = require("client.logic.armory.logic_armory")
                            if
                                Arm.rsp_list
                                and Arm.rsp_list.skin_list
                                and wid
                                and Arm.rsp_list.skin_list[wid]
                            then
                                Arm.rsp_list.skin_list[wid][resID] = nil
                            end
                            if Arm.WardrobeInsList then
                                Arm.WardrobeInsList[resID] = nil
                            end
                            if wid and Arm.rsp_list and Arm.rsp_list.install_list then
                                local entry = Arm.rsp_list.install_list[wid]
                                if entry and tonumber(entry.skin_id) == insID then
                                    Arm.rsp_list.install_list[wid] = nil
                                end
                            end
                            if wid and R.byWeapon[wid] then
                                R.byWeapon[wid][resID] = nil
                            end
                            F.clearWeaponEquippedMark(wid)
                        end)
                    end

                    R.resToIns[resID] = nil
                    R.insToRes[insID] = nil
                    F.loadDumpExtraSkins()
                    if _G.NTHUY2004_DumpExtraSkins then
                        _G.NTHUY2004_DumpExtraSkins[resID] = nil
                    end
                    if PERSIST.configDepotItems then
                        PERSIST.configDepotItems[resID] = nil
                    end
                    F.persistMarkDirty()
                    return true
                end

                function F.clearDumpSkinsByCategory(category)
                    category = tonumber(category) or 0
                    F.loadDumpExtraSkins()
                    local entity = F.getEntity()
                    local removed, todo = 0, {}
                    local seen = {}
                    for resID, insID in pairs(R.resToIns) do
                        resID, insID = tonumber(resID), tonumber(insID)
                        if resID and insID and F.shouldClearDumpSkin(resID, category) and not seen[resID] then
                            seen[resID] = true
                            todo[#todo + 1] = { resID, insID }
                        end
                    end
                    for resID, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        resID = tonumber(resID)
                        if on and resID and not seen[resID] and F.shouldClearDumpSkin(resID, category) then
                            seen[resID] = true
                            todo[#todo + 1] = { resID, R.resToIns[resID] or F.dumpInsForRes(resID) }
                        end
                    end
                    for i = 1, #todo do
                        local pair = todo[i]
                        if F.removeInjectedFromDepot(entity, pair[1], pair[2]) then
                            removed = removed + 1
                        end
                    end
                    if _G.NTHUY2004_DumpExtraSkins then
                        for resID, on in pairs(_G.NTHUY2004_DumpExtraSkins) do
                            resID = tonumber(resID)
                            if
                                on
                                and resID
                                and (category == 0 or F.classifyDumpSkinCategory(resID) == category)
                            then
                                _G.NTHUY2004_DumpExtraSkins[resID] = nil
                                if PERSIST.configDepotItems then
                                    PERSIST.configDepotItems[resID] = nil
                                end
                            end
                        end
                    end
                    F.persistMarkDirty()
                    pcall(F.perfInvalidateLobby)
                    F.forceWardrobeDepotRefresh()
                    F.later(0.15, function()
                        F.forceWardrobeDepotRefresh()
                    end)
                    return removed
                end

                _G.NTHUY2004_ClearDumpSkinsByCategory = function(category)
                    return F.clearDumpSkinsByCategory(category) or 0
                end

                function F.injectAll(entity)
                    if _G.NTHUY2004Config and _G.NTHUY2004Config.ModSkin == false then
                        return false
                    end
                    entity = entity or F.getEntity()
                    if not entity or not entity.bInit then
                        return false
                    end
                    F.loadDumpExtraSkins()
                    local n, nNew = 0, 0

                    local useScript = true
                    if _G.NTHUY2004Config and _G.NTHUY2004Config.UseScriptSkins == false then
                        useScript = false
                    end
                    if useScript then
                        for i, resID in ipairs(ITEMS) do
                            local insID = INS_BASE + i
                            local had = R.resToIns[resID] ~= nil
                            if F.injectOne(entity, resID, insID) then
                                n = n + 1
                                if not had then
                                    nNew = nNew + 1
                                end
                                local c = F.cfg(resID)
                                if GUN_SUB[F.subType(c)] or F.subType(c) == MELEE_ID then
                                    F.injectArmory(resID, insID)
                                end
                            end
                        end
                    end
                    for resID, on in pairs(_G.NTHUY2004_DumpExtraSkins or {}) do
                        if on then
                            resID = tonumber(resID)
                            if
                                resID
                                and not F.isInjectedDepotAlive(resID)
                                and F.shouldInjectDepotRes(resID)
                            then
                                local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                                if F.injectOne(entity, resID, insID) then
                                    n = n + 1
                                    nNew = nNew + 1
                                    insID = R.resToIns[resID] or insID
                                    local c = F.cfg(resID)
                                    if GUN_SUB[F.subType(c)] or F.subType(c) == MELEE_ID then
                                        F.injectArmory(resID, insID)
                                    end
                                end
                            end
                        end
                    end
                    if not _G.AddOutfitUnexpireDone then
                        _G.AddOutfitUnexpireDone = true
                        pcall(F.reviveExpiredOwned, entity)
                    end
                    F.mergeRevivedIntoMaps()
                    F.sanitizeAllInjectedExpire()
                    F.ensureInjectedResources()
                    pcall(F.fixInjectedVehicleDepotTabs, entity)
                    pcall(F.fixInjectedEmoteDepotTabs, entity)
                    pcall(F.fixInjectedParachuteDepotTabs, entity)

                    pcall(function()
                        local fls = _G.NTHUY2004_FreeLobbyShop
                        if type(fls) ~= "table" or not fls.scanDepotAndUnlockXSuits then
                            return
                        end
                        fls.scanDepotAndUnlockXSuits()
                        local ticker = require("common.time_ticker")
                        if ticker and ticker.AddTimerOnce then
                            ticker.AddTimerOnce(1.0, function()
                                pcall(fls.scanDepotAndUnlockXSuits)
                            end)
                            ticker.AddTimerOnce(3.0, function()
                                pcall(fls.scanDepotAndUnlockXSuits)
                            end)
                        end
                    end)
                    return n > 0
                end

                function F.refreshWardrobe()
                    pcall(function()
                        if EventSystem and EVENTTYPE_WARDROBE then
                            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                            end
                            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
                            end
                            if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                                EventSystem:postEvent(
                                    EVENTTYPE_WARDROBE,
                                    EVENTID_WARDROBE_UPDATE_GUN_LIST,
                                    -1
                                )
                            end
                        end
                    end)
                end

                function F.refreshWardrobeOnce()
                    if LOBBY.wardrobeRefreshed then
                        return
                    end
                    LOBBY.wardrobeRefreshed = true
                    F.refreshWardrobe()
                end

                function F.scheduleInjectRefresh()
                    LOBBY.injectRefreshGen = (LOBBY.injectRefreshGen or 0) + 1
                    local gen = LOBBY.injectRefreshGen
                    F.later(0.5, function()
                        if gen ~= LOBBY.injectRefreshGen then
                            return
                        end
                        F.refreshWardrobe()
                    end)
                end

                function F.scheduleDepotReinject()
                    if LOBBY.depotReinjectScheduled then
                        return
                    end
                    LOBBY.depotReinjectScheduled = true
                    F.later(2.0, function()
                        LOBBY.depotReinjectScheduled = false
                        local n = 0
                        pcall(function()
                            n = F.reinjectMissingDumpExtras() or 0
                        end)
                        pcall(function()
                            local fls = _G.NTHUY2004_FreeLobbyShop
                            if type(fls) == "table" and fls.scanDepotAndUnlockXSuits then
                                fls.scanDepotAndUnlockXSuits()
                            end
                        end)
                        if n > 0 then
                            F.refreshWardrobe()
                        end
                    end)
                end

                function F.putOnOutfit(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d0 = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d0 and tonumber(d0.resID or d0.res_id)
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    if not F.isSuitRes(resID) then
                        if F.isTshirtRes(resID) then
                            return F.putOnRoleWear(insID)
                        end
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not d then
                        return
                    end

                    local suitFilter = function(r)
                        return F.isSuitRes(r)
                    end
                    local oldIns, oldRes = F.findWornInsBySubType(OUTFIT_SUB, suitFilter)
                    F.removeRoleWearBySubType(OUTFIT_SUB, suitFilter)
                    F.saveEquip(resID, insID)

                    local slot = PKG_SLOT
                    pcall(function()
                        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                        local idx = wfu.GetRoleWearIndexBySubType
                            and wfu:GetRoleWearIndexBySubType(OUTFIT_SUB)
                        if idx then
                            slot = idx
                        end
                    end)

                    local olditem
                    if oldIns and oldIns ~= insID then
                        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                    end

                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    local item = { res_id = resID, count = 1, instid = insID }
                    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

                    pcall(function()
                        local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                        av:AddToWearInfo(OUTFIT_SUB, insID, resID, 0, 0)
                        F.syncFashionBagRolewear()
                    end)
                    F.rememberLobbyOutfitRes(resID)
                    pcall(function()
                        F.patchSelfWearCache(true)
                    end)
                    pcall(function()
                        F.requestSocialAvatarRefresh()
                    end)
                end

                function F.putOnHat(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d0 = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d0 and tonumber(d0.resID or d0.res_id)
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not d then
                        return
                    end
                    local st = F.subType(F.cfg(resID)) or HAT_SUB

                    local oldIns, oldRes = F.findWornInsBySubType(st)
                    if not oldIns and st ~= HAT_SUB then
                        oldIns, oldRes = F.findWornInsBySubType(HAT_SUB)
                    end
                    F.removeRoleWearBySubType(st)
                    if st ~= HAT_SUB then
                        F.removeRoleWearBySubType(HAT_SUB)
                    end
                    F.saveEquip(resID, insID)

                    local slot = 1
                    pcall(function()
                        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
                        if idx then
                            slot = idx
                        end
                    end)

                    local olditem
                    if oldIns and oldIns ~= insID then
                        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                    end

                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    local item =
                        { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
                    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        fbd:SetHeadShow(insID)
                        F.syncFashionBagRolewear()
                    end)
                    F.invalidateSocialWearCache()
                end

                function F.putOnFaceAccessory(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d0 = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d0 and tonumber(d0.resID or d0.res_id)
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not d then
                        return
                    end
                    local st = F.subType(F.cfg(resID)) or tonumber(d.itemSubType)
                    if not FACE_SUBS[st] then
                        return
                    end

                    local oldIns, oldRes = F.findWornInsBySubType(st)
                    F.removeRoleWearBySubType(st)
                    F.saveEquip(resID, insID)

                    local slot = (st == MASK_SUB) and 2 or 6
                    pcall(function()
                        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
                        if idx then
                            slot = idx
                        end
                    end)

                    local olditem
                    if oldIns and oldIns ~= insID then
                        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                    end

                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    local item =
                        { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
                    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

                    pcall(function()
                        F.syncFashionBagRolewear()
                    end)
                    F.invalidateSocialWearCache()
                end

                function F.canRoleWear(resID, st)
                    st = st or F.subType(F.cfg(resID))
                    if FACE_SUBS[st] or BODY_SUBS[st] then
                        return true
                    end
                    if st == GLOVES_SUB then
                        return true
                    end
                    if st == OUTFIT_SUB and F.wardrobeTab(resID) == TAB_CLOTHES then
                        return true
                    end
                    return false
                end

                F.putOnRoleWear = function(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d0 = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d0 and tonumber(d0.resID or d0.res_id)
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not d then
                        return
                    end
                    local st = F.subType(F.cfg(resID)) or tonumber(d.itemSubType)
                    if not F.canRoleWear(resID, st) then
                        return
                    end

                    if BAG_SUBS[st] or HELMET_SUBS[st] then
                        local norm = F.equipToLobbyMappingID(resID)
                        if norm and norm > 0 and norm ~= resID then
                            resID = norm
                            R.insToRes[insID] = resID
                            R.resToIns[resID] = insID
                            pcall(function()
                                if d.resID ~= nil then
                                    d.resID = resID
                                end
                                if d.res_id ~= nil then
                                    d.res_id = resID
                                end
                            end)
                        end
                    end

                    local filterFn
                    if st == OUTFIT_SUB then
                        filterFn = function(r)
                            return F.wardrobeTab(r) == TAB_CLOTHES
                        end
                    end
                    local oldIns, oldRes = F.findWornInsBySubType(st, filterFn)
                    F.removeRoleWearBySubType(st, filterFn)
                    F.saveEquip(resID, insID)

                    local slot = PKG_SLOT
                    pcall(function()
                        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
                        if idx then
                            slot = idx
                        end
                    end)

                    local olditem
                    if oldIns and oldIns ~= insID then
                        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                    end

                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    local item =
                        { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
                    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

                    if BAG_SUBS[st] or HELMET_SUBS[st] then
                        pcall(function()
                            DataMgr.equipmentSkinInsIDTable = DataMgr.equipmentSkinInsIDTable or {}
                            DataMgr.equipmentSkinInsIDTable[st] = insID
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                            if bag then
                                if st == 504 or st == 501 then
                                    DataMgr.equipmentSkinInsIDTable[504] = insID
                                    bag.bag_skin = insID
                                elseif st == 505 or st == 502 then
                                    DataMgr.equipmentSkinInsIDTable[505] = insID
                                    bag.helmet_skin = insID
                                end
                            end
                        end)

                        pcall(function()
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            local level = 3
                            if HELMET_SUBS[st] then
                                level = tonumber(fbd:GetHelmetLevel()) or 3
                            else
                                level = tonumber(fbd:GetBagLevel()) or 3
                            end
                            local displayID = 0
                            if DataMgr and DataMgr.GetEquipmentItemIDByResID then
                                displayID = tonumber(DataMgr.GetEquipmentItemIDByResID(level, resID)) or 0
                            end
                            if displayID <= 0 then
                                displayID = resID
                            end
                            F.ensureSkinDownload(displayID)
                            local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                            local skinSub = HELMET_SUBS[st] and 505 or 504
                            if av.AddToWearInfo then
                                av:AddToWearInfo(skinSub, insID, resID, d.color or 0, d.pattern or 0)
                            end
                            if av.AvatarChange then
                                av:AvatarChange(displayID, true, d.color or 0, d.pattern or 0)
                            end
                        end)
                    end

                    pcall(function()
                        F.syncFashionBagRolewear()
                    end)
                    F.invalidateSocialWearCache()
                end

                function F.putOnGloves(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d0 = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d0 and tonumber(d0.resID or d0.res_id)
                    end
                    if not resID or resID <= 0 then
                        return
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                        R.resToIns[resID] = insID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if not d then
                        return
                    end

                    local oldIns, oldRes = F.findWornInsBySubType(GLOVES_SUB)
                    F.removeRoleWearBySubType(GLOVES_SUB)
                    F.saveEquip(resID, insID)

                    local slot = 8
                    pcall(function()
                        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
                        local idx = wfu.GetRoleWearIndexBySubType
                            and wfu:GetRoleWearIndexBySubType(GLOVES_SUB)
                        if idx then
                            slot = idx
                        end
                    end)

                    local olditem
                    if oldIns and oldIns ~= insID then
                        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
                    end

                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    local item = {
                        res_id = resID,
                        count = 1,
                        instid = insID,
                        color = d.color,
                        pattern = d.pattern,
                        expire_ts = 0,
                    }
                    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

                    pcall(function()
                        local logic_wardrobe_avatar =
                            require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
                        logic_wardrobe_avatar:AddToWearInfo(
                            GLOVES_SUB,
                            insID,
                            resID,
                            d.color or 0,
                            d.pattern or 0
                        )
                        DataMgr.UpdateRoleWearData(insID, oldIns or 0)
                        logic_wardrobe_avatar:AvatarChange(resID, true, d.color, d.pattern)
                    end)
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if wl.SetClickItemInsId then
                            wl:SetClickItemInsId(insID)
                        end
                    end)
                    pcall(function()
                        if EventSystem and EVENTTYPE_WARDROBE then
                            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
                            end
                            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
                            end
                        end
                    end)
                    F.invalidateSocialWearCache()
                end

                function F.ensureDepotItemValid(insID, resID)
                    insID = tonumber(insID)
                    if not insID then
                        return
                    end
                    pcall(function()
                        local entity = F.getEntity()
                        if entity and entity.GetDataByInsID then
                            local d = entity:GetDataByInsID(insID)
                            if d then
                                d.expire_ts = 0
                                if d.expireTS ~= nil then
                                    d.expireTS = 0
                                end
                                if d.valid_hours ~= nil then
                                    d.valid_hours = 0
                                end
                            end
                        end
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local hd = wd:GetHallDepotItemDataByInsID(insID)
                        if hd then
                            hd.expire_ts = 0
                            if hd.expireTS ~= nil then
                                hd.expireTS = 0
                            end
                            if hd.valid_hours ~= nil then
                                hd.valid_hours = 0
                            end
                        end
                    end)
                end

                function F.clearItemExpire(itemData, insID, resID)
                    F.ensureDepotItemValid(insID, resID)
                    if type(itemData) == "table" then
                        itemData.expireTS = 0
                        itemData.expire_ts = 0
                        itemData.expireTs = 0
                    end
                end

                function F.onGlideClick(self, itemData)
                    if not itemData then
                        return
                    end
                    local insID = tonumber(itemData.ins_id)
                    local resID = tonumber(itemData.res_id)
                    F.clearItemExpire(itemData, insID, resID)
                    local isGlide = resID and F.isGlideRes(resID)
                    if not isGlide and itemData.itemSubType then
                        isGlide = GLIDER_SUBS[tonumber(itemData.itemSubType)] == true
                    end
                    if insID and resID and isGlide then
                        F.saveEquip(resID, insID)
                        if F.putOnGlider(insID) then
                            pcall(function()
                                if self.ShowGlide then
                                    self:ShowGlide(resID)
                                end
                                if self.ChangeItemStatus then
                                    self:ChangeItemStatus(insID, true)
                                end
                            end)
                            return
                        end
                    end
                    if _G.AddOutfitGlideClickOrig then
                        F.clearItemExpire(itemData, insID, resID)
                        return _G.AddOutfitGlideClickOrig(self, itemData)
                    end
                end

                function F.onParachuteClick(self, itemData)
                    if not itemData then
                        return
                    end
                    local insID = tonumber(itemData.ins_id)
                    local resID = tonumber(itemData.res_id)
                    F.clearItemExpire(itemData, insID, resID)
                    if insID and resID and F.isParachuteRes(resID) then
                        F.saveEquip(resID, insID)
                        if F.putOnParachute(insID) then
                            pcall(function()
                                if self.ChangeItemStatus then
                                    self:ChangeItemStatus(insID, true)
                                end
                            end)
                            return
                        end
                    end
                    if _G.AddOutfitParaClickOrig then
                        return _G.AddOutfitParaClickOrig(self, itemData)
                    end
                end

                function F.onThrowObjectClick(self, widget, index)
                    local itemData = nil
                    pcall(function()
                        if self.LoopScrollGrid_Normal and self.LoopScrollGrid_Normal.GetItemData then
                            itemData = self.LoopScrollGrid_Normal:GetItemData(index)
                        end
                    end)
                    if itemData then
                        local insID = tonumber(itemData.ins_id or itemData.insID)
                        local resID = tonumber(itemData.res_id or itemData.resID)
                        F.clearItemExpire(itemData, insID, resID)
                        local st = tonumber(itemData.itemSubType) or (resID and F.subType(F.cfg(resID)))
                        if insID and resID and GRENADE_SUB[st] then
                            if
                                (F.isInjectedIns(insID) or F.isInjectedRes(resID)) and F.putOnGrenade(insID)
                            then
                                pcall(function()
                                    if self.ChangeItemStatusByInsID then
                                        self:ChangeItemStatusByInsID(insID, true)
                                    elseif self.ChangeItemStatus then
                                        self:ChangeItemStatus(insID, true)
                                    end
                                end)
                                return
                            end
                        end
                    end
                    if _G.AddOutfitThrowClickOrig then
                        return _G.AddOutfitThrowClickOrig(self, widget, index)
                    end
                end

                function F.hookAirborneClick()
                    pcall(function()
                        local WG = require("client.slua.umg.Wardrobe.subtab_gliding")
                        if WG then
                            if not WG._AddOutfitGlideWrapped then
                                WG._AddOutfitGlideWrapped = true
                                _G.AddOutfitGlideClickOrig = WG.ClickItem
                            end
                            WG.ClickItem = function(self, itemData)
                                return F.onGlideClick(self, itemData)
                            end
                        end
                        local WP = require("client.slua.umg.Wardrobe.subtab_parachute")
                        if WP then
                            if not WP._AddOutfitParaWrapped then
                                WP._AddOutfitParaWrapped = true
                                _G.AddOutfitParaClickOrig = WP.ClickItem
                            end
                            WP.ClickItem = function(self, itemData)
                                return F.onParachuteClick(self, itemData)
                            end
                        end

                        local WT = require("client.slua.umg.Wardrobe.subtab_throw_object")
                        if WT then
                            if not WT._AddOutfitThrowWrapped then
                                WT._AddOutfitThrowWrapped = true
                                _G.AddOutfitThrowClickOrig = WT.OnClickItem
                            end
                            WT.OnClickItem = function(self, widget, index)
                                return F.onThrowObjectClick(self, widget, index)
                            end
                        end
                    end)
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if fbd and not fbd._AddOutfitAirborneFBHooked then
                            fbd._AddOutfitAirborneFBHooked = true
                            local oG = fbd.UpdateAircraftOrGliding
                            fbd.UpdateAircraftOrGliding = function(self, putOnID, bAircraft)
                                local r = oG(self, putOnID, bAircraft)
                                local ins = tonumber(putOnID)
                                if ins and ins > 0 then
                                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                    local d = wd:GetValidHallDepotItemDataByInsID(ins)
                                        or wd:GetHallDepotItemDataByInsID(ins)
                                    local res = d and tonumber(d.resID)
                                    if res and F.isGlideRes(res) then
                                        F.saveEquip(res, ins)
                                    end
                                end
                                return r
                            end
                            local oP = fbd.UpdateParachute
                            if oP then
                                fbd.UpdateParachute = function(self, insID)
                                    local r = oP(self, insID)
                                    local ins = tonumber(insID)
                                    if ins and ins > 0 then
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetValidHallDepotItemDataByInsID(ins)
                                            or wd:GetHallDepotItemDataByInsID(ins)
                                        local res = d and tonumber(d.resID)
                                        if res and F.isParachuteRes(res) then
                                            F.saveEquip(res, ins)
                                        end
                                    end
                                    return r
                                end
                            end
                            local oT = fbd.PutOnThrowObjectSkin
                            if oT then
                                fbd.PutOnThrowObjectSkin = function(self, putOnId, index)
                                    local r = oT(self, putOnId, index)
                                    local ins = tonumber(putOnId)
                                    if ins and ins > 0 then
                                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                        local d = wd:GetValidHallDepotItemDataByInsID(ins)
                                            or wd:GetHallDepotItemDataByInsID(ins)
                                        local res = d and tonumber(d.resID)
                                        local base = res and F.grenadeBaseFromSkin(res)
                                        if base then
                                            F.saveGrenadeToCache(base, res, ins)
                                        end
                                    end
                                    return r
                                end
                            end
                        end
                    end)
                    pcall(function()
                        if not ModuleManager or not ModuleManager.GetModule then
                            return
                        end
                        local FB =
                            ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.FashionBagEditUtils)
                        if FB and not FB._AddOutfitFBBagHooked then
                            FB._AddOutfitFBBagHooked = true
                            local o = FB.PutOnFashionBagItem
                            FB.PutOnFashionBagItem = function(self, itemData)
                                if itemData then
                                    F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
                                end
                                local r = o(self, itemData)
                                if itemData then
                                    local res = tonumber(itemData.res_id)
                                    local ins = tonumber(itemData.ins_id)
                                    if res and ins and (F.isGlideRes(res) or F.isParachuteRes(res)) then
                                        F.saveEquip(res, ins)
                                    elseif res and ins and F.isGrenadeSkinRes(res) then
                                        local base = F.grenadeBaseFromSkin(res)
                                        if base then
                                            F.saveGrenadeToCache(base, res, ins)
                                        end
                                    end
                                end
                                return r
                            end
                        end
                    end)
                end

                function F.putOnParachute(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d and tonumber(d.resID)
                    end
                    if not resID or not F.isParachuteRes(resID) then
                        return false
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    F.saveEquip(resID, insID)
                    F.ensureInjectedItemAlive(nil, resID, insID)
                    local ready = F.isResourcesReady(resID)
                    if not ready then
                        F.requestResourceDownload(resID)
                    end
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if fbd.SetParachute then
                            fbd:SetParachute(insID)
                        end
                        if fbd.UpdateParachute then
                            fbd:UpdateParachute(insID)
                        end
                    end)
                    if ready then
                        local item = {
                            res_id = resID,
                            resID = resID,
                            instid = insID,
                            ins_id = insID,
                            insID = insID,
                            expire_ts = 0,
                            expireTS = 0,
                            count = 1,
                        }
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
                    end
                    return true
                end

                function F.putOnGlider(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        resID = d and tonumber(d.resID)
                    end
                    if not resID or resID <= 0 then
                        return false
                    end
                    local st = F.depotSubType(insID, resID)
                    if not F.isGlideRes(resID) and not GLIDER_SUBS[st] then
                        return false
                    end
                    if not R.insToRes[insID] then
                        R.insToRes[insID] = resID
                    end
                    F.ensureDepotItemValid(insID, resID)
                    F.saveEquip(resID, insID)
                    F.ensureInjectedItemAlive(nil, resID, insID)
                    local ready = F.isResourcesReady(resID)
                    if not ready then
                        F.requestResourceDownload(resID)
                    end
                    local bAircraft = false
                    pcall(function()
                        local ModelDisplayTypeHelper = require("client.logic.avatar.ModelDisplayTypeHelper")
                        local st = F.subType(F.cfg(resID))
                        bAircraft = ModelDisplayTypeHelper.IsGlideSmoke(st)
                    end)
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if fbd.UpdateAircraftOrGliding then
                            fbd:UpdateAircraftOrGliding(insID, bAircraft)
                        elseif fbd.SetGliding then
                            fbd:SetGliding(insID)
                            if DataMgr.UpdateEffect then
                                DataMgr.UpdateEffect(insID)
                            end
                        end
                    end)
                    if ready then
                        local item = {
                            res_id = resID,
                            resID = resID,
                            instid = insID,
                            ins_id = insID,
                            insID = insID,
                            expire_ts = 0,
                            expireTS = 0,
                            count = 1,
                        }
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
                    end
                    return true
                end

                function F.syncAirborneToDataMgr()
                    F.applyPersistSlotsToCache()
                    local cch = F.cache()
                    local paraRes = F.getDesiredParachuteRes()
                    local gliderRes = F.getDesiredGliderRes()
                    if paraRes and paraRes > 0 and not cch.parachuteIns then
                        cch.parachuteIns = F.resolveInsForRes(paraRes)
                        cch.parachuteRes = paraRes
                    end
                    if gliderRes and gliderRes > 0 and not cch.gliderIns then
                        cch.gliderIns = F.resolveInsForRes(gliderRes)
                        cch.gliderRes = gliderRes
                    end
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if cch.parachuteIns and tonumber(cch.parachuteIns) > 0 then
                            if fbd.SetParachute then
                                fbd:SetParachute(cch.parachuteIns)
                            end
                            if DataMgr.roleData then
                                DataMgr.roleData.parachute = tostring(cch.parachuteIns)
                            end
                        end
                        if cch.gliderIns and tonumber(cch.gliderIns) > 0 then
                            local bAircraft = false
                            if cch.gliderRes then
                                pcall(function()
                                    local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
                                    bAircraft = not MDH.IsGlideSmoke(F.subType(F.cfg(cch.gliderRes)))
                                end)
                            end
                            if fbd.UpdateAircraftOrGliding then
                                fbd:UpdateAircraftOrGliding(cch.gliderIns, bAircraft)
                            elseif fbd.SetGliding then
                                fbd:SetGliding(cch.gliderIns)
                                if DataMgr.UpdateEffect then
                                    DataMgr.UpdateEffect(cch.gliderIns)
                                end
                            end
                            if DataMgr.roleData then
                                if bAircraft then
                                    DataMgr.roleData.aircraft_put_id = tostring(cch.gliderIns)
                                    DataMgr.gliding = cch.gliderIns
                                else
                                    DataMgr.roleData.gliding = tostring(cch.gliderIns)
                                end
                            end
                        end
                    end)
                end

                function F.putOnGenericInjected(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        return
                    end
                    if not F.isResourcesReady(resID) then
                        F.requestResourceDownload(resID)
                        return
                    end
                    F.saveEquip(resID, insID)
                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    WRH.on_depot_put_on_rsp(
                        NET_OK,
                        { res_id = resID, count = 1, instid = insID },
                        nil,
                        1,
                        insID,
                        0
                    )
                end

                function F.clearEquipCache(resID)
                    local st = F.subType(F.cfg(resID))
                    local cch = F.cache()
                    if st == OUTFIT_SUB then
                        if F.wardrobeTab(resID) == TAB_CLOTHES then
                            cch.tshirtRes, cch.tshirtIns = nil, nil
                            _G.AddOutfitLastLobbyTshirtRes = nil
                            F.persistForgetSlot("tshirt")
                        else
                            cch.outfitRes, cch.outfitIns = nil, nil
                            _G.AddOutfitLastLobbyOutfitRes = nil
                            F.persistForgetSlot("outfit")
                        end
                    elseif st == HAT_SUB or HEAD_SUBS[st] then
                        cch.hatRes, cch.hatIns = nil, nil
                        _G.AddOutfitLastLobbyHatRes = nil
                        F.persistForgetSlot("hat")
                    elseif st == MASK_SUB then
                        cch.maskRes, cch.maskIns = nil, nil
                        _G.AddOutfitLastLobbyMaskRes = nil
                        F.persistForgetSlot("mask")
                    elseif st == GLASS_SUB then
                        cch.glassRes, cch.glassIns = nil, nil
                        _G.AddOutfitLastLobbyGlassRes = nil
                        F.persistForgetSlot("glass")
                    elseif st == PANTS_SUB then
                        cch.pantsRes, cch.pantsIns = nil, nil
                        _G.AddOutfitLastLobbyPantsRes = nil
                        F.persistForgetSlot("pants")
                    elseif st == SHOES_SUB then
                        cch.shoesRes, cch.shoesIns = nil, nil
                        _G.AddOutfitLastLobbyShoesRes = nil
                        F.persistForgetSlot("shoes")
                    elseif BAG_SUBS[st] then
                        cch.bagRes, cch.bagIns = nil, nil
                        _G.AddOutfitLastLobbyBagRes = nil
                        F.persistForgetSlot("bag")
                    elseif HELMET_SUBS[st] then
                        cch.helmetRes, cch.helmetIns = nil, nil
                        _G.AddOutfitLastLobbyHelmetRes = nil
                        F.persistForgetSlot("helmet")
                    elseif st == PARACHUTE_SUB then
                        cch.parachuteRes, cch.parachuteIns = nil, nil
                        _G.AddOutfitLastLobbyParachuteRes = nil
                        F.persistForgetSlot("parachute")
                    elseif F.isGlideRes(resID) then
                        cch.gliderRes, cch.gliderIns = nil, nil
                        _G.AddOutfitLastLobbyGliderRes = nil
                        F.persistForgetSlot("glider")
                    elseif st == GLOVES_SUB then
                        cch.glovesRes, cch.glovesIns = nil, nil
                        _G.AddOutfitLastLobbyGlovesRes = nil
                        F.persistForgetSlot("gloves")
                    end
                    _matchApplied = false
                    F.invalidateSocialWearCache()
                    F.perfInvalidateLobby()
                    F.persistMarkDirty()
                end

                function F.takeOffInjected(insID)
                    insID = tonumber(insID)
                    local resID = R.insToRes[insID]
                    if not resID then
                        return
                    end
                    local st = F.subType(F.cfg(resID))

                    pcall(function()
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        WRH.on_depot_put_down_rsp(NET_OK, { res_id = resID, count = 1 }, insID)
                    end)

                    pcall(function()
                        local AvatarData = require("client.logic.data.AvatarData")
                        AvatarData.RemoveRoleWearDataByValue(insID)
                    end)
                    if st == HAT_SUB or HEAD_SUBS[st] then
                        pcall(function()
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                            if bag and tonumber(bag.head_show) == insID then
                                fbd:SetHeadShow(0)
                            end
                        end)
                    end
                    if BAG_SUBS[st] or HELMET_SUBS[st] then
                        pcall(function()
                            local t = DataMgr.equipmentSkinInsIDTable
                            if t then
                                for _, k in ipairs({ st, 504, 505 }) do
                                    if tonumber(t[k]) == insID then
                                        t[k] = 0
                                    end
                                end
                            end
                            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                            if bag then
                                if tonumber(bag.bag_skin) == insID then
                                    bag.bag_skin = 0
                                end
                                if tonumber(bag.helmet_skin) == insID then
                                    bag.helmet_skin = 0
                                end
                            end
                        end)
                    end

                    F.clearEquipCache(resID)
                    pcall(function()
                        F.syncFashionBagRolewear()
                    end)
                end

                function F.syncWeaponArmorySilent(weaponID, insID)
                    weaponID, insID = tonumber(weaponID), tonumber(insID)
                    if not weaponID or not insID or not F.isInjectedIns(insID) then
                        return
                    end
                    local resID = R.insToRes[insID]
                    if not resID then
                        return
                    end
                    local Arm = require("client.logic.armory.logic_armory")
                    Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
                    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
                    F.injectArmory(resID, insID)
                    Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
                    pcall(function()
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        if fbd.UpdateCurrentFashionBagWeaponSkin then
                            fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
                        end
                    end)
                end

                function F.equipWeaponSkin(weaponID, insID, forceVisual)
                    weaponID, insID = tonumber(weaponID), tonumber(insID)
                    if not weaponID or not insID or not F.isInjectedIns(insID) then
                        return false
                    end
                    local resID = R.insToRes[insID]
                    if not resID then
                        return false
                    end

                    local meleeSkin = F.subType(F.cfg(resID)) == MELEE_ID
                    local mappedWid = tonumber(F.weaponIdFromSkin(resID))

                    local displayWid = weaponID
                    if meleeSkin then
                        if mappedWid and mappedWid > 0 then
                            displayWid = mappedWid
                        elseif weaponID >= 108000 and weaponID < 109000 then
                            displayWid = weaponID
                        end
                    end

                    _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
                    if not forceVisual and F.isWeaponVisuallyEquipped(displayWid, insID) then
                        F.syncWeaponArmorySilent(displayWid, insID)
                        return false
                    end
                    F.saveEquip(resID, insID)

                    local Arm = require("client.logic.armory.logic_armory")
                    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                    local HT = require("client.logic.lobby.hall_theme_utils")
                    local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")

                    F.injectArmory(resID, insID)
                    Arm.rsp_list.install_list[displayWid] = { skin_id = insID }
                    if fbd.UpdateCurrentFashionBagWeaponSkin then
                        fbd:UpdateCurrentFashionBagWeaponSkin(displayWid, insID)
                    end

                    local bagIdx = fbd:GetFashionBagUseIndex()
                    HT.proc_skin_list_chg("weapon_skin", displayWid, insID, bagIdx, {})

                    wgl:SetGunID(displayWid)
                    wgl:UpdateCurrentGunAvatar(displayWid, insID)

                    if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
                        EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, resID)
                    end
                    if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                        EventSystem:postEvent(
                            EVENTTYPE_WARDROBE,
                            EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN,
                            resID
                        )
                    end
                    _G.AddOutfitWeaponEquipped[displayWid] = insID
                    return true
                end

                local SOCIAL = _G.AddOutfitSocialState or {}
                _G.AddOutfitSocialState = SOCIAL
                SOCIAL.debGen = SOCIAL.debGen or 0
                SOCIAL.wearPatchKey = SOCIAL.wearPatchKey or nil
                SOCIAL.snapshotKey = SOCIAL.snapshotKey or nil
                SOCIAL.fullSnapshot = SOCIAL.fullSnapshot or nil

                function F.socialDebounce(sec, fn)
                    SOCIAL.debGen = (SOCIAL.debGen or 0) + 1
                    local gen = SOCIAL.debGen
                    F.later(sec, function()
                        if gen ~= SOCIAL.debGen then
                            return
                        end
                        pcall(fn)
                    end)
                end

                function F.getLobbyCurPage()
                    local p = nil
                    pcall(function()
                        local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
                        if LMC.GetCurPage then
                            p = LMC.GetCurPage()
                        end
                    end)
                    return p
                end

                function F.isLobbyLeftPage()
                    return ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left
                end

                function F.isSelfRoleInfoOpen()
                    local ok = false
                    pcall(function()
                        if UIManager and UIManager.UI_Config then
                            local cfgs = {
                                UIManager.UI_Config.roleinfo_main,
                                UIManager.UI_Config.Personalization_UIBP,
                                UIManager.UI_Config.Lobby_RoleInfo_Segment180_UIBP,
                                UIManager.UI_Config.Lobby_RoleInfo_Combat180_UIBP,
                            }
                            for _, cfg in ipairs(cfgs) do
                                if cfg and UIManager.IsUIShow and UIManager.IsUIShow(cfg) then
                                    ok = true
                                    break
                                end
                            end
                        end
                    end)
                    return ok
                end

                function F.isSelfUid(uid)
                    if uid == nil then
                        return false
                    end
                    local myUid
                    pcall(function()
                        myUid = DataMgr.roleData.uid
                    end)
                    return myUid and tostring(uid) == tostring(myUid)
                end

                function F.isBattleResultOrMvpOpen()
                    local ok = false
                    pcall(function()
                        if not UIManager or not UIManager.UI_Config_InGame then
                            return
                        end
                        local cfgs = {
                            UIManager.UI_Config_InGame.BattleResultRanking_UIBP,
                            UIManager.UI_Config_InGame.BattleResultShowMvp_UIBP,
                            UIManager.UI_Config_InGame.BattleResultChickenUI,
                            UIManager.UI_Config_InGame.BattleResultMedalDisplayUI,
                            UIManager.UI_Config_InGame.Mvp_Sequence_Mask,
                        }
                        for _, cfg in ipairs(cfgs) do
                            if cfg and UIManager.IsUIShow and UIManager.IsUIShow(cfg) then
                                ok = true
                                break
                            end
                        end
                    end)
                    return ok
                end

                function F.prepareBattleResultWearPatch()
                    LOBBY.outfitResolved = false
                    LOBBY.skinResolved = false
                    F.syncWeaponCacheFromLobby(true)
                    F.applyPersistSlotsToCache()
                end

                function F.setBattleResultWearExtSlot(wear_ext, slot, res)
                    if not wear_ext or not slot or not res or res <= 0 then
                        return
                    end
                    wear_ext[slot] = wear_ext[slot] or { 0, 0, 0 }
                    wear_ext[slot][1] = res
                end

                function F.patchSelfBattleResultWearExt(wear_ext)
                    if not wear_ext or not ENUM_AVATAR_SHOW_TYPE then
                        return
                    end
                    F.prepareBattleResultWearPatch()
                    local outfitRes = F.resolveLobbyOutfitRes()
                    if outfitRes and outfitRes > 0 then
                        F.setBattleResultWearExtSlot(
                            wear_ext,
                            ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH,
                            outfitRes
                        )
                    end
                    local skinRes = F.resolveLobbyWeaponSkinRes()
                    if skinRes and skinRes > 0 then
                        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON, 0)
                        F.setBattleResultWearExtSlot(
                            wear_ext,
                            ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN,
                            skinRes
                        )
                    end
                    local cch = F.cache()
                    if cch.hatRes and cch.hatRes > 0 then
                        F.setBattleResultWearExtSlot(
                            wear_ext,
                            ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEADWEAR,
                            cch.hatRes
                        )
                    end
                    if cch.helmetRes and cch.helmetRes > 0 then
                        F.setBattleResultWearExtSlot(
                            wear_ext,
                            ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HELMET,
                            cch.helmetRes
                        )
                    end
                    if cch.bagRes and cch.bagRes > 0 then
                        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_BAG, cch.bagRes)
                    end
                end

                function F.patchSelfInTeammateList(list)
                    if not list then
                        return
                    end
                    for _, v in pairs(list) do
                        if v and F.isSelfUid(v.UID or v.uid) then
                            v.wear_ext = v.wear_ext or {}
                            F.patchSelfBattleResultWearExt(v.wear_ext)
                        end
                    end
                end

                function F.shouldApplySelfOutfitPatch()
                    if F.isLobbyLeftPage() or F.isSelfRoleInfoOpen() then
                        return true
                    end
                    if F.isBattleResultOrMvpOpen() then
                        return true
                    end
                    local ok = false
                    pcall(function()
                        if
                            GameStatus
                            and GameStatus.IsInLobbyOrMainCity
                            and GameStatus.IsInLobbyOrMainCity()
                        then
                            ok = true
                        end
                    end)
                    return ok
                end

                function F.getWeaponSkinResFast()
                    local cch = F.cache()
                    local wid = tonumber(DataMgr.Weapon_ID) or 0
                    local w = wid > 0 and cch.weapons[wid] or nil
                    if w and w.resID and w.resID > 0 then
                        return w.resID
                    end
                    for _, ww in pairs(cch.weapons) do
                        if ww.resID and ww.resID > 0 then
                            return ww.resID
                        end
                    end
                    return nil
                end

                function F.resolveLobbyWeaponSkinRes()
                    if LOBBY.skinResolved then
                        return LOBBY.cachedSkin
                    end
                    local wid = tonumber(DataMgr.Weapon_ID) or 0
                    local skin = F.getWeaponSkinResFast()
                    if skin and skin > 0 then
                        return skin
                    end

                    if wid > 0 then
                        local fromMatch = F.getMatchWeaponSkin(wid)
                        if fromMatch and fromMatch > 0 then
                            return fromMatch
                        end
                    end
                    if MATCH_CONFIG.weaponSkins then
                        for _, s in pairs(MATCH_CONFIG.weaponSkins) do
                            s = tonumber(s)
                            if s and s > 0 then
                                return s
                            end
                        end
                    end

                    pcall(function()
                        local Arm = require("client.logic.armory.logic_armory")
                        local entry = Arm.rsp_list
                            and Arm.rsp_list.install_list
                            and Arm.rsp_list.install_list[wid > 0 and wid or 101004]
                        local insID = tonumber(entry and entry.skin_id) or 0
                        if insID > 0 and F.isInjectedIns(insID) then
                            skin = tonumber(R.insToRes[insID])
                        elseif insID > 0 then
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            if d and d.resID then
                                skin = tonumber(d.resID)
                            end
                        end
                    end)
                    if skin and skin > 0 then
                        return skin
                    end

                    pcall(function()
                        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                        if wgl.GetSkinIdByWeaponID and wid > 0 then
                            local insID = tonumber(wgl:GetSkinIdByWeaponID(wid)) or 0
                            if insID > 0 and F.isInjectedIns(insID) then
                                skin = tonumber(R.insToRes[insID])
                            end
                        end
                    end)
                    LOBBY.skinResolved = true
                    LOBBY.cachedSkin = (skin and skin > 0) and skin or nil
                    return LOBBY.cachedSkin
                end

                function F.resolveLobbyOutfitRes()
                    if LOBBY.outfitResolved and LOBBY.cachedOutfit then
                        return LOBBY.cachedOutfit
                    end
                    LOBBY.outfitResolved = false
                    LOBBY.cachedOutfit = nil
                    local cch = F.cache()
                    local outfitRes = tonumber(cch.outfitRes) or 0
                    if outfitRes > 0 then
                        LOBBY.outfitResolved = true
                        LOBBY.cachedOutfit = outfitRes
                        return outfitRes
                    end
                    outfitRes = tonumber(_G.AddOutfitLastLobbyOutfitRes) or 0
                    if outfitRes > 0 then
                        LOBBY.outfitResolved = true
                        LOBBY.cachedOutfit = outfitRes
                        return outfitRes
                    end
                    if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
                        LOBBY.outfitResolved = true
                        LOBBY.cachedOutfit = tonumber(MATCH_CONFIG.outfitRes)
                        return LOBBY.cachedOutfit
                    end

                    local injectedRes, anyRes
                    pcall(function()
                        local AvatarData = require("client.logic.data.AvatarData")
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local function resFromIns(ins)
                            ins = tonumber(ins)
                            if not ins or ins <= 0 then
                                return nil
                            end
                            if F.isInjectedIns(ins) then
                                return tonumber(R.insToRes[ins])
                            end
                            local d = wd:GetHallDepotItemDataByInsID(ins)
                            return d and tonumber(d.resID) or nil
                        end
                        for _, ins in pairs(AvatarData.GetRoleWear()) do
                            local res = resFromIns(ins)
                            if res and F.isSuitRes(res) then
                                if F.isInjectedRes(res) then
                                    injectedRes = res
                                end
                                anyRes = anyRes or res
                            end
                        end
                        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                        if bag and bag.rolewear_list then
                            for _, ins in pairs(bag.rolewear_list) do
                                local res = resFromIns(ins)
                                if res and F.isSuitRes(res) then
                                    if F.isInjectedRes(res) then
                                        injectedRes = res
                                    end
                                    anyRes = anyRes or res
                                end
                            end
                        end
                    end)
                    if injectedRes and injectedRes > 0 then
                        LOBBY.outfitResolved = true
                        LOBBY.cachedOutfit = injectedRes
                        return injectedRes
                    end
                    if anyRes and anyRes > 0 then
                        LOBBY.outfitResolved = true
                        LOBBY.cachedOutfit = anyRes
                        return anyRes
                    end
                    LOBBY.outfitResolved = true
                    LOBBY.cachedOutfit = nil
                    return nil
                end

                function F.rememberLobbyOutfitRes(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 or not F.isSuitRes(resID) then
                        return
                    end
                    _G.AddOutfitLastLobbyOutfitRes = resID
                    F.invalidateLobbyResolved()
                    local cch = F.cache()
                    if not cch.outfitRes or cch.outfitRes <= 0 then
                        cch.outfitRes = resID
                        if F.isInjectedRes(resID) then
                            cch.outfitIns = R.resToIns[resID]
                        end
                    end
                end

                function F.wearPatchKey()
                    local outfit = F.resolveLobbyOutfitRes() or 0
                    local skin = F.resolveLobbyWeaponSkinRes() or 0
                    local openGun = 1
                    pcall(function()
                        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                        if lds.data and lds.data.OpenGun ~= nil then
                            openGun = lds.data.OpenGun and 1 or 0
                        end
                    end)
                    return outfit .. "_" .. skin .. "_" .. openGun
                end

                function F.syncDepotShowWeaponFlags(depot)
                    depot = depot or {}
                    pcall(function()
                        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                        if lds.data then
                            if lds.data.OpenGun ~= nil then
                                depot.weapon = lds.data.OpenGun
                            end
                            if lds.data.OpenSocialWeapon ~= nil then
                                depot.social_weapon = lds.data.OpenSocialWeapon
                            end
                        end
                    end)
                    return depot
                end

                function F.applyInjectedPspace(roleData)
                    if not roleData then
                        return
                    end
                    roleData.bshow = true
                    roleData.pspace_wear_ext = roleData.pspace_wear_ext or {}
                    local outfitRes = F.resolveLobbyOutfitRes()
                    if outfitRes and outfitRes > 0 then
                        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
                    end
                    local skinRes = F.resolveLobbyWeaponSkinRes()
                    if skinRes and skinRes > 0 then
                        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 }
                        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] =
                            { skinRes, 0, 0 }
                        roleData.depot_show_info = roleData.depot_show_info or {}
                        if roleData.depot_show_info.weapon == nil then
                            roleData.depot_show_info.weapon = true
                        end
                    end
                    roleData.depot_show_info = F.syncDepotShowWeaponFlags(roleData.depot_show_info)
                end

                function F.patchSelfWearCache(force)
                    local key = F.wearPatchKey()
                    if not force and SOCIAL.wearPatchKey == key then
                        return false
                    end
                    SOCIAL.wearPatchKey = key
                    SOCIAL.snapshotKey = nil
                    SOCIAL.fullSnapshot = nil

                    local myUid = tonumber(DataMgr.roleData.uid)
                    if not myUid then
                        return false
                    end

                    local changed = false
                    pcall(function()
                        local BD =
                            ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
                        local d = BD:GetCacheData(myUid)
                        if not d then
                            BD:OnHandleMsgDataAndCallback(myUid, F.buildLocalRoleDataForCoupleAvatar())
                            return true
                        end
                        local oldCloth = d.pspace_wear_ext
                            and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
                        local oldSkin = d.pspace_wear_ext
                            and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
                        F.applyInjectedPspace(d)
                        local nc = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
                        local ns = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
                        if oldCloth ~= nc or oldSkin ~= ns or not d.bshow then
                            changed = true
                        end
                    end)
                    return force or changed
                end

                function F.requestSocialAvatarRefresh()
                    pcall(function()
                        if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR then
                            EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR)
                        end
                    end)
                end

                function F.onSocialWearDirty(forceRefresh)
                    SOCIAL.lastHandSkin = nil
                    if F.patchSelfWearCache(forceRefresh) then
                        F.requestSocialAvatarRefresh()
                    end
                end

                function F.buildLocalRoleDataForCoupleAvatar()
                    local key = F.wearPatchKey()
                    if SOCIAL.fullSnapshot and SOCIAL.snapshotKey == key then
                        return SOCIAL.fullSnapshot
                    end
                    F.syncWeaponCacheFromLobby()
                    local cch = F.cache()
                    local ad = DataMgr.avatarData or {}
                    local gender = tonumber(ad.gamegender) or 2
                    if gender < 1 then
                        gender = 2
                    end

                    local data = {
                        uid = DataMgr.roleData.uid,
                        gender = gender,
                        bshow = true,
                        pspace_wear_ext = {
                            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEAD] = { tonumber(ad.headid) or 401993, 0, 0 },
                            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HAIR] = { tonumber(ad.hairid) or 40601001, 0, 0 },
                            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 },
                            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { 0, 0, 0 },
                        },
                        depot_show_info = {
                            weapon = true,
                            social_weapon = true,
                            idle = true,
                            helmet = true,
                            bag = true,
                            vehicle = true,
                            hand = true,
                        },
                    }

                    local outfitRes = F.resolveLobbyOutfitRes()
                    if outfitRes and outfitRes > 0 then
                        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
                    end

                    local skinRes = F.resolveLobbyWeaponSkinRes()
                    if skinRes and skinRes > 0 then
                        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON][1] = 0
                        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN][1] = skinRes
                    end
                    data.depot_show_info = F.syncDepotShowWeaponFlags(data.depot_show_info)
                    SOCIAL.fullSnapshot = data
                    SOCIAL.snapshotKey = F.wearPatchKey()
                    return data
                end

                local _myUidCached
                function F.isMyWearData(wearData)
                    if not wearData then
                        return false
                    end
                    if not _myUidCached then
                        pcall(function()
                            _myUidCached = tonumber(DataMgr.roleData.uid)
                        end)
                    end
                    return _myUidCached and tonumber(wearData.uid) == _myUidCached
                end

                function F.mergeInjectedWeaponIntoWearData(wearData)
                    if not F.isMyWearData(wearData) then
                        return
                    end
                    local skinRes = F.resolveLobbyWeaponSkinRes()
                    wearData.depot_show_info = F.syncDepotShowWeaponFlags(wearData.depot_show_info)
                    if not skinRes or skinRes <= 0 then
                        return
                    end
                    wearData.mainWeaponInfo = wearData.mainWeaponInfo
                        or {
                            weaponResId = 0,
                            weaponSkinId = 0,
                            diyInfo = { diyWeaponId = 0, diyDefaultScheme = false, diyScheme = nil },
                        }
                    if
                        wearData.mainWeaponInfo.weaponSkinId == skinRes
                        and (tonumber(wearData.mainWeaponInfo.weaponResId) or 0) == 0
                    then
                        return
                    end
                    wearData.mainWeaponInfo.weaponSkinId = skinRes
                    wearData.mainWeaponInfo.weaponResId = 0
                end

                function F.equipSocialHandWeapon(avatar, skinRes)
                    if not avatar or not skinRes or skinRes <= 0 then
                        return
                    end
                    if SOCIAL.lastHandSkin == skinRes then
                        return
                    end
                    SOCIAL.lastHandSkin = skinRes
                    pcall(function()
                        avatar:PutonEquipment(skinRes, nil, { bIsUse = true })
                    end)
                end

                function F.shouldShowHandWeapon()
                    local show = true
                    pcall(function()
                        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                        if lds.data and lds.data.OpenGun ~= nil then
                            show = lds.data.OpenGun ~= false
                        end
                    end)
                    return show
                end

                function F.mergeInjectedOutfitIntoWearData(wearData)
                    if not F.isMyWearData(wearData) then
                        return
                    end
                    local outfitRes = F.resolveLobbyOutfitRes()
                    if not outfitRes or outfitRes <= 0 then
                        return
                    end
                    F.rememberLobbyOutfitRes(outfitRes)
                    local AvatarData = require("client.logic.data.AvatarData")
                    local converted = AvatarData.ConvertToAvatarCustom({ outfitRes, 0, 0 })
                    if not converted then
                        return
                    end
                    wearData.WearInfoList = wearData.WearInfoList or {}
                    local replaced = false
                    for i, e in ipairs(wearData.WearInfoList) do
                        if e and e.ItemID and F.isSuitRes(e.ItemID) then
                            wearData.WearInfoList[i] = converted
                            replaced = true
                            break
                        end
                    end
                    if not replaced then
                        table.insert(wearData.WearInfoList, converted)
                    end
                end

                function F.mergeInjectedIntoWearData(wearData)
                    if not wearData then
                        return
                    end
                    F.mergeInjectedWeaponIntoWearData(wearData)
                    F.mergeInjectedOutfitIntoWearData(wearData)
                end

                function F.reapplyLobbyEquipped()
                    if
                        not GameStatus
                        or not GameStatus.IsInLobbyOrMainCity
                        or not GameStatus.IsInLobbyOrMainCity()
                    then
                        return
                    end
                    F.syncWeaponCacheFromLobby()
                    F.applyPersistSlotsToCache()
                    local curPage = F.getLobbyCurPage()

                    if ENUM_LobbyPageType and curPage == ENUM_LobbyPageType.Left then
                        F.onSocialWearDirty(true)
                        return
                    end

                    local cch = F.cache()
                    if cch.outfitIns and F.isInjectedIns(cch.outfitIns) then
                        F.putOnOutfit(cch.outfitIns)
                    end
                    if cch.hatIns and F.isInjectedIns(cch.hatIns) then
                        F.putOnHat(cch.hatIns)
                    end
                    if cch.maskIns and F.isInjectedIns(cch.maskIns) then
                        F.putOnRoleWear(cch.maskIns)
                    end
                    if cch.glassIns and F.isInjectedIns(cch.glassIns) then
                        F.putOnRoleWear(cch.glassIns)
                    end
                    if cch.tshirtIns and F.isInjectedIns(cch.tshirtIns) then
                        F.putOnRoleWear(cch.tshirtIns)
                    end
                    if cch.pantsIns and F.isInjectedIns(cch.pantsIns) then
                        F.putOnRoleWear(cch.pantsIns)
                    end
                    if cch.shoesIns and F.isInjectedIns(cch.shoesIns) then
                        F.putOnRoleWear(cch.shoesIns)
                    end
                    if cch.bagIns and F.isInjectedIns(cch.bagIns) then
                        F.putOnRoleWear(cch.bagIns)
                    end
                    if cch.helmetIns and F.isInjectedIns(cch.helmetIns) then
                        F.putOnRoleWear(cch.helmetIns)
                    end
                    if cch.parachuteIns then
                        F.putOnParachute(cch.parachuteIns)
                    end
                    if cch.gliderIns then
                        F.putOnGlider(cch.gliderIns)
                    end
                    if cch.glovesIns and F.isInjectedIns(cch.glovesIns) then
                        F.putOnGloves(cch.glovesIns)
                    end

                    F.reapplyLobbyCurrentWeapon()
                    F.reapplyVehicleSlotsFromConfig(true)
                    F.reapplyHallThemeFromConfig(true)
                    F.reapplyWeaponsFromConfig()
                    pcall(F.applyVehicleSkinsToPC)
                    if _G.NTHUY2004Config and _G.NTHUY2004Config.ModPet then
                        pcall(F.injectAllPets)
                        pcall(F.applyPersistedPet)
                    end
                end

                function F.reapplyLobbyCurrentWeapon()
                    if
                        not GameStatus
                        or not GameStatus.IsInLobbyOrMainCity
                        or not GameStatus.IsInLobbyOrMainCity()
                    then
                        return
                    end
                    F.syncWeaponCacheFromLobby()
                    local cch = F.cache()
                    local displayWid = tonumber(DataMgr.Weapon_ID) or 0
                    if displayWid <= 0 then
                        return
                    end
                    local w = cch.weapons[displayWid]

                    if (not w or not w.resID) and displayWid == MELEE_ID then
                        for wid, ww in pairs(cch.weapons or {}) do
                            wid = tonumber(wid)
                            if wid and wid >= 108000 and wid < 109000 and ww and ww.resID then
                                w = ww
                                displayWid = wid
                                break
                            end
                        end
                    end
                    if not w or not w.resID or w.resID <= 0 then
                        return
                    end
                    if w.insID and F.isInjectedIns(w.insID) then
                        local prev = _G.AddOutfitSkipGunReapply
                        _G.AddOutfitSkipGunReapply = true
                        pcall(function()
                            F.equipWeaponSkin(displayWid, w.insID)
                        end)
                        _G.AddOutfitSkipGunReapply = prev
                        pcall(function()
                            local uid = tostring(DataMgr.roleData.uid)
                            local LAM = require("client.logic.avatar.LobbyAvatarManager")
                            local TAM = require("client.logic.avatar.logic_team_avatar_manager")
                            if TAM.GetAvatarByUid(uid) then
                                LAM.EquipWeapon(uid, { weaponId = displayWid, skinId = w.resID }, nil, true)
                            end
                        end)
                    else
                        pcall(function()
                            DataMgr.InitWeaponData(displayWid, w.resID, w.insID or 0)
                        end)
                    end
                end

                F.scheduleLobbyReapplyOnce = function()
                    if LOBBY.reapplyDone or LOBBY.reapplyScheduled then
                        return
                    end
                    LOBBY.reapplyScheduled = true
                    F.later(2.0, function()
                        LOBBY.reapplyScheduled = false
                        if LOBBY.reapplyDone then
                            return
                        end
                        LOBBY.reapplyDone = true
                        F.reapplyLobbyEquipped()
                    end)
                end

                function F.hookBattleResultSkins()
                    if _G.AddOutfitBattleResultHooked then
                        return
                    end
                    _G.AddOutfitBattleResultHooked = true

                    pcall(function()
                        local M = require(
                            "GameLua.Mod.BaseMod.Client.BattleResult.BattleResultData.BattleResultDataLogic"
                        )
                        local impl = M and (M.__inner_impl or M)
                        if not impl or not impl.OnBattleResult or impl._AddOutfitBRDataHooked then
                            return
                        end
                        impl._AddOutfitBRDataHooked = true
                        local o = impl.OnBattleResult
                        impl.OnBattleResult = function(self, result)
                            if result and result.TeammateList then
                                F.patchSelfInTeammateList(result.TeammateList)
                            end
                            return o(self, result)
                        end
                    end)

                    pcall(function()
                        local M = require(
                            "GameLua.Mod.Library.Client.BattleResultLib.SpecialShow.Logic.BattleResultSpecialShowBaseLogic"
                        )
                        local impl = M and (M.__inner_impl or M)
                        if not impl or not impl.PutOnAvatar or impl._AddOutfitBRPutOnHooked then
                            return
                        end
                        impl._AddOutfitBRPutOnHooked = true
                        local o = impl.PutOnAvatar
                        impl.PutOnAvatar = function(self, InPawn, InData)
                            if InData and InData.wear_ext and F.isSelfUid(InData.UID) then
                                F.patchSelfBattleResultWearExt(InData.wear_ext)
                            end
                            return o(self, InPawn, InData)
                        end
                    end)

                    pcall(function()
                        local M = require(
                            "GameLua.Mod.BaseMod.Client.BattleResult.ShowAvatar.BattleResultShowAvatarLogic"
                        )
                        local impl = M and (M.__inner_impl or M)
                        if not impl or not impl.InitRoleInfoList or impl._AddOutfitBRAvatarHooked then
                            return
                        end
                        impl._AddOutfitBRAvatarHooked = true
                        local oInit = impl.InitRoleInfoList
                        impl.InitRoleInfoList = function(self, result)
                            if result and result.TeammateList then
                                F.patchSelfInTeammateList(result.TeammateList)
                            end
                            return oInit(self, result)
                        end
                        if impl.OnResultProcessStart then
                            local oStart = impl.OnResultProcessStart
                            impl.OnResultProcessStart = function(self, ...)
                                F.prepareBattleResultWearPatch()
                                F.patchSelfWearCache(true)
                                return oStart(self, ...)
                            end
                        end
                    end)

                    pcall(function()
                        local M = require(
                            "GameLua.Mod.BaseMod.Client.BattleResult.ShowMvp.BattleResultShowMvpLogic"
                        )
                        local impl = M and (M.__inner_impl or M)
                        if not impl or impl._AddOutfitBRMvpHooked then
                            return
                        end
                        impl._AddOutfitBRMvpHooked = true
                        if impl.InitBRModeMvpInfo then
                            local o = impl.InitBRModeMvpInfo
                            impl.InitBRModeMvpInfo = function(self, result)
                                if result and result.TeammateList then
                                    F.patchSelfInTeammateList(result.TeammateList)
                                end
                                return o(self, result)
                            end
                        end
                        if impl._InitTDMModeMvpInfo then
                            local o = impl._InitTDMModeMvpInfo
                            impl._InitTDMModeMvpInfo = function(self, list)
                                F.patchSelfInTeammateList(list)
                                return o(self, list)
                            end
                        end
                        if impl.OnResultProcessStart then
                            local oStart = impl.OnResultProcessStart
                            impl.OnResultProcessStart = function(self, ...)
                                F.prepareBattleResultWearPatch()
                                F.patchSelfWearCache(true)
                                return oStart(self, ...)
                            end
                        end
                    end)
                end

                function F.hookLobbySwipePersistence()
                    if _G.AddOutfitLobbySwipeHooked then
                        return
                    end
                    _G.AddOutfitLobbySwipeHooked = true
                    pcall(function()
                        local BD =
                            ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
                        local oRsp = BD.on_get_avatar_show_rsp
                        BD.on_get_avatar_show_rsp = function(self, res, target_uid, data)
                            if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) and data then
                                F.applyInjectedPspace(data)
                            end
                            oRsp(self, res, target_uid, data)
                            if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) then
                                F.patchSelfWearCache(true)
                                SOCIAL.forceAvatarRedraw = true
                                SOCIAL.lastHandSkin = nil
                                if ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left then
                                    F.requestSocialAvatarRefresh()
                                end
                            end
                        end
                    end)

                    pcall(function()
                        local AC = require("client.slua.logic.avatar.avatar_common")
                        local oGetWear = AC.GetWearDataFromRoleData
                        AC.GetWearDataFromRoleData = function(roleData)
                            local wearData = oGetWear(roleData)
                            if
                                wearData
                                and roleData
                                and tonumber(roleData.uid) == tonumber(DataMgr.roleData.uid)
                                and F.shouldApplySelfOutfitPatch()
                            then
                                F.mergeInjectedIntoWearData(wearData)
                            end
                            return wearData
                        end
                        local oUp = AC.UpdateAvatar
                        AC.UpdateAvatar = function(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
                            if F.isMyWearData(wearData) and F.shouldApplySelfOutfitPatch() then
                                F.mergeInjectedIntoWearData(wearData)
                            end
                            local showGun = isShowWeapon and F.shouldShowHandWeapon()
                            if wearData and wearData.depot_show_info then
                                showGun = showGun and wearData.depot_show_info.weapon ~= false
                            end
                            if F.isMyWearData(wearData) and F.shouldApplySelfOutfitPatch() then
                                for _, e in ipairs(wearData.WearInfoList or {}) do
                                    if e and e.ItemID and F.isSuitRes(e.ItemID) then
                                        F.rememberLobbyOutfitRes(e.ItemID)
                                        break
                                    end
                                end
                            end
                            local ret = oUp(avatar, wearData, showGun, isShowHelmet, isShowBag)
                            if
                                showGun
                                and F.isMyWearData(wearData)
                                and avatar
                                and F.shouldApplySelfOutfitPatch()
                            then
                                local skin = tonumber(
                                    wearData.mainWeaponInfo and wearData.mainWeaponInfo.weaponSkinId
                                ) or 0
                                if skin <= 0 then
                                    skin = F.resolveLobbyWeaponSkinRes() or 0
                                end
                                if skin > 0 then
                                    F.equipSocialHandWeapon(avatar, skin)
                                end
                            end
                            return ret
                        end
                    end)

                    pcall(function()
                        local CA = require("client.logic.avatar.CoupleAvatar")
                        local Cfg = require("client.slua.logic.lobby.Left.CoupleAvatarConfig")
                        local oMulti = CA._UpdateMultiAvatar
                        if oMulti then
                            CA._UpdateMultiAvatar = function(self, avatar, avatarType)
                                local isSelf = avatarType == Cfg.AvatarType.Self
                                    and self.SelfUID
                                    and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
                                if isSelf and F.shouldApplySelfOutfitPatch() then
                                    pcall(function()
                                        local BD = ModuleManager.GetModule(
                                            ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo
                                        )
                                        local d = BD:GetCacheData(tonumber(self.SelfUID))
                                        if d then
                                            F.applyInjectedPspace(d)
                                        end
                                    end)
                                    if SOCIAL.forceAvatarRedraw then
                                        self.CompareDataCache[avatarType] = nil
                                        SOCIAL.forceAvatarRedraw = nil
                                    end
                                end
                                oMulti(self, avatar, avatarType)
                                if
                                    isSelf
                                    and F.shouldApplySelfOutfitPatch()
                                    and self.isShowWeapon ~= false
                                    and F.shouldShowHandWeapon()
                                then
                                    local skin = F.resolveLobbyWeaponSkinRes()
                                    if skin and skin > 0 then
                                        F.equipSocialHandWeapon(avatar, skin)
                                    end
                                end
                            end
                        end
                        local oHideCheck = CA.CheckSelfIsHideAvatar
                        CA.CheckSelfIsHideAvatar = function(self, nSelfUId, tRoleData)
                            if
                                F.shouldApplySelfOutfitPatch()
                                and tostring(nSelfUId) == tostring(DataMgr.roleData.uid)
                            then
                                return false
                            end
                            return oHideCheck(self, nSelfUId, tRoleData)
                        end

                        local oUpdate = CA.Update
                        CA.Update = function(self)
                            if not F.shouldApplySelfOutfitPatch() and not F.isLobbyLeftPage() then
                                return oUpdate(self)
                            end
                            local isSelf = self.SelfUID
                                and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
                            local oHide = CA.HideAvatars
                            if isSelf then
                                CA.HideAvatars = function() end
                            end
                            local ok, err = pcall(oUpdate, self)
                            CA.HideAvatars = oHide
                        end

                        local oRecv = CA.OnReceiveData
                        CA.OnReceiveData = function(self, uid, data)
                            if
                                tostring(uid) == tostring(DataMgr.roleData.uid)
                                and F.shouldApplySelfOutfitPatch()
                            then
                                if data then
                                    F.applyInjectedPspace(data)
                                else
                                    data = F.buildLocalRoleDataForCoupleAvatar()
                                end
                            end
                            return oRecv(self, uid, data)
                        end
                    end)

                    pcall(function()
                        if not EventSystem or not EventSystem.registEvent then
                            return
                        end
                        if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_START then
                            EventSystem:registEvent(
                                EVENTTYPE_LOBBY,
                                EVENTID_SWITCHTO_PAGE_START,
                                function(_, _, toPage)
                                    if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                                        F.syncWeaponCacheFromLobby()
                                        SOCIAL.lastHandSkin = nil
                                        local o = F.resolveLobbyOutfitRes()
                                        if o then
                                            F.rememberLobbyOutfitRes(o)
                                        end
                                        F.patchSelfWearCache(true)
                                        SOCIAL.forceAvatarRedraw = true
                                    end
                                end
                            )
                        end
                        if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_END then
                            EventSystem:registEvent(
                                EVENTTYPE_LOBBY,
                                EVENTID_SWITCHTO_PAGE_END,
                                function(_, _, _, toPage)
                                    if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                                        F.syncWeaponCacheFromLobby()
                                        SOCIAL.lastHandSkin = nil
                                        F.socialDebounce(0.45, function()
                                            F.onSocialWearDirty(true)
                                        end)
                                    elseif ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Mid then
                                        SOCIAL.wearPatchKey = nil
                                        F.invalidateLobbyResolved()
                                        if not LOBBY.reapplyDone then
                                            F.socialDebounce(0.5, F.scheduleLobbyReapplyOnce)
                                        end
                                    end
                                end
                            )
                        end
                        if EVENTTYPE_LOBBY_SOCIAL and EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA then
                            EventSystem:registEvent(
                                EVENTTYPE_LOBBY_SOCIAL,
                                EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA,
                                function(_, _, nUId)
                                    if tonumber(nUId) == tonumber(DataMgr.roleData.uid) then
                                        F.socialDebounce(0.2, function()
                                            F.patchSelfWearCache(false)
                                        end)
                                    end
                                end
                            )
                        end
                        if EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_UPDATE_ROLEINFO then
                            EventSystem:registEvent(
                                EVENTTYPE_ROLEINFO,
                                EVENTID_ROLEINFO_UPDATE_ROLEINFO,
                                function()
                                    F.invalidateLobbyResolved()
                                    F.patchSelfWearCache(true)
                                    F.requestSocialAvatarRefresh()
                                end
                            )
                        end
                        if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
                            EventSystem:registEvent(
                                EVENTTYPE_WARDROBE,
                                EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN,
                                function()
                                    if _G.AddOutfitSkipGunReapply then
                                        return
                                    end
                                    SOCIAL.wearPatchKey = nil
                                    SOCIAL.snapshotKey = nil
                                    F.syncWeaponCacheFromLobby()

                                    local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
                                    if curPage == ENUM_LobbyPageType.Left then
                                        F.socialDebounce(0.25, function()
                                            F.onSocialWearDirty(true)
                                        end)
                                    end

                                    F.socialDebounce(0.3, function()
                                        if F.reapplyLobbyCurrentWeapon then
                                            F.reapplyLobbyCurrentWeapon()
                                        end
                                    end)
                                end
                            )
                        end
                    end)

                    pcall(function()
                        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
                        local oSwitch = lds.SwitchGun
                        lds.SwitchGun = function(...)
                            local r = oSwitch(...)
                            if _G.AddOutfitSkipGunReapply then
                                return r
                            end
                            SOCIAL.wearPatchKey = nil

                            local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
                            if curPage == ENUM_LobbyPageType.Left then
                                F.socialDebounce(0.2, function()
                                    F.onSocialWearDirty(true)
                                end)
                            end

                            F.socialDebounce(0.3, function()
                                if F.reapplyLobbyCurrentWeapon then
                                    F.reapplyLobbyCurrentWeapon()
                                end
                            end)

                            return r
                        end
                    end)
                end

                function F.hookDepotInit()
                    pcall(function()
                        local WDE = require("client.slua.logic.wardrobe.WardrobeDataEntity")
                        if WDE._AddOutfitInitHooked then
                            return
                        end
                        WDE._AddOutfitInitHooked = true
                        local orig = WDE.InitData
                        WDE.InitData = function(self, pkg)
                            orig(self, pkg)
                            _G.AddOutfitUnexpireDone = false
                            pcall(function()
                                if F.injectAll(self) then
                                    F.scheduleInjectRefresh()
                                    LOBBY.reapplyDone = false
                                    LOBBY.reapplyScheduled = false
                                    F.scheduleLobbyReapplyOnce()
                                end
                            end)
                        end
                    end)
                end

                function F.hookWardrobeData()
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        if wd._AddOutfitDataHooked then
                            return
                        end
                        wd._AddOutfitDataHooked = true
                        local function wrapGet(name)
                            local o = wd[name]
                            if not o then
                                return
                            end
                            wd[name] = function(self, insID, ...)
                                insID = tonumber(insID)
                                local r
                                if F.isInjectedIns(insID) then
                                    local e = F.getEntity()
                                    if e then
                                        r = e:GetDataByInsID(insID)
                                    end
                                else
                                    r = o(self, insID, ...)
                                end
                                if r and (tonumber(r.count) or 0) <= 0 then
                                    return nil
                                end
                                if r and (F.isInjectedIns(insID) or F.isInjectedRes(r.resID or r.res_id)) then
                                    r.expire_ts = 0
                                    r.expireTS = 0
                                    r.valid_hours = 0
                                end
                                return r
                            end
                        end
                        wrapGet("GetHallDepotItemDataByInsID")
                        wrapGet("GetValidHallDepotItemDataByInsID")
                        local oCountByRes = wd.GetHallDepotItemCountByResID
                        if oCountByRes then
                            F._wardrobeOrigCountByRes = oCountByRes
                            wd.GetHallDepotItemCountByResID = function(self, resID, ...)
                                resID = tonumber(resID)

                                if
                                    resID
                                    and type(FLS) == "table"
                                    and FLS.IsEnabled
                                    and FLS.IsEnabled()
                                    and FLS.getXSuitVirtualMatCount
                                then
                                    local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
                                    if vn > 0 then
                                        return vn
                                    end
                                end
                                local n = tonumber(oCountByRes(self, resID, ...)) or 0
                                if n <= 0 and resID then
                                    local c = F.getEntityDepotCount and F.getEntityDepotCount(resID) or 0
                                    if c > 0 then
                                        return c
                                    end
                                end
                                return n
                            end
                        end
                        local oCountValid = wd.GetHallDepotItemCountByResIDAndValidInfo
                        if oCountValid then
                            wd.GetHallDepotItemCountByResIDAndValidInfo = function(
                                self,
                                resID,
                                isValidTime,
                                ...
                            )
                                resID = tonumber(resID)
                                if
                                    resID
                                    and type(FLS) == "table"
                                    and FLS.IsEnabled
                                    and FLS.IsEnabled()
                                    and FLS.getXSuitVirtualMatCount
                                then
                                    local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
                                    if vn > 0 then
                                        return vn
                                    end
                                end
                                local n = tonumber(oCountValid(self, resID, isValidTime, ...)) or 0
                                if n <= 0 and resID then
                                    local c = F.getEntityDepotCount and F.getEntityDepotCount(resID) or 0
                                    if c > 0 then
                                        return c
                                    end
                                end
                                return n
                            end
                        end
                        local oDataValidExpire = wd.GetHallDepotItemDataByResIDAndValidExpireTime
                        if oDataValidExpire then
                            wd.GetHallDepotItemDataByResIDAndValidExpireTime = function(self, resID, ...)
                                local r = oDataValidExpire(self, resID, ...)
                                if r and (tonumber(r.count) or 0) > 0 then
                                    return r
                                end
                                resID = tonumber(resID)
                                if
                                    resID
                                    and (
                                        F.isInjectedRes(resID)
                                        or (F.getEntityDepotCount and F.getEntityDepotCount(resID) > 0)
                                    )
                                then
                                    local e = F.getEntity()
                                    local ins = R.resToIns[resID]
                                        or (e and F.firstInsForRes and F.firstInsForRes(e, resID))
                                    local d = e and ins and e.GetDataByInsID and e:GetDataByInsID(ins)
                                    if d and (tonumber(d.count) or 0) > 0 then
                                        return d
                                    end
                                end
                                return r
                            end
                        end
                        local oListByRes = wd.GetHallDepotItemListByResID
                        if oListByRes then
                            wd.GetHallDepotItemListByResID = function(self, resID, ...)
                                resID = tonumber(resID)
                                if resID and F.isInjectedRes(resID) and F.isInjectedDepotAlive(resID) then
                                    local e = F.getEntity()
                                    local ins = R.resToIns[resID]
                                    local d = e and ins and e.GetDataByInsID and e:GetDataByInsID(ins)
                                    if d and (tonumber(d.count) or 0) > 0 then
                                        return { d }
                                    end
                                    return {}
                                end
                                return oListByRes(self, resID, ...)
                            end
                        end
                        local function wrapBool(name)
                            local o = wd[name]
                            if not o then
                                return
                            end
                            wd[name] = function(self, id, ...)
                                id = tonumber(id)
                                if id and (F.isInjectedRes(id) or F.isInjectedIns(id)) then
                                    if F.isInjectedIns(id) then
                                        return F.isInjectedDepotAlive(nil, id)
                                    end
                                    return F.isInjectedDepotAlive(id, nil)
                                end
                                return o(self, id, ...)
                            end
                        end
                        wrapBool("HasItem")
                        wrapBool("HasValidItem")
                        wrapBool("CheckHasPermanentItem")
                    end)
                end

                function F.hookPageFilter()
                    pcall(function()
                        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if wl._AddOutfitPageFilterHooked then
                            return
                        end
                        wl._AddOutfitPageFilterHooked = true
                        local o1 = wl.IsValidCurrentPageItem
                        wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, t)
                            if v then
                                local cnt = tonumber(v.count)
                                if cnt ~= nil and cnt <= 0 then
                                    return o1(self, mainTab, subTab, v, t)
                                end
                            end
                            local resID = v and tonumber(v.resID or v.res_id)
                            if v and resID and F.isInjectedRes(resID) then
                                if not F.isInjectedDepotAlive(resID) then
                                    return o1(self, mainTab, subTab, v, t)
                                end

                                if F.isEmoteRes(resID) then
                                    local c = F.cfg(resID)
                                    local main = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                                    local itemTab = (c and c.WardrobeTab)
                                        or v.subTabType
                                        or F.wardrobeTab(resID)
                                        or 21
                                    if itemTab == 0 or itemTab == "" then
                                        itemTab = 21
                                    end
                                    v.mainTabType = main
                                    v.subTabType = itemTab
                                    if v.resID == nil then
                                        v.resID = resID
                                    end
                                    v.expire_ts = 0
                                    v.expireTS = 0
                                    return F.tabsEqual(mainTab, main) and F.tabsEqual(itemTab, subTab)
                                end

                                if mainTab == PAGE_VEHICLE and F.isVehicleRes(resID) then
                                    local itemTab = v.subTabType
                                    if itemTab == nil or itemTab == 0 or itemTab == "" then
                                        itemTab = F.vehicleWardrobeTab(resID)
                                        if itemTab ~= nil and itemTab ~= 0 and itemTab ~= "" then
                                            v.subTabType = itemTab
                                            v.mainTabType = PAGE_VEHICLE
                                        end
                                    end
                                    return F.tabsEqual(itemTab, subTab)
                                end
                                local itemTab = v.subTabType
                                if itemTab == nil or itemTab == 0 or itemTab == "" then
                                    itemTab = F.wardrobeTab(resID)
                                end
                                if itemTab and F.tabsEqual(itemTab, subTab) then
                                    if mainTab == PAGE_AVATAR then
                                        if F.isVehicleRes(resID) or F.isWeaponSkinRes(resID) then
                                            return o1(self, mainTab, subTab, v, t)
                                        end
                                        return true
                                    end

                                    if mainTab == PAGE_PARACHUTE then
                                        if F.isWeaponSkinRes(resID) then
                                            return o1(self, mainTab, subTab, v, t)
                                        end

                                        local mainCfg = tonumber((F.cfg(resID) or {}).WardrobeMainTab)
                                        if F.isVehicleRes(resID) and mainCfg == PAGE_VEHICLE then
                                            return o1(self, mainTab, subTab, v, t)
                                        end
                                        return true
                                    end
                                end
                            end
                            return o1(self, mainTab, subTab, v, t)
                        end
                        local o2 = wl.IsCanUse
                        wl.IsCanUse = function(self, resId)
                            if F.isInjectedRes(resId) then
                                return F.isInjectedDepotAlive(resId)
                            end
                            return o2(self, resId)
                        end
                        local o3 = wl.IsCharacterUse
                        wl.IsCharacterUse = function(self, resId)
                            if F.isInjectedRes(resId) then
                                return F.isInjectedDepotAlive(resId)
                            end
                            return o3(self, resId)
                        end
                        local o4 = wl.GetWardrobeInsIdByResId
                        wl.GetWardrobeInsIdByResId = function(self, resid)
                            resid = tonumber(resid)
                            if F.isInjectedRes(resid) then
                                if not F.isInjectedDepotAlive(resid) then
                                    return nil
                                end
                                return R.resToIns[resid]
                            end
                            return o4(self, resid)
                        end
                    end)
                end

                function F.hookArmory()
                    pcall(function()
                        local Arm = require("client.logic.armory.logic_armory")
                        if Arm._AddOutfitArmoryHooked then
                            return
                        end
                        Arm._AddOutfitArmoryHooked = true
                        local oa = Arm.get_weapon_skin_list_rsp
                        Arm.get_weapon_skin_list_rsp = function(a, b, c, d)
                            oa(a, b, c, d)
                            F.mergeInjectedArmorySkins()
                        end
                        local oi = Arm.install_weapon_skin
                        Arm.install_weapon_skin = function(cd, wid, ins)
                            ins = tonumber(ins)
                            if F.isWeaponSkinIns(ins) then
                                wid = tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                                F.equipWeaponSkin(wid, ins)
                                return
                            end
                            return oi(cd, wid, ins)
                        end
                    end)
                    pcall(function()
                        local AH = require("client.network.Protocol.ArmoryHandler")
                        if AH._AddOutfitArmorySendHooked then
                            return
                        end
                        AH._AddOutfitArmorySendHooked = true
                        local o = AH.send_install_weapon_skin
                        AH.send_install_weapon_skin = function(cd, wid, ins)
                            ins = tonumber(ins)
                            if F.isWeaponSkinIns(ins) then
                                wid = tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                                F.equipWeaponSkin(wid, ins)
                                return
                            end
                            return o(cd, wid, ins)
                        end
                    end)
                end

                function F.hookGunSkinId()
                    pcall(function()
                        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                        if wgl._AddOutfitGunSkinHooked then
                            return
                        end
                        wgl._AddOutfitGunSkinHooked = true
                        local o = wgl.GetSkinIdByWeaponID
                        wgl.GetSkinIdByWeaponID = function(self, wid)
                            local c = F.cache()
                            local w = c.weapons[wid]
                            if w and F.isWeaponSkinIns(w.insID) then
                                return w.insID
                            end
                            local Arm = require("client.logic.armory.logic_armory")
                            if
                                Arm.rsp_list
                                and Arm.rsp_list.install_list
                                and Arm.rsp_list.install_list[wid]
                            then
                                local sid = Arm.rsp_list.install_list[wid].skin_id
                                if sid and F.isWeaponSkinIns(sid) then
                                    return sid
                                end
                            end
                            return o(self, wid)
                        end
                    end)
                end

                function F.hookPutOn()
                    pcall(function()
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        if WRH._AddOutfitPutOnHooked then
                            return
                        end
                        WRH._AddOutfitPutOnHooked = true
                        local o = WRH.send_depot_put_on_req
                        WRH.send_depot_put_on_req = function(insID, extra)
                            insID = tonumber(insID)
                            if F.tryLocalWearByIns(insID) then
                                return
                            end
                            return o(insID, extra)
                        end
                    end)
                end

                function F.hookPutDown()
                    pcall(function()
                        local WRH = require("client.network.Protocol.WardRobeHandler")
                        if WRH._AddOutfitPutDownHooked then
                            return
                        end
                        WRH._AddOutfitPutDownHooked = true
                        local o = WRH.send_depot_put_down_req
                        WRH.send_depot_put_down_req = function(insID)
                            if F.isInjectedIns(tonumber(insID)) then
                                F.takeOffInjected(insID)
                                return
                            end
                            return o(insID)
                        end
                        local ob = WRH.send_depot_batch_put_down_req
                        WRH.send_depot_batch_put_down_req = function(instid_list)
                            local rest = {}
                            for _, id in ipairs(instid_list or {}) do
                                if F.isInjectedIns(tonumber(id)) then
                                    F.takeOffInjected(id)
                                else
                                    rest[#rest + 1] = id
                                end
                            end
                            if #rest > 0 then
                                return ob(rest)
                            end
                        end
                    end)
                end

                function F.isEmoteRes(resID)
                    resID = tonumber(resID)
                    if not resID then
                        return false
                    end
                    if resID >= 12200000 and resID < 12300000 then
                        return true
                    end
                    local c = F.cfg(resID)
                    local t = tonumber(c and (c.ItemType or c.itemType))
                    local st = tonumber(c and (c.ItemSubType or c.itemSubType))
                    return t == 22 and (st == 2201 or st == 2206)
                end

                function F.ensureMotionSlotCapacity(slot)
                    slot = tonumber(slot) or 0
                    if slot <= 0 then
                        return
                    end
                    local max = tonumber(DataMgr.MotionSlotMax) or 0
                    if max < slot then
                        DataMgr.MotionSlotMax = slot
                    end
                    while #DataMgr.MotionSlotList < slot do
                        table.insert(DataMgr.MotionSlotList, 0)
                    end
                end

                function F.buildMotionItem(insID)
                    insID = tonumber(insID)
                    if not insID or insID <= 0 then
                        return nil
                    end
                    local resID = R.insToRes[insID]
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetHallDepotItemDataByInsID(insID)
                    if d then
                        resID = resID or tonumber(d.resID or d.res_id)
                    end
                    if not resID then
                        return nil
                    end
                    return {
                        instid = insID,
                        insID = insID,
                        ins_id = insID,
                        res_id = resID,
                        resID = resID,
                        count = 1,
                    }
                end

                function F.postMotionSlotUpdate()
                    F.invalidateInGameEmoteCache()
                    pcall(function()
                        if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
                            EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
                        end
                    end)
                end

                function F.invalidateInGameEmoteCache()
                    _G.__EMOTE_INGAME_CACHE_DIRTY = true
                end

                function F.rememberLocalMotionSlot(slot, insID)
                    _G.AddOutfitLocalMotionSlots = _G.AddOutfitLocalMotionSlots or {}
                    slot = tonumber(slot)
                    insID = tonumber(insID) or 0
                    if not slot or slot <= 0 then
                        return
                    end
                    if insID > 0 then
                        _G.AddOutfitLocalMotionSlots[slot] = insID
                        local resID = R.insToRes[insID]
                        if not resID then
                            pcall(function()
                                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                local d = wd:GetHallDepotItemDataByInsID(insID)
                                if d then
                                    resID = tonumber(d.resID or d.res_id)
                                end
                            end)
                        end
                        if resID and resID > 0 then
                            F.persistRememberMotionSlot(slot, resID)
                        end
                    else
                        _G.AddOutfitLocalMotionSlots[slot] = nil
                        F.persistRememberMotionSlot(slot, nil)
                    end
                    F.invalidateInGameEmoteCache()
                end

                function F.applyLocalMotionSlots()
                    F.applyPersistedMotionSlots()
                    local slots = _G.AddOutfitLocalMotionSlots
                    if not slots then
                        return
                    end
                    for slot, ins in pairs(slots) do
                        slot = tonumber(slot)
                        ins = tonumber(ins) or 0
                        if slot and slot > 0 then
                            F.ensureMotionSlotCapacity(slot)
                            DataMgr.MotionSlotList[slot] = ins
                        end
                    end
                end

                function F.buildInGameEmoteListFromMotionSlots()
                    F.applyLocalMotionSlots()
                    local list = {}
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    for _, ins in ipairs(DataMgr.MotionSlotList or {}) do
                        ins = tonumber(ins)
                        if ins and ins > 0 then
                            local resID = tonumber(R.insToRes[ins])
                            local d = wd:GetHallDepotItemDataByInsID(ins)
                            if d then
                                resID = resID or tonumber(d.resID or d.res_id)
                            end
                            if resID and resID > 0 and F.isEmoteRes(resID) then
                                local name = tostring(resID)
                                pcall(function()
                                    local c = F.cfg(resID)
                                    if c and c.ItemName then
                                        name = c.ItemName
                                    end
                                end)
                                list[#list + 1] = {
                                    DefineID = { Type = 22, TypeSpecificID = resID },
                                    Name = name,
                                }
                            end
                        end
                    end
                    return list
                end

                function F.mergeMotionListWithSpecials(baseList, motionList)
                    local merged = {}
                    if baseList then
                        for _, data in ipairs(baseList) do
                            if data and data.bWeaponShow then
                                merged[#merged + 1] = data
                                break
                            end
                        end
                    end
                    for _, data in ipairs(motionList or {}) do
                        merged[#merged + 1] = data
                    end
                    if baseList then
                        for _, data in ipairs(baseList) do
                            if data and data.bClothEmote then
                                merged[#merged + 1] = data
                                break
                            end
                        end
                    end
                    return merged
                end

                function F.hookMotionSync()
                    pcall(function()
                        if _G.AddOutfitMotionSyncHooked then
                            return
                        end
                        _G.AddOutfitMotionSyncHooked = true
                        local orig = DataMgr.InitMotionInfo
                        if not orig then
                            return
                        end
                        DataMgr.InitMotionInfo = function(motion_info, limit)
                            orig(motion_info, limit)
                            F.applyLocalMotionSlots()
                            F.invalidateInGameEmoteCache()
                        end
                    end)
                end

                function F.localEquipMotion(instid, dst_slot)
                    instid = tonumber(instid)
                    dst_slot = tonumber(dst_slot)
                    if not instid or not dst_slot or dst_slot <= 0 then
                        return false
                    end
                    if not F.isInjectedIns(instid) then
                        return false
                    end
                    F.ensureDepotItemValid(instid)
                    local item = F.buildMotionItem(instid)
                    if not item or not F.isEmoteRes(item.resID) then
                        return false
                    end
                    F.ensureMotionSlotCapacity(dst_slot)
                    local oldIns = tonumber(DataMgr.MotionSlotList[dst_slot]) or 0
                    for i = 1, #DataMgr.MotionSlotList do
                        if tonumber(DataMgr.MotionSlotList[i]) == instid then
                            DataMgr.MotionSlotList[i] = 0
                        end
                    end
                    DataMgr.MotionSlotList[dst_slot] = instid
                    F.rememberLocalMotionSlot(dst_slot, instid)
                    local old_item = (oldIns > 0 and oldIns ~= instid) and F.buildMotionItem(oldIns) or nil
                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    WRH.on_equip_motion_rsp(NET_OK, dst_slot, item, old_item)
                    F.postMotionSlotUpdate()
                    return true
                end

                function F.localExchangeMotion(src_slot, dst_slot)
                    src_slot = tonumber(src_slot)
                    dst_slot = tonumber(dst_slot)
                    if not src_slot or not dst_slot or src_slot <= 0 or dst_slot <= 0 then
                        return false
                    end
                    F.ensureMotionSlotCapacity(math.max(src_slot, dst_slot))
                    local srcIns = tonumber(DataMgr.MotionSlotList[src_slot]) or 0
                    local dstIns = tonumber(DataMgr.MotionSlotList[dst_slot]) or 0
                    DataMgr.MotionSlotList[src_slot] = dstIns
                    DataMgr.MotionSlotList[dst_slot] = srcIns
                    F.rememberLocalMotionSlot(src_slot, dstIns)
                    F.rememberLocalMotionSlot(dst_slot, srcIns)
                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    WRH.on_exchange_motion_rsp(NET_OK, F.buildMotionItem(srcIns), F.buildMotionItem(dstIns))
                    F.postMotionSlotUpdate()
                    return true
                end

                function F.localUnequipMotion(instid, slot)
                    instid = tonumber(instid)
                    slot = tonumber(slot)
                    if not instid or not slot or slot <= 0 then
                        return false
                    end
                    if not F.isInjectedIns(instid) then
                        return false
                    end
                    F.ensureMotionSlotCapacity(slot)
                    if (tonumber(DataMgr.MotionSlotList[slot]) or 0) ~= instid then
                        return false
                    end
                    DataMgr.MotionSlotList[slot] = 0
                    F.rememberLocalMotionSlot(slot, 0)
                    local WRH = require("client.network.Protocol.WardRobeHandler")
                    WRH.on_unequip_motion_rsp(NET_OK, slot, F.buildMotionItem(instid))
                    F.postMotionSlotUpdate()
                    return true
                end

