                            VAH._nth_send_feature = VAH.send_equip_car_feature_req
                            VAH.send_equip_car_feature_req = function(car_id, resid, op_type)
                                if not F.vehicleModUnlockOn() then
                                    return VAH._nth_send_feature(car_id, resid, op_type)
                                end
                                local LVF = ModuleManager.GetModule(
                                    ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                                )
                                if not LVF then
                                    return VAH._nth_send_feature(car_id, resid, op_type)
                                end
                                local feature_data =
                                    F.applyExtendedFeatureEquipLocal(LVF, car_id, resid, op_type)
                                if not feature_data then
                                    return
                                end
                                return VAH.on_equip_car_feature_rsp(0, car_id, resid, op_type, feature_data)
                            end
                        end
                        if VAH.send_car_feature_op_req and not VAH._nth_send_feat_op then
                            VAH._nth_send_feat_op = VAH.send_car_feature_op_req
                            VAH.send_car_feature_op_req = function(feature_id, op_type)
                                if F.vehicleModUnlockOn() then
                                    return VAH.on_car_feature_op_rsp(0, feature_id, op_type)
                                end
                                return VAH._nth_send_feat_op(feature_id, op_type)
                            end
                        end
                    end)

                    pcall(function()
                        local LVF = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                        )
                        if not LVF or LVF._nth_FeatureEquipUnlock then
                            return
                        end
                        LVF._nth_FeatureEquipUnlock = true
                        if LVF.GetFeatureItemStateFlag and not LVF._nth_GetFeatureFlag then
                            LVF._nth_GetFeatureFlag = LVF.GetFeatureItemStateFlag
                            LVF.GetFeatureItemStateFlag = function(self, featureId)
                                if F.vehicleModUnlockOn() and featureId then
                                    F.seedExtendedFeatureOwnership()
                                    return 0
                                end
                                return LVF._nth_GetFeatureFlag(self, featureId)
                            end
                        end
                        if LVF.on_equip_car_feature_rsp and not LVF._nth_feature_rsp then
                            LVF._nth_feature_rsp = LVF.on_equip_car_feature_rsp
                            LVF.on_equip_car_feature_rsp = function(
                                self,
                                car_id,
                                resid,
                                op_type,
                                feature_data
                            )
                                if not resid or op_type == nil or not feature_data then
                                    return
                                end
                                if self.InitServerData then
                                    self:InitServerData(feature_data)
                                end
                                if car_id then
                                    pcall(function()
                                        local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                                        if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                                            HallThemeUtils.ShowThemeVehicle()
                                        end
                                    end)
                                end
                                pcall(function()
                                    EventSystem:postEvent(
                                        EVENTTYPE_VEHICLE_ACCESSORY,
                                        EVENTID_VEHICLE_EXTENDED_FEATURE_EQUIP_UPDATE,
                                        resid,
                                        op_type,
                                        car_id
                                    )
                                end)
                            end
                        end
                        if LVF.send_equip_car_feature_req and not LVF._nth_send_feature then
                            LVF._nth_send_feature = LVF.send_equip_car_feature_req
                            LVF.send_equip_car_feature_req = function(self, car_id, resid, op_type)
                                if not F.vehicleModUnlockOn() then
                                    return LVF._nth_send_feature(self, car_id, resid, op_type)
                                end
                                local VAH = require("client.network.Protocol.VehicleAccessoryHandler")
                                if VAH and VAH.send_equip_car_feature_req then
                                    return VAH.send_equip_car_feature_req(car_id, resid, op_type)
                                end
                                local feature_data =
                                    F.applyExtendedFeatureEquipLocal(self, car_id, resid, op_type)
                                if feature_data and self.on_equip_car_feature_rsp then
                                    return self:on_equip_car_feature_rsp(car_id, resid, op_type, feature_data)
                                end
                                return LVF._nth_send_feature(self, car_id, resid, op_type)
                            end
                        end
                        pcall(F.seedExtendedFeatureOwnership)
                    end)

                    pcall(function()
                        local VM = require("client.slua.umg.vehicle.vehicle_main")
                        if not VM or VM._nth_EquipPatch then
                            return
                        end
                        VM._nth_EquipPatch = true
                        if VM.GetRefitCarList and not VM._nth_GetRefitCarList then
                            VM._nth_GetRefitCarList = VM.GetRefitCarList
                            VM.GetRefitCarList = function(self)
                                if F.vehicleModUnlockOn() then
                                    pcall(F.ensureWorkshopVehiclesInDepot)
                                    pcall(F.seedAllVehicleRefitOwnership)
                                end
                                local list = VM._nth_GetRefitCarList(self)
                                if F.vehicleModUnlockOn() and type(list) == "table" then
                                    for _, group in pairs(list) do
                                        if type(group) == "table" then
                                            for _, info in pairs(group) do
                                                F.patchCarInfoForEquip(info)
                                            end
                                        end
                                    end
                                end
                                return list
                            end
                        end
                        if VM.GetCarInfoByIndex and not VM._nth_GetCarInfoByIndex then
                            VM._nth_GetCarInfoByIndex = VM.GetCarInfoByIndex
                            VM.GetCarInfoByIndex = function(self, index)
                                local info = VM._nth_GetCarInfoByIndex(self, index)
                                if F.vehicleModUnlockOn() then
                                    F.patchCarInfoForEquip(info)
                                end
                                return info
                            end
                        end
                        if VM.OnBtnEquipClick and not VM._nth_OnBtnEquipClick then
                            VM._nth_OnBtnEquipClick = VM.OnBtnEquipClick
                            VM.OnBtnEquipClick = function(self)
                                if F.vehicleModUnlockOn() then
                                    local carInfo = self:GetCarInfoByIndex(self.curSelectCarIndex)
                                    F.patchCarInfoForEquip(carInfo)
                                    if carInfo and carInfo.itemData and carInfo.itemData.insID then
                                        local WardrobeLogicManager =
                                            require("client.slua.logic.wardrobe.logic_wardrobe_new")
                                        if
                                            F.tryLocalWearByIns
                                            and F.tryLocalWearByIns(carInfo.itemData.insID)
                                        then
                                            pcall(function()
                                                self:UpdateJumpStoreBtn()
                                            end)
                                            return
                                        end
                                        return WardrobeLogicManager:wardrobe_puton_req(carInfo.itemData.insID)
                                    end
                                end
                                return VM._nth_OnBtnEquipClick(self)
                            end
                        end
                    end)

                    pcall(function()
                        local VRM = require("client.slua.umg.vehicle.vehicle_refit_main")
                        if not VRM or VRM._nth_EquipPatch then
                            return
                        end
                        VRM._nth_EquipPatch = true
                        if VRM.InitData and not VRM._nth_InitData then
                            VRM._nth_InitData = VRM.InitData
                            VRM.InitData = function(self)
                                if F.vehicleModUnlockOn() and self.carInfo then
                                    F.patchCarInfoForEquip(self.carInfo)
                                end
                                local ret = VRM._nth_InitData(self)
                                if F.vehicleModUnlockOn() and type(self.tabDataList) == "table" then
                                    for _, tab in pairs(self.tabDataList) do
                                        if type(tab) == "table" then
                                            tab.bLocked = false
                                        end
                                    end
                                end
                                return ret
                            end
                        end
                        if VRM.OnBtnEquipClick and not VRM._nth_OnBtnEquipClick then
                            VRM._nth_OnBtnEquipClick = VRM.OnBtnEquipClick
                            VRM.OnBtnEquipClick = function(self)
                                if F.vehicleModUnlockOn() then
                                    F.patchCarInfoForEquip(self.carInfo)
                                    if
                                        not (
                                            self.carInfo
                                            and self.carInfo.itemData
                                            and self.carInfo.itemData.insID
                                        )
                                    then
                                        ShowNotice(8087)
                                        return
                                    end
                                end
                                return VRM._nth_OnBtnEquipClick(self)
                            end
                        end
                        if VRM.OnBtnSaveClick and not VRM._nth_OnBtnSaveClick then
                            VRM._nth_OnBtnSaveClick = VRM.OnBtnSaveClick
                            VRM.OnBtnSaveClick = function(self)
                                if F.vehicleModUnlockOn() then
                                    F.patchCarInfoForEquip(self.carInfo)
                                end
                                return VRM._nth_OnBtnSaveClick(self)
                            end
                        end
                    end)

                    pcall(function()
                        local VRS = require("client.slua.umg.vehicle.vehicle_refit_save")
                        if not VRS or VRS._nth_EquipPatch then
                            return
                        end
                        VRS._nth_EquipPatch = true
                        if VRS.OnBtnEquipClick and not VRS._nth_OnBtnEquipClick then
                            VRS._nth_OnBtnEquipClick = VRS.OnBtnEquipClick
                            VRS.OnBtnEquipClick = function(self)
                                if F.vehicleModUnlockOn() then
                                    F.patchCarInfoForEquip(self.carInfo)
                                    if
                                        self.carInfo
                                        and self.carInfo.itemData
                                        and self.carInfo.itemData.insID
                                    then
                                        local ins = self.carInfo.itemData.insID
                                        if F.tryLocalWearByIns and F.tryLocalWearByIns(ins) then
                                            pcall(function()
                                                self:UpdateJumpStoreBtn()
                                            end)
                                            return
                                        end
                                    end
                                end
                                return VRS._nth_OnBtnEquipClick(self)
                            end
                        end
                    end)

                    pcall(function()
                        local VF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.VehicleFeature)
                        if VF and VF.IsUnlockFeature and not VF._nth_IsUnlockFeature then
                            VF._nth_IsUnlockFeature = VF.IsUnlockFeature
                            VF.IsUnlockFeature = function(self, itemID)
                                if F.vehicleModUnlockOn() then
                                    return true
                                end
                                return VF._nth_IsUnlockFeature(self, itemID)
                            end
                        end
                    end)

                    pcall(function()
                        local utilMod =
                            require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                        if
                            utilMod
                            and utilMod.CheckHasUnLockFeature
                            and not utilMod._nth_UnlockAllFeature
                        then
                            utilMod._nth_UnlockAllFeature = true
                            local orig = utilMod.CheckHasUnLockFeature
                            utilMod.CheckHasUnLockFeature = function(ft, uid, itemId)
                                if F.vehicleModUnlockOn() then
                                    return true
                                end
                                return orig(ft, uid, itemId)
                            end
                        end
                    end)

                    pcall(F.seedAllVehicleRefitOwnership)
                    _G.AddOutfitVehModUnlockHooked = true
                end

                function F.hookVehicleChassisLight()
                    if _G.AddOutfitVehChassisHooked then
                        return
                    end
                    pcall(function()
                        local LIC = require(
                            "GameLua.Activity.Commercialize.Actor.ActorComponent.BP_VehicleLicenseComponentBase"
                        )
                        if LIC and LIC.CheckHasVehicleDownloaded and not _G.AddOutfitVehOrigLicDownload then
                            _G.AddOutfitVehOrigLicDownload = LIC.CheckHasVehicleDownloaded
                            LIC.CheckHasVehicleDownloaded = function(self, itemID)
                                local id = tonumber(itemID)
                                if F.vehicleModUnlockOn() then
                                    return true
                                end
                                if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then
                                    return true
                                end
                                return _G.AddOutfitVehOrigLicDownload(self, itemID)
                            end
                        end
                    end)
                    pcall(function()
                        local LVF = ModuleManager.GetModule(
                            ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                        )
                        if not LVF or LVF._AddOutfitChassisHooked then
                            return
                        end
                        LVF._AddOutfitChassisHooked = true

                        if not _G.AddOutfitVehOrigGetFeature then
                            _G.AddOutfitVehOrigGetFeature = LVF.CheckHasGetFeatureItem
                        end
                        LVF.CheckHasGetFeatureItem = function(self, featureId)
                            if F.vehicleModUnlockOn() then
                                return true
                            end
                            if F.isChassisLightId(featureId) then
                                return true
                            end
                            return _G.AddOutfitVehOrigGetFeature(self, featureId)
                        end

                        if not _G.AddOutfitVehOrigEquippedFeature then
                            _G.AddOutfitVehOrigEquippedFeature = LVF.CheckHasEquippedItem
                        end
                        LVF.CheckHasEquippedItem = function(self, featureId, vehicleId)
                            if _G.NTHUY2004Config and _G.NTHUY2004Config.ModSkin ~= false then
                                if F.isChassisLightId(featureId) then
                                    return F.getDesiredChassisLight(vehicleId) == tonumber(featureId)
                                end
                            end
                            return _G.AddOutfitVehOrigEquippedFeature(self, featureId, vehicleId)
                        end

                        if not _G.AddOutfitVehOrigEquipChassisData then
                            _G.AddOutfitVehOrigEquipChassisData = LVF.GetEquipedChassisLightData
                        end
                        LVF.GetEquipedChassisLightData = function(self, vehicleId, source)
                            if _G.NTHUY2004Config and _G.NTHUY2004Config.ModSkin ~= false then
                                local our = F.getDesiredChassisLight(vehicleId)
                                if our then
                                    return our
                                end
                            end
                            return _G.AddOutfitVehOrigEquipChassisData(self, vehicleId, source)
                        end

                        if not _G.AddOutfitVehOrigChassisLightData then
                            _G.AddOutfitVehOrigChassisLightData = LVF.GetVehicleChassisLightData
                        end
                        LVF.GetVehicleChassisLightData = function(self, uid, vehicleId, position, source)
                            if _G.NTHUY2004Config and _G.NTHUY2004Config.ModSkin ~= false then
                                if
                                    uid
                                    and DataMgr
                                    and DataMgr.roleData
                                    and tonumber(uid) == tonumber(DataMgr.roleData.uid)
                                then
                                    local our = F.getDesiredChassisLight(vehicleId)
                                    if our then
                                        return our
                                    end
                                end
                            end
                            return _G.AddOutfitVehOrigChassisLightData(self, uid, vehicleId, position, source)
                        end

                        if not _G.AddOutfitVehOrigPutOnFeature then
                            _G.AddOutfitVehOrigPutOnFeature = LVF.PutOnVehicleFeature
                        end
                        LVF.PutOnVehicleFeature = function(self, featureId, vehicleId)
                            featureId = tonumber(featureId)
                            vehicleId = tonumber(vehicleId)
                            if F.isChassisLightId(featureId) then
                                F.saveChassisLight(vehicleId, featureId)
                                self.equip_chassis_light = self.equip_chassis_light or {}
                                if vehicleId and vehicleId > 0 then
                                    self.equip_chassis_light[vehicleId] = featureId
                                end
                                return
                            end
                            return _G.AddOutfitVehOrigPutOnFeature(self, featureId, vehicleId)
                        end

                        if not _G.AddOutfitVehOrigPutOffFeature then
                            _G.AddOutfitVehOrigPutOffFeature = LVF.PutOffVehicleFeature
                        end
                        LVF.PutOffVehicleFeature = function(self, featureId, vehicleId)
                            featureId = tonumber(featureId)
                            vehicleId = tonumber(vehicleId)
                            if F.isChassisLightId(featureId) then
                                PERSIST.configChassisLightMap = PERSIST.configChassisLightMap or {}
                                if vehicleId and vehicleId > 0 then
                                    PERSIST.configChassisLightMap[vehicleId] = nil
                                end
                                if self.equip_chassis_light and vehicleId then
                                    self.equip_chassis_light[vehicleId] = nil
                                end
                                F.persistMarkDirty()
                                return
                            end
                            return _G.AddOutfitVehOrigPutOffFeature(self, featureId, vehicleId)
                        end
                    end)
                    _G.AddOutfitVehChassisHooked = true
                end

                function F.hookVehicles()
                    F.hookVehicleSwitchEffect()
                    F.hookVehicleChassisLight()
                    pcall(F.hookVehicleExtendedFeaturesServerData)
                    F.hookVehicleModSystemUnlock()
                    pcall(function()
                        local WV = require("client.slua.umg.Wardrobe.subtab_vehicles")
                        if not WV or WV._AddOutfitVehClickHooked then
                            return
                        end
                        WV._AddOutfitVehClickHooked = true
                        local oClick = WV.ClickItem
                        WV.ClickItem = function(self, vehicleSkin, bForceUsing)
                            if vehicleSkin and F.isInjectedRes(vehicleSkin.res_id) then
                                vehicleSkin.expireTS = 0
                                vehicleSkin.expire_ts = 0
                            end
                            return oClick(self, vehicleSkin, bForceUsing)
                        end
                        local oDrop = WV.OnVehicleSlotDrop
                        if oDrop then
                            WV.OnVehicleSlotDrop = function(self, DragWidget, Index, DragDropData)
                                pcall(function()
                                    local ins = DragDropData and DragDropData.ins_id
                                    if F.isInjectedIns(tonumber(ins)) then
                                        F.ensureInjectedItemAlive(nil, nil, ins)
                                    end
                                end)
                                return oDrop(self, DragWidget, Index, DragDropData)
                            end
                        end
                    end)
                    pcall(function()
                        local WNH = require("client.network.Protocol.WardrobeNewHandler")
                        if WNH._AddOutfitVehicleHooked then
                            return
                        end
                        WNH._AddOutfitVehicleHooked = true
                        local oMod = WNH.send_depot_modify_combat_vehicle_req
                        WNH.send_depot_modify_combat_vehicle_req = function(instid, slot_index, ope_type)
                            if F.modifyInjectedVehicleSlot(instid, slot_index, ope_type == true) then
                                return
                            end
                            return oMod(instid, slot_index, ope_type)
                        end
                        local oRsp = WNH.on_depot_modify_combat_vehicle_rsp
                        WNH.on_depot_modify_combat_vehicle_rsp = function(err_code, knapsack_vst)
                            if err_code == 0 or err_code == NET_OK then
                                knapsack_vst = F.mergeInjectedIntoVehicleSlotList(knapsack_vst)
                            end
                            oRsp(err_code, knapsack_vst)
                            if err_code == 0 or err_code == NET_OK then
                                F.syncVehicleSlotsToDataMgr()
                                F.equipVehicleTypesFromConfig(PERSIST.configVehicleSlots)
                                if not (_G.AddOutfitLobbyVeh and _G.AddOutfitLobbyVeh.manual) then
                                    pcall(F.applyVehicleSkinsToPC)
                                end
                                F.persistMarkDirty()
                            end
                        end
                    end)
                    pcall(function()
                        local gsm =
                            ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.golden_suit_module)
                        if gsm and gsm.VehicleNeedClothes and not gsm._AddOutfitVehClothesHooked then
                            gsm._AddOutfitVehClothesHooked = true
                            local o = gsm.VehicleNeedClothes
                            gsm.VehicleNeedClothes = function(self, vehicleId)
                                vehicleId = tonumber(vehicleId)
                                if vehicleId and F.isInjectedRes(vehicleId) then
                                    return 0
                                end
                                return o(self, vehicleId)
                            end
                        end
                    end)
                    pcall(function()
                        local mod = require("GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
                        if mod._FillVehicleSkinList then
                            if not _G.AddOutfitVehFillOrig then
                                _G.AddOutfitVehFillOrig = mod._FillVehicleSkinList
                            end
                            local o = _G.AddOutfitVehFillOrig
                            mod._FillVehicleSkinList = function(self, playerInfo, uPlayerController)
                                F.mergeVstIntoPlayerInfo(playerInfo)

                                pcall(function()
                                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then
                                        return
                                    end
                                    local EA = require("Server.config.ExtendAttribute")
                                    if not playerInfo or not EA then
                                        return
                                    end
                                    playerInfo.ext_attr = playerInfo.ext_attr or {}
                                    local key = EA.VehicleExtendedFeatures
                                    playerInfo.ext_attr[key] =
                                        F.buildVehicleExtendedFeaturesTable(playerInfo.ext_attr[key])
                                end)
                                local ret = o(self, playerInfo, uPlayerController)
                                pcall(function()
                                    if slua.isValid(uPlayerController) then
                                        F.applyVehiclePartDataToPC(
                                            uPlayerController,
                                            uPlayerController.ShowVehicleSkin
                                        )
                                    end
                                end)
                                return ret
                            end
                            mod._AddOutfitFillVehHooked = true
                        end
                    end)
                    pcall(function()
                        local classMod =
                            require("GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinItem")
                        if not classMod or not classMod.__inner_impl then
                            return
                        end
                        local impl = classMod.__inner_impl
                        if not _G.AddOutfitVehOrigClick then
                            _G.AddOutfitVehOrigClick = impl.OnClickSkinButton
                        end
                        local oClick = _G.AddOutfitVehOrigClick
                        impl.OnClickSkinButton = function(self)
                            local resID = tonumber(self.resID)
                            if resID and resID > 0 then
                                if F.matchApplyVehicleSkin(resID) then
                                    pcall(function()
                                        if
                                            EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL
                                            and EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK
                                        then
                                            EventSystem:postEvent(
                                                EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL,
                                                EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK
                                            )
                                        end
                                    end)
                                end
                                return
                            end
                            return oClick(self)
                        end
                        if not _G.AddOutfitVehOrigRefresh then
                            _G.AddOutfitVehOrigRefresh = impl.OnRefresh
                        end
                        local oRefresh = _G.AddOutfitVehOrigRefresh
                        impl.OnRefresh = function(self, resID, selectIndex)
                            oRefresh(self, resID, selectIndex)
                            if self.resID and tonumber(self.resID) and tonumber(self.resID) > 0 then
                                if F.isResourcesReady(self.resID) then
                                    pcall(function()
                                        local PufferConst = require("client.slua.logic.download.puffer_const")
                                        self.dowloadState = PufferConst.ENUM_DownloadState.Done
                                        self.UIRoot.Image_Download:SetWidgetVisibility(
                                            UEnums.ESlateVisibility.Collapsed
                                        )
                                        self:SetWidgetVisible(self.UIRoot.Image_Mask, false)
                                    end)
                                else
                                    F.requestResourceDownload(self.resID)
                                end
                            end
                        end
                        classMod._AddOutfitSkinClickHooked = true
                    end)
                    pcall(function()
                        local utilMod =
                            require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                        if utilMod.CheckHasUnLockFeature and not utilMod._AddOutfitVehPlateHooked then
                            utilMod._AddOutfitVehPlateHooked = true
                            local orig = utilMod.CheckHasUnLockFeature
                            utilMod.CheckHasUnLockFeature = function(ft, uid, itemId)
                                local id = tonumber(itemId)
                                if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then
                                    return true
                                end
                                return orig(ft, uid, itemId)
                            end
                        end
                    end)
                    pcall(function()
                        local panelMod = require(
                            "GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinAndMusicPanel"
                        )
                        if panelMod and panelMod.__inner_impl and not panelMod._AddOutfitInitSkinHooked then
                            panelMod._AddOutfitInitSkinHooked = true
                            local o = panelMod.__inner_impl.InitSkinList
                            panelMod.__inner_impl.InitSkinList = function(self)
                                F.applyVehicleSkinsToPC(F.getPC())
                                return o(self)
                            end
                        end
                    end)
                    pcall(function()
                        local VUC = require("GameLua.GameCore.Module.Vehicle.Component.VehicleUserComponent")
                        if not VUC then
                            return
                        end
                        if not _G.AddOutfitVehOrigEnter then
                            _G.AddOutfitVehOrigEnter = VUC.SendUIMsgWhenEnterVehicleCompleted
                        end
                        local oEnter = _G.AddOutfitVehOrigEnter
                        VUC.SendUIMsgWhenEnterVehicleCompleted = function(self)
                            oEnter(self)
                            pcall(function()
                                if slua.isValid(self.Vehicle) then
                                    F.autoApplyVehicleSkinOnEnter(self.Vehicle)
                                end
                            end)
                        end
                        VUC._AddOutfitEnterVehHooked = true
                    end)
                end

                function F.hookWeaponWear()
                    pcall(function()
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        local o = HT.IsWeaponWear
                        HT.IsWeaponWear = function(insId)
                            insId = tonumber(insId)
                            if F.isInjectedIns(insId) then
                                local c = F.cache()
                                local Arm = require("client.logic.armory.logic_armory")
                                for wid, w in pairs(c.weapons) do
                                    if tonumber(w.insID) == insId then
                                        if
                                            Arm.rsp_list
                                            and Arm.rsp_list.install_list
                                            and Arm.rsp_list.install_list[wid]
                                        then
                                            return tonumber(Arm.rsp_list.install_list[wid].skin_id) == insId
                                        end
                                        return true
                                    end
                                end
                            end
                            return o(insId)
                        end
                    end)
                end

                function F.hookNotice()
                    pcall(function()
                        if DataMgr and not DataMgr._AddOutfitExpireHooked then
                            DataMgr._AddOutfitExpireHooked = true
                            local oValid = DataMgr.IsValidTime
                            DataMgr.IsValidTime = function(expireTS)
                                if expireTS == nil or tonumber(expireTS) == 0 then
                                    return true
                                end
                                if oValid and oValid(expireTS) then
                                    return true
                                end
                                local inMatch = false
                                pcall(function()
                                    inMatch = GameStatus
                                        and GameStatus.IsInFightingStatus
                                        and GameStatus.IsInFightingStatus()
                                end)
                                if not inMatch then
                                    return true
                                end
                                return false
                            end
                        end
                    end)
                end

                function F.wrapWardrobeClick(classMod, key)
                    if not classMod or not classMod[key] or classMod["_AddOutfitWrap_" .. key] then
                        return
                    end
                    classMod["_AddOutfitWrap_" .. key] = true
                    local orig = classMod[key]
                    classMod[key] = function(self, widget, index)
                        local itemData = self.LoopScrollGrid_Normal
                            and self.LoopScrollGrid_Normal:GetItemData(index)
                        if itemData then
                            F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
                            F.ensureDepotItemValid(itemData.ins_id, itemData.res_id)
                        end
                        return orig(self, widget, index)
                    end
                end

                function F.hookWardrobeWearClicks()
                    if _G.AddOutfitWearClickHooked then
                        return
                    end
                    _G.AddOutfitWearClickHooked = true
                    F.hookNotice()
                    pcall(function()
                        local avatarClass = require("client.slua.umg.Wardrobe.subtab_avatar")
                        F.wrapWardrobeClick(avatarClass, "OnClickItem")
                        F.wrapWardrobeClick(avatarClass, "ClickAvatarItem")
                    end)
                    pcall(function()
                        local suitClass = require("client.slua.umg.Wardrobe.subtab_suit")
                        F.wrapWardrobeClick(suitClass, "OnClickItem")
                    end)
                    pcall(function()
                        local bagClass = require("client.slua.umg.Wardrobe.subtab_bag")
                        F.wrapWardrobeClick(bagClass, "OnClickItem")
                    end)
                end

                function F.hookAvatarValid()
                    pcall(function()
                        local path = "GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent"
                        local comp = require(path)
                        if comp and comp.CheckItemValid then
                            local o = comp.CheckItemValid
                            comp.CheckItemValid = function(self, resID)
                                if F.isInjectedRes(resID) then
                                    return true
                                end
                                return o(self, resID)
                            end
                        end
                    end)
                end

                function F.isInRealMatch()
                    local ok, r = pcall(function()
                        return GameStatus
                            and GameStatus.IsInFightingStatus
                            and GameStatus.IsInFightingStatus()
                    end)
                    return ok and r == true
                end

                function F.getLocalChar()
                    local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
                    if not ok or not GD then
                        return nil
                    end
                    local char = GD.GetPlayerCharacter()
                    if char and slua.isValid(char) then
                        return char
                    end
                    return nil
                end

                function F.getWAC(char)
                    local w = char and char.GetCurrentWeapon and char:GetCurrentWeapon()
                    if slua.isValid(w) and slua.isValid(w.WeaponAvatarComponent) then
                        return w.WeaponAvatarComponent
                    end
                    return nil
                end

                function F.notify(msg)
                    if not DEBUG then
                        return
                    end
                    pcall(function()
                        if ShowNotice then
                            ShowNotice("[AddOutfit] " .. tostring(msg))
                        end
                    end)
                end

                function F.getDesiredOutfit()
                    if MATCH_CONFIG.outfitRes and MATCH_CONFIG.outfitRes > 0 then
                        return MATCH_CONFIG.outfitRes
                    end
                    local wornSuitRes
                    pcall(function()
                        local _, res = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                            return F.isSuitRes(r)
                        end)
                        wornSuitRes = tonumber(res)
                    end)
                    if wornSuitRes and wornSuitRes > 0 then
                        return wornSuitRes
                    end
                    local tshirtWorn = false
                    pcall(function()
                        local ins = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                            return F.isTshirtRes(r)
                        end)
                        tshirtWorn = ins ~= nil
                    end)
                    if tshirtWorn then
                        return nil
                    end
                    F.syncBodyCacheFromLobby()
                    local c = F.cache()
                    return c.outfitRes
                end

                function F.matchApplyOutfit(char)
                    local outfitRes = F.getDesiredOutfit()
                    if not outfitRes then
                        return true
                    end
                    if not F.isResourcesReady(outfitRes) then
                        F.requestResourceDownload(outfitRes)
                        return false
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp then
                        return false
                    end
                    local ok =
                        F.setMakeSkin(comp, outfitRes, F.CUST_SLOT.ClothesEquipemtSlot, { allowPutOn = true })
                    return ok
                end

                function F.getDesiredHat()
                    if MATCH_CONFIG.hatRes and tonumber(MATCH_CONFIG.hatRes) > 0 then
                        return tonumber(MATCH_CONFIG.hatRes)
                    end
                    F.syncHatCacheFromLobby()
                    local h = F.cache().hatRes
                    if h and tonumber(h) > 0 then
                        return tonumber(h)
                    end
                    return tonumber(_G.AddOutfitLastLobbyHatRes) or nil
                end

                function F.ensureSkinDownload(resID)
                    resID = tonumber(resID)
                    if not resID or resID <= 0 then
                        return
                    end
                    _G.skinIdCache = _G.skinIdCache or {}
                    if not _G.skinIdCache[resID] then
                        F.requestResourceDownload(resID)
                        _G.skinIdCache[resID] = true
                    end
                end

                function F.syncGlobalWearSkins()
                    _G.CustSlotType = F.CUST_SLOT
                    _G.skinIdCache = _G.skinIdCache or {}
                    _G.HatSkin = tonumber(F.getDesiredHat()) or 0
                    local outfit = F.getDesiredOutfit()
                    _G.SuitSkin = tonumber(outfit)
                        or tonumber(
                            F.getDesiredWear(
                                "tshirtRes",
                                "tshirtRes",
                                "AddOutfitLastLobbyTshirtRes",
                                F.syncBodyCacheFromLobby
                            )
                        )
                        or 0
                    _G.PantsSkin = tonumber(
                        F.getDesiredWear(
                            "pantsRes",
                            "pantsRes",
                            "AddOutfitLastLobbyPantsRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or 0
                    _G.ShoesSkin = tonumber(
                        F.getDesiredWear(
                            "shoesRes",
                            "shoesRes",
                            "AddOutfitLastLobbyShoesRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or 0
                    _G.GlovesSkin = tonumber(
                        F.getDesiredWear(
                            "glovesRes",
                            "glovesRes",
                            "AddOutfitLastLobbyGlovesRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or 0
                    _G.MaskSkin = tonumber(F.getDesiredMask()) or 0
                    _G.GlassSkin = tonumber(F.getDesiredGlass()) or 0
                    _G.GliderSkin = tonumber(F.getDesiredGliderRes()) or 0
                    _G.ParachuteSkin = tonumber(F.getDesiredParachuteRes()) or 0
                    _G.BackpackSkin = tonumber(
                        F.getDesiredWear(
                            "bagRes",
                            "bagRes",
                            "AddOutfitLastLobbyBagRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or tonumber(_G.BackpackSkin) or 0
                    _G.HelmetSkin = tonumber(
                        F.getDesiredWear(
                            "helmetRes",
                            "helmetRes",
                            "AddOutfitLastLobbyHelmetRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or tonumber(_G.HelmetSkin) or 0
                end

                function F.setMakeSkinAtIndex(comp, applyIdx, resID, slotID)
                    resID = tonumber(resID)
                    slotID = tonumber(slotID)
                    applyIdx = tonumber(applyIdx)
                    if
                        not comp
                        or not slua.isValid(comp)
                        or not resID
                        or resID <= 0
                        or not slotID
                        or applyIdx == nil
                    then
                        return false
                    end
                    local changed = false
                    pcall(function()
                        local net = comp.NetAvatarData
                        if not net then
                            return
                        end
                        local applyData = net.SlotSyncData
                        if not applyData or not slua.isValid(applyData) then
                            return
                        end
                        local equipment = applyData:Get(applyIdx)
                        if equipment and equipment.SlotID == slotID then
                            local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                            if cur ~= resID then
                                F.ensureSkinDownload(resID)
                                equipment.ItemId = resID
                                if equipment.ItemID ~= nil then
                                    equipment.ItemID = resID
                                end
                                applyData:Set(applyIdx, equipment)
                                changed = true
                            end
                        end
                    end)
                    return changed
                end

                function F.applySlotSkinBatch(comp, entries, opts)
                    opts = opts or {}
                    if not comp or not slua.isValid(comp) or not entries then
                        return false
                    end
                    local changed, anyOk = false, false
                    pcall(function()
                        local net = comp.NetAvatarData
                        if not net then
                            return
                        end
                        local applyData = net.SlotSyncData
                        if not applyData or not slua.isValid(applyData) then
                            return
                        end
                        local num = applyData:Num()
                        for _, e in ipairs(entries) do
                            local itemId, slotId = tonumber(e[1]), tonumber(e[2])
                            if itemId and itemId > 0 and slotId then
                                F.ensureSkinDownload(itemId)
                                for i = 0, num - 1 do
                                    local equipment = applyData:Get(i)
                                    if equipment and equipment.SlotID == slotId then
                                        local cur = tonumber(equipment.ItemId)
                                            or tonumber(equipment.ItemID)
                                            or 0
                                        local add = tonumber(equipment.AdditionalItemID) or 0
                                        if cur == itemId and (add == 0 or add == itemId) then
                                            anyOk = true
                                        else
                                            equipment.ItemId = itemId
                                            if equipment.ItemID ~= nil then
                                                equipment.ItemID = itemId
                                            end
                                            if equipment.FakeItemID ~= nil then
                                                equipment.FakeItemID = itemId
                                            end
                                            if equipment.AdditionalItemID ~= nil then
                                                equipment.AdditionalItemID = itemId
                                            end
                                            applyData:Set(i, equipment)
                                            changed = true
                                            anyOk = true
                                        end
                                        break
                                    end
                                end
                            end
                        end
                        if (changed or opts.forceRep) and comp.OnRep_BodySlotStateChanged then
                            comp:OnRep_BodySlotStateChanged()
                        end
                    end)
                    return anyOk or changed
                end

                function F.setMakeSkin(comp, resID, slotID, opts)
                    opts = opts or {}
                    slotID, resID = tonumber(slotID), tonumber(resID)
                    if not comp or not slua.isValid(comp) or not slotID or not resID or resID <= 0 then
                        return false
                    end
                    local changed = false
                    local already = false
                    pcall(function()
                        local net = comp.NetAvatarData
                        if not net then
                            return
                        end
                        local applyData = net.SlotSyncData
                        if not applyData or not slua.isValid(applyData) then
                            return
                        end
                        local num = applyData:Num()
                        for i = 0, num - 1 do
                            local equipment = applyData:Get(i)
                            if equipment and equipment.SlotID == slotID then
                                local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                                local add = tonumber(equipment.AdditionalItemID) or 0
                                if cur == resID and (add == 0 or add == resID) then
                                    already = true
                                else
                                    F.ensureSkinDownload(resID)
                                    equipment.ItemId = resID
                                    if equipment.ItemID ~= nil then
                                        equipment.ItemID = resID
                                    end
                                    if equipment.FakeItemID ~= nil then
                                        equipment.FakeItemID = resID
                                    end
                                    if equipment.AdditionalItemID ~= nil then
                                        equipment.AdditionalItemID = resID
                                    end
                                    applyData:Set(i, equipment)
                                    changed = true
                                end
                                break
                            end
                        end
                        if changed and not opts.skipRep and comp.OnRep_BodySlotStateChanged then
                            comp:OnRep_BodySlotStateChanged()
                        end
                        if opts.inAir and comp.PutOnCustomEquipmentByID then
                            comp:PutOnCustomEquipmentByID(resID)
                        end
                    end)
                    if already or changed then
                        return true
                    end
                    if opts.allowPutOn and comp.PutOnCustomEquipmentByID then
                        pcall(function()
                            comp:PutOnCustomEquipmentByID(resID)
                        end)
                        return true
                    end
                    return false
                end
                F.setSlotSkin = F.setMakeSkin

                _G.setMakeSkin = function(applyIdx, itemId, applyEquipSlot)
                    local char = F.getLocalChar()
                    if not char then
                        return
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp then
                        return
                    end
                    if F.setMakeSkinAtIndex(comp, applyIdx, itemId, applyEquipSlot) then
                        pcall(function()
                            if comp.OnRep_BodySlotStateChanged then
                                comp:OnRep_BodySlotStateChanged()
                            end
                        end)
                    end
                end

                function F.patchWearNetAvatar(comp, resID, slotName, noForceShow)
                    if not comp or not slua.isValid(comp) or not resID or resID <= 0 or not slotName then
                        return false
                    end
                    local ok = false
                    pcall(function()
                        local EAvatarSlotType = import("EAvatarSlotType")
                        local ESyncOperation = import("ESyncOperation")
                        local slot = EAvatarSlotType[slotName]
                        if not slot then
                            return
                        end
                        local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
                        if sync then
                            sync.ItemID = resID
                            if sync.FakeItemID ~= nil then
                                sync.FakeItemID = resID
                            end
                            sync.OperationType = ESyncOperation.PutOn
                            if comp.ChangeSlotSyncData then
                                comp:ChangeSlotSyncData(sync)
                                ok = true
                            end
                        end
                        if not noForceShow and comp.SetAvatarVisibility then
                            comp:SetAvatarVisibility(slot, true, true)
                        end
                    end)
                    return ok
                end

                function F.patchHatNetAvatar(comp, hatRes)
                    return F.patchWearNetAvatar(comp, hatRes, "EAvatarSlotType_HatEquipemtSlot")
                end

                function F.matchApplyWearItem(char, resID, slotID, label, opts)
                    if not resID or resID <= 0 then
                        return true
                    end
                    slotID = slotID or F.resToCustSlot(resID)
                    if not slotID then
                        return false
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp then
                        return false
                    end
                    opts = opts or {}
                    opts.allowPutOn = true
                    local ok = F.setMakeSkin(comp, resID, slotID, opts)
                    return ok
                end

                function F.getDesiredMask()
                    if MATCH_CONFIG.maskRes and tonumber(MATCH_CONFIG.maskRes) > 0 then
                        return tonumber(MATCH_CONFIG.maskRes)
                    end
                    F.syncFaceCacheFromLobby()
                    local m = F.cache().maskRes
                    if m and tonumber(m) > 0 then
                        return tonumber(m)
                    end
                    return tonumber(_G.AddOutfitLastLobbyMaskRes) or nil
                end

                function F.getDesiredGlass()
                    if MATCH_CONFIG.glassRes and tonumber(MATCH_CONFIG.glassRes) > 0 then
                        return tonumber(MATCH_CONFIG.glassRes)
                    end
                    F.syncFaceCacheFromLobby()
                    local g = F.cache().glassRes
                    if g and tonumber(g) > 0 then
                        return tonumber(g)
                    end
                    return tonumber(_G.AddOutfitLastLobbyGlassRes) or nil
                end

                function F.matchApplyFaceWear(char)
                    if not F.skinFeat("SkinMatchFace") then
                        return true
                    end
                    local maskRes = F.getDesiredMask()
                    local glassRes = F.getDesiredGlass()
                    if (not maskRes or maskRes <= 0) and (not glassRes or glassRes <= 0) then
                        return true
                    end
                    char = char or F.getLocalChar()
                    if not char then
                        return false
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp then
                        return false
                    end

                    local ok = false
                    pcall(function()
                        local EAvatarSlotType = import("EAvatarSlotType")
                        local ESyncOperation = import("ESyncOperation")
                        local net = comp.NetAvatarData
                        local applyData = net and net.SlotSyncData

                        local function forceApplySlot(resID, slotID, slotNameStr)
                            if not resID or resID <= 0 then
                                return
                            end

                            local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
                            local needRep = false

                            if applyData and slua.isValid(applyData) then
                                local found = false
                                for i = 0, applyData:Num() - 1 do
                                    local equipment = applyData:Get(i)
                                    if equipment and equipment.SlotID == slotID then
                                        found = true
                                        local cur = tonumber(equipment.ItemId)
                                            or tonumber(equipment.ItemID)
                                            or 0
                                        if cur ~= resID then
                                            F.ensureSkinDownload(resID)
                                            equipment.ItemId = resID
                                            if equipment.ItemID ~= nil then
                                                equipment.ItemID = resID
                                            end
                                            if equipment.FakeItemID ~= nil then
                                                equipment.FakeItemID = resID
                                            end
                                            applyData:Set(i, equipment)
                                            needRep = true
                                        end
                                        break
                                    end
                                end

                                if not found then
                                    F.ensureSkinDownload(resID)
                                    local entry = import("AvatarSyncData")()
                                    entry.SlotID = slotID
                                    entry.ItemId = resID
                                    entry.ItemID = resID
                                    entry.FakeItemID = resID
                                    entry.OperationType = ESyncOperation.PutOn
                                    applyData:Add(entry)
                                    needRep = true
                                end
                            end

                            _G.FaceWearStateCache = _G.FaceWearStateCache or {}

                            local cacheKey = tostring(comp) .. "_" .. tostring(slotID)

                            if needRep or _G.FaceWearStateCache[cacheKey] ~= resID then
                                if slotEnum then
                                    if comp.CancelHideAvatarBySlot then
                                        comp:CancelHideAvatarBySlot(slotEnum)
                                    end
                                    if comp.SetAvatarVisibility then
                                        comp:SetAvatarVisibility(slotEnum, true, true)
                                    end
                                end
                                if comp.PutOnCustomEquipmentByID then
                                    comp:PutOnCustomEquipmentByID(resID)
                                end

                                _G.FaceWearStateCache[cacheKey] = resID
                                ok = true
                            else
                                if slotEnum and comp.CancelHideAvatarBySlot then
                                    comp:CancelHideAvatarBySlot(slotEnum)
                                end
                            end
                        end

                        forceApplySlot(
                            maskRes,
                            F.CUST_SLOT.FaceEquipemtSlot,
                            "EAvatarSlotType_FaceEquipemtSlot"
                        )

                        forceApplySlot(
                            glassRes,
                            F.CUST_SLOT.GlassEquipemtSlot,
                            "EAvatarSlotType_GlassEquipemtSlot"
                        )

                        if ok and comp.OnRep_BodySlotStateChanged then
                            comp:OnRep_BodySlotStateChanged()
                        end
                    end)
                    return ok
                end

                function F.matchApplyGloves(char)
                    local glovesRes = tonumber(
                        F.getDesiredWear(
                            "glovesRes",
                            "glovesRes",
                            "AddOutfitLastLobbyGlovesRes",
                            F.syncBodyCacheFromLobby
                        )
                    ) or 0
                    if glovesRes <= 0 then
                        glovesRes = tonumber(_G.GlovesSkin) or 0
                    end
                    if glovesRes <= 0 then
                        return true
                    end
                    _G.GlovesSkin = glovesRes
                    char = char or F.getLocalChar()
                    if not char then
                        return false
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp then
                        return false
                    end

                    local ok = false
                    pcall(function()
                        local EAvatarSlotType = import("EAvatarSlotType")
                        local ESyncOperation = import("ESyncOperation")
                        local slotID = F.CUST_SLOT.HandEffectEquipemtSlot
                        local slotNameStr = "EAvatarSlotType_HandEffectEquipemtSlot"
                        local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
                        local net = comp.NetAvatarData
                        local applyData = net and net.SlotSyncData
                        local needRep = false

                        if applyData and slua.isValid(applyData) then
                            local found = false
                            for i = 0, applyData:Num() - 1 do
                                local equipment = applyData:Get(i)
                                if equipment and equipment.SlotID == slotID then
                                    found = true
                                    local cur = tonumber(equipment.ItemID) or tonumber(equipment.ItemId) or 0
                                    local add = tonumber(equipment.AdditionalItemID) or 0
                                    if
                                        cur ~= glovesRes
                                        or (equipment.AdditionalItemID ~= nil and add ~= glovesRes)
                                    then
                                        F.ensureSkinDownload(glovesRes)
                                        equipment.ItemId = glovesRes
                                        if equipment.ItemID ~= nil then
                                            equipment.ItemID = glovesRes
                                        end
                                        if equipment.FakeItemID ~= nil then
                                            equipment.FakeItemID = glovesRes
                                        end
                                        if equipment.AdditionalItemID ~= nil then
                                            equipment.AdditionalItemID = glovesRes
                                        end
                                        applyData:Set(i, equipment)
                                        needRep = true
                                    end
                                    break
                                end
                            end
                            if not found then
                                F.ensureSkinDownload(glovesRes)
                                local entry = import("AvatarSyncData")()
                                entry.SlotID = slotID
                                entry.ItemId = glovesRes
                                entry.ItemID = glovesRes
                                if entry.FakeItemID ~= nil then
                                    entry.FakeItemID = glovesRes
                                end
                                if entry.AdditionalItemID ~= nil then
                                    entry.AdditionalItemID = glovesRes
                                end
                                entry.OperationType = ESyncOperation.PutOn
                                applyData:Add(entry)
                                needRep = true
                            end
                        end

                        _G.GlovesWearStateCache = _G.GlovesWearStateCache or {}
                        local cacheKey = tostring(comp)
                        if needRep or _G.GlovesWearStateCache[cacheKey] ~= glovesRes then
                            if slotEnum then
                                if comp.CancelHideAvatarBySlot then
                                    comp:CancelHideAvatarBySlot(slotEnum)
                                end
                                if comp.SetAvatarVisibility then
                                    comp:SetAvatarVisibility(slotEnum, true, true)
                                end
                            end
                            if comp.PutOnCustomEquipmentByID then
                                comp:PutOnCustomEquipmentByID(glovesRes)
                            end
                            if needRep then
                                pcall(function()
                                    if comp.OnRep_BodySlotStateChangedInternal then
                                        comp:OnRep_BodySlotStateChangedInternal()
                                    elseif comp.OnRep_BodySlotStateChanged then
                                        comp:OnRep_BodySlotStateChanged()
                                    end
                                    if comp.ProcessAvatarRectify then
                                        comp:ProcessAvatarRectify()
                                    end
                                end)
                            end
                            _G.GlovesWearStateCache[cacheKey] = glovesRes
                            ok = true
                        else
                            ok = true
                        end
                    end)
                    return ok
                end

                function F.getDesiredWear(configKey, cacheResKey, globalKey, syncFn)
                    local fixed = MATCH_CONFIG[configKey] and tonumber(MATCH_CONFIG[configKey])
                    if fixed and fixed > 0 then
                        return fixed
                    end
                    local persistKey = cacheResKey and cacheResKey:gsub("Res$", "")
                    if persistKey and PERSIST.configSlots then
                        local pr = tonumber(PERSIST.configSlots[persistKey])
                        if pr and pr > 0 then
                            return pr
                        end
                    end
                    if syncFn then
                        syncFn()
                    end
                    local v = F.cache()[cacheResKey]
                    if v and tonumber(v) > 0 then
                        return tonumber(v)
                    end
                    return tonumber(_G[globalKey]) or nil
                end

                local EQUIP_APPLY = { lastBagWrite = 0, lastHelmetWrite = 0 }

                local EQUIP_SLOT_BAG = 8
                local EQUIP_SLOT_HELMET = 9

                function F.resolveBackpackMappingBase(skinID)
                    skinID = tonumber(skinID) or 0
                    if skinID <= 0 then
                        return 0
                    end
                    local found = 0
                    pcall(function()
                        local function mappingOk(id)
                            local t = CDataTable.GetTableData("BackpackMapping", id)
                            if not t then
                                return false
                            end
                            return (tonumber(t.SkinItemIDLv1) or tonumber(t.LobbyShowItemID) or 0) > 0
                        end
                        if mappingOk(skinID) then
                            found = skinID
                            return
                        end

                        if
                            (skinID >= 1501001000 and skinID < 1501002000)
                            or (skinID >= 1502001000 and skinID < 1502002000)
                        then
                            local lobbyKey = skinID - 1000
                            if mappingOk(lobbyKey) then
                                found = lobbyKey
                                return
                            end
                            found = lobbyKey
                            return
                        end
                        for _, d in ipairs({ 1000, 2000 }) do
                            local try = skinID - d
                            if try > 0 and mappingOk(try) then
                                local t2 = CDataTable.GetTableData("BackpackMapping", try)
                                local l1 = tonumber(t2.SkinItemIDLv1) or 0
                                local l2 = tonumber(t2.SkinItemIDLv2) or 0
                                local l3 = tonumber(t2.SkinItemIDLv3) or 0
                                if skinID == l1 or skinID == l2 or skinID == l3 or skinID == try then
                                    found = try
                                    return
                                end
                            end
                        end
                    end)
                    return found > 0 and found or skinID
                end

                function F.normalizeLobbyEquipSkinID(resID)
                    return F.equipToLobbyMappingID(resID)
                end

                function F.getEquippedArmorLevelBySubType(subType)
                    local lvl, equipID = 0, 0
                    pcall(function()
                        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                        if not pc or not slua.isValid(pc) then
                            return
                        end
                        local bp = pc.GetBackpackComponent and pc:GetBackpackComponent()
                        if not bp or not slua.isValid(bp) then
                            return
                        end
                        local BackpackUtils = import("BackpackUtils")
                        local arr = BackpackUtils.GetEuqippedArmorInBackpack(bp)
                        if not arr then
                            return
                        end
                        for _, BattleItemData in pairs(arr) do
                            local DefineID = BattleItemData
                                and (
                                    slua.IndexReference(BattleItemData, "DefineID") or BattleItemData.DefineID
                                )
                            local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                            if tid > 0 then
                                local ItemCfg = CDataTable.GetTableData("Item", tid)
                                local ist = ItemCfg and tonumber(ItemCfg.ItemSubType) or 0
                                if
                                    ist == subType
                                    or (subType == 501 and tid >= 501001 and tid <= 501099)
                                    or (subType == 502 and tid >= 502001 and tid <= 502099)
                                then
                                    equipID = tid
                                    if BackpackUtils.GetEquipmentLevel then
                                        local itemID = tonumber(ItemCfg and ItemCfg.ItemID) or tid
                                        pcall(function()
                                            lvl = tonumber(BackpackUtils.GetEquipmentLevel(itemID)) or 0
                                        end)
                                    end
                                    if lvl < 1 and subType == 501 and BackpackUtils.GetEquipmentBagLevel then
                                        pcall(function()
                                            lvl = tonumber(BackpackUtils.GetEquipmentBagLevel(tid)) or 0
                                        end)
                                    end
                                    if
                                        lvl < 1
                                        and subType == 502
                                        and BackpackUtils.GetEquipmentHelmetLevel
                                    then
                                        pcall(function()
                                            lvl = tonumber(BackpackUtils.GetEquipmentHelmetLevel(tid)) or 0
                                        end)
                                    end
                                    if lvl < 1 then
                                        local rem = tid % 10
                                        if rem >= 1 and rem <= 6 then
                                            lvl = rem
                                        end
                                    end
                                    break
                                end
                            end
                        end
                    end)
                    return lvl, equipID
                end

                function F.levelSkinID(baseSkin, level)
                    level = tonumber(level) or 1
                    if level < 1 then
                        level = 1
                    end
                    if level > 3 then
                        level = 3
                    end
                    baseSkin = F.resolveBackpackMappingBase(baseSkin)
                    local mapped = 0
                    pcall(function()
                        if DataMgr and DataMgr.GetEquipmentItemIDByResID then
                            mapped = tonumber(DataMgr.GetEquipmentItemIDByResID(level, baseSkin)) or 0
                        end
                    end)
                    if mapped <= 0 then
                        pcall(function()
                            local t = CDataTable.GetTableData("BackpackMapping", baseSkin)
                            if t then
                                if level <= 1 then
                                    mapped = tonumber(t.SkinItemIDLv1) or 0
                                elseif level == 2 then
                                    mapped = tonumber(t.SkinItemIDLv2) or 0
                                else
                                    mapped = tonumber(t.SkinItemIDLv3) or 0
                                end
                            end
                        end)
                    end
                    if mapped > 0 then
                        return mapped
                    end
                    return baseSkin + (level - 1) * 1000
                end

                function F.applyEquipSkinToComp(comp, bagRes, helmetRes)
                    bagRes = tonumber(bagRes) or 0
                    helmetRes = tonumber(helmetRes) or 0
                    if bagRes <= 0 and helmetRes <= 0 then
                        return false, false
                    end
                    if not comp or not slua.isValid(comp) then
                        return false, false
                    end

                    if bagRes > 0 then
                        _G.BackpackSkin = bagRes
                    end
                    if helmetRes > 0 then
                        _G.HelmetSkin = helmetRes
                    end

                    local applied, found = false, false
                    pcall(function()
                        if not comp.NetAvatarData or not comp.NetAvatarData.SlotSyncData then
                            return
                        end
                        local TempSlotSyncData = slua.IndexReference(comp.NetAvatarData, "SlotSyncData")
                        if not TempSlotSyncData then
                            return
                        end

                        local function skinForSlot(slotID, curItemID)
                            if slotID == EQUIP_SLOT_BAG and bagRes > 0 then
                                local lvl = F.levelFromEquipArmorID(curItemID)
                                if lvl < 1 and F.getEquippedArmorLevelBySubType then
                                    lvl = tonumber(F.getEquippedArmorLevelBySubType(501)) or 1
                                end
                                return tonumber(F.levelSkinID(F.resolveBackpackMappingBase(bagRes), lvl)) or 0
                            elseif slotID == EQUIP_SLOT_HELMET and helmetRes > 0 then
                                local lvl = F.levelFromEquipArmorID(curItemID)
                                if lvl < 1 and F.getEquippedArmorLevelBySubType then
                                    lvl = tonumber(F.getEquippedArmorLevelBySubType(502)) or 1
                                end
                                return tonumber(F.levelSkinID(F.resolveBackpackMappingBase(helmetRes), lvl))
                                    or 0
                            end
                            return nil
                        end

                        for Index, AvatarSyncData in pairs(TempSlotSyncData) do
                            if AvatarSyncData and AvatarSyncData.ItemID and AvatarSyncData.ItemID > 0 then
                                local slotID = AvatarSyncData.SlotID
                                if slotID == EQUIP_SLOT_BAG or slotID == EQUIP_SLOT_HELMET then
                                    found = true
                                    local cur = tonumber(AvatarSyncData.ItemID) or 0
                                    local targetSkin = skinForSlot(slotID, cur)
                                    if
                                        targetSkin
                                        and targetSkin > 0
                                        and (
                                            targetSkin ~= cur
                                            or tonumber(AvatarSyncData.AdditionalItemID) ~= targetSkin
                                        )
                                    then
                                        pcall(function()
                                            if F.ensureSkinDownload then
                                                F.ensureSkinDownload(targetSkin)
                                            end
                                        end)
                                        AvatarSyncData.ItemID = targetSkin
                                        AvatarSyncData.AdditionalItemID = targetSkin
                                        slua.IndexReference(comp.NetAvatarData, "SlotSyncData")
                                            :Set(Index, AvatarSyncData)
                                        applied = true
                                        if slotID == EQUIP_SLOT_BAG then
                                            EQUIP_APPLY.lastBagWrite = targetSkin
                                        else
                                            EQUIP_APPLY.lastHelmetWrite = targetSkin
                                        end
                                    end
                                end
                            end
                        end
                    end)
                    return applied, found
                end

                function F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
                    bagRes = tonumber(bagRes) or 0
                    helmetRes = tonumber(helmetRes) or 0
                    if bagRes <= 0 and helmetRes <= 0 then
                        return true
                    end
                    if bagRes > 0 then
                        _G.BackpackSkin = bagRes
                    end
                    if helmetRes > 0 then
                        _G.HelmetSkin = helmetRes
                    end
                    pcall(F.hookArmorInventoryAvatar)
                    pcall(F.applyInitialEquipmentAvatar)
                    local comp = char and (char.CharacterAvatarComp2_BP or F.getAvatarComp2(char))
                    if not slua.isValid(comp) then
                        pcall(function()
                            if char.getAvatarComponent2 then
                                comp = char:getAvatarComponent2()
                            end
                        end)
                    end
                    if not slua.isValid(comp) then
                        return false
                    end

                    local applied, found = F.applyEquipSkinToComp(comp, bagRes, helmetRes)

                    if applied then
                        pcall(function()
                            local ok1 = pcall(function()
                                if comp.OnRep_BodySlotStateChangedInternal then
                                    comp:OnRep_BodySlotStateChangedInternal()
                                end
                            end)
                            if not ok1 and comp.OnRep_BodySlotStateChanged then
                                comp:OnRep_BodySlotStateChanged()
                            end
                            if comp.ProcessAvatarRectify then
                                comp:ProcessAvatarRectify()
                            end
                        end)
                        return true
                    end
                    return found
                end

                function F.hookEquipmentRectify()
                    _G.AddOutfitEquipRectifyFn = function(self)
                        pcall(function()
                            if self.IsLobbyActor and self:IsLobbyActor() then
                                return
                            end
                            if not (self.IsSelf and self:IsSelf()) then
                                return
                            end
                            local bagRes = F.getDesiredWear(
                                "bagRes",
                                "bagRes",
                                "AddOutfitLastLobbyBagRes",
                                F.syncBodyCacheFromLobby
                            )
                            local helmetRes = F.getDesiredWear(
                                "helmetRes",
                                "helmetRes",
                                "AddOutfitLastLobbyHelmetRes",
                                F.syncBodyCacheFromLobby
                            )
                            if (tonumber(bagRes) or 0) <= 0 and (tonumber(helmetRes) or 0) <= 0 then
                                return
                            end
                            local applied = F.applyEquipSkinToComp(self, bagRes, helmetRes)
                            if applied then
                                pcall(function()
                                    local ok1 = pcall(function()
                                        if self.OnRep_BodySlotStateChangedInternal then
                                            self:OnRep_BodySlotStateChangedInternal()
                                        end
                                    end)
                                    if not ok1 and self.OnRep_BodySlotStateChanged then
                                        self:OnRep_BodySlotStateChanged()
                                    end
                                    if self.ProcessAvatarRectify then
                                        self:ProcessAvatarRectify()
                                    end
                                end)
                            end
                        end)
                    end
                    pcall(function()
                        local MCAC = require("GameLua.Mod.TPlan.Component.MetroCharacterAvatarComponent")
                        if MCAC._AddOutfitRectifyHooked then
                            return
                        end
                        MCAC._AddOutfitRectifyHooked = true
                        local o = MCAC.ProcessClientAvatarRectify
                        MCAC.ProcessClientAvatarRectify = function(self)
                            o(self)
                            if _G.AddOutfitEquipRectifyFn then
                                _G.AddOutfitEquipRectifyFn(self)
                            end
                        end
                    end)
                end

                function F.applyAirborneSlots(char, forceInAir)
                    if not F.skinFeat("SkinMatchAirborne") then
                        return false
                    end
                    local comp = F.getAvatarComp2(char)
                    if not comp or not slua.isValid(comp) then
                        return false
                    end
                    local inAir = forceInAir == true or F.isCharacterAirborne(char)
                    local paraRes = tonumber(F.getDesiredParachuteRes()) or 0
                    local gliderRes = tonumber(F.getDesiredGliderRes()) or 0
                    if paraRes <= 0 and gliderRes <= 0 then
                        return false
                    end

                    F._airApplied = F._airApplied or { para = 0, glider = 0, inAir = nil }
                    local prev = F._airApplied
                    if prev.para == paraRes and prev.glider == gliderRes and prev.inAir == inAir then
                        return true
                    end

                    if prev.para ~= paraRes or prev.glider ~= gliderRes then
                        pcall(function()
                            F.syncAirborneToDataMgr()
                        end)
                    end

                    local any = false
                    if paraRes > 0 then
                        any = true
                        if not F.isResourcesReady(paraRes) then
                            F.requestResourceDownload(paraRes)
                        end
                        F.setMakeSkin(comp, paraRes, F.CUST_SLOT.ParachuteEquipemtSlot, { inAir = inAir })
                    end
                    if gliderRes > 0 then
                        any = true
                        if not F.isResourcesReady(gliderRes) then
                            F.requestResourceDownload(gliderRes)
                        end
                        F.setMakeSkin(comp, gliderRes, F.CUST_SLOT.GlideEquipemtSlot, { inAir = inAir })
                    end
                    F._airApplied = { para = paraRes, glider = gliderRes, inAir = inAir }
                    return any
                end

                function F.tryApplyAirborneOnEnter(char)
                    if not F.skinFeat("SkinMatchAirborne") then
                        return false
                    end
                    char = char or F.getLocalChar()
                    if not char then
                        return false
                    end
                    local air = F.isCharacterAirborne(char)
                    local was = PERF._wasAirborne == true
                    PERF._wasAirborne = air
                    if air and not was then
                        return F.applyAirborneSlots(char, true)
                    end
                    return false
                end

