                        12204601,
                        12215701,
                        12219003,
                        12219004,
                        12219009,
                        12219216,
                    }

                    local CachedInGameEmotes = nil
                    local LastBaseCount = -1
                    local LastEmoteSwitchState = nil
                    local LastUseEquipped = nil

                    local function GetOptimizedEmoteList(baseList, useEquipped)
                        local baseCount = baseList and #baseList or 0
                        local isEmoteModEnabled = _G.NTHUY2004Config.ModEmote == true
                        useEquipped = useEquipped == true

                        if
                            CachedInGameEmotes
                            and not _G.__EMOTE_INGAME_CACHE_DIRTY
                            and LastBaseCount == baseCount
                            and LastEmoteSwitchState == isEmoteModEnabled
                            and LastUseEquipped == useEquipped
                        then
                            return CachedInGameEmotes
                        end

                        local compact = {}
                        local seen = {}

                        if baseList then
                            for _, data in pairs(baseList) do
                                if data and data.DefineID and data.DefineID.TypeSpecificID then
                                    local id = data.DefineID.TypeSpecificID
                                    if not seen[id] then
                                        compact[#compact + 1] = data
                                        seen[id] = true
                                    end
                                end
                            end
                        end

                        if isEmoteModEnabled and not useEquipped then
                            for _, nEmoteID in ipairs(EXTRA_EMOTES) do
                                if not seen[nEmoteID] then
                                    compact[#compact + 1] = {
                                        DefineID = { TypeSpecificID = nEmoteID },
                                        Name = tostring(nEmoteID),
                                    }
                                    seen[nEmoteID] = true
                                end
                            end
                        end

                        CachedInGameEmotes = compact
                        LastBaseCount = baseCount
                        LastEmoteSwitchState = isEmoteModEnabled
                        LastUseEquipped = useEquipped
                        _G.__EMOTE_INGAME_CACHE_DIRTY = false
                        return CachedInGameEmotes
                    end

                    if QuickExpressionUtils and not _G.__EMOTE_INGAME_HOOKED then
                        _G.__EMOTE_INGAME_HOOKED = true
                        _G.__EMOTE_ORIG_GET_LIST = QuickExpressionUtils.GetShowExpressionList

                        QuickExpressionUtils.GetShowExpressionList = function()
                            local baseList, nWeaponShowEmoteID = _G.__EMOTE_ORIG_GET_LIST()
                            local motionList = F.buildInGameEmoteListFromMotionSlots()
                            if motionList and #motionList > 0 then
                                local merged = F.mergeMotionListWithSpecials(baseList, motionList)
                                return GetOptimizedEmoteList(merged, true), nWeaponShowEmoteID
                            end
                            return GetOptimizedEmoteList(baseList, false), nWeaponShowEmoteID
                        end
                    end

                    pcall(function()
                        local BU = import("BackpackUtils")
                        if BU and not BU.__NTHUY2004_MOTION_EXIST_HOOKED then
                            BU.__NTHUY2004_MOTION_EXIST_HOOKED = true
                            local orig = BU.IsBattleItemHandleExist
                            BU.IsBattleItemHandleExist = function(defineID, bUseCache, bLobby, bForceLobby)
                                local id = defineID and tonumber(defineID.TypeSpecificID)
                                if id and id > 0 and F.isEmoteRes(id) then
                                    for _, data in ipairs(F.buildInGameEmoteListFromMotionSlots()) do
                                        if data.DefineID and tonumber(data.DefineID.TypeSpecificID) == id then
                                            return true
                                        end
                                    end
                                    if F.isInjectedRes(id) then
                                        return true
                                    end
                                end
                                return orig(defineID, bUseCache, bLobby, bForceLobby)
                            end
                        end
                    end)

                    if not _G.__EMOTE_MENU_EVENT_HOOKED and EventSystem and EventSystem.registEvent then
                        _G.__EMOTE_MENU_EVENT_HOOKED = true
                        EventSystem:registEvent(
                            EVENTTYPE_INGAME,
                            EVENTID_INGAME_QUICK_EXPRESSION_DECAL_CLICK,
                            function()
                                pcall(function()
                                    local motionList = F.buildInGameEmoteListFromMotionSlots()
                                    local hasEquipped = motionList and #motionList > 0
                                    if not _G.NTHUY2004Config.ModEmote and not hasEquipped then
                                        return
                                    end

                                    local UIManager = require("client.slua_ui_framework.manager")
                                    if not UIManager or not UIManager.UI_Config_InGame then
                                        return
                                    end
                                    local subPanel = UIManager.GetUI(
                                        UIManager.UI_Config_InGame.QuickExpressionDecalSubPanel
                                    )

                                    local showList = CachedInGameEmotes
                                    if hasEquipped then
                                        showList = F.mergeMotionListWithSpecials(
                                            _G.__EMOTE_ORIG_GET_LIST and select(1, _G.__EMOTE_ORIG_GET_LIST())
                                                or nil,
                                            motionList
                                        )
                                    end

                                    if
                                        subPanel
                                        and subPanel.GetQuickExpressionDecalItemByIndex
                                        and showList
                                    then
                                        local showCount = 0
                                        for _, data in ipairs(showList) do
                                            local nEmoteID = data.DefineID and data.DefineID.TypeSpecificID
                                            if nEmoteID and nEmoteID > 0 then
                                                showCount = showCount + 1
                                                local item =
                                                    subPanel:GetQuickExpressionDecalItemByIndex(showCount)
                                                if item then
                                                    if item.UIRoot.WidgetSwitcher_Effect then
                                                        item.UIRoot.WidgetSwitcher_Effect:SetWidgetVisibility(
                                                            UEnums.ESlateVisibility.Collapsed
                                                        )
                                                    end
                                                    if item.UIRoot.Image_Weapon then
                                                        item.UIRoot.Image_Weapon:SetWidgetVisibility(
                                                            UEnums.ESlateVisibility.Collapsed
                                                        )
                                                    end

                                                    item:Show()
                                                    item:RefreshData(nEmoteID, -1)
                                                end
                                            end
                                        end
                                        if subPanel.HideRestBlocks then
                                            subPanel:HideRestBlocks(showCount)
                                        end
                                        if subPanel.UIRoot then
                                            subPanel.UIRoot.WrapBox_List:SetWidgetVisibility(
                                                UEnums.ESlateVisibility.Visible
                                            )
                                            subPanel.UIRoot.VerticalBox_Empty:SetWidgetVisibility(
                                                UEnums.ESlateVisibility.Collapsed
                                            )
                                        end
                                    end
                                end)
                            end
                        )
                    end
                end)

                local HALL_THEME_ID = 202408061

                local MY_VEHICLES = {
                    1915021,
                    1915022,
                    1915026,
                    1908117,
                    1908118,
                    1908119,
                }

                local GARAGE_THEME_IDS = {
                    [202408061] = true,
                    [202408087] = true,
                }

                if not _G.LobbyThemeSystem then
                    _G.LobbyThemeSystem = {}
                end

                _G.HallThemeApplicationValue = HALL_THEME_ID
                _G.LobbyThemeSystem.MY_VEHICLES = MY_VEHICLES

                local function isCustomGarageTheme()
                    if not _G.NTHUY2004Config.SanhSieuXeVip then
                        return false
                    end
                    return GARAGE_THEME_IDS[_G.HallThemeApplicationValue] == true
                end

                local function buildVehicleList()
                    local Result = {}
                    for i = 1, #MY_VEHICLES do
                        local id = MY_VEHICLES[i]
                        if id and id > 0 then
                            Result[i] = id
                        end
                    end
                    return Result
                end

                local function buildVehicleInfoList()
                    local Result = {}
                    for i = 1, #MY_VEHICLES do
                        local id = MY_VEHICLES[i]
                        if id and id > 0 then
                            Result[i] = {
                                ItemID = id,
                                Source = EWardrobeDataSource and EWardrobeDataSource.Wardrobe or 0,
                            }
                        end
                    end
                    return Result
                end

                local function tryInitHooks()
                    local ok, ModuleManager = pcall(require, "client.module_framework.ModuleManager")
                    if not ok or not ModuleManager or not ModuleManager.GetModule then
                        return false
                    end
                    if not ModuleManager.LobbyModuleConfig then
                        return false
                    end

                    local MyThemeVehicleManager =
                        ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.ThemeVehicleManager)
                    local MyGarageThemeSystem =
                        ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.GarageThemeSystem)

                    if not MyThemeVehicleManager or not MyGarageThemeSystem then
                        return false
                    end

                    _G.LobbyThemeSystem.ModuleManager = ModuleManager
                    _G.LobbyThemeSystem.MyThemeVehicleManager = MyThemeVehicleManager
                    _G.LobbyThemeSystem.MyGarageThemeSystem = MyGarageThemeSystem

                    if
                        MyGarageThemeSystem.GetSelfGarageVehicleIDs
                        and not _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs
                    then
                        _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs =
                            MyGarageThemeSystem.GetSelfGarageVehicleIDs
                    end
                    if MyGarageThemeSystem.GetSelfGarageVehicleIDs then
                        MyGarageThemeSystem.GetSelfGarageVehicleIDs = function(self)
                            if isCustomGarageTheme() then
                                return buildVehicleList()
                            end
                            if _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs then
                                return _G.LobbyThemeSystem.OriginalGetSelfVehicleIDs(self)
                            end
                            return {}
                        end
                    end

                    if
                        MyGarageThemeSystem.GetSelfGarageVehicleAndSource
                        and not _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource
                    then
                        _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource =
                            MyGarageThemeSystem.GetSelfGarageVehicleAndSource
                    end
                    if MyGarageThemeSystem.GetSelfGarageVehicleAndSource then
                        MyGarageThemeSystem.GetSelfGarageVehicleAndSource = function(self)
                            if isCustomGarageTheme() then
                                return buildVehicleInfoList()
                            end
                            if _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource then
                                return _G.LobbyThemeSystem.OriginalGetSelfVehicleAndSource(self)
                            end
                            return {}
                        end
                    end

                    if
                        MyThemeVehicleManager.ShowThemeVehicle
                        and not _G.LobbyThemeSystem.OriginalShowThemeVehicle
                    then
                        _G.LobbyThemeSystem.OriginalShowThemeVehicle = MyThemeVehicleManager.ShowThemeVehicle
                    end
                    if MyThemeVehicleManager.ShowThemeVehicle then
                        MyThemeVehicleManager.ShowThemeVehicle = function(self)
                            if not self then
                                return
                            end
                            if isCustomGarageTheme() then
                                self:_ShowSelfVehicle()
                            elseif _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                                _G.LobbyThemeSystem.OriginalShowThemeVehicle(self)
                            end
                        end
                    end

                    if
                        MyThemeVehicleManager._ShowSelfVehicle
                        and not _G.LobbyThemeSystem.Original_ShowSelfVehicle
                    then
                        _G.LobbyThemeSystem.Original_ShowSelfVehicle = MyThemeVehicleManager._ShowSelfVehicle
                    end
                    if MyThemeVehicleManager._ShowSelfVehicle then
                        MyThemeVehicleManager._ShowSelfVehicle = function(self)
                            if not self then
                                return
                            end

                            if not isCustomGarageTheme() then
                                if _G.LobbyThemeSystem.Original_ShowSelfVehicle then
                                    return _G.LobbyThemeSystem.Original_ShowSelfVehicle(self)
                                end
                                return
                            end

                            local VehicleRefitHandler = require("client.network.Protocol.VehicleRefitHandler")
                            if not VehicleRefitHandler then
                                return
                            end

                            local uid = _ENV.DataMgr and _ENV.DataMgr.roleData and _ENV.DataMgr.roleData.uid
                                or 0
                            local LogicVehicleAccessory =
                                ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleAccessory)
                            local LogicVehicleExtendedFeature = ModuleManager.GetModule(
                                ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature
                            )

                            for Position = 1, #MY_VEHICLES do
                                local ItemID = MY_VEHICLES[Position]
                                if ItemID and ItemID > 0 then
                                    local StyleList = VehicleRefitHandler.GetCarStyleList(ItemID, nil, nil)
                                        or {}
                                    local accessoryList = LogicVehicleAccessory
                                            and LogicVehicleAccessory:GetEquipedAccessoryList(ItemID)
                                        or {}
                                    local ChassisLight = LogicVehicleExtendedFeature
                                            and LogicVehicleExtendedFeature:GetEquipedChassisLightData(ItemID)
                                        or nil
                                    local MultiSlotParts = LogicVehicleExtendedFeature
                                            and LogicVehicleExtendedFeature:GetEquipedMultiSlotParts(ItemID)
                                        or nil

                                    self:_TryCreateVehicleModel(
                                        ItemID,
                                        StyleList,
                                        true,
                                        Position,
                                        accessoryList,
                                        ChassisLight,
                                        uid,
                                        MultiSlotParts
                                    )
                                end
                            end

                            if self.OnVehicleChange then
                                self:OnVehicleChange()
                            end
                        end
                    end

                    _G.LobbyThemeSystem.UpdateTheme = function()
                        local lobbyThemeManager = nil
                        pcall(function()
                            lobbyThemeManager =
                                ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LobbyThemeManager)
                        end)

                        if not _G.NTHUY2004Config.SanhSieuXeVip then
                            if not _G.LobbyThemeSystem.IsRestoredToOriginal then
                                local mgr = _G.LobbyThemeSystem.MyThemeVehicleManager
                                if mgr and _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                                    _G.LobbyThemeSystem.OriginalShowThemeVehicle(mgr)
                                end

                                if lobbyThemeManager then
                                    pcall(function()
                                        local realResID = 0
                                        local HT = require("client.logic.lobby.hall_theme_utils")
                                        local insID = HT.GetThemeInstId and HT.GetThemeInstId()
                                        if insID and tonumber(insID) > 0 then
                                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                            local d = wd.GetHallDepotItemDataByInsID
                                                and wd:GetHallDepotItemDataByInsID(insID)
                                            if d and d.resID then
                                                realResID = tonumber(d.resID)
                                            end
                                        end

                                        lobbyThemeManager:ShowThemeByItemID(realResID or 0)
                                    end)
                                end

                                _G.LobbyThemeSystem.IsRestoredToOriginal = true
                            end
                            return
                        end

                        _G.LobbyThemeSystem.IsRestoredToOriginal = false

                        if not _G.HallThemeApplicationValue or _G.HallThemeApplicationValue == 0 then
                            return
                        end

                        if not lobbyThemeManager then
                            return
                        end

                        local currentThemeID = lobbyThemeManager:GetDisplayItemID()
                        if currentThemeID ~= _G.HallThemeApplicationValue then
                            lobbyThemeManager:ShowThemeByItemID(_G.HallThemeApplicationValue)
                        end

                        local mgr = _G.LobbyThemeSystem.MyThemeVehicleManager
                        if not mgr then
                            return
                        end

                        if isCustomGarageTheme() then
                            mgr:ShowThemeVehicle()
                        elseif _G.LobbyThemeSystem.OriginalShowThemeVehicle then
                            _G.LobbyThemeSystem.OriginalShowThemeVehicle(mgr)
                        end
                    end

                    _G.LobbyThemeSystem.__inited = true
                    return true
                end

                local function startTimers()
                    if _G.LobbyThemeSystem.TimersStarted then
                        return
                    end

                    local ok, TXtime_ticker = pcall(require, "common.time_ticker")
                    if not ok or not TXtime_ticker then
                        return
                    end

                    local delays = { 0.5, 1, 2, 5, 10 }
                    for i = 1, #delays do
                        TXtime_ticker.AddTimerOnce(delays[i], function()
                            if not _G.LobbyThemeSystem.__inited then
                                if tryInitHooks() and _G.LobbyThemeSystem.UpdateTheme then
                                    _G.LobbyThemeSystem.UpdateTheme()
                                end
                            elseif _G.LobbyThemeSystem.UpdateTheme then
                                _G.LobbyThemeSystem.UpdateTheme()
                            end
                        end)
                    end

                    TXtime_ticker.AddTimerLoop(0, function()
                        if not _G.NTHUY2004Config.SanhSieuXeVip then
                            return
                        end

                        if not _G.LobbyThemeSystem.__inited then
                            tryInitHooks()
                        end

                        local GameStatus = _ENV.GameStatus
                        if not GameStatus or not GameStatus.GetGameStatus then
                            return
                        end

                        local status = GameStatus.GetGameStatus()
                        if status == GameStatus.Lobby then
                            if _G.LobbyThemeSystem and _G.LobbyThemeSystem.UpdateTheme then
                                _G.LobbyThemeSystem.UpdateTheme()
                            end
                        end
                    end, -1, 0.5)

                    _G.LobbyThemeSystem.TimersStarted = true
                end

                pcall(startTimers)
            end

            _G.StartSkinAlwaysOn = function()
                if _G._SkinAlwaysOnStarted then
                    _G._SkinAlwaysOnStopped = false
                    _G._AddOutfitPendingStart = true
                    pcall(function()
                        if _G.NTHUY2004Config then
                            _G.NTHUY2004Config.ModSkin = true
                            _G.NTHUY2004Config.UseScriptSkins = true
                        end
                    end)
                    return
                end
                _G._SkinAlwaysOnStopped = false
                if _G.NTHUY2004Config == nil then
                    _G.NTHUY2004Config = {}
                end
                local C = _G.NTHUY2004Config
                C.ModSkin = true
                C.UseScriptSkins = true
                C.SkinMatchLoop = true
                C.SkinMatchWatcher = true
                C.SkinMatchOutfit = true
                C.SkinMatchFace = true
                C.SkinMatchWeapon = true
                C.SkinMatchGrenade = true
                C.SkinWeaponWatcher = true
                C.SkinMatchVehicle = true
                C.SkinMatchAirborne = true
                C.SkinDeadBox = true
                C.SkinAttachment = true
                C.InventureNTHUY2004 = true
                C.ModEmote = true
                C.ModPet = true
                C.KillMessage = true
                for _, k in ipairs({
                    "SkinEnable_Suit",
                    "SkinEnable_Top",
                    "SkinEnable_Gloves",
                    "SkinEnable_Bottom",
                    "SkinEnable_Shoes",
                    "SkinEnable_Bag",
                    "SkinEnable_Helmet",
                    "SkinEnable_Parachute",
                    "SkinEnable_M416",
                    "SkinEnable_AKM",
                    "SkinEnable_SCAR",
                    "SkinEnable_M762",
                    "SkinEnable_AUG",
                    "SkinEnable_UMP",
                    "SkinEnable_UZI",
                    "SkinEnable_Groza",
                    "SkinEnable_S12K",
                    "SkinEnable_DBS",
                    "SkinEnable_Dacia",
                    "SkinEnable_UAZ",
                    "SkinEnable_Coupe",
                    "SkinEnable_Buggy",
                    "SkinEnable_Mirado",
                }) do
                    C[k] = true
                end
                _G.NTHUY2004LoggedIn = true
                _G._AddOutfitPendingStart = true

                _G.SkinAlwaysOnDefaults = {
                    outfitRes = 1407895,
                    weaponSkins = {
                        [101004] = 1101004163,
                        [101001] = 1101001174,
                        [101003] = 1101003146,
                        [101002] = 1101008081,
                        [103001] = 1103001202,
                    },
                    vehicleSkin = 1961007,
                    parachuteRes = 1401000,
                }

                _G._SkinLastStartError = nil
                local okS, errS = pcall(function()
                    if _G.AddOutfit and _G.AddOutfit.start then
                        _G.AddOutfit.start()
                    end
                end)
                if not okS then
                    _G._SkinLastStartError = tostring(errS)
                    pcall(function()
                        Notify("Skin START FAIL: " .. tostring(errS))
                    end)
                end
                pcall(function()
                    local ok, ticker = pcall(require, "common.time_ticker")
                    if ok and ticker and ticker.AddTimerOnce then
                        for _, d in ipairs({ 1.0, 2.0, 5.0 }) do
                            ticker.AddTimerOnce(d, function()
                                pcall(function()
                                    if
                                        not _G._SkinAlwaysOnStopped
                                        and _G.AddOutfit
                                        and _G.AddOutfit.start
                                    then
                                        _G.AddOutfit.start()
                                    end
                                end)
                            end)
                        end
                    end
                end)
                pcall(function()
                    local ok, ticker = pcall(require, "common.time_ticker")
                    if ok and ticker and ticker.AddTimerLoop then
                        ticker.AddTimerLoop(0, function()
                            pcall(function()
                                if _G._SkinAlwaysOnStopped then
                                    return
                                end
                                local C2 = _G.NTHUY2004Config
                                if C2 and C2.ModSkin == false then
                                    C2.ModSkin = true
                                end
                                if C2 and C2.UseScriptSkins == false then
                                    C2.UseScriptSkins = true
                                end
                                if _G.AddOutfit and _G.AddOutfit.start and _G._AddOutfitPendingStart then
                                    _G._AddOutfitPendingStart = false
                                    _G.AddOutfit.start()
                                end
                                if _G.HandlePetLogic then
                                    _G.HandlePetLogic()
                                end
                            end)
                        end, -1, 5.0)
                    end
                end)
                _G._SkinAlwaysOnStarted = true
            end

            _G.StopSkinAlwaysOn = function()
                _G._SkinAlwaysOnStopped = true
                _G._AddOutfitPendingStart = false
                pcall(function()
                    if _G.NTHUY2004Config then
                        _G.NTHUY2004Config.ModSkin = false
                        _G.NTHUY2004Config.UseScriptSkins = false
                    end
                end)
            end
        end
        return _G.AddOutfit
    end

    -- MODULE: ui-base.lua
    _G.MWMenu = {
        root = nil,
        rootSlot = nil,
        open = true,
        sec = 1,
        tab = 1,
        k = 1,
        W = 1104,
        H = 678,
        items = {},
        content = {},
        nav = {},
        tabs = {},
    }
    LM = _G.MWMenu
    login = { verified = true }
    function LM.IsVerified()
        return embeddedLogin == _G.AdityaOrgLogin
            and embeddedLogin.IsAuthorized()
            and login.verified
            and _G.MWMenu == LM
    end
    function LM.Translate(text)
        return tostring(text)
    end
    function LM.FxScale(it, scale)
        if it and Valid(it.w) then
            it.w:SetRenderScale(FVector2D(scale, scale))
        end
    end
    LM.C = Core.Theme
    local function LMlin(c)
        if c <= 0.04045 then
            return c / 12.92
        end
        return ((c + 0.055) / 1.055) ^ 2.4
    end
    local function LMcol(c)
        return FLinearColor(LMlin(c[1]), LMlin(c[2]), LMlin(c[3]), c[4])
    end
    local function LMslate(c)
        local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
        local lc = LMcol(c)
        if FSlateColor then
            return FSlateColor(lc)
        end
        return lc
    end
    function LM.OpenCollection()
        if not _G.KinovaOfficialNeonLobbySceneAllowed or not _G.KinovaOfficialNeonLobbySceneAllowed() then
            return false
        end
        if not _G.MWConfig.CollectionHallUnlock then
            return
        end
        _G.KinovaOfficialCollectionOpenRequested = true
        if _G.KinovaOfficialInstallCollectionHall then
            _G.KinovaOfficialInstallCollectionHall()
        end
    end

    function LM.Protect(w)
        if not PlayerMapMarker._ProtectedWidgetStrs then
            PlayerMapMarker._ProtectedWidgetStrs = {}
        end
        PlayerMapMarker._ProtectedWidgetStrs[tostring(w)] = true
    end
    function LM.Rect(x, y, w, h, c, z, list)
        local k = LM.k
        local b = nil
        pcall(function()
            b = CGame:NewObjectFromPath("/Script/UMG.Border", LM.root)
        end)
        if not b or not slua.isValid(b) then
            return nil
        end
        pcall(function()
            b:SetBrushColor(LMcol(c))
        end)
        pcall(function()
            b:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
        end)
        local slot = nil
        pcall(function()
            slot = LM.root:AddChildToCanvas(b)
        end)
        if slot then
            pcall(function()
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x * k, y * k))
                slot:SetSize(FVector2D(w * k, h * k))
                slot:SetZOrder(z or 1)
            end)
        end
        LM.Protect(b)
        local it = { w = b, slot = slot }
        if list then
            list[#list + 1] = it
        end
        return it
    end
    function LM.Img(key, x, y, w, h, c, z, list, angle)
        local k = LM.k
        local it = _G.MWIconImageAt(LM.root, x * k, y * k, w * k, h * k, key, 0, 0, z or 5)
        if not it then
            return nil
        end
        if c then
            pcall(function()
                it.w:SetColorAndOpacity(LMcol(c))
            end)
        end
        if angle then
            pcall(function()
                it.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                it.w:SetRenderAngle(angle)
            end)
        end
        if list then
            list[#list + 1] = it
        end
        return it
    end
    function LM.Text(str, x, y, size, c, ax, ay, z, list, outline)
        local k = LM.k
        local t = nil
        pcall(function()
            t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", LM.root)
        end)
        if not t or not slua.isValid(t) then
            return nil
        end
        pcall(function()
            t:SetText(LM.Translate(str))
        end)
        pcall(function()
            t:SetColorAndOpacity(LMslate(c))
        end)
        pcall(function()
            local f = t.Font
            f.Size = math.max(8, math.floor(size * k + 0.5))
            if f.OutlineSettings then
                f.OutlineSettings.OutlineSize = 0
            end
            t.Font = f
        end)
        pcall(function()
            t:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
        end)
        local slot = nil
        pcall(function()
            slot = LM.root:AddChildToCanvas(t)
        end)
        if slot then
            pcall(function()
                slot:SetAutoSize(true)
                slot:SetPosition(FVector2D(x * k, y * k))
                slot:SetAlignment(FVector2D(ax or 0, ay or 0))
                slot:SetZOrder(z or 6)
            end)
        end
        LM.Protect(t)
        local it = { w = t, slot = slot }
        if list then
            list[#list + 1] = it
        end
        return it
    end
    function LM.Button(x, y, w, h, z, list, onClick, onPress, onRelease)
        local k = LM.k
        local loginControl = list ~= nil and list == LM.loginWidgets
        local function acceptsInput()
            return loginControl and LM.loginWidgets == list or not loginControl and login.verified
        end
        local btn = nil
        pcall(function()
            local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
            btn = CGame:NewObjectFromPath("/Script/UMG.Button", LM.root)
            if not btn or not slua.isValid(btn) then
                btn = nil
                return
            end
            local tr = FLinearColor(0, 0, 0, 0)
            pcall(function()
                btn:SetBackgroundColor(tr)
            end)
            pcall(function()
                btn.WidgetStyle.Normal.TintColor = FSlateColor(tr)
            end)
            pcall(function()
                btn.WidgetStyle.Hovered.TintColor = FSlateColor(tr)
            end)
            pcall(function()
                btn.WidgetStyle.Pressed.TintColor = FSlateColor(tr)
            end)
            pcall(function()
                btn:SetBrushColor(tr)
            end)
            pcall(function()
                btn.bIsFocusable = false
            end)
            pcall(function()
                btn.IsFocusable = false
            end)
            if onClick then
                btn.OnClicked:Add(function()
                    if not acceptsInput() then
                        return
                    end
                    pcall(onClick)
                end)
            end
            btn.OnPressed:Add(function()
                if not acceptsInput() then
                    return
                end
                pcall(function()
                    btn:SetRenderScale(FVector2D(0.97, 0.97))
                end)
                if onPress then
                    pcall(onPress)
                end
            end)
            btn.OnReleased:Add(function()
                if not acceptsInput() then
                    return
                end
                pcall(function()
                    btn:SetRenderScale(FVector2D(1, 1))
                end)
                if onRelease then
                    pcall(onRelease)
                end
            end)
            if w < 1000 then
                pcall(function()
                    btn.WidgetStyle.Hovered.TintColor = FSlateColor(LMcol(LM.C.hoverWash))
                    btn.WidgetStyle.Pressed.TintColor = FSlateColor(LMcol(LM.C.pressWash))
                    btn.OnUnhovered:Add(function()
                        btn:SetRenderScale(FVector2D(1, 1))
                    end)
                end)
            end
            local slot = LM.root:AddChildToCanvas(btn)
            if slot then
                pcall(function()
                    slot:SetAutoSize(false)
                    slot:SetPosition(FVector2D(x * k, y * k))
                    slot:SetSize(FVector2D(w * k, h * k))
                    slot:SetZOrder(z or 10)
                end)
            end
            pcall(function()
                if not loginControl and not login.verified then
                    btn:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
                else
                    btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
                end
            end)
            LM.Protect(btn)
            local it = { w = btn, slot = slot }
            if list then
                list[#list + 1] = it
            end
        end)
        return btn
    end
    function LM.Clear(list)
        for _, it in ipairs(list) do
            if it.w then
                if PlayerMapMarker._ProtectedWidgetStrs then
                    PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil
                end
                if Valid(it.w) then
                    pcall(function()
                        it.w:RemoveFromParent()
                    end)
                end
            end
        end
        for i = #list, 1, -1 do
            list[i] = nil
        end
    end
    function LM.RoundRect(x, y, w, h, r, c, z, list, leftOnly)
        LM.Rect(x + r - 1, y, w - (leftOnly and r or 2 * r) + 2, r + 1, c, z, list)
        LM.Rect(x, y + r - 1, w, h - 2 * r + 2, c, z, list)
        LM.Rect(x + r - 1, y + h - r - 1, w - (leftOnly and r or 2 * r) + 2, r + 1, c, z, list)
        LM.Img("ui_fill_corner", x, y, r, r, c, z, list, 0)
        LM.Img("ui_fill_corner", x, y + h - r, r, r, c, z, list, 270)
        if not leftOnly then
            LM.Img("ui_fill_corner", x + w - r, y, r, r, c, z, list, 90)
            LM.Img("ui_fill_corner", x + w - r, y + h - r, r, r, c, z, list, 180)
        end
    end
    function LM.CloseLoginPage() end
    function LM.Create(pc)
        if LM.root and _G.MWWidgetLive(LM.root) then
            return true
        end
        LM.CloseLoginPage()
        LM.root = nil
        LM.items = {}
        LM.content = {}
        LM.drop = {}
        LM.drag = nil
        local canvas = _G.MWHud.GetCanvas()
        if not canvas or not Game:IsValid(canvas) then
            return false
        end
        local W, H = 1920, 1080
        pcall(function()
            W, H = PlayerMapMarker.GetDynamicViewportSize(pc)
        end)
        if Core.UpdateCanvasTransform then
            Core.ESPCanvas = canvas
            Core.UpdateCanvasTransform(pc)
        end
        local measured
        if _G.SRCPanelMeasure then
            local ok, value = pcall(_G.SRCPanelMeasure, canvas)
            if ok then
                measured = value
                W, H = value.Width, value.Height
            end
        end
        local k = math.min(H * 0.76 / 678, W * 0.66 / 1104)
        LM.k = k
        local mw, mh = 1104 * k, 678 * k
        local root = nil
        pcall(function()
            root = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        end)
        if not root or not slua.isValid(root) then
            return false
        end
        local rs = nil
        pcall(function()
            rs = canvas:AddChildToCanvas(root)
        end)
        local nx, ny = tonumber(_G.MWConfig.MenuPosX) or -1, tonumber(_G.MWConfig.MenuPosY) or -1
        local x = nx >= 0 and nx * math.max(0, W - mw) or (W - mw) * 0.5
        local y = ny >= 0 and ny * math.max(0, H - mh) or (H - mh) * 0.5
        x, y = math.max(0, math.min(W - mw, x)), math.max(0, math.min(H - mh, y))
        LM.X, LM.Y, LM.ViewW, LM.ViewH = x, y, W, H
        LM.CanvasLayout = measured
        if not rs then
            pcall(root.RemoveFromParent, root)
            return false
        end
        do
            pcall(function()
                rs:SetAutoSize(false)
                rs:SetPosition(
                    FVector2D(
                        x * (Core._CanvasScaleX or 1) + (Core._CanvasOffsetX or 0),
                        y * (Core._CanvasScaleY or 1) + (Core._CanvasOffsetY or 0)
                    )
                )
                rs:SetSize(FVector2D(mw, mh))
                rs:SetZOrder(1200)
                root:SetRenderTransformPivot(FVector2D(0, 0))
                root:SetRenderScale(FVector2D(Core._CanvasScaleX or 1, Core._CanvasScaleY or 1))
                if measured then
                    local px, py = measured.Point(x, y)
                    rs:SetPosition(FVector2D(px, py))
                    root:SetRenderScale(FVector2D(1 / measured.ScaleX, 1 / measured.ScaleY))
                end
            end)
        end
        LM.Protect(root)
        LM.root, LM.rootSlot = root, rs
        LM.mainBuilt = false
        return true
    end

