    function LM.RowCheck(r, key, x, y, cw)
        check(x, y + 3, r.GetFunc() == true, LM.content)
        LM.Text(LM.Label(key), x + 61, y + 25, 18, white, 0, 0.5, 8, LM.content)
        LM.Button(x - 5, y, cw + 10, 52, 12, LM.content, function()
            r.SetFunc(nil, not r.GetFunc())
            LM.BuildContent()
        end)
