    function LM.RowSlider(r, key, x, y, cw)
        local value = r.GetFunc()
        local fraction = math.max(0, math.min(1, (value - r.MinValue) / (r.MaxValue - r.MinValue)))
        local suffix = key == "ModMenu_ESPTextSize" and "%" or key == "ModMenu_EspMaxDistance" and " m" or ""
        LM.Text(LM.Label(key), x, y + 14, 15, white, 0, 0.5, 6, LM.content)
        local valueText =
            LM.Text(tostring(value) .. suffix, x + cw, y + 14, 13, theme.tabText, 1, 0.5, 6, LM.content)
        LM.RoundRect(x, y + 46, cw, 5, 2, theme.track, 5, LM.content)
        local fill = LM.Rect(x, y + 46, math.max(4, cw * fraction), 5, purple, 6, LM.content)
        local knob = {}
        LM.RoundRect(x + (cw - 16) * fraction, y + 40, 16, 16, 8, white, 7, knob)
        for _, item in ipairs(knob) do
            LM.content[#LM.content + 1] = item
        end
        local lastFraction = fraction
        local slider = CGame:NewObjectFromPath("/Script/UMG.Slider", LM.root)
        if slider and slua.isValid(slider) then
            pcall(function()
                slider:SetSliderBarColor(FLinearColor(0, 0, 0, 0))
                slider:SetSliderHandleColor(FLinearColor(0, 0, 0, 0))
                slider:SetStepSize(1 / (r.MaxValue - r.MinValue))
                slider:SetValue(fraction)
            end)
            slider.OnValueChanged:Add(function(v)
                if not login.verified then
                    return
                end
                if not finite(v) then
                    return
                end
                v = math.max(0, math.min(1, v))
                r.SetFunc(nil, r.MinValue + v * (r.MaxValue - r.MinValue))
                v = (r.GetFunc() - r.MinValue) / (r.MaxValue - r.MinValue)
                if valueText then
                    valueText.w:SetText(tostring(r.GetFunc()) .. suffix)
                end
                if fill and fill.slot then
                    fill.slot:SetSize(FVector2D(math.max(4, cw * v) * LM.k, 5 * LM.k))
                end
                local shift = (cw - 16) * (v - lastFraction) * LM.k
                for _, item in ipairs(knob) do
                    if item.slot and item.slot.GetPosition then
                        local p = item.slot:GetPosition()
                        p.X = p.X + shift
                        item.slot:SetPosition(p)
                    end
                end
                lastFraction = v
            end)
            local slot = LM.root:AddChildToCanvas(slider)
            slot:SetPosition(FVector2D(x * LM.k, (y + 32) * LM.k))
            slot:SetSize(FVector2D(cw * LM.k, 34 * LM.k))
            slot:SetZOrder(15)
            LM.content[#LM.content + 1] = { w = slider, slot = slot }
        end
    end
