    -- MODULE: draw.lua
    local BoxESP = Core
    Core.LineWidgets = {}
    Core.CornerThickness = 1
    Core.CornerLengthRatio = 0.28
    Core.SnapLineThickness = 1.35
    Core.SnapLineOriginY = 0
    Core._CanvasScaleX, Core._CanvasScaleY, Core._CanvasOffsetX, Core._CanvasOffsetY = 1, 1, 0, 0
    local TempProjVec2D = FVector2D(0, 0)
    local ColorWhite = FLinearColor(1, 1, 1, 1)
    local ColorGreen = FLinearColor(table.unpack(Core.VisualPalette.Visible))
    local HealthCyan = FLinearColor(0, 1, 1, 1)
    local ColorRed = FLinearColor(table.unpack(Core.VisualPalette.Covered))
    local ColorBlue = FLinearColor(0.18, 0.62, 1, 1)
    local FSlateColor = import("SlateColor")
    local cornerKeys = {
        "TopLeft_H",
        "TopLeft_V",
        "TopRight_H",
        "TopRight_V",
        "BottomLeft_H",
        "BottomLeft_V",
        "BottomRight_H",
        "BottomRight_V",
    }
    local appliedVisibility = setmetatable({}, { __mode = "k" })
    local function visibility(w, enabled)
        if w and appliedVisibility[w] ~= enabled and Valid(w) then
            w:SetWidgetVisibility(
                enabled and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed
            )
            appliedVisibility[w] = enabled
        end
    end
    local function movePart(part, x, y, w, h)
        if part.x ~= x or part.y ~= y then
            local p = part.positionVector or FVector2D(0, 0)
            part.positionVector = p
            p.X, p.Y = x, y
            part.slot:SetPosition(p)
            part.x, part.y = x, y
        end
        if w and (part.w ~= w or part.h ~= h) then
            local p = part.sizeVector or FVector2D(0, 0)
            part.sizeVector = p
            p.X, p.Y = w, h
            part.slot:SetSize(p)
            part.w, part.h = w, h
        end
    end
    local function border(parent, color, x, y, w, h, z)
        local obj = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if not Valid(obj) then
            return nil
        end
        obj:SetBrushColor(color)
        visibility(obj, true)
        local slot = parent:AddChildToCanvas(obj)
        if not slot then
            obj:RemoveFromParent()
            return nil
        end
        slot:SetAutoSize(false)
        slot:SetPosition(FVector2D(x, y))
        slot:SetSize(FVector2D(w, h))
        slot:SetZOrder(z or 4)
        return { widget = obj, slot = slot }
    end
    local function text(parent, color, noOutline)
        local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", parent)
        if not Valid(txt) then
            return nil
        end
        local f = txt.Font
        f.Size = 10
        if f.OutlineSettings then
            f.OutlineSettings.OutlineSize = 0
            f.OutlineSettings.OutlineColor = FLinearColor(0, 0, 0, 1)
        end
        if txt.SetFont then
            txt:SetFont(f)
        else
            txt.Font = f
        end
        txt:SetText("")
        txt:SetJustification(1)
        txt:SetColorAndOpacity(FSlateColor and FSlateColor(color) or color)
        txt:SetShadowOffset(FVector2D(0, 0))
        txt:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 0))
        local slot = parent:AddChildToCanvas(txt)
        if not slot then
            txt:RemoveFromParent()
            return nil
        end
        slot:SetAutoSize(true)
        slot:SetAlignment(FVector2D(0.5, 0))
        slot:SetZOrder(1000)
        return { widget = txt, slot = slot }
    end
    local function requirePart(part, message)
        if type(part) ~= "table" or not part.widget or not part.slot then
            error(message)
        end
        return part
    end
    function Core.EnsureMarkParts(mark, cfg)
        local parent = Core.Canvas
        if cfg.EspPlayerBox and not mark.CornerContainer then
            local container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", parent)
            if not Valid(container) then
                error("corner_container_unavailable")
            end
            local slot = parent:AddChildToCanvas(container)
            if not slot then
                container:RemoveFromParent()
                error("corner_slot_unavailable")
            end
            mark.CornerContainer, mark.CornerSlot, mark.Corners = container, slot, {}
            mark.CornerLayout = { slot = slot }
            slot:SetAutoSize(false)
            slot:SetZOrder(995)
            slot:SetAlignment(FVector2D(0.5, 0.5))
        end
        if cfg.EspPlayerBox and not mark.CornersReady then
            for _, key in ipairs(cornerKeys) do
                if not mark.Corners[key] then
                    mark.Corners[key] = requirePart(
                        border(mark.CornerContainer, ColorWhite, 0, 0, 1, 1, 1),
                        "corner_part_unavailable"
                    )
                end
            end
            mark.CornersReady = true
        end
        if cfg.EspPlayerHP then
            if not mark.HealthBG then
                mark.HealthBG = requirePart(
                    border(parent, FLinearColor(0, 0, 0, 0.85), 0, 0, 2, 1, 998),
                    "health_background_unavailable"
                )
                mark.HealthBG.slot:SetAlignment(FVector2D(0.5, 1))
            end
            if not mark.Health then
                mark.Health =
                    requirePart(border(parent, HealthCyan, 0, 0, 2, 1, 999), "health_fill_unavailable")
                mark.Health.slot:SetAlignment(FVector2D(0.5, 1))
            end
        end
        if cfg.EspPlayerName and not mark.Name then
            mark.Name = requirePart(text(parent, ColorBlue), "name_widget_unavailable")
        end
        if cfg.EspPlayerDistance and not mark.Distance then
            mark.Distance = requirePart(text(parent, ColorWhite), "distance_widget_unavailable")
        end
    end
    function Core.NewMark()
        return {}
    end
    local function showPart(item, enabled)
        if item then
            visibility(item.widget, enabled)
        end
    end
    function Core.Hide(mark)
        visibility(mark.CornerContainer, false)
        showPart(mark.HealthBG, false)
        showPart(mark.Health, false)
        showPart(mark.Name, false)
        showPart(mark.Distance, false)
    end
    function Core.DrawPlayer(data)
        local cfg = _G.MWConfig
        local mark = Core.Widgets[data.key]
        if not cfg.EspPlayer then
            if mark then
                Core.Hide(mark)
            end
            Core.HideSnapLine(data.key)
            return
        end
        local bounds = cfg.EspPlayerBox or cfg.EspPlayerHP or cfg.EspPlayerName or cfg.EspPlayerDistance
        if
            not finite(data.x)
            or not finite(data.y1)
            or (bounds and (not finite(data.y2) or data.y2 <= data.y1))
        then
            if mark then
                Core.Hide(mark)
            end
            Core.HideSnapLine(data.key)
            return
        end
        if not mark then
            mark = Core.NewMark()
            if not mark then
                return
            end
            Core.Widgets[data.key] = mark
        end
        Core.EnsureMarkParts(mark, cfg)
        mark.LastSeen = now()
        local height = bounds and (data.y2 - data.y1) or 0
        local width = math.max(1, height * (data.prone and 1.1 or data.crouch and 0.7 or 0.55))
        if cfg.EspPlayerBox then
            Core.UpdateCornerDimensions(mark, width, height)
            local cy = (data.y1 + data.y2) * 0.5
            if mark.boxX ~= data.x or mark.boxY ~= cy then
                mark.CornerSlot:SetPosition(FVector2D(data.x, cy))
                mark.boxX, mark.boxY = data.x, cy
            end
        end
        visibility(mark.CornerContainer, cfg.EspPlayerBox)

        local percent = math.max(0, math.min(1, data.hp or 0))
        local barWidth = 2
        local bx = data.x - width * 0.5 - 2.5 - barWidth * 0.5
        showPart(mark.HealthBG, cfg.EspPlayerHP)
        showPart(mark.Health, cfg.EspPlayerHP and percent > 0)
        if cfg.EspPlayerHP then
            movePart(mark.HealthBG, bx, data.y2, barWidth, height)
            movePart(mark.Health, bx, data.y2, barWidth, height * percent)
        end

        local scale = math.max(0.8, math.min(1.4, (tonumber(cfg.ESPTextSize) or 100) / 100))
        if cfg.EspPlayerName and mark.Name then
            local name = data.bot and "Bot" or tostring(data.name or "Player")
            if mark.Name.lastText ~= name then
                mark.Name.widget:SetText(name)
                mark.Name.lastText = name
            end
            movePart(mark.Name, data.x, data.y2 + 4)
            if mark.Name.scale ~= scale then
                mark.Name.widget:SetRenderScale(FVector2D(scale, scale))
                mark.Name.scale = scale
            end
        end
        showPart(mark.Name, cfg.EspPlayerName)

        if cfg.EspPlayerDistance and mark.Distance then
            local value = tostring(math.floor(data.distance or 0)) .. "m"
            if mark.Distance.lastText ~= value then
                mark.Distance.widget:SetText(value)
                mark.Distance.lastText = value
            end
            movePart(mark.Distance, data.x, data.y2 + 20.5 * scale)
            if mark.Distance.scale ~= scale then
                mark.Distance.widget:SetRenderScale(FVector2D(scale, scale))
                mark.Distance.scale = scale
            end
        end
        showPart(mark.Distance, cfg.EspPlayerDistance)

        if cfg.EspPlayerLine then
            Core.UpdateSnapLine(
                data.key,
                data.x,
                data.y1,
                data.fromX,
                data.fromY,
                (data.visible == true or data.visible == 1) and ColorGreen or ColorRed,
                Core.Canvas
            )
        else
            Core.HideSnapLine(data.key)
        end
    end
    function Core.Remove(key)
        local mark = Core.Widgets[key]
        if mark then
            if Valid(mark.CornerContainer) then
                mark.CornerContainer:RemoveFromParent()
            end
            for _, part in ipairs({ "HealthBG", "Health", "Name", "Distance" }) do
                local item = mark[part]
                if item and Valid(item.widget) then
                    item.widget:RemoveFromParent()
                end
            end
        end
        local line = Core.LineWidgets[key]
        if line and Valid(line.Widget) then
            line.Widget:RemoveFromParent()
        end
        Core.LineWidgets[key] = nil
        Core.Widgets[key] = nil
    end
    function Core.Clear()
        if next(Core.ActorRows) then
            Core.ActorRows = {}
        end
        if Core.ClearWorld then
            Core.ClearWorld()
        end
        for key in pairs(Core.Widgets) do
            Core.Remove(key)
        end
        for key in pairs(Core.LineWidgets) do
            Core.Remove(key)
        end
        if Core.Counter and Valid(Core.Counter.root) then
            Core.Counter.root:RemoveFromParent()
        end
        if Core.Fov then
            for _, item in ipairs(Core.Fov) do
                if Valid(item.widget) then
                    item.widget:RemoveFromParent()
                end
            end
        end
        Core.Counter = nil
        Core.Fov = nil
        Core.FovLayout = nil
        Core.FovShown = false
    end
    function Core.DrawCounter(players, bots, x, y)
        if not (_G.MWConfig.EspPlayerCount and _G.MWConfig.EspPlayer) then
            if Core.Counter then
                visibility(Core.Counter.root, false)
            end
            return
        end
        if not Core.Counter then
            local style = Core.CounterStyle
            local root = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", Core.Canvas)
            if not Valid(root) then
                return
            end
            local slot = Core.Canvas:AddChildToCanvas(root)
            if not slot then
                root:RemoveFromParent()
                return
            end
            slot:SetSize(FVector2D(style.Width, style.Height))
            slot:SetAlignment(FVector2D(0.5, 0))
            slot:SetZOrder(1002)
            local function roundPanel(px, py, w, h, r, color, z)
                border(root, color, px + r, py, w - 2 * r, r, z)
                if h > 2 * r then
                    border(root, color, px, py + r, w, h - 2 * r, z)
                end
                border(root, color, px + r, py + h - r, w - 2 * r, r, z)
                for _, corner in ipairs({
                    { px, py, 0 },
                    { px + w - r, py, 90 },
                    { px + w - r, py + h - r, 180 },
                    {
                        px,
                        py + h - r,
                        270,
                    },
                }) do
                    local it = _G.MWIconImageAt(root, corner[1], corner[2], r, r, "ui_fill_corner", 0, 0, z)
                    if it then
                        it.w:SetColorAndOpacity(color)
                        it.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                        it.w:SetRenderAngle(corner[3])
                    end
                end
            end
            local radius = style.Radius or style.Height * 0.5
            local fill, edge = style.Fill, style.Edge
            roundPanel(
                0,
                0,
                style.Width,
                style.Height,
                radius,
                FLinearColor(fill[1], fill[2], fill[3], fill[4]),
                2
            )
            local ec = FLinearColor(edge[1], edge[2], edge[3], edge[4])
            border(root, ec, radius, 0, style.Width - 2 * radius, 1, 3)
            border(root, ec, radius, style.Height - 1, style.Width - 2 * radius, 1, 3)
            border(root, ec, 0, radius, 1, style.Height - 2 * radius, 3)
            border(root, ec, style.Width - 1, radius, 1, style.Height - 2 * radius, 3)
            for _, arc in ipairs({
                { radius, radius, math.pi },
                { style.Width - radius, radius, math.pi * 1.5 },
                { style.Width - radius, style.Height - radius, 0 },
                { radius, style.Height - radius, math.pi * 0.5 },
            }) do
                for i = 0, 7 do
                    local a, b = arc[3] + i * math.pi / 16, arc[3] + (i + 1) * math.pi / 16
                    local x1, y1 =
                        arc[1] + (radius - 0.5) * math.cos(a), arc[2] + (radius - 0.5) * math.sin(a)
                    local dx, dy =
                        (radius - 0.5) * (math.cos(b) - math.cos(a)),
                        (radius - 0.5) * (math.sin(b) - math.sin(a))
                    local p = border(root, ec, x1, y1, math.sqrt(dx * dx + dy * dy) + 0.3, 1, 3)
                    if p then
                        p.widget:SetRenderTransformPivot(FVector2D(0, 0.5))
                        p.widget:SetRenderAngle((math.atan2 or math.atan)(dy, dx) * 180 / math.pi)
                    end
                end
            end
            local color = style.Text
            local total = text(root, FLinearColor(color[1], color[2], color[3], color[4]))
            if total then
                local f = total.widget.Font
                f.Size = style.FontSize
                f.OutlineSettings.OutlineSize = 0
                total.widget.Font = f
                total.slot:SetAlignment(FVector2D(0.5, 0.5))
                total.slot:SetPosition(FVector2D(style.Width * 0.5, style.Height * 0.5))
                total.slot:SetZOrder(5)
            end
            Core.Counter = { root = root, slot = slot, total = total }
        end
        local c = Core.Counter
        visibility(c.root, _G.MWConfig.EspPlayerCount and _G.MWConfig.EspPlayer)
        local cy = (Core._CanvasOffsetY or 0) + (Core.CounterStyle.Top or 8) * (Core._CanvasScaleY or 1)
        if c.x ~= x or c.y ~= cy then
            c.slot:SetPosition(FVector2D(x, cy))
            c.x, c.y = x, cy
        end
        local value = tostring(math.max(0, math.floor((tonumber(players) or 0) + (tonumber(bots) or 0))))
        if c.value ~= value and c.total then
            c.total.widget:SetText(value)
            c.value = value
        end
    end
    function Core.DrawFov(pc)
        local show = _G.MWConfig.AimTouchEnable and _G.MWConfig.AimTouchShowFOV
        if not show then
            if Core.FovShown and Core.Fov then
                for _, item in ipairs(Core.Fov) do
                    visibility(item.widget, false)
                end
            end
            Core.FovShown = false
            return
        end
        Core.Fov = Core.Fov or {}
        for i = 1, 48 do
            if not Core.Fov[i] or not Valid(Core.Fov[i].widget) then
                Core.FovLayout = nil
                Core.Fov[i] =
                    requirePart(border(Core.Canvas, ColorWhite, 0, 0, 1, 1, 998), "fov_segment_unavailable")
            end
        end
        local w, h = PlayerMapMarker.GetDynamicViewportSize(pc)
        local cfg = _G.MWState.CustomTextData
        local r = (tonumber(cfg.AimTouchHipFOV) or 30) / 100 * w * 0.5
        local key = Core.FovLayout
        if
            key
            and key.w == w
            and key.h == h
            and key.r == r
            and key.sx == Core._CanvasScaleX
            and key.sy == Core._CanvasScaleY
            and key.ox == Core._CanvasOffsetX
            and key.oy == Core._CanvasOffsetY
        then
            if not Core.FovShown then
                for _, item in ipairs(Core.Fov) do
                    visibility(item.widget, true)
                end
            end
            Core.FovShown = true
            return
        end
        for i, item in ipairs(Core.Fov) do
            local a, b = (i - 1) * math.pi * 2 / 48, i * math.pi * 2 / 48
            local x1, y1 = w * 0.5 + math.cos(a) * r, h * 0.5 + math.sin(a) * r
            local x2, y2 = w * 0.5 + math.cos(b) * r, h * 0.5 + math.sin(b) * r
            local dx, dy = x2 - x1, y2 - y1
            item.slot:SetPosition(
                FVector2D(
                    x1 * Core._CanvasScaleX + Core._CanvasOffsetX,
                    y1 * Core._CanvasScaleY + Core._CanvasOffsetY
                )
            )
            item.slot:SetSize(FVector2D(math.sqrt(dx * dx + dy * dy) * Core._CanvasScaleX, 1))
            item.widget:SetRenderTransformPivot(FVector2D(0, 0))
            item.widget:SetRenderAngle((math.atan2 or math.atan)(dy, dx) * 180 / math.pi)
            visibility(item.widget, true)
        end
        Core.FovLayout = {
            w = w,
            h = h,
            r = r,
            sx = Core._CanvasScaleX,
            sy = Core._CanvasScaleY,
            ox = Core._CanvasOffsetX,
            oy = Core._CanvasOffsetY,
        }
        Core.FovShown = true
    end

    -- MODULE: knox-geometry.lua
    local IsValid = Valid
    function BoxESP.UpdateCornerDimensions(boxData, width, height)
        if
            boxData.lastW == width
            and boxData.lastH == height
            and boxData.lastThickness == BoxESP.CornerThickness
            and boxData.lastRatio == BoxESP.CornerLengthRatio
        then
            return
        end

        local t = BoxESP.CornerThickness
        local cLen = math.min(
            width * 0.45,
            height * 0.45,
            math.max(0.5, math.min(width, height) * BoxESP.CornerLengthRatio)
        )
        local C = boxData.Corners

        local layout = boxData.CornerLayout
        if not layout then
            layout = { slot = boxData.CornerSlot }
            boxData.CornerLayout = layout
        end
        if layout.w ~= width or layout.h ~= height then
            local v = layout.sizeVector or FVector2D(0, 0)
            layout.sizeVector = v
            v.X, v.Y = width, height
            layout.slot:SetSize(v)
            layout.w, layout.h = width, height
        end
        movePart(C.TopLeft_H, 0, 0, cLen, t)
        movePart(C.TopLeft_V, 0, 0, t, cLen)
        movePart(C.TopRight_H, width - cLen, 0, cLen, t)
        movePart(C.TopRight_V, width - t, 0, t, cLen)
        movePart(C.BottomLeft_H, 0, height - t, cLen, t)
        movePart(C.BottomLeft_V, 0, height - cLen, t, cLen)
        movePart(C.BottomRight_H, width - cLen, height - t, cLen, t)
        movePart(C.BottomRight_V, width - t, height - cLen, t, cLen)
        boxData.lastW, boxData.lastH = width, height
        boxData.lastThickness, boxData.lastRatio = BoxESP.CornerThickness, BoxESP.CornerLengthRatio
    end
    function BoxESP.UpdateCanvasTransform(PC)
        if not BoxESP.ESPCanvas or not IsValid(BoxESP.ESPCanvas) then
            return
        end

        local success = false
        if SlateBlueprintLibrary and SlateBlueprintLibrary.AbsoluteToLocal then
            local cg = BoxESP.ESPCanvas:GetCachedGeometry()
            if cg then
                local pt0 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(0, 0))
                local pt1 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(100, 100))
                if pt0 and pt1 then
                    BoxESP._CanvasScaleX = (pt1.X - pt0.X) / 100
                    BoxESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
                    BoxESP._CanvasOffsetX = pt0.X
                    BoxESP._CanvasOffsetY = pt0.Y
                    success = true
                end
            end
        end

        if not success and WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportScale then
            local scale = WidgetLayoutLibrary.GetViewportScale(PC) or 1.0
            BoxESP._CanvasScaleX = 1.0 / scale
            BoxESP._CanvasScaleY = 1.0 / scale
            BoxESP._CanvasOffsetX = 0
            BoxESP._CanvasOffsetY = 0
        end
    end
    function BoxESP.ProjectWorldToCanvasLocal(PC, WorldLoc)
        if not IsValid(PC) or not WorldLoc or not TempProjVec2D then
            return false, 0, 0
        end

        local res = PC:ProjectWorldLocationToScreen(WorldLoc, TempProjVec2D, true)
        if (res == true or res == 1) and (TempProjVec2D.X ~= 0 or TempProjVec2D.Y ~= 0) then
            local finalX = TempProjVec2D.X * BoxESP._CanvasScaleX + BoxESP._CanvasOffsetX
            local finalY = TempProjVec2D.Y * BoxESP._CanvasScaleY + BoxESP._CanvasOffsetY
            return true, finalX, finalY
        end
        return false, 0, 0
    end
    function BoxESP.GetSnapLineStartPos(PC, ParentCanvas)
        local width = PlayerMapMarker.GetDynamicViewportSize(PC)
        return width * 0.5 * BoxESP._CanvasScaleX + BoxESP._CanvasOffsetX,
            BoxESP.SnapLineOriginY * BoxESP._CanvasScaleY + BoxESP._CanvasOffsetY
    end
    function BoxESP.CreateSnapLine(ParentCanvas)
        if not IsValid(ParentCanvas) then
            return nil
        end
        local border = CGame:NewObjectFromPath("/Script/UMG.Border", ParentCanvas)
        if not IsValid(border) then
            return nil
        end

        border:SetBrushColor(ColorWhite)
        border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        border.RenderTransformPivot = FVector2D(0.0, 0.5)
        border:SetRenderTransformPivot(FVector2D(0.0, 0.5))

        local slot = ParentCanvas:AddChildToCanvas(border)
        if slot then
            slot:SetAutoSize(false)
            slot:SetZOrder(990)
        end
        return { Widget = border, Slot = slot, bVisible = true }
    end
    function BoxESP.UpdateSnapLine(KeyStr, toX, toY, fromX, fromY, CustomColor, ParentCanvas)
        local lineData = BoxESP.LineWidgets[KeyStr]
        if not lineData or not IsValid(lineData.Widget) then
            lineData = BoxESP.CreateSnapLine(ParentCanvas)
            if not lineData or not lineData.Widget or not lineData.Slot then
                return
            end
            BoxESP.LineWidgets[KeyStr] = lineData
        end

        if not lineData.bVisible then
            lineData.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            lineData.bVisible = true
        end

        if CustomColor and lineData.lastColor ~= CustomColor then
            local ok = pcall(function()
                lineData.Widget:SetBrushColor(CustomColor)
            end)
            if ok then
                lineData.lastColor = CustomColor
            end
        end

        local dx = toX - fromX
        local dy = toY - fromY
        local length = math.sqrt(dx * dx + dy * dy)
        local angle = (math.atan2 and math.atan2(dy, dx) or math.atan(dy, dx)) * (180.0 / math.pi)
        local t = BoxESP.SnapLineThickness or 1.0

        pcall(function()
            if lineData.lastX ~= fromX or lineData.lastY ~= fromY or lineData.lastT ~= t then
                local v = lineData._CachedPosVec or FVector2D(0, 0)
                lineData._CachedPosVec = v
                v.X, v.Y = fromX, fromY - t * 0.5
                lineData.Slot:SetPosition(v)
            end
            if lineData.lastLength ~= length or lineData.lastT ~= t then
                local v = lineData._CachedSizeVec or FVector2D(0, 0)
                lineData._CachedSizeVec = v
                v.X, v.Y = length, t
                lineData.Slot:SetSize(v)
            end
            if lineData.lastAngle ~= angle then
                lineData.Widget:SetRenderAngle(angle)
            end
            lineData.lastX, lineData.lastY, lineData.lastT = fromX, fromY, t
            lineData.lastLength, lineData.lastAngle = length, angle
        end)
    end
    function BoxESP.HideSnapLine(KeyStr)
        local lineData = BoxESP.LineWidgets[KeyStr]
        if lineData and lineData.Widget and IsValid(lineData.Widget) and lineData.bVisible then
            lineData.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
            lineData.bVisible = false
        end
    end

    -- MODULE: world.lua
    Core.WorldLimits = {
        VehicleDistance = 400,
        GrenadeDistance = 80,
        EnemyDistance = 300,
        DyeFadeDistance = 99999,
        DyeMaxDistance = 99999,
        VehicleScan = 1,
        GrenadeScan = 0.25,
        LabelUpdate = 0.1,
        MaxVehicles = 64,
        MaxGrenades = 32,
        MaxEnemies = 128,
        NewMeshApplies = 2,
        MeshRepairs = 1,
        MeshDiscoveries = 1,
        MaxWallMeshes = 8,
        MeshRefresh = 2,
        MeshDiscoveryInterval = 30,
        MeshWarmupInterval = 2,
        MeshRetryInterval = 5,
        UpdateInterval = 1 / 15,
    }
    local World = {
        Labels = {},
        Arrows = {},
        Meshes = {},
        Rejected = setmetatable({}, { __mode = "k" }),
        Sets = {},
        NextVehicle = 0,
        NextGrenade = 0,
        GrenadeCursor = 1,
    }
    Core.World = World
    local function member(obj, key)
        local ok, value = pcall(function()
            return obj[key]
        end)
        if ok then
            return value
        end
    end
    local function call(obj, key, ...)
        local fn = member(obj, key)
        if type(fn) ~= "function" then
            return false
        end
        return pcall(fn, obj, ...)
    end
    local function className(actor)
        local ok, cls = call(actor, "GetClass")
        local good, name = false, nil
        if ok and cls then
            good, name = call(cls, "GetName")
        end
        return good and tostring(name) or tostring(actor)
    end
    local function remove(item)
        if item and Valid(item.widget) then
            item.widget:RemoveFromParent()
        end
    end
    local function clearGroup(group)
        for key, item in pairs(World.Labels) do
            if item.group == group then
                remove(item)
                World.Labels[key] = nil
            end
        end
    end
    local function collect(name)
        local set = World.Sets[name]
        if not set then
            local ok, cls = pcall(import, name)
            if not ok or not cls then
                Core.Report("world-scan:" .. name, "Native class unavailable")
                return {}
            end
            set = { class = cls }
            World.Sets[name] = set
        end
        local ok, actors
        if Game.GetActorsByClass then
            ok, actors = pcall(Game.GetActorsByClass, Game, set.class)
        else
            if not set.array then
                local made, array = pcall(function()
                    return slua.Array(UEnums.EPropertyClass.Object, set.class)
                end)
                if not made then
                    made, array = pcall(slua.Array, set.class)
                end
                if made then
                    set.array = array
                end
            end
            if not set.array or not slua.getWorld then
                Core.Report("world-scan:" .. name, "Actor array/world unavailable")
                return {}
            end
            ok, actors = pcall(Clock.GetAllActorsOfClass, slua.getWorld(), set.class, set.array)
            if ok and not actors then
                actors = set.array
            end
        end
        if not ok or not actors then
            Core.Report("world-scan:" .. name, "Actor query failed")
            return {}
        end
        Core.Errors["world-scan:" .. name] = nil
        local result = {}
        if type(actors) == "table" and not actors.Num then
            for _, actor in pairs(actors) do
                if #result >= 256 then
                    break
                end
                result[#result + 1] = actor
            end
        else
            local n = math.min(tonumber(actors:Num()) or 0, 256)
            for i = 0, n - 1 do
                result[#result + 1] = actors:Get(i)
            end
        end
        return result
    end
    local function label(key, group, value, x, y, color, time)
        local it = World.Labels[key]
        if not it then
            it = text(Core.Canvas, color, group == "vehicle")
            if not it then
                return
            end
            it.group = group
            World.Labels[key] = it
        end
        if it.value ~= value then
            it.widget:SetText(value)
            it.value = value
        end
        if group == "vehicle" then
            it.widget:SetRenderAngle(0)
        end
        movePart(it, x, y)
        visibility(it.widget, true)
        it.seen = time
    end
    local function location(actor)
        return actor:K2_GetActorLocation()
    end
    local function distance(player, actor)
        local d = player:GetDistanceTo(actor) / 100
        return finite(d) and d >= 0 and d or nil
    end
    local function view(pc)
        local w, h = PlayerMapMarker.GetDynamicViewportSize(pc)
        return Core._CanvasOffsetX, Core._CanvasOffsetY, w * Core._CanvasScaleX, h * Core._CanvasScaleY
    end
    local function onScreen(pc, loc)
        local ok, x, y = Core.ProjectWorldToCanvasLocal(pc, loc)
        local ox, oy, w, h = view(pc)
        return ok and x >= ox and x <= ox + w and y >= oy and y <= oy + h, x, y
    end
    local vehicleNames = {
        { "Motorcycle", "Motorcycle" },
        { "Scooter", "Scooter" },
        { "Buggy", "Buggy" },
        { "UAZ", "UAZ" },
        { "Dacia", "Dacia" },
        { "Coupe", "Coupe" },
        { "Pickup", "Pickup" },
        { "Mirado", "Mirado" },
        { "Boat", "Boat" },
        { "Aquarail", "Jet Ski" },
        { "Rony", "Rony" },
        { "MiniBus", "Minibus" },
        { "Bigfoot", "Monster Truck" },
        { "Snowmobile", "Snowmobile" },
        { "SnowBike", "Snow Bike" },
        { "UTV", "UTV" },
        { "BRDM", "BRDM" },
        { "Glider", "Glider" },
    }
    local function vehicleName(actor)
        local name = className(actor)
        for _, pair in ipairs(vehicleNames) do
            if name:find(pair[1], 1, true) then
                return pair[2]
            end
        end
        return "Vehicle"
    end
    function World.GrenadeKind(actor)
        local name = className(actor):lower()
        if
            name:find("pickup", 1, true)
            or name:find("wrapper", 1, true)
            or name:find("smoke", 1, true)
            or name:find("flash", 1, true)
            or name:find("stun", 1, true)
        then
            return nil
        end
        local id = tonumber(member(actor, "CurGrenadeID"))
        if id == 602002 or id == 602001 then
            return nil
        end
        if name:find("molotov", 1, true) or name:find("burn", 1, true) or id == 602003 then
            return "Molotov"
        end
        if id == 602004 or name:find("frag", 1, true) or name:find("grenade", 1, true) then
            return "Grenade"
        end
    end
    function World.Remaining(actor)
        for _, key in ipairs({ "GetRemainingTimeBeforeExplode", "GetGrenadeRemainingTime" }) do
            local ok, value = call(actor, key)
            value = ok and tonumber(value)
            if value and finite(value) and value > 0 and value <= 60 then
                return value
            end
        end
    end
    local VehicleColor = FLinearColor(1, 1, 0, 1)
    local GrenadeColor = FLinearColor(1, 0.28, 0.12, 1)
    local DangerColor = FLinearColor(1, 0.32, 0.18, 1)
    local function updateVehicles(pc, player, time)
        if time >= World.NextVehicle then
            World.NextVehicle = time + Core.WorldLimits.VehicleScan
            World.Vehicles = {}
            local own = member(player, "CurrentVehicle")
            local ok, v = call(player, "GetCurrentVehicle")
            if ok and v then
                own = v
            end
            for _, actor in ipairs(collect("STExtraVehicleBase")) do
                if #World.Vehicles >= Core.WorldLimits.MaxVehicles then
                    break
                end
                if
                    Valid(actor)
                    and actor ~= own
                    and not actor.bHidden
                    and not actor.bTearOff
                    and (tonumber(actor.VehicleHealthState) or 0) < 2
                then
                    local d = distance(player, actor)
                    if d and d <= Core.WorldLimits.VehicleDistance then
                        World.Vehicles[#World.Vehicles + 1] = { actor = actor, name = vehicleName(actor) }
                    end
                end
            end
        end
        for _, row in ipairs(World.Vehicles or {}) do
            if
                Valid(row.actor)
                and not row.actor.bHidden
                and not row.actor.bTearOff
                and (tonumber(row.actor.VehicleHealthState) or 0) < 2
            then
                local d = distance(player, row.actor)
                if d and d <= Core.WorldLimits.VehicleDistance then
                    local ok, x, y = onScreen(pc, location(row.actor))
                    if ok then
                        label(
                            "vehicle:" .. tostring(row.actor),
                            "vehicle",
                            row.name .. "  " .. math.floor(d) .. "m",
                            x,
                            y,
                            VehicleColor,
                            time
                        )
                    else
                        local old = World.Labels["vehicle:" .. tostring(row.actor)]
                        if old then
                            visibility(old.widget, false)
                        end
                    end
                end
            end
        end
    end
    local function updateGrenades(pc, player, time)
        if time >= World.NextGrenade then
            World.NextGrenade = time + Core.WorldLimits.GrenadeScan
            local names = { "STExtraGrenadeBase", "STProjectileBase" }
            local idx = World.GrenadeCursor
            World.GrenadeCursor = idx % 2 + 1
            World.Grenades = World.Grenades or {}
            World.Grenades[idx] = {}
            for _, actor in ipairs(collect(names[idx])) do
                if #World.Grenades[idx] >= Core.WorldLimits.MaxGrenades then
                    break
                end
                if Valid(actor) then
                    local kind = World.GrenadeKind(actor)
                    local d = kind and distance(player, actor)
                    if d and d <= Core.WorldLimits.GrenadeDistance then
                        local ok, parent = call(actor, "GetAttachParentActor")
                        if not (ok and Valid(parent)) then
                            World.Grenades[idx][#World.Grenades[idx] + 1] = { actor = actor, kind = kind }
                        end
                    end
                end
            end
        end
        local seen = {}
        local nearest
        for _, bucket in pairs(World.Grenades or {}) do
            for _, row in ipairs(bucket) do
                local a = row.actor
                if Valid(a) and not seen[a] then
                    seen[a] = true
                    local d = distance(player, a)
                    if d and d <= Core.WorldLimits.GrenadeDistance then
                        local ok, x, y = onScreen(pc, location(a))
                        local remaining = World.Remaining(a)
                        local value = row.kind
                            .. "  "
                            .. math.floor(d)
                            .. "m"
                            .. (remaining and string.format("  %.1fs", remaining) or "")
                        if ok then
                            label("grenade:" .. tostring(a), "grenade", value, x, y, GrenadeColor, time)
                        end
                        if not nearest or d < nearest.distance then
                            nearest = { distance = d, value = value }
                        end
                    end
                end
            end
        end
        if nearest then
            local ox, oy, w = view(pc)
            label(
                "grenade:alert",
                "grenade",
                "DANGER  " .. nearest.value,
                ox + w * 0.5,
                oy + 56 * Core._CanvasScaleY,
                DangerColor,
                time
            )
        end
    end
    local function bodyColor(channels)
        local gain = Core.VisualPalette.BodyGain
        return FLinearColor(channels[1] * gain, channels[2] * gain, channels[3] * gain, channels[4])
    end
    local WallVisible = bodyColor(Core.VisualPalette.BodyVisible)
    local WallOccluded = bodyColor(Core.VisualPalette.BodyCovered)
    local function savedColor(value)
        if not value then
            return
        end
        local r, g, b, a = member(value, "R"), member(value, "G"), member(value, "B"), member(value, "A")
        if type(r) == "number" and type(g) == "number" and type(b) == "number" and type(a) == "number" then
            return FLinearColor(r, g, b, a)
        end
    end
    local function restoreMesh(mesh, state)
        if not Valid(mesh) then
            return
        end
        call(mesh, "SetDrawDyeing", state.draw)
        call(mesh, "SetDrawDyeingMode", state.mode)
        if state.visible then
            call(mesh, "SetVisibleDyeingColor", state.visible)
        end
        if state.occluded then
            call(mesh, "SetOccludedDyeingColor", state.occluded)
        end
        if state.fade then
            call(mesh, "SetDyeingColorFadeDistance", state.fade)
        end
        if state.minimum and state.maximum then
            call(mesh, "SetDyeingColorMinMaxDistance", state.minimum, state.maximum)
        end
    end
    function World.SetOutlineRenderer(enabled)
        if World.RenderEnabled == enabled then
            return
        end
        if enabled and now() < (World.RenderRetry or 0) then
            return
        end
        local system = import("KismetSystemLibrary")
        local key = "r.EnableDrawDyeingColor"
        local function read()
            local ok, value = pcall(function()
                return system.GetConsoleVariableIntValue(key)
            end)
            return ok and tonumber(value) or nil
        end
        local previous = read()
        local value = enabled and 1 or (World.RenderPrevious or 0)
        if enabled then
            World.RenderPrevious = previous or 0
        end
        local sent = false
        if system and system.ExecuteConsoleCommand and slua.getWorld then
            local ok, result =
                pcall(system.ExecuteConsoleCommand, slua.getWorld(), key .. " " .. tostring(value))
            sent = ok and result ~= false
        end
        local actual = read()
        if not sent or (actual and actual ~= value) then
            local gi = rawget(_G, "GameInstance")
            if not gi then
                local ok, ui = pcall(require, "client.common.ui_util")
                if ok and ui and ui.GetGameInstance then
                    gi = ui.GetGameInstance()
                end
            end
            if gi and gi.ExecuteCMD then
                local ok, result = pcall(gi.ExecuteCMD, gi, key, tostring(value))
                sent = ok and result ~= false
            end
            actual = read()
        end

        World.RenderVerified = actual == value
        if not sent then
            World.RenderRetry = now() + Core.WorldLimits.MeshRetryInterval
            Core.Report("world-dye-render", "Native dye renderer did not accept requested state")
            return
        end
        World.RenderEnabled = enabled
        World.RenderRetry = nil
        if not enabled then
            World.RenderPrevious = nil
        end
    end
    local dyeMethods = {
        "SetDrawDyeing",
        "SetDrawDyeingMode",
        "SetVisibleDyeingColor",
        "SetOccludedDyeingColor",
        "SetDyeingColorFadeDistance",
        "SetDyeingColorMinMaxDistance",
    }
    local function dyeMeshLive(mesh)
        if not Valid(mesh) then
            return false
        end
        local ok, pending = call(mesh, "IsPendingKill")
        return not (ok and pending == true)
    end
    local function outlineMesh(mesh, time)
        if not dyeMeshLive(mesh) then
            return
        end
        local retry = World.Rejected[mesh]
        if retry and time < retry then
            return
        end
        local state = World.Meshes[mesh]
        if state then
            state.seen = time
            if time < (state.refresh or 0) then
                return
            end
            if member(mesh, "bDrawDyeing") ~= false then
                state.refresh = time + Core.WorldLimits.MeshRefresh
                return
            end
        end
        local budget = state and "RepairsLeft" or "AppliesLeft"
        if (World[budget] or 0) <= 0 then
            return
        end
        local ok, count = call(mesh, "GetNumMaterials")
        if ok and tonumber(count) == 0 then
            return
        end
        for _, key in ipairs(dyeMethods) do
            if type(member(mesh, key)) ~= "function" then
                World.Rejected[mesh] = time + Core.WorldLimits.MeshRetryInterval
                Core.Report("world-dye", "Body dye API unavailable: " .. key)
                return
            end
        end
        World[budget] = World[budget] - 1
        state = state
            or {
                draw = member(mesh, "bDrawDyeing") == true,
                mode = tonumber(member(mesh, "DrawDyeingMode")) or 0,
                visible = savedColor(member(mesh, "VisibleDyeingColor")),
                occluded = savedColor(member(mesh, "OccludedDyeingColor")),
                fade = tonumber(member(mesh, "DyeingColorFadeDistance")),
                minimum = tonumber(member(mesh, "DyeingColorMinDistance")),
                maximum = tonumber(member(mesh, "DyeingColorMaxDistance")),
            }
        local distance = Core.WorldLimits.DyeFadeDistance
        local function apply(name, ...)
            local success, result = call(mesh, name, ...)
            if not success or result == false then
                error(name .. ": " .. tostring(result))
            end
        end
        local success, err = pcall(function()
            apply("SetDrawDyeing", true)
            apply("SetDrawDyeingMode", 1)
            apply("SetVisibleDyeingColor", WallVisible)
            apply("SetOccludedDyeingColor", WallOccluded)
            apply("SetDyeingColorFadeDistance", distance)
            apply("SetDyeingColorMinMaxDistance", 0, Core.WorldLimits.DyeMaxDistance)
        end)
        if not success then
            restoreMesh(mesh, state)
            World.Meshes[mesh] = nil
            World.Rejected[mesh] = time + Core.WorldLimits.MeshRetryInterval
            Core.Report("world-dye", err)
            return
        end
        state.seen = time
        state.refresh = time + Core.WorldLimits.MeshRefresh
        World.Meshes[mesh] = state
        World.Rejected[mesh] = nil
    end
    local function outline(actor, time, visible)
        World.PawnMeshes = World.PawnMeshes or setmetatable({}, { __mode = "k" })
        local cached = World.PawnMeshes[actor]
        local primary = member(actor, "Mesh")
        if not cached or not rawequal(cached.primary, primary) then
            cached = { primary = primary, next = 0, meshes = {} }
            if dyeMeshLive(primary) then
                cached.meshes[1] = primary
            end
            World.PawnMeshes[actor] = cached
        end
        if time >= cached.next and (World.DiscoveriesLeft or 0) > 0 then
            World.DiscoveriesLeft = World.DiscoveriesLeft - 1
            cached.discoveries = (cached.discoveries or 0) + 1
            local interval = cached.discoveries < 3 and Core.WorldLimits.MeshWarmupInterval
                or Core.WorldLimits.MeshDiscoveryInterval
            cached.next = time
                + math.max(interval, (Core.PawnCount or 0) * Core.WorldLimits.UpdateInterval * 1.5)
            local candidates, seen = {}, {}
            local function add(mesh)
                if not dyeMeshLive(mesh) or seen[mesh] then
                    return
                end
                seen[mesh] = true
                local ok, count = call(mesh, "GetNumMaterials")
                local score = ok and tonumber(count) or 1
                if score and score > 0 then
                    candidates[#candidates + 1] = { mesh = mesh, score = score }
                end
            end
            add(primary)
            local ok, cls = pcall(import, "SkeletalMeshComponent")
            if ok and cls then
                local good, items = call(actor, "GetComponentsByClass", cls)
                if good and items then
                    local n = items.Num and items:Num() or #items
                    for i = 1, math.min(tonumber(n) or 0, 16) do
                        add(items.Get and items:Get(i - 1) or items[i])
                    end
                end
            end
            local gotWeapon, weapon = call(actor, "GetCurrentWeapon")
            if gotWeapon and dyeMeshLive(weapon) then
                add(member(weapon, "Mesh"))
            end
            cached.meshes = {}
            for i = 1, math.min(#candidates, Core.WorldLimits.MaxWallMeshes) do
                cached.meshes[i] = candidates[i].mesh
            end
        end
        for _, mesh in ipairs(cached.meshes) do
            outlineMesh(mesh, time, visible)
        end
    end
    local function arrowBasis(pc, basis)
        local cam = pc.PlayerCameraManager
        if Valid(cam) then
            local ok, pos = call(cam, "GetCameraLocation")
            local good, rot = call(cam, "GetCameraRotation")
            if not good then
                good, rot = call(pc, "GetControlRotation")
            end
            if ok and good and pos and rot then
                local yaw, pitch = math.rad(rot.Yaw or 0), math.rad(rot.Pitch or 0)
                basis = basis or {}
                basis.x, basis.y, basis.z = pos.X, pos.Y, pos.Z
                basis.cy, basis.sy, basis.cp, basis.sp =
                    math.cos(yaw), math.sin(yaw), math.cos(pitch), math.sin(pitch)
                return basis
            end
        end
        return false
    end
    function World.ArrowPoint(pc, loc, basis)
        local inside, x, y = onScreen(pc, loc)
        if inside then
            return nil
        end
        local ox, oy, w, h = view(pc)
        local dx, dy
        if basis == nil then
            basis = arrowBasis(pc)
        end
        if basis then
            local ax, ay, az = loc.X - basis.x, loc.Y - basis.y, loc.Z - basis.z
            local forward = ax * basis.cp * basis.cy + ay * basis.cp * basis.sy + az * basis.sp
            dx = -ax * basis.sy + ay * basis.cy
            dy = -(-ax * basis.sp * basis.cy - ay * basis.sp * basis.sy + az * basis.cp)
            if forward < 0 then
                dy = math.max(math.abs(dy), -forward)
            end
        end
        if not dx then
            local projected, px, py = Core.ProjectWorldToCanvasLocal(pc, loc)
            if not projected then
                return nil
            end
            dx, dy = px - (ox + w * 0.5), py - (oy + h * 0.5)
        end
        local length = math.sqrt(dx * dx + dy * dy)
        if length < 0.001 then
            dx, dy, length = 0, 1, 1
        end
        local rx, ry = math.max(1, w * 0.5 - 38), math.max(1, h * 0.5 - 38)
        local scale = math.min(rx / math.max(0.001, math.abs(dx)), ry / math.max(0.001, math.abs(dy)))
        return ox + w * 0.5 + dx * scale,
            oy + h * 0.5 + dy * scale,
            (math.atan2 or math.atan)(dy, dx) * 180 / math.pi
    end
    function World.DrawArrow(key, x, y, angle, time, distance)
        local row = World.Arrows[key]
        if not row then
            local root = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", Core.Canvas)
            if not Valid(root) then
                return
            end
            local slot = Core.Canvas:AddChildToCanvas(root)
            if not slot then
                root:RemoveFromParent()
                return
            end
            slot:SetAutoSize(false)
            slot:SetSize(FVector2D(72, 72))
            slot:SetAlignment(FVector2D(0.5, 0.5))
            slot:SetZOrder(1001)
            local icon = _G.MWIconImageAt(root, 0, 0, 72, 72, "edge_marker", 0, 0, 1)
            row = {
                parts = { { widget = root } },
                root = root,
                slot = slot,
                label = text(root, FLinearColor(1, 1, 1, 1)),
            }
            if row.label then
                local f = row.label.widget.Font
                f.Size = 12
                f.OutlineSettings.OutlineSize = 0
                row.label.widget.Font = f
                row.label.slot:SetAlignment(FVector2D(0.5, 0.5))
            end
            World.Arrows[key] = row
        end
        movePart(row, x, y)
        visibility(row.root, true)
        if row.label then
            movePart(row.label, 36, 36)
            local value = tostring(math.floor(distance or 0)) .. "M"
            if row.value ~= value then
                row.label.widget:SetText(value)
                row.value = value
            end
        end
        row.seen = time
    end
    function Core.ClearWorld()
        clearGroup("vehicle")
        clearGroup("grenade")
        for key, row in pairs(World.Arrows) do
            for _, p in ipairs(row.parts) do
                remove(p)
            end
            World.Arrows[key] = nil
        end
        for mesh, state in pairs(World.Meshes) do
            restoreMesh(mesh, state)
            World.Meshes[mesh] = nil
        end
        if World.RenderEnabled then
            safe("world-outline-restore", World.SetOutlineRenderer, false)
        end
        World.Vehicles = nil
        World.Grenades = nil
        World.Player = nil
        World.Canvas = nil
        World.PawnMeshes = nil
        World.NextVehicle = 0
        World.NextGrenade = 0
        World.NextLabels = 0
        World.Flags = nil
        World.NextTick = 0
        World.Rejected = setmetatable({}, { __mode = "k" })
    end
    local function updateEnemy(key, actor, pc, player, time, basis, mine, cfg)
        local row = Core.ActorRows[tostring(key)]
        if not (row and row.pawn == actor and row.time == time) then
            row = nil
        end
        if row then
            if not row.eligible then
                return
            end
        else
            if
                not Valid(actor)
                or actor == player
                or actor.HealthStatus == 2
                or (tonumber(actor.Health) or 0) <= 0
            then
                return
            end
            local theirs = Core.TeamID(actor)
            if mine ~= nil and theirs ~= nil and mine == theirs then
                return
            end
        end
        local d = row and row.distance or distance(player, actor)
        if not d or d > Core.WorldLimits.EnemyDistance then
            return
        end
        if cfg.WorldWallVision and World.RenderEnabled then
            outline(actor, time)
        end
        if cfg.WorldArrows then
            local x, y, angle = World.ArrowPoint(pc, row and row.location or location(actor), basis)
            if x then
                World.DrawArrow(tostring(actor), x, y, angle, time, d)
            end
        end
    end
    function Core.WorldTick(pc, player, time)
        local cfg = _G.MWConfig
        World.AppliesLeft = Core.WorldLimits.NewMeshApplies
        World.RepairsLeft = Core.WorldLimits.MeshRepairs
        World.DiscoveriesLeft = Core.WorldLimits.MeshDiscoveries
        if World.Player ~= player or World.Canvas ~= Core.Canvas then
            Core.ClearWorld()
            World.Player = player
            World.Canvas = Core.Canvas
        end
        local flags = (cfg.WorldVehicle and 1 or 0)
            + (cfg.WorldWallVision and 2 or 0)
            + (cfg.WorldGrenade and 4 or 0)
            + (cfg.WorldArrows and 8 or 0)
        if cfg.WorldVehicle then
            safe("world-vehicle", updateVehicles, pc, player, time)
        end
        if World.Flags == flags and time < (World.NextTick or 0) then
            return
        end
        World.Flags = flags
        World.NextTick = time + Core.WorldLimits.UpdateInterval
        if not cfg.WorldWallVision then
            World.PawnMeshes = nil
            World.RenderRetry = nil
        end
        if cfg.WorldWallVision then
            safe("world-outline-render", World.SetOutlineRenderer, true)
        end
        if not cfg.WorldVehicle then
            clearGroup("vehicle")
            World.Vehicles = nil
            World.NextVehicle = 0
        end
        if not cfg.WorldGrenade then
            clearGroup("grenade")
            World.Grenades = nil
            World.NextGrenade = 0
        end
        if time >= (World.NextLabels or 0) then
            World.NextLabels = time + Core.WorldLimits.LabelUpdate
            if cfg.WorldGrenade then
                safe("world-grenade", updateGrenades, pc, player, time)
            end
        end
        if cfg.WorldWallVision or cfg.WorldArrows then
            local basis = false
            if cfg.WorldArrows then
                basis = arrowBasis(pc, World.CameraBasis)
                if basis then
                    World.CameraBasis = basis
                end
            end
            local count = 0
            local mine = Core.TeamID(player)
            for key, actor in pairs(Core.Pawns) do
                count = count + 1
                if count > Core.WorldLimits.MaxEnemies then
                    break
                end
                safe("world-enemy", updateEnemy, key, actor, pc, player, time, basis, mine, cfg)
            end
        end
        for key, item in pairs(World.Labels) do
            if time - (item.seen or 0) > 0.16 then
                visibility(item.widget, false)
            end
            if time - (item.seen or 0) > 1 then
                remove(item)
                World.Labels[key] = nil
            end
        end
        for key, row in pairs(World.Arrows) do
            if not cfg.WorldArrows then
                for _, p in ipairs(row.parts) do
                    remove(p)
                end
                World.Arrows[key] = nil
            elseif row.seen ~= time then
                visibility(row.root, false)
                if time - (row.seen or 0) > 1 then
                    for _, p in ipairs(row.parts) do
                        remove(p)
                    end
                    World.Arrows[key] = nil
                end
            end
        end
        for mesh, state in pairs(World.Meshes) do
            if not cfg.WorldWallVision or state.seen ~= time then
                restoreMesh(mesh, state)
                World.Meshes[mesh] = nil
            end
        end
        if not cfg.WorldWallVision and World.RenderEnabled then
            safe("world-outline-restore", World.SetOutlineRenderer, false)
        end
    end

    -- MODULE: crosshair.lua
    -- Camera ownership is released on toggle-off, pawn travel and auth shutdown.
    Core.AimRecoilHeightPerMeter = 1.1
    local ipad = { camera = nil, original = nil, next = 0 }
    function Core.RestoreIpadView()
        if Valid(ipad.camera) and ipad.original ~= nil then
            local ok, err = pcall(function() ipad.camera.FieldOfView = ipad.original end)
            if not ok then
                Core.Report("ipad-restore", err)
                return false
            end
        end
        ipad.camera, ipad.original, ipad.next = nil, nil, 0
        return true
    end
    function Core.IpadViewTick(player, time, force)
        if not _G.MWConfig.IpadView or not Valid(player) or not LM.IsVerified() then
            return Core.RestoreIpadView()
        end
        if not force and time < ipad.next then return end
        ipad.next = time + 0.25
        local camera = player.ThirdPersonCameraComponent
        if camera ~= ipad.camera then
            if not Core.RestoreIpadView() then return end
        end
        if not Valid(camera) then return end
        if player.bIsWeaponAiming == true or player.bIsWeaponAiming == 1 then return end
        if not ipad.camera then
            local original = tonumber(camera.FieldOfView)
            if not finite(original) or original <= 0 then
                Core.Report("ipad-view", "ThirdPersonCameraComponent.FieldOfView unavailable")
                return
            end
            ipad.camera, ipad.original = camera, original
        end
        local desired = _G.MWState.CustomTextData.IpadViewFOV
        if camera.FieldOfView ~= desired then camera.FieldOfView = desired end
        ipad.next = time + 0.25
    end
    Core.SmallCrosshairValue = 0.6
    local cross = { entity = nil, original = nil, next = 0 }
    function Core.RestoreCrosshair()
        if Valid(cross.entity) and cross.original ~= nil then
            pcall(function()
                cross.entity.GameDeviationFactor = cross.original
            end)
        end
        cross.entity = nil
        cross.original = nil
        cross.next = 0
    end
    function Core.CrosshairTick(player, time)
        if not _G.MWConfig.SmallCrosshair then
            if cross.entity then
                Core.RestoreCrosshair()
            end
            return
        end
        if time < cross.next then
            return
        end
        cross.next = time + 0.25
        local weapon
        if player.GetCurrentShootWeapon then
            weapon = player:GetCurrentShootWeapon()
        elseif player.GetCurrentWeapon then
            weapon = player:GetCurrentWeapon()
        end
        if not Valid(weapon) then
            local wm = player.WeaponManagerComponent
            if Valid(wm) then
                weapon = wm.GetCurrentUsingWeapon and wm:GetCurrentUsingWeapon() or wm.CurrentWeaponReplicated
            end
        end
        local entity = Valid(weapon)
            and (
                weapon.ShootWeaponEntity
                or weapon.ShootWeaponEntity_GEN_VARIABLE
                or weapon.ShootWeaponEntityComp
            )
        if entity ~= cross.entity then
            Core.RestoreCrosshair()
            if Valid(entity) and type(entity.GameDeviationFactor) == "number" then
                cross.entity = entity
                cross.original = entity.GameDeviationFactor
            end
        end
        if cross.entity then
            cross.entity.GameDeviationFactor = Core.SmallCrosshairValue
        else
            Core.Report("small-crosshair", "Native weapon GameDeviationFactor unavailable")
        end
    end

