        local function number(v, fallback, lo, hi)
            v = tonumber(v)
            if not v or v ~= v or v == math.huge or v == -math.huge then
                v = fallback
            end
            return math.max(lo, math.min(hi, v))
        end
        function M.Profiles:Group(weapon)
