            if id >= 1000000000 then
                id = tonumber(tostring(math.floor(id)):sub(2, 7)) or 0
            end
            return ({
                [101] = "AR",
                [102] = "SMG",
                [103] = "SR",
                [104] = "SG",
                [105] = "LMG",
                [106] = "PISTOL",
            })[math.floor(id / 1000)] or "OTHER"
        end
        function M.Profiles:Read(weapon, fov, speed, bone)
            local cfg = _G.MWConfig
            local group = self:Group(weapon)
            if cfg.AimWeaponProfiles ~= true then
                return fov, speed, bone
            end
            local prefix = "AimProfile_" .. group .. "_"
            return number(cfg[prefix .. "FOV"], fov, 1, 100),
                number(cfg[prefix .. "Speed"], speed, 1, 100),
                math.floor(number(cfg[prefix .. "Bone"], bone, 1, 5))
        end
        function M.Target:Allowed(enemy, player, maxMeters, ignoreKnock, ignoreBot)
            if not Valid(enemy) or enemy == player or enemy.HealthStatus == 2 then
                return false
            end
            if enemy.TeamID ~= nil and player.TeamID ~= nil and enemy.TeamID == player.TeamID then
                return false
            end
            if ignoreKnock and enemy.HealthStatus == 1 then
                return false
            end
            if type(enemy.IsDead) == "function" then
                local ok, dead = pcall(enemy.IsDead, enemy)
                if ok and (dead == true or dead == 1) then
                    return false
                end
            end
            if ignoreBot and _G.PlayerMapMarker and _G.PlayerMapMarker.IsAI(enemy) == true then
                return false
            end
            if type(player.GetDistanceTo) == "function" then
                local ok, d = pcall(player.GetDistanceTo, player, enemy)
                if ok and tonumber(d) and d > maxMeters * 100 then
                    return false
                end
            end
            return true
        end
        function M.Target:Score(enemy, player, screenDistance, mode)
            if mode == 2 then
                return player:GetDistanceTo(enemy)
            end
            if mode == 3 then
                return tonumber(enemy.Health) or 100
            end
            if mode == 4 then
                return (tonumber(enemy.Health) or 100) / math.max(1, tonumber(enemy.HealthMax) or 100)
            end
            return screenDistance
        end
        M.Calculate.BoneNames = { "head", "spine_03", "spine_01", "pelvis", "neck_01", "calf_l" }
        M.Calculate.BoneScratch = { X = 0, Y = 0, Z = 0 }
        function M.Calculate:Bone(enemy, name, index)
            name = self.BoneNames[tonumber(index)] or name
            if not enemy or type(name) ~= "string" then
                return nil
            end
            local function point(value)
                local ok, x, y, z = pcall(function()
                    return value.X, value.Y, value.Z
                end)
                if not ok then
                    return nil
                end
                local function finite(v)
                    return type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge
                end
                if not finite(x) or not finite(y) or not finite(z) or (x == 0 and y == 0 and z == 0) then
                    return nil
                end
                return { X = x, Y = y, Z = z }
            end
            local scratch = self.BoneScratch
            scratch.X, scratch.Y, scratch.Z = 0, 0, 0
            if type(enemy.GetBonePos) == "function" then
                local got, value = pcall(enemy.GetBonePos, enemy, name, scratch)
                if got then
                    local p = point(value) or point(scratch)
                    if p then
                        return p
                    end
                end
            end
            local mesh = enemy.Mesh
            if Valid(mesh) and type(mesh.GetSocketLocation) == "function" then
                local got, value = pcall(mesh.GetSocketLocation, mesh, name)
                if got then
                    local p = point(value)
                    if p then
                        return p
                    end
                end
            end
            if type(enemy.GetSocketLocation) == "function" then
                local got, value = pcall(enemy.GetSocketLocation, enemy, name)
                if got then
                    local p = point(value)
                    if p then
                        return p
                    end
                end
            end
            return nil
        end
        function M.Calculate:Smooth(speed, dt)
            speed = number(speed, 30, 1, 100)
            if speed >= 100 then
                return 1
            end
            local a = math.max(0.01, speed * 0.003)
            return 1 - (1 - a) ^ number((tonumber(dt) or 1 / 60) * 60, 1, 0.01, 4)
        end
    end
