            _G.KinovaOfficialStopAimAutoFire = StopAimAutoFire
            local function SGRead(object, key)
                local ok, value = pcall(function()
                    return object and object[key]
                end)
                if ok then
                    return value
                end
            end
            local function SGCall(object, key, ...)
                local method = SGRead(object, key)
                if type(method) ~= "function" then
                    return nil
                end
                local ok, value = pcall(method, object, ...)
                if ok then
                    return value
                end
            end
            local function AimShotgunAmmo(weapon)
                if not Valid(weapon) then
                    return nil
                end
                local value = tonumber(SGCall(weapon, "GetCurrentBulletNumInClip", 0))
                if value == nil then
                    value = tonumber(SGCall(weapon, "GetCurrentAmmo"))
                end
                if value == nil then
                    value = tonumber(SGCall(SGRead(weapon, "ShootWeaponComponent"), "GetCurrentAmmo"))
                end
                if value == nil then
                    value = tonumber(SGRead(weapon, "CurrentAmmo"))
                end
                if value == nil then
                    value = tonumber(SGRead(SGRead(weapon, "CurBulletInClip"), "CurBulletNumInClip"))
                end
                if value and value == value and value >= 0 then
                    return value
                end
            end
            local function SGInterval(weapon)
                local entity = SGCall(weapon, "GetShootWeaponEntityComponent")
                if not entity then
                    entity = SGRead(weapon, "ShootWeaponEntityComp")
                        or SGRead(weapon, "ShootWeaponEntity_GEN_VARIABLE")
                        or SGRead(weapon, "ShootWeaponEntity")
                end
                local interval = tonumber(SGRead(entity, "ShootInterval"))
                    or tonumber(SGRead(weapon, "ShootInterval"))
                if not interval or interval ~= interval or interval <= 0 then
                    interval = 0.8
                end
                return math.max(0.05, interval)
            end
            local function AimStepShotgunAutoFire(player, pc, weapon)
                local ammo = AimShotgunAmmo(weapon)
                if
                    not Valid(player)
                    or not Valid(weapon)
                    or not ammo
                    or ammo <= 0
                    or AimEnabled(SGRead(player, "bIsReloading"))
                    or AimEnabled(SGRead(weapon, "bIsReloading"))
                then
                    StopAimAutoFire(player)
                    _G.MWState.AimAutoFireStatus = ammo == 0 and "empty_magazine" or "paused"
                    return false
                end
                if AIM_AUTOFIRE_WEAPON and AIM_AUTOFIRE_WEAPON ~= weapon then
                    StopAimAutoFire(player)
                end
                local now = _G.RealNow()
                local interval = SGInterval(weapon)
                if AIM_AUTOFIRE_COOLDOWN_WEAPON ~= weapon then
                    AIM_AUTOFIRE_COOLDOWN_WEAPON = weapon
                    AIM_AUTOFIRE_NEXT_SHOT = 0
                end
                local state = AIM_AUTOFIRE_STATE
                if not state then
                    state = { Ammo = ammo }
                    AIM_AUTOFIRE_STATE = state
                end
                if state.Ammo and ammo < state.Ammo then
                    AIM_AUTOFIRE_NEXT_SHOT = now + interval
                end
                state.Ammo = ammo
                AIM_AUTOFIRE_WEAPON, AIM_AUTOFIRE_PLAYER = weapon, player
                _G.MWState.AimAutoFiring = true
                if now < AIM_AUTOFIRE_NEXT_SHOT then
                    return true
                end
                if type(SGRead(weapon, "StartFire")) ~= "function" then
                    StopAimAutoFire(player)
                    _G.MWState.AimAutoFireStatus = "start_fire_unavailable"
                    return false
                end
                local ok, err = pcall(function()
                    if state.Triggered and type(SGRead(weapon, "StopFire")) == "function" then
                        weapon:StopFire()
                    end
                    if _G.MWState and _G.MWState.AimAutoFireSaved == nil then
                        local cur = SGRead(player, "bIsWeaponFiring")
                        _G.MWState.AimAutoFireSaved = { Held = (cur == true or cur == 1), T = _G.RealNow() }
                    end
                    player.bIsWeaponFiring = true
                    if type(SGRead(player, "SetIsWeaponFiring")) == "function" then
                        player:SetIsWeaponFiring(true)
                    end
                    if Valid(pc) and type(SGRead(pc, "SetIsWeaponFiring")) == "function" then
                        pc:SetIsWeaponFiring(true)
                    end
                    local manager = SGRead(player, "WeaponManagerComponent")
                    if Valid(manager) then
                        manager.bIsWeaponFiring = true
                    end
                    assert(weapon:StartFire() ~= false, "start_fire_rejected")
                end)
                AIM_AUTOFIRE_NEXT_SHOT = now + interval
                if not ok then
                    StopAimAutoFire(player)
                    _G.MWState.AimAutoFireStatus = tostring(err)
                    return false
                end
                state.Triggered = true
                state.Ammo = AimShotgunAmmo(weapon) or ammo
                if state.Ammo <= 0 then
                    StopAimAutoFire(player)
                    _G.MWState.AimAutoFireStatus = "empty_magazine"
                    return false
                end
                _G.MWState.AimAutoFireStatus = "continuous_fire"
                return true
            end
